{
  "name": "MedPass: MR Hospital Booking System",
  "description": "A fair, transparent, and efficient hospital pass booking system for Medical Representatives (MRs) featuring priority-based lottery selection and QR gate verification.",
  "requestFramePermissions": [
    "camera"
  ]
}

export type MRStatus = 'active' | 'suspended';
export type ApplicationStatus = 'applied' | 'selected' | 'waitlisted' | 'rejected';
export type EntryStatus = 'not_entered' | 'entered' | 'expired';
export type UserRole = 'MR' | 'ADMIN' | 'SECURITY';

export interface MedicalRep {
  id: string;
  fullName: string;
  companyName: string;
  mrId: string;
  mobileNumber: string;
  status: MRStatus;
  createdAt: string;
}

export interface Hospital {
  id: string;
  name: string;
  dailyPassLimit: number;
  bookingWindowStart: string; // e.g. "18:00"
  bookingWindowEnd: string;   // e.g. "18:10"
}

export interface PassApplication {
  id: string;
  mrId: string;
  hospitalId: string;
  applicationDate: string;
  priorityScore: number;
  status: ApplicationStatus;
  createdAt: string;
}

export interface IssuedPass {
  id: string;
  mrId: string;
  hospitalId: string;
  passDate: string;
  timeSlot: string; // e.g. "09:00 - 10:00"
  qrCode: string;
  entryStatus: EntryStatus;
}

export interface EntryLog {
  id: string;
  issuedPassId: string;
  entryTime: string;
  verifiedBy: string;
}

export const TIME_SLOTS = [
  "09:00 - 10:00",
  "10:00 - 11:00",
  "11:00 - 12:00"
];

export const PRIORITY_WEIGHTS = {
  NO_PASS_14_DAYS: 5,
  NO_PASS_7_DAYS: 3,
  PASS_IN_LAST_3_DAYS: -5,
  MISSED_ENTRY: -10,
};

export const HOSPITAL_CONFIG = {
  DEFAULT_PASS_LIMIT: 15,
  WINDOW_START: "18:00",
  WINDOW_END: "18:10",
};

import { MedicalRep, Hospital, PassApplication, IssuedPass, EntryLog } from '../types';

const KEYS = {
  MRS: 'medpass_mrs',
  HOSPITALS: 'medpass_hospitals',
  APPLICATIONS: 'medpass_applications',
  PASSES: 'medpass_passes',
  LOGS: 'medpass_logs',
  SESSION: 'medpass_session'
};

export const storageService = {
  getMRs: (): MedicalRep[] => JSON.parse(localStorage.getItem(KEYS.MRS) || '[]'),
  saveMRs: (mrs: MedicalRep[]) => localStorage.setItem(KEYS.MRS, JSON.stringify(mrs)),

  getHospitals: (): Hospital[] => {
    const hospitals = localStorage.getItem(KEYS.HOSPITALS);
    if (!hospitals) {
      const initial = [{
        id: 'h1',
        name: 'City General Hospital',
        dailyPassLimit: 5,
        bookingWindowStart: '18:00',
        bookingWindowEnd: '21:00' // Widened for demo convenience
      }];
      localStorage.setItem(KEYS.HOSPITALS, JSON.stringify(initial));
      return initial;
    }
    return JSON.parse(hospitals);
  },

  getApplications: (): PassApplication[] => JSON.parse(localStorage.getItem(KEYS.APPLICATIONS) || '[]'),
  saveApplications: (apps: PassApplication[]) => localStorage.setItem(KEYS.APPLICATIONS, JSON.stringify(apps)),

  getPasses: (): IssuedPass[] => JSON.parse(localStorage.getItem(KEYS.PASSES) || '[]'),
  savePasses: (passes: IssuedPass[]) => localStorage.setItem(KEYS.PASSES, JSON.stringify(passes)),

  getLogs: (): EntryLog[] => JSON.parse(localStorage.getItem(KEYS.LOGS) || '[]'),
  saveLogs: (logs: EntryLog[]) => localStorage.setItem(KEYS.LOGS, JSON.stringify(logs)),

  getCurrentUser: () => JSON.parse(localStorage.getItem(KEYS.SESSION) || 'null'),
  setCurrentUser: (user: any) => localStorage.setItem(KEYS.SESSION, JSON.stringify(user)),
  clearSession: () => localStorage.removeItem(KEYS.SESSION)
};

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const getPriorityInsights = async (history: any[]) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Explain the priority score logic to a Medical Representative. 
      Their history: ${JSON.stringify(history)}. 
      Logic rules: 14 days no pass = +5, 7 days no pass = +3, pass in last 3 days = -5, missed entry = -10. 
      Summarize why their score is what it is in 2 friendly sentences.`,
    });
    return response.text;
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Priority is calculated based on your recent activity to ensure everyone gets a fair turn.";
  }
};

export const getAdminBriefing = async (apps: any[], passes: any[]) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Analyze today's booking activity. Applications: ${apps.length}, Passes Issued: ${passes.length}. 
      Give a one-sentence recommendation for tomorrow's pass limit based on this demand.`,
    });
    return response.text;
  } catch (error) {
    return "Demand remains steady. Recommend maintaining current pass limits.";
  }
};

