import React, { useState, useEffect } from 'react';
import { Calendar, Clock, QrCode, AlertCircle, CheckCircle2, Info } from 'lucide-react';
import { storageService } from '../services/storageService';
import { MedicalRep, PassApplication, IssuedPass, Hospital } from '../types';
import { getPriorityInsights } from '../services/geminiService';

interface MRDashboardProps {
  user: MedicalRep;
}

const MRDashboard: React.FC<MRDashboardProps> = ({ user }) => {
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [isWindowOpen, setIsWindowOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [aiInsight, setAiInsight] = useState<string>('');

  useEffect(() => {
    refreshData();
    const interval = setInterval(checkWindow, 10000);
    return () => clearInterval(interval);
  }, []);

  const refreshData = async () => {
    const h = storageService.getHospitals();
    const a = storageService.getApplications().filter(ap => ap.mrId === user.id);
    const p = storageService.getPasses().filter(ps => ps.mrId === user.id);
    setHospitals(h);
    setApps(a);
    setPasses(p);
    checkWindow();

    // Mock history for Gemini
    const history = a.slice(-3).map(app => ({ date: app.applicationDate, status: app.status }));
    const insight = await getPriorityInsights(history);
    setAiInsight(insight);
  };

  const checkWindow = () => {
    const now = new Date();
    const timeStr = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
    const h = storageService.getHospitals()[0]; // Just check first hospital for demo
    setIsWindowOpen(timeStr >= h.bookingWindowStart && timeStr <= h.bookingWindowEnd);
  };

  const handleApply = async (hospitalId: string) => {
    const today = new Date().toISOString().split('T')[0];

    // Check if already applied
    if (apps.some(a => a.hospitalId === hospitalId && a.applicationDate === today)) {
      alert("You have already applied for today.");
      return;
    }

    // Check blocking rule: No passes in last 2 days if entered today
    const recentPasses = passes.filter(p => p.entryStatus === 'entered');
    const lastEntry = recentPasses.length > 0 
      ? new Date(recentPasses[recentPasses.length - 1].passDate) 
      : null;

    if (lastEntry) {
      const diffDays = Math.floor((new Date().getTime() - lastEntry.getTime()) / (1000 * 3600 * 24));
      if (diffDays < 2) {
        alert("System Block: You can only apply 2 days after your last entry.");
        return;
      }
    }

    setLoading(true);
    const newApp: PassApplication = {
      id: Math.random().toString(36).substr(2, 9),
      mrId: user.id,
      hospitalId,
      applicationDate: today,
      priorityScore: 0, // Admin logic calculates this later
      status: 'applied',
      createdAt: new Date().toISOString()
    };

    const allApps = storageService.getApplications();
    storageService.saveApplications([...allApps, newApp]);

    setTimeout(() => {
      refreshData();
      setLoading(false);
    }, 800);
  };

  return (
    <div className="space-y-8">
      {/* Current Window Alert */}
      <div className={`p-4 rounded-xl flex items-center justify-between ${isWindowOpen ? 'bg-green-100 text-green-800' : 'bg-amber-100 text-amber-800'}`}>
        <div className="flex items-center gap-3">
          {isWindowOpen ? <CheckCircle2 className="h-6 w-6" /> : <Clock className="h-6 w-6" />}
          <div>
            <p className="font-bold">{isWindowOpen ? 'Booking Window Open!' : 'Booking Window Closed'}</p>
            <p className="text-sm opacity-90">Daily: {hospitals[0]?.bookingWindowStart} - {hospitals[0]?.bookingWindowEnd}</p>
          </div>
        </div>
        {isWindowOpen && (
          <span className="bg-green-600 text-white px-3 py-1 rounded-full text-xs font-bold animate-pulse">LIVE</span>
        )}
      </div>

      {/* AI Insight Card */}
      <div className="bg-indigo-50 border border-indigo-100 p-4 rounded-xl">
        <div className="flex items-start gap-3">
          <Info className="h-5 w-5 text-indigo-500 mt-1" />
          <div>
            <h3 className="text-sm font-semibold text-indigo-800">Priority Score Insight</h3>
            <p className="text-sm text-indigo-700 mt-1">{aiInsight || "Calculating your ranking factors..."}</p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Available Hospitals */}
        <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <h3 className="text-lg font-bold mb-4 flex items-center gap-2">
            <Calendar className="h-5 w-5 text-indigo-500" />
            Active Hospitals
          </h3>
          <div className="space-y-4">
            {hospitals.map(h => (
              <div key={h.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-lg border border-slate-100">
                <div>
                  <p className="font-semibold text-slate-800">{h.name}</p>
                  <p className="text-xs text-slate-500">Daily Limit: {h.dailyPassLimit}</p>
                </div>
                <button
                  disabled={!isWindowOpen || loading}
                  onClick={() => handleApply(h.id)}
                  className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${
                    isWindowOpen 
                      ? 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-md active:scale-95' 
                      : 'bg-slate-200 text-slate-400 cursor-not-allowed'
                  }`}
                >
                  {loading ? 'Processing...' : 'Book Pass'}
                </button>
              </div>
            ))}
          </div>
        </section>

        {/* Current Active Passes */}
        <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <h3 className="text-lg font-bold mb-4 flex items-center gap-2">
            <QrCode className="h-5 w-5 text-indigo-500" />
            Your Passes
          </h3>
          <div className="space-y-4">
            {passes.filter(p => p.entryStatus === 'not_entered').map(p => (
              <div key={p.id} className="p-4 bg-indigo-50 border border-indigo-200 rounded-xl relative overflow-hidden">
                <div className="flex justify-between items-start mb-2">
                  <div>
                    <p className="text-xs font-bold text-indigo-600 uppercase">Confirmed Pass</p>
                    <p className="font-bold text-slate-800">{hospitals.find(h => h.id === p.hospitalId)?.name}</p>
                  </div>
                  <div className="bg-white p-1 rounded border border-indigo-200">
                     <QrCode className="h-10 w-10 text-slate-800" />
                  </div>
                </div>
                <div className="flex gap-4 text-xs text-slate-600">
                  <div className="flex items-center gap-1">
                    <Calendar className="h-3 w-3" />
                    {p.passDate}
                  </div>
                  <div className="flex items-center gap-1">
                    <Clock className="h-3 w-3" />
                    {p.timeSlot}
                  </div>
                </div>
              </div>
            ))}
            {passes.filter(p => p.entryStatus === 'not_entered').length === 0 && (
              <div className="text-center py-8 text-slate-400 italic text-sm">
                No active passes found.
              </div>
            )}
          </div>
        </section>
      </div>

      {/* Recent History */}
      <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
        <h3 className="text-lg font-bold mb-4">Application History</h3>
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead className="bg-slate-50 text-slate-500">
              <tr>
                <th className="px-4 py-2 font-semibold">Date</th>
                <th className="px-4 py-2 font-semibold">Hospital</th>
                <th className="px-4 py-2 font-semibold">Status</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {apps.sort((a,b) => b.createdAt.localeCompare(a.createdAt)).map(app => (
                <tr key={app.id}>
                  <td className="px-4 py-3">{app.applicationDate}</td>
                  <td className="px-4 py-3 font-medium">{hospitals.find(h => h.id === app.hospitalId)?.name}</td>
                  <td className="px-4 py-3">
                    <span className={`px-2 py-1 rounded-full text-xs font-bold ${
                      app.status === 'selected' ? 'bg-green-100 text-green-700' :
                      app.status === 'waitlisted' ? 'bg-blue-100 text-blue-700' :
                      app.status === 'rejected' ? 'bg-red-100 text-red-700' :
                      'bg-slate-100 text-slate-600'
                    }`}>
                      {app.status.toUpperCase()}
                    </span>
                  </td>
                </tr>
              ))}
              {apps.length === 0 && (
                <tr>
                  <td colSpan={3} className="px-4 py-8 text-center text-slate-400">No previous applications.</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </section>
    </div>
  );
};

export default MRDashboard;

import React, { useState, useEffect } from 'react';
import { Users, Settings, PieChart, Play, CheckCircle, Trash2, ShieldAlert, Sparkles } from 'lucide-react';
import { storageService } from '../services/storageService';
import { MedicalRep, Hospital, PassApplication, IssuedPass } from '../types';
import { PRIORITY_WEIGHTS, TIME_SLOTS } from '../constants';
import { getAdminBriefing } from '../services/geminiService';

const AdminDashboard: React.FC = () => {
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [adminBrief, setAdminBrief] = useState("");
  const [activeTab, setActiveTab] = useState<'mrs' | 'lottery' | 'settings'>('lottery');

  useEffect(() => {
    refreshData();
  }, []);

  const refreshData = async () => {
    const _mrs = storageService.getMRs();
    const _hospitals = storageService.getHospitals();
    const _apps = storageService.getApplications();
    const _passes = storageService.getPasses();
    setMrs(_mrs);
    setHospitals(_hospitals);
    setApps(_apps);
    setPasses(_passes);

    const briefing = await getAdminBriefing(_apps, _passes);
    setAdminBrief(briefing);
  };

  const calculatePriority = (mrId: string) => {
    let score = 0;
    const now = new Date();
    const mrPasses = passes.filter(p => p.mrId === mrId && p.entryStatus === 'entered');

    if (mrPasses.length > 0) {
      const lastPassDate = new Date(mrPasses[mrPasses.length - 1].passDate);
      const diffDays = Math.floor((now.getTime() - lastPassDate.getTime()) / (1000 * 3600 * 24));

      if (diffDays >= 14) score += PRIORITY_WEIGHTS.NO_PASS_14_DAYS;
      else if (diffDays >= 7) score += PRIORITY_WEIGHTS.NO_PASS_7_DAYS;
      else if (diffDays <= 3) score += PRIORITY_WEIGHTS.PASS_IN_LAST_3_DAYS;
    } else {
      score += PRIORITY_WEIGHTS.NO_PASS_14_DAYS; // New MRs get high priority
    }

    // Penalties for missed entries
    const missed = passes.filter(p => p.mrId === mrId && p.entryStatus === 'expired').length;
    score += (missed * PRIORITY_WEIGHTS.MISSED_ENTRY);

    return score;
  };

  const runLottery = () => {
    const today = new Date().toISOString().split('T')[0];
    const hospital = hospitals[0];
    const todayApps = apps.filter(a => a.applicationDate === today && a.status === 'applied');

    if (todayApps.length === 0) {
      alert("No new applications to process for today.");
      return;
    }

    // 1. Calculate scores for all today's applicants
    const scoredApps = todayApps.map(a => ({
      ...a,
      priorityScore: calculatePriority(a.mrId)
    }));

    // 2. Sort by score descending
    scoredApps.sort((a, b) => b.priorityScore - a.priorityScore);

    // 3. Selection
    const selectedApps = scoredApps.slice(0, hospital.dailyPassLimit);
    const waitlistedApps = scoredApps.slice(hospital.dailyPassLimit);

    // 4. Update apps and create passes
    const newPasses: IssuedPass[] = selectedApps.map((a, index) => ({
      id: `PASS-${Math.random().toString(36).substr(2, 6).toUpperCase()}`,
      mrId: a.mrId,
      hospitalId: a.hospitalId,
      passDate: a.applicationDate,
      timeSlot: TIME_SLOTS[index % TIME_SLOTS.length],
      qrCode: `QR-${a.id}`,
      entryStatus: 'not_entered'
    }));

    // Update statuses in local storage
    const updatedAllApps = apps.map(originalApp => {
      const selected = selectedApps.find(s => s.id === originalApp.id);
      if (selected) return { ...originalApp, status: 'selected' as const, priorityScore: selected.priorityScore };

      const waitlisted = waitlistedApps.find(w => w.id === originalApp.id);
      if (waitlisted) return { ...originalApp, status: 'waitlisted' as const, priorityScore: waitlisted.priorityScore };

      return originalApp;
    });

    storageService.saveApplications(updatedAllApps);
    storageService.savePasses([...passes, ...newPasses]);

    alert(`Lottery complete! ${selectedApps.length} passes issued, ${waitlistedApps.length} waitlisted.`);
    refreshData();
  };

  return (
    <div className="space-y-6">
      {/* AI Header */}
      <div className="bg-gradient-to-r from-indigo-600 to-violet-600 rounded-2xl p-6 text-white shadow-lg">
        <div className="flex items-center gap-2 mb-2">
          <Sparkles className="h-5 w-5 text-indigo-200" />
          <h3 className="text-sm font-bold tracking-widest uppercase">Admin AI Briefing</h3>
        </div>
        <p className="text-lg font-medium opacity-90">{adminBrief || "Generating today's operations report..."}</p>
      </div>

      <div className="flex bg-white p-1 rounded-xl border border-slate-200 shadow-sm w-fit">
        <button 
          onClick={() => setActiveTab('lottery')}
          className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'lottery' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
        >
          <Play className="h-4 w-4" />
          Lottery Control
        </button>
        <button 
          onClick={() => setActiveTab('mrs')}
          className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'mrs' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
        >
          <Users className="h-4 w-4" />
          Manage MRs
        </button>
        <button 
          onClick={() => setActiveTab('settings')}
          className={`flex items-center gap-2 px-6 py-2 rounded-lg text-sm font-bold transition-all ${activeTab === 'settings' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
        >
          <Settings className="h-4 w-4" />
          Settings
        </button>
      </div>

      {activeTab === 'lottery' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 space-y-6">
            <section className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-lg font-bold">Today's Applicants</h3>
                <button 
                  onClick={runLottery}
                  className="bg-indigo-600 text-white px-6 py-2 rounded-xl font-bold hover:bg-indigo-700 shadow-lg active:scale-95 transition-all flex items-center gap-2"
                >
                  <Sparkles className="h-4 w-4" />
                  Run Lottery Engine
                </button>
              </div>

              <div className="overflow-x-auto">
                <table className="w-full text-left text-sm">
                  <thead className="bg-slate-50 text-slate-500 uppercase">
                    <tr>
                      <th className="px-4 py-3 font-semibold">MR Name</th>
                      <th className="px-4 py-3 font-semibold">Company</th>
                      <th className="px-4 py-3 font-semibold">Priority</th>
                      <th className="px-4 py-3 font-semibold">Status</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {apps.filter(a => a.applicationDate === new Date().toISOString().split('T')[0]).map(app => (
                      <tr key={app.id}>
                        <td className="px-4 py-3 font-medium">{mrs.find(m => m.id === app.mrId)?.fullName}</td>
                        <td className="px-4 py-3 text-slate-500">{mrs.find(m => m.id === app.mrId)?.companyName}</td>
                        <td className="px-4 py-3 font-bold text-indigo-600">{app.priorityScore || 'Pending'}</td>
                        <td className="px-4 py-3">
                          <span className={`px-2 py-1 rounded-full text-[10px] font-black uppercase ${
                            app.status === 'selected' ? 'bg-green-100 text-green-700' :
                            app.status === 'waitlisted' ? 'bg-amber-100 text-amber-700' :
                            'bg-slate-100 text-slate-500'
                          }`}>
                            {app.status}
                          </span>
                        </td>
                      </tr>
                    ))}
