              <HospitalIcon className="h-10 w-10 text-white" />
            </div>
            <h1 className="text-2xl font-black text-slate-800">MedPass System</h1>
            <p className="text-slate-500 font-medium">Hospital Entry Management</p>
          </div>

          <div className="p-8">
            <div className="flex bg-slate-100 p-1 rounded-xl mb-8">
              {(['MR', 'ADMIN', 'SECURITY'] as const).map(r => (
                <button 
                  key={r}
                  onClick={() => setRole(r)}
                  className={`flex-1 py-2 text-xs font-bold rounded-lg transition-all ${role === r ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}
                >
                  {r}
                </button>
              ))}
            </div>

            <form onSubmit={handleLogin} className="space-y-4">
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase ml-1">Mobile Number</label>
                <div className="relative">
                  <input 
                    type="tel" 
                    required
                    value={mobile}
                    onChange={(e) => setMobile(e.target.value)}
                    placeholder="e.g. 0712345678"
                    className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 transition-all outline-none"
                  />
                  <Key className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400" />
                </div>
              </div>

              <button className="w-full bg-indigo-600 text-white font-bold py-4 rounded-xl shadow-lg hover:bg-indigo-700 transition-all flex items-center justify-center gap-2 active:scale-95">
