            </form>

            <div className="mt-8 text-center">
              <p className="text-slate-500 text-sm">New Representative?</p>
              <button onClick={() => setView('REGISTER')} className="text-indigo-600 font-bold text-sm hover:underline mt-1">Create an Account</button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (view === 'REGISTER') {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
        <div className="bg-white w-full max-w-xl rounded-3xl shadow-xl overflow-hidden animate-in slide-in-from-bottom duration-300">
          <div className="p-8 border-b border-slate-100">
            <h2 className="text-2xl font-black text-slate-800">MR Registration</h2>
            <p className="text-slate-500">Enter your official details to get started</p>
          </div>
          <form onSubmit={handleRegister} className="p-8 space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-1">
                <label className="text-xs font-bold text-slate-500 uppercase ml-1">Full Name</label>
