                <input required value={mobile} onChange={e => setMobile(e.target.value)} type="tel" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all" />
              </div>
            </div>

            <div className="flex gap-4">
              <button type="button" onClick={() => setView('LOGIN')} className="flex-1 px-6 py-4 border border-slate-200 text-slate-600 font-bold rounded-xl hover:bg-slate-50">Back to Login</button>
              <button type="submit" className="flex-[2] bg-indigo-600 text-white px-6 py-4 rounded-xl font-bold shadow-lg hover:bg-indigo-700 active:scale-95 transition-all">Submit Registration</button>
            </div>
          </form>
        </div>
      </div>
    );
  }

  return (
    <Layout 
      user={user} 
      onLogout={handleLogout} 
      title={user.role === 'MR' ? 'Representative Dashboard' : user.role === 'ADMIN' ? 'Control Panel' : 'Gate Control'}
    >
      {user.role === 'MR' && <MRDashboard user={user} />}
      {user.role === 'ADMIN' && <AdminDashboard />}
      {user.role === 'SECURITY' && <SecurityView />}
    </Layout>
  );
};

