import { MedicalRep, Hospital, PassApplication, IssuedPass, EntryLog } from '../types';

const KEYS = {
  MRS: 'medpass_mrs',
  HOSPITALS: 'medpass_hospitals',
  APPLICATIONS: 'medpass_applications',
  PASSES: 'medpass_passes',
  LOGS: 'medpass_logs',
  SESSION: 'medpass_session'
};

export const storageService = {
  getMRs: (): MedicalRep[] => {
    const mrs = localStorage.getItem(KEYS.MRS);
    if (!mrs) {
      const initial: MedicalRep[] = [{
        id: 'demo-mr-1',
        fullName: 'John Doe',
        companyName: 'Global Pharma Co.',
        mrId: 'MR-7890',
        mobileNumber: '0771234567',
        status: 'active',
        createdAt: new Date().toISOString()
      }];
      localStorage.setItem(KEYS.MRS, JSON.stringify(initial));
      return initial;
    }
    return JSON.parse(mrs);
  },
  saveMRs: (mrs: MedicalRep[]) => localStorage.setItem(KEYS.MRS, JSON.stringify(mrs)),

  getHospitals: (): Hospital[] => {
    const hospitals = localStorage.getItem(KEYS.HOSPITALS);
    if (!hospitals) {
      const initial = [{
        id: 'h1',
        name: 'City General Hospital',
        dailyPassLimit: 5,
        bookingWindowStart: '00:00', // Set wide for easy demoing
        bookingWindowEnd: '23:59'
      }];
      localStorage.setItem(KEYS.HOSPITALS, JSON.stringify(initial));
      return initial;
    }
    return JSON.parse(hospitals);
  },

  getApplications: (): PassApplication[] => JSON.parse(localStorage.getItem(KEYS.APPLICATIONS) || '[]'),
  saveApplications: (apps: PassApplication[]) => localStorage.setItem(KEYS.APPLICATIONS, JSON.stringify(apps)),

  getPasses: (): IssuedPass[] => JSON.parse(localStorage.getItem(KEYS.PASSES) || '[]'),
  savePasses: (passes: IssuedPass[]) => localStorage.setItem(KEYS.PASSES, JSON.stringify(passes)),

  getLogs: (): EntryLog[] => JSON.parse(localStorage.getItem(KEYS.LOGS) || '[]'),
  saveLogs: (logs: EntryLog[]) => localStorage.setItem(KEYS.LOGS, JSON.stringify(logs)),

  getCurrentUser: () => JSON.parse(localStorage.getItem(KEYS.SESSION) || 'null'),
  setCurrentUser: (user: any) => localStorage.setItem(KEYS.SESSION, JSON.stringify(user)),
  clearSession: () => localStorage.removeItem(KEYS.SESSION)
};

