import { MedicalRep, Hospital, PassApplication, IssuedPass, EntryLog, MRHospitalApproval } from '../types';

const KEYS = {
  MRS: 'medpass_mrs',
  HOSPITALS: 'medpass_hospitals',
  APPLICATIONS: 'medpass_applications',
  PASSES: 'medpass_passes',
  LOGS: 'medpass_logs',
  SESSION: 'medpass_session',
  APPROVALS: 'medpass_approvals'
};

export const storageService = {
  getMRs: (): MedicalRep[] => {
    const mrs = localStorage.getItem(KEYS.MRS);
    if (!mrs) {
      const initial: MedicalRep[] = [{
        id: 'demo-mr-1',
        fullName: 'John Doe',
        companyName: 'Global Pharma Co.',
        mrId: 'MR-7890',
        mobileNumber: '0771234567',
        status: 'active',
        createdAt: new Date().toISOString()
      }];
      localStorage.setItem(KEYS.MRS, JSON.stringify(initial));
      return initial;
    }
    return JSON.parse(mrs);
  },
  saveMRs: (mrs: MedicalRep[]) => localStorage.setItem(KEYS.MRS, JSON.stringify(mrs)),

  getHospitals: (): Hospital[] => {
    const hospitals = localStorage.getItem(KEYS.HOSPITALS);
    if (!hospitals) {
      const initial = [
        {
          id: 'h1',
          name: 'Colombo General Hospital',
          dailyPassLimit: 5,
          bookingWindowStart: '00:00',
          bookingWindowEnd: '23:59'
        },
        {
          id: 'h2',
          name: 'Kandy National Hospital',
          dailyPassLimit: 3,
          bookingWindowStart: '00:00',
          bookingWindowEnd: '23:59'
        },
        {
          id: 'h3',
          name: 'Galle Karapitiya Teaching Hospital',
          dailyPassLimit: 10,
          bookingWindowStart: '18:00',
          bookingWindowEnd: '18:10'
        }
      ];
      localStorage.setItem(KEYS.HOSPITALS, JSON.stringify(initial));
      return initial;
    }
    return JSON.parse(hospitals);
  },

  getApprovals: (): MRHospitalApproval[] => {
    const approvals = localStorage.getItem(KEYS.APPROVALS);
    if (!approvals) {
      const initial: MRHospitalApproval[] = [
        {
          id: 'app-1',
          mrId: 'demo-mr-1',
          hospitalId: 'h1',
          status: 'approved',
          updatedAt: new Date().toISOString()
        }
      ];
      localStorage.setItem(KEYS.APPROVALS, JSON.stringify(initial));
      return initial;
    }
    return JSON.parse(approvals);
  },
  saveApprovals: (apps: MRHospitalApproval[]) => localStorage.setItem(KEYS.APPROVALS, JSON.stringify(apps)),

  getApplications: (): PassApplication[] => JSON.parse(localStorage.getItem(KEYS.APPLICATIONS) || '[]'),
  saveApplications: (apps: PassApplication[]) => localStorage.setItem(KEYS.APPLICATIONS, JSON.stringify(apps)),

  getPasses: (): IssuedPass[] => JSON.parse(localStorage.getItem(KEYS.PASSES) || '[]'),
  savePasses: (passes: IssuedPass[]) => localStorage.setItem(KEYS.PASSES, JSON.stringify(passes)),

  getLogs: (): EntryLog[] => JSON.parse(localStorage.getItem(KEYS.LOGS) || '[]'),
  saveLogs: (logs: EntryLog[]) => localStorage.setItem(KEYS.LOGS, JSON.stringify(logs)),

  getCurrentUser: () => JSON.parse(localStorage.getItem(KEYS.SESSION) || 'null'),
  setCurrentUser: (user: any) => localStorage.setItem(KEYS.SESSION, JSON.stringify(user)),
  clearSession: () => localStorage.removeItem(KEYS.SESSION)
};

import React, { useState, useEffect } from 'react';
import { Calendar, Clock, QrCode, AlertCircle, CheckCircle2, Info, Building2, PlusCircle, Lock } from 'lucide-react';
import { storageService } from '../services/storageService';
import { MedicalRep, PassApplication, IssuedPass, Hospital, MRHospitalApproval } from '../types';
import { getPriorityInsights } from '../services/geminiService';

interface MRDashboardProps {
  user: MedicalRep;
}

const MRDashboard: React.FC<MRDashboardProps> = ({ user }) => {
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [loading, setLoading] = useState(false);
  const [aiInsight, setAiInsight] = useState<string>('');

  useEffect(() => {
    refreshData();
  }, []);

  const refreshData = async () => {
    const h = storageService.getHospitals();
    const apprvs = storageService.getApprovals();
    const a = storageService.getApplications().filter(ap => ap.mrId === user.id);
    const p = storageService.getPasses().filter(ps => ps.mrId === user.id);

    setHospitals(h);
    setApprovals(apprvs);
    setApps(a);
    setPasses(p);

    const history = a.slice(-3).map(app => ({ date: app.applicationDate, status: app.status }));
    const insight = await getPriorityInsights(history);
    setAiInsight(insight);
  };

  const isWindowOpenForHospital = (h: Hospital) => {
    const now = new Date();
    const timeStr = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
    return timeStr >= h.bookingWindowStart && timeStr <= h.bookingWindowEnd;
  };

  const handleApply = async (hospitalId: string) => {
    const today = new Date().toISOString().split('T')[0];

    if (apps.some(a => a.hospitalId === hospitalId && a.applicationDate === today)) {
      alert("You have already applied for this hospital today.");
      return;
    }

    setLoading(true);
    const newApp: PassApplication = {
      id: Math.random().toString(36).substr(2, 9),
      mrId: user.id,
      hospitalId,
      applicationDate: today,
      priorityScore: 0,
      status: 'applied',
      createdAt: new Date().toISOString()
    };

    const allApps = storageService.getApplications();
    storageService.saveApplications([...allApps, newApp]);

    setTimeout(() => {
      refreshData();
      setLoading(false);
    }, 800);
  };

  const handleRequestAccess = (hospitalId: string) => {
    const allApprovals = storageService.getApprovals();
    const existing = allApprovals.find(a => a.mrId === user.id && a.hospitalId === hospitalId);

    if (existing) {
      alert(`Request is already ${existing.status}.`);
      return;
    }

    const newApproval: MRHospitalApproval = {
      id: `req-${Math.random().toString(36).substr(2, 6)}`,
      mrId: user.id,
      hospitalId,
      status: 'pending',
      updatedAt: new Date().toISOString()
    };

    storageService.saveApprovals([...allApprovals, newApproval]);
    alert("Access request sent to hospital administration.");
    refreshData();
  };

  const approvedHospitals = hospitals.filter(h => 
    approvals.some(a => a.mrId === user.id && a.hospitalId === h.id && a.status === 'approved')
  );

  const pendingHospitals = hospitals.filter(h => 
    approvals.some(a => a.mrId === user.id && a.hospitalId === h.id && a.status === 'pending')
  );

  const otherHospitals = hospitals.filter(h => 
    !approvals.some(a => a.mrId === user.id && a.hospitalId === h.id)
  );

  return (
    <div className="space-y-8">
      {/* AI Insight Card */}
      <div className="bg-indigo-50 border border-indigo-100 p-4 rounded-xl">
        <div className="flex items-start gap-3">
          <Info className="h-5 w-5 text-indigo-500 mt-1" />
          <div>
            <h3 className="text-sm font-semibold text-indigo-800">Priority Score Insight</h3>
            <p className="text-sm text-indigo-700 mt-1">{aiInsight || "Calculating your ranking factors..."}</p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {/* Approved Hospitals - Booking Section */}
        <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 md:col-span-2">
          <h3 className="text-lg font-bold mb-4 flex items-center gap-2">
            <Building2 className="h-5 w-5 text-indigo-500" />
            My Approved Hospitals
          </h3>
          <div className="grid gap-4 sm:grid-cols-2">
            {approvedHospitals.map(h => {
              const open = isWindowOpenForHospital(h);
              return (
                <div key={h.id} className="p-4 bg-slate-50 rounded-xl border border-slate-100 flex flex-col justify-between">
                  <div>
                    <div className="flex justify-between items-start mb-1">
                      <p className="font-bold text-slate-800">{h.name}</p>
                      {open && <span className="bg-green-500 h-2 w-2 rounded-full animate-pulse"></span>}
                    </div>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Window: {h.bookingWindowStart} - {h.bookingWindowEnd}</p>
                  </div>
                  <button
                    disabled={!open || loading}
                    onClick={() => handleApply(h.id)}
                    className={`mt-4 px-4 py-2 rounded-lg text-sm font-bold transition-all ${
                      open 
                        ? 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-md' 
                        : 'bg-slate-200 text-slate-400 cursor-not-allowed'
                    }`}
                  >
                    {open ? 'Apply for Pass' : 'Window Closed'}
                  </button>
                </div>
              );
            })}
            {approvedHospitals.length === 0 && (
              <div className="sm:col-span-2 p-8 text-center bg-slate-50 rounded-xl border border-dashed border-slate-300">
                <p className="text-sm text-slate-500 italic">No approved hospitals yet. Request access below.</p>
              </div>
            )}
          </div>
        </section>

        {/* Current Passes */}
        <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <h3 className="text-lg font-bold mb-4 flex items-center gap-2">
            <QrCode className="h-5 w-5 text-indigo-500" />
            Confirmed Passes
          </h3>
          <div className="space-y-4">
            {passes.filter(p => p.entryStatus === 'not_entered').map(p => (
              <div key={p.id} className="p-4 bg-indigo-50 border border-indigo-200 rounded-xl">
                <p className="font-bold text-slate-800 text-sm">{hospitals.find(h => h.id === p.hospitalId)?.name}</p>
                <div className="flex items-center gap-2 text-[10px] text-slate-500 mt-2 font-mono">
                  <Clock className="h-3 w-3" />
                  {p.timeSlot} | {p.passDate}
                </div>
                <div className="mt-3 flex justify-center bg-white p-2 rounded border border-indigo-100">
                  <QrCode className="h-20 w-20 text-indigo-900" />
                </div>
              </div>
            ))}
            {passes.filter(p => p.entryStatus === 'not_entered').length === 0 && (
              <div className="text-center py-8 text-slate-400 text-sm italic">
                No active passes.
              </div>
            )}
          </div>
        </section>
      </div>

      {/* Directory & Access Requests */}
      <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
        <h3 className="text-lg font-bold mb-4 flex items-center gap-2">
          <PlusCircle className="h-5 w-5 text-indigo-500" />
          Hospital Directory
        </h3>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
          {pendingHospitals.map(h => (
            <div key={h.id} className="p-4 border border-amber-100 bg-amber-50 rounded-xl flex items-center justify-between">
              <div>
                <p className="font-bold text-slate-800 text-sm">{h.name}</p>
                <p className="text-[10px] font-bold text-amber-600">PENDING APPROVAL</p>
              </div>
              <Clock className="h-5 w-5 text-amber-400" />
            </div>
          ))}
          {otherHospitals.map(h => (
            <div key={h.id} className="p-4 border border-slate-100 bg-slate-50 rounded-xl flex items-center justify-between group">
              <div>
                <p className="font-bold text-slate-800 text-sm">{h.name}</p>
                <p className="text-[10px] text-slate-400">Restricted Access</p>
              </div>
              <button 
                onClick={() => handleRequestAccess(h.id)}
                className="p-2 text-indigo-600 hover:bg-indigo-600 hover:text-white rounded-lg transition-all"
                title="Request Access"
              >
                <PlusCircle className="h-5 w-5" />
              </button>
            </div>
          ))}
        </div>
      </section>
    </div>
  );
};

