                    <td className="px-4 py-3 font-medium">{companies.find(c => c.id === inv.companyId)?.name}</td>
                    <td className="px-4 py-3">{inv.activeMRCount}</td>
                    <td className="px-4 py-3 font-bold">LKR {inv.amount.toLocaleString()}</td>
                    <td className="px-4 py-3">
                      <span className={`px-2 py-1 rounded-full text-[10px] font-bold ${inv.status === 'paid' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>{inv.status.toUpperCase()}</span>
                    </td>
                    <td className="px-4 py-3 text-slate-500">{inv.date}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </section>
      )}
    </div>
  );
};

