import React, { useState, useEffect } from 'react';
import { Calendar, Clock, QrCode, AlertCircle, CheckCircle2, Info, Building2, PlusCircle, Sun, Moon, Maximize } from 'lucide-react';
import { storageService } from '../services/storageService';
import { MedicalRep, PassApplication, IssuedPass, Hospital, MRHospitalApproval, SessionType } from '../types';
import { getPriorityInsights } from '../services/geminiService';

interface MRDashboardProps {
  user: MedicalRep;
}

const MRDashboard: React.FC<MRDashboardProps> = ({ user }) => {
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [loading, setLoading] = useState(false);
  const [aiInsight, setAiInsight] = useState<string>('');

  useEffect(() => { refreshData(); }, []);

  const refreshData = async () => {
    const h = storageService.getHospitals();
    const apprvs = storageService.getApprovals();
    const a = storageService.getApplications().filter(ap => ap.mrId === user.id);
    const p = storageService.getPasses().filter(ps => ps.mrId === user.id);
    setHospitals(h); setApprovals(apprvs); setApps(a); setPasses(p);
    const insight = await getPriorityInsights(a.slice(-3).map(app => ({ date: app.applicationDate, status: app.status })));
    setAiInsight(insight);
  };

  const isWindowOpen = (h: Hospital) => {
    const now = new Date();
    const time = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
    return time >= h.bookingWindowStart && time <= h.bookingWindowEnd;
  };

  const checkEligibility = (hospitalId: string, session: SessionType) => {
    const today = new Date();
    const recentPasses = passes.filter(p => p.hospitalId === hospitalId && p.entryStatus !== 'expired');

    for (const p of recentPasses) {
      const passDate = new Date(p.passDate);
      const diff = Math.floor((today.getTime() - passDate.getTime()) / (1000 * 3600 * 24));
      if (diff < 3) {
        if (p.session === 'FULL_DAY') return { eligible: false, reason: "Full Day pass blocks all applications for 3 days." };
        if (p.session === session) return { eligible: false, reason: `You already had a ${session} pass within the last 3 days.` };
      }
    }
    return { eligible: true };
  };

  const handleApply = async (hospitalId: string, session: SessionType) => {
    const { eligible, reason } = checkEligibility(hospitalId, session);
    if (!eligible) { alert(reason); return; }

    const todayStr = new Date().toISOString().split('T')[0];
    if (apps.some(a => a.hospitalId === hospitalId && a.applicationDate === todayStr && a.session === session)) {
      alert("Application already submitted for this session today."); return;
    }

    setLoading(true);
    const newApp: PassApplication = {
      id: Math.random().toString(36).substr(2, 9),
      mrId: user.id, hospitalId, session,
      applicationDate: todayStr, priorityScore: 0, status: 'applied',
      createdAt: new Date().toISOString()
    };
    storageService.saveApplications([...storageService.getApplications(), newApp]);
    setTimeout(() => { refreshData(); setLoading(false); }, 600);
  };

  const approvedHospitals = hospitals.filter(h => 
    approvals.some(a => a.mrId === user.id && a.hospitalId === h.id && a.status === 'approved')
  );

  return (
    <div className="space-y-8">
      <div className="bg-indigo-50 border border-indigo-100 p-4 rounded-xl flex items-start gap-3">
        <Info className="h-5 w-5 text-indigo-500 mt-0.5" />
        <p className="text-sm text-indigo-800">{aiInsight || "Analyzing your profile..."}</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 md:col-span-2">
          <h3 className="text-lg font-bold mb-4 flex items-center gap-2"><Building2 className="h-5 w-5 text-indigo-500" /> My Approved Clinics</h3>
          <div className="grid gap-4 sm:grid-cols-2">
            {approvedHospitals.map(h => (
              <div key={h.id} className="p-4 bg-slate-50 rounded-xl border border-slate-100">
                <div className="flex justify-between items-start mb-2">
                  <p className="font-bold text-slate-800">{h.name}</p>
                  {isWindowOpen(h) && <span className="bg-green-500 text-white text-[8px] font-bold px-1.5 rounded animate-pulse">WINDOW OPEN</span>}
                </div>
                <div className="space-y-2 mt-4">
                  {h.supportedSessions.map(sess => (
                    <button
                      key={sess}
                      disabled={!isWindowOpen(h) || loading}
                      onClick={() => handleApply(h.id, sess)}
                      className={`w-full py-2 px-3 rounded-lg text-xs font-bold flex items-center justify-between transition-all ${
                        isWindowOpen(h) ? 'bg-white border border-slate-200 hover:border-indigo-400 text-slate-700' : 'bg-slate-100 text-slate-400'
                      }`}
                    >
                      <span className="flex items-center gap-2">
                        {sess === 'MORNING' ? <Sun className="h-3 w-3" /> : sess === 'EVENING' ? <Moon className="h-3 w-3" /> : <Maximize className="h-3 w-3" />}
                        {sess}
                      </span>
                      <span>Apply</span>
                    </button>
                  ))}
                </div>
              </div>
            ))}
            {approvedHospitals.length === 0 && <div className="sm:col-span-2 p-8 text-center bg-slate-50 border border-dashed rounded-xl italic text-slate-400 text-sm">No hospital access yet.</div>}
          </div>
        </section>

        <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <h3 className="text-lg font-bold mb-4 flex items-center gap-2"><QrCode className="h-5 w-5 text-indigo-500" /> Active Passes</h3>
          <div className="space-y-4">
            {passes.filter(p => p.entryStatus === 'not_entered').map(p => (
              <div key={p.id} className="p-4 bg-indigo-50 border border-indigo-200 rounded-xl">
                <div className="flex justify-between text-[10px] font-black uppercase text-indigo-600 mb-1">
                  <span>{p.session} SESSION</span>
                  <span>{p.passDate}</span>
                </div>
                <p className="font-bold text-slate-800 mb-2">{hospitals.find(h => h.id === p.hospitalId)?.name}</p>
                <div className="bg-white p-3 rounded border border-indigo-100 flex justify-center">
                  <QrCode className="h-20 w-20 text-indigo-900" />
                </div>
              </div>
            ))}
          </div>
        </section>
      </div>
    </div>
  );
};

