import React, { useState, useEffect } from 'react';
import { Play, Sparkles, CheckCircle, Clock, UserPlus, Users, Settings } from 'lucide-react';
import { storageService } from '../services/storageService';
import { MedicalRep, Hospital, PassApplication, IssuedPass, MRHospitalApproval, SessionType } from '../types';
import { PRIORITY_WEIGHTS, TIME_SLOTS } from '../constants';
import { getAdminBriefing } from '../services/geminiService';

const AdminDashboard: React.FC = () => {
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [activeTab, setActiveTab] = useState<'lottery' | 'approvals'>('lottery');
  const [brief, setBrief] = useState('');

  useEffect(() => { refreshData(); }, []);

  const refreshData = async () => {
    setMrs(storageService.getMRs()); setHospitals(storageService.getHospitals());
    setApps(storageService.getApplications()); setPasses(storageService.getPasses());
    setApprovals(storageService.getApprovals());
    setBrief(await getAdminBriefing(storageService.getApplications(), storageService.getPasses()));
  };

  const runLottery = (session: SessionType) => {
    const today = new Date().toISOString().split('T')[0];
    const hospital = hospitals[0]; // Demo
    const sessionApps = apps.filter(a => a.hospitalId === hospital.id && a.applicationDate === today && a.session === session && a.status === 'applied');

    if (sessionApps.length === 0) { alert(`No ${session} applications for today.`); return; }

    const scored = sessionApps.map(a => ({ ...a, score: calculatePriority(a.mrId) })).sort((a,b) => b.score - a.score);
    const limit = hospital.passLimits[session] || 0;
    const selected = scored.slice(0, limit);
    const waitlisted = scored.slice(limit);

    const newPasses: IssuedPass[] = selected.map((s, i) => ({
      id: `PASS-${Math.random().toString(36).substr(2, 6).toUpperCase()}`,
      mrId: s.mrId, hospitalId: s.hospitalId, session, passDate: today,
      timeSlot: TIME_SLOTS[i % TIME_SLOTS.length], qrCode: `QR-${s.id}`, entryStatus: 'not_entered'
    }));

    const updatedApps = apps.map(original => {
      if (selected.find(x => x.id === original.id)) return { ...original, status: 'selected' as const };
      if (waitlisted.find(x => x.id === original.id)) return { ...original, status: 'waitlisted' as const };
      return original;
    });

    storageService.saveApplications(updatedApps);
    storageService.savePasses([...passes, ...newPasses]);
    refreshData();
    alert(`Lottery complete for ${session}! Issued ${selected.length} passes.`);
  };

  const calculatePriority = (mrId: string) => {
    let s = 0; const now = new Date();
    const entered = passes.filter(p => p.mrId === mrId && p.entryStatus === 'entered');
    if (entered.length > 0) {
      const last = new Date(entered[entered.length - 1].passDate);
      const diff = Math.floor((now.getTime() - last.getTime()) / (1000 * 3600 * 24));
      if (diff >= 14) s += PRIORITY_WEIGHTS.NO_PASS_14_DAYS;
      else if (diff >= 7) s += PRIORITY_WEIGHTS.NO_PASS_7_DAYS;
    } else s += PRIORITY_WEIGHTS.NO_PASS_14_DAYS;
    return s;
  };

  const updateApproval = (id: string, status: 'approved' | 'rejected') => {
    const updated = approvals.map(a => a.id === id ? { ...a, status, updatedAt: new Date().toISOString() } : a);
    storageService.saveApprovals(updated); refreshData();
  };

  return (
    <div className="space-y-6">
      <div className="bg-indigo-600 rounded-2xl p-6 text-white shadow-lg flex items-center gap-4">
        <Sparkles className="h-6 w-6 text-indigo-200" />
        <p className="text-sm font-medium">{brief || "Scanning daily activity..."}</p>
      </div>

      <div className="flex bg-white p-1 rounded-xl border w-fit gap-1">
        <button onClick={() => setActiveTab('lottery')} className={`px-6 py-2 rounded-lg text-sm font-bold flex items-center gap-2 ${activeTab === 'lottery' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><Play className="h-4 w-4" /> Lottery</button>
        <button onClick={() => setActiveTab('approvals')} className={`px-6 py-2 rounded-lg text-sm font-bold flex items-center gap-2 ${activeTab === 'approvals' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><UserPlus className="h-4 w-4" /> Approvals</button>
      </div>

      {activeTab === 'lottery' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 space-y-6 bg-white p-6 rounded-2xl border">
            <div className="flex justify-between items-center mb-4">
              <h3 className="text-lg font-bold">Today's Pool</h3>
              <div className="flex gap-2">
                <button onClick={() => runLottery('MORNING')} className="text-xs font-bold bg-indigo-50 text-indigo-600 px-3 py-1.5 rounded-lg hover:bg-indigo-100 border border-indigo-200">Run Morning</button>
                <button onClick={() => runLottery('EVENING')} className="text-xs font-bold bg-indigo-50 text-indigo-600 px-3 py-1.5 rounded-lg hover:bg-indigo-100 border border-indigo-200">Run Evening</button>
              </div>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-left text-xs">
                <thead><tr className="bg-slate-50 text-slate-500 uppercase"><th className="px-4 py-2">MR</th><th className="px-4 py-2">Session</th><th className="px-4 py-2">Status</th></tr></thead>
                <tbody className="divide-y divide-slate-100">
                  {apps.filter(a => a.applicationDate === new Date().toISOString().split('T')[0]).map(app => (
                    <tr key={app.id}><td className="px-4 py-3 font-bold">{mrs.find(m => m.id === app.mrId)?.fullName}</td><td className="px-4 py-3">{app.session}</td><td className="px-4 py-3 uppercase font-black text-[9px]">{app.status}</td></tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
          <div className="bg-white p-6 rounded-2xl border h-fit">
            <h4 className="font-bold mb-4">Live Counters</h4>
            <div className="p-4 bg-green-50 rounded-xl mb-3"><p className="text-[10px] font-bold text-green-600 uppercase">Today's Passes</p><p className="text-2xl font-black">{passes.filter(p => p.passDate === new Date().toISOString().split('T')[0]).length}</p></div>
            <div className="p-4 bg-slate-50 rounded-xl"><p className="text-[10px] font-bold text-slate-400 uppercase">Pending Pool</p><p className="text-2xl font-black">{apps.filter(a => a.status === 'applied').length}</p></div>
          </div>
        </div>
      )}

      {activeTab === 'approvals' && (
        <section className="bg-white p-6 rounded-2xl border">
          <h3 className="text-lg font-bold mb-6">Pending MR Access Requests</h3>
          <div className="space-y-4">
            {approvals.filter(a => a.status === 'pending').map(req => (
              <div key={req.id} className="flex justify-between items-center p-4 bg-slate-50 rounded-xl">
                <div><p className="font-bold text-sm">{mrs.find(m => m.id === req.mrId)?.fullName}</p><p className="text-xs text-slate-500">{mrs.find(m => m.id === req.mrId)?.companyName}</p></div>
                <div className="flex gap-2">
                  <button onClick={() => updateApproval(req.id, 'approved')} className="bg-green-600 text-white text-xs px-4 py-1.5 rounded font-bold">Approve</button>
                  <button onClick={() => updateApproval(req.id, 'rejected')} className="bg-red-50 text-red-600 text-xs px-4 py-1.5 rounded font-bold">Reject</button>
                </div>
              </div>
            ))}
            {approvals.filter(a => a.status === 'pending').length === 0 && <p className="text-center py-10 text-slate-400 italic text-sm">No pending requests.</p>}
          </div>
        </section>
      )}
    </div>
  );
};

