import React, { useState, useEffect } from 'react';
import { storageService } from './services/storageService';
import Layout from './components/Layout';
import MRDashboard from './components/MRDashboard';
import AdminDashboard from './components/AdminDashboard';
import SuperAdminDashboard from './components/SuperAdminDashboard';
import SecurityView from './components/SecurityView';
import { Shield, User, Key, ArrowRight, Hospital as HospitalIcon, Info, Laptop, ShieldCheck, Crown } from 'lucide-react';
import { MedicalRep, UserRole } from './types';

const App: React.FC = () => {
  const [user, setUser] = useState<any>(null);
  const [view, setView] = useState<'LOGIN' | 'REGISTER' | 'DASHBOARD'>('LOGIN');
  const [role, setRole] = useState<UserRole>('MR');
  const [mobile, setMobile] = useState('');

  useEffect(() => {
    const session = storageService.getCurrentUser();
    if (session) { setUser(session); setView('DASHBOARD'); }
  }, []);

  const handleLogin = (e?: React.FormEvent) => {
    e?.preventDefault();
    if (role === 'MR') {
      const mrs = storageService.getMRs();
      const existing = mrs.find(m => m.mobileNumber === mobile);
      if (existing) {
        const u = { ...existing, role: 'MR' };
        storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
      } else alert("Mobile not found.");
    } else {
      const mockUser = { role, fullName: role === 'SUPER_ADMIN' ? 'Software Owner' : role === 'ADMIN' ? 'Hospital Admin' : 'Gate Security' };
      storageService.setCurrentUser(mockUser); setUser(mockUser); setView('DASHBOARD');
    }
  };

  const quickLogin = (r: UserRole, phone = '') => { setRole(r); setMobile(phone); setTimeout(() => handleLogin(), 100); };

  if (view === 'LOGIN') {
    return (
      <div className="min-h-screen bg-indigo-600 flex items-center justify-center p-4">
        <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden">
          <div className="bg-slate-50 p-8 text-center border-b border-slate-100">
            <div className="bg-indigo-600 w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-4"><HospitalIcon className="h-10 w-10 text-white" /></div>
            <h1 className="text-2xl font-black text-slate-800 tracking-tighter">MedPass Engine</h1>
          </div>
          <div className="p-8">
            <div className="mb-6 bg-indigo-50 rounded-xl p-4">
              <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-2">System Demo Credentials</p>
              <div className="grid grid-cols-2 gap-2">
                <button onClick={() => quickLogin('MR', '0771234567')} className="p-2 bg-white border border-indigo-100 rounded text-[10px] font-bold text-slate-700 flex items-center gap-1"><User className="h-3 w-3" /> MR (Pfizer)</button>
                <button onClick={() => quickLogin('SUPER_ADMIN')} className="p-2 bg-indigo-100 rounded text-[10px] font-bold text-indigo-700 flex items-center gap-1"><Crown className="h-3 w-3" /> Super Admin</button>
                <button onClick={() => quickLogin('ADMIN')} className="p-2 bg-white border border-indigo-100 rounded text-[10px] font-bold text-slate-700 flex items-center gap-1"><Laptop className="h-3 w-3" /> Hosp Admin</button>
                <button onClick={() => quickLogin('SECURITY')} className="p-2 bg-white border border-indigo-100 rounded text-[10px] font-bold text-slate-700 flex items-center gap-1"><ShieldCheck className="h-3 w-3" /> Security</button>
              </div>
            </div>
            <div className="flex bg-slate-100 p-1 rounded-xl mb-6">
              {(['MR', 'ADMIN', 'SECURITY', 'SUPER_ADMIN'] as const).map(r => (
                <button key={r} onClick={() => setRole(r)} className={`flex-1 py-1.5 text-[10px] font-black rounded-lg ${role === r ? 'bg-white text-indigo-600 shadow' : 'text-slate-400'}`}>{r}</button>
              ))}
            </div>
            <form onSubmit={handleLogin} className="space-y-4">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Login ID / Mobile</label>
                <input disabled={role !== 'MR'} type="tel" value={mobile} onChange={e => setMobile(e.target.value)} className="w-full px-4 py-3 bg-slate-50 border rounded-xl outline-none focus:ring-2 focus:ring-indigo-500" />
              </div>
              <button className="w-full bg-indigo-600 text-white font-black py-4 rounded-xl shadow-lg hover:bg-indigo-700 active:scale-95 transition-all flex items-center justify-center gap-2">Enter System <ArrowRight className="h-5 w-5" /></button>
            </form>
          </div>
        </div>
      </div>
    );
  }

  return (
    <Layout user={user} onLogout={() => { storageService.clearSession(); setUser(null); setView('LOGIN'); }} title={user.role === 'SUPER_ADMIN' ? 'Root Authority' : user.role === 'MR' ? 'MR Dashboard' : 'Control Panel'}>
      {user.role === 'MR' && <MRDashboard user={user} />}
      {user.role === 'ADMIN' && <AdminDashboard />}
      {user.role === 'SUPER_ADMIN' && <SuperAdminDashboard />}
      {user.role === 'SECURITY' && <SecurityView />}
    </Layout>
  );
};

