  };

  const handleSaveHospital = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingHospital?.name) return;

    const currentHospitals = storageService.getHospitals();
    let updated: Hospital[];

    if (editingHospital.id) {
      updated = currentHospitals.map(h => h.id === editingHospital.id ? (editingHospital as Hospital) : h);
    } else {
      const newH: Hospital = {
        ...(editingHospital as Hospital),
        id: 'h' + Date.now(),
        isActive: true,
        supportedSessions: editingHospital.supportedSessions || ['MORNING'],
        passLimits: editingHospital.passLimits || { 'MORNING': 10 },
        bookingWindowStart: editingHospital.bookingWindowStart || '09:00',
        bookingWindowEnd: editingHospital.bookingWindowEnd || '10:00',
      };
      updated = [...currentHospitals, newH];
    }

    storageService.saveHospitals(updated);
    setHospitals(updated);
    setIsHospitalModalOpen(false);
    setEditingHospital(null);
  };

  const toggleHospitalStatus = (id: string) => {
    const updated = hospitals.map(h => h.id === id ? { ...h, isActive: !h.isActive } : h);
    storageService.saveHospitals(updated);
    setHospitals(updated);
  };

  const handleSaveCompany = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingCompany?.name) return;

    const currentCompanies = storageService.getCompanies();
    let updated: PharmaCompany[];

    if (editingCompany.id) {
      updated = currentCompanies.map(c => c.id === editingCompany.id ? (editingCompany as PharmaCompany) : c);
    } else {
      const newC: PharmaCompany = {
        ...(editingCompany as PharmaCompany),
        id: 'c' + Date.now(),
      };
      updated = [...currentCompanies, newC];
    }

    storageService.saveCompanies(updated);
    setCompanies(updated);
    setIsCompanyModalOpen(false);
    setEditingCompany(null);
  };

  const calculateBilling = () => {
    const today = new Date().toISOString().split('T')[0];
    const newInvoices: Invoice[] = companies.map(company => {
      const activeMRs = mrs.filter(m => m.companyName === company.name && m.status === 'active').length;
      return {
        id: 'INV-' + Math.random().toString(36).substr(2, 6).toUpperCase(),
        companyId: company.id,
        amount: activeMRs * 250,
        activeMRCount: activeMRs,
        status: 'unpaid',
        date: today
      };
    });
    const updatedInvoices = [...invoices, ...newInvoices];
    storageService.saveInvoices(updatedInvoices);
    setInvoices(updatedInvoices);
    alert("Quotations generated for all companies.");
  };

  return (
    <div className="space-y-6">
      <div className="flex bg-white p-1 rounded-xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => {setActiveTab('hospitals'); setSelectedCompanyId(null);}} className={`px-4 md:px-6 py-2 rounded-lg text-sm font-bold flex items-center gap-2 whitespace-nowrap ${activeTab === 'hospitals' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Building2 className="h-4 w-4" /> Hospitals</button>
        <button onClick={() => setActiveTab('companies')} className={`px-4 md:px-6 py-2 rounded-lg text-sm font-bold flex items-center gap-2 whitespace-nowrap ${activeTab === 'companies' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Briefcase className="h-4 w-4" /> Companies</button>
        <button onClick={() => setActiveTab('billing')} className={`px-4 md:px-6 py-2 rounded-lg text-sm font-bold flex items-center gap-2 whitespace-nowrap ${activeTab === 'billing' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><DollarSign className="h-4 w-4" /> Billing</button>
        <button onClick={() => setActiveTab('monitoring')} className={`px-4 md:px-6 py-2 rounded-lg text-sm font-bold flex items-center gap-2 whitespace-nowrap ${activeTab === 'monitoring' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Activity className="h-4 w-4" /> Monitoring</button>
      </div>

      {activeTab === 'hospitals' && (
        <section className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
          <div className="flex justify-between items-center mb-6">
            <div>
              <h3 className="text-lg font-bold">Hospital Network Control</h3>
              <p className="text-sm text-slate-500">Configure hospital sessions, limits and access windows.</p>
            </div>
            <button 
              onClick={() => { setEditingHospital({ supportedSessions: ['MORNING'], passLimits: { 'MORNING': 10 }, bookingWindowStart: '00:00', bookingWindowEnd: '23:59' }); setIsHospitalModalOpen(true); }}
              className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-sm font-bold flex items-center gap-2 hover:bg-indigo-700 transition-all shadow-md active:scale-95"
            >
              <Plus className="h-4 w-4" /> Add Hospital
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {hospitals.map(h => (
              <div key={h.id} className="group p-5 border border-slate-100 bg-slate-50 rounded-2xl hover:shadow-lg transition-all relative overflow-hidden">
                <div className={`absolute top-0 right-0 w-1 h-full ${h.isActive ? 'bg-green-500' : 'bg-red-500'}`}></div>
                <div className="flex justify-between items-start mb-4">
                  <div>
                    <h4 className="font-bold text-slate-800 text-lg">{h.name}</h4>
                    <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${h.isActive ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                      {h.isActive ? 'ACTIVE' : 'INACTIVE'}
                    </span>
                  </div>
                  <button 
                    onClick={() => { setEditingHospital(h); setIsHospitalModalOpen(true); }}
                    className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all"
                  >
                    <Edit3 className="h-4 w-4" />
                  </button>
                </div>

                <div className="space-y-3">
                  <div className="flex items-center justify-between text-xs text-slate-500">
                    <span className="flex items-center gap-1"><Settings className="h-3 w-3" /> Sessions:</span>
                    <span className="font-bold text-slate-700">{h.supportedSessions.join(', ')}</span>
                  </div>
                  <div className="flex items-center justify-between text-xs text-slate-500">
                    <span className="flex items-center gap-1"><Users className="h-3 w-3" /> Daily Limit:</span>
                    <span className="font-bold text-slate-700">{Object.values(h.passLimits).reduce((a, b) => a + b, 0)} Passes</span>
                  </div>
                  <div className="flex items-center justify-between text-xs text-slate-500">
                    <span className="flex items-center gap-1"><FileText className="h-3 w-3" /> Window:</span>
                    <span className="font-bold text-slate-700">{h.bookingWindowStart} - {h.bookingWindowEnd}</span>
                  </div>
                </div>

                <div className="mt-6 flex gap-2">
                  <button 
                    onClick={() => toggleHospitalStatus(h.id)}
                    className={`flex-1 py-2 rounded-xl text-xs font-bold transition-all border ${h.isActive ? 'border-red-200 text-red-600 hover:bg-red-50' : 'border-green-200 text-green-600 hover:bg-green-50'}`}
                  >
                    {h.isActive ? 'Suspend' : 'Activate'}
                  </button>
                </div>
              </div>
            ))}
          </div>
        </section>
      )}

      {activeTab === 'companies' && (
        <section className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
          <div className="flex justify-between items-center mb-6">
            <div>
              <h3 className="text-lg font-bold">Pharma Companies</h3>
              <p className="text-sm text-slate-500">Manage registered pharmaceutical companies and their representatives.</p>
            </div>
            <button 
              onClick={() => { setEditingCompany({}); setIsCompanyModalOpen(true); }}
              className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-sm font-bold flex items-center gap-2 hover:bg-indigo-700 transition-all shadow-md active:scale-95"
            >
              <Plus className="h-4 w-4" /> Add Company
            </button>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-1 space-y-4">
              {companies.map(c => {
                const companyMRCount = mrs.filter(m => m.companyName === c.name).length;
                return (
                  <button 
                    key={c.id}
                    onClick={() => setSelectedCompanyId(c.id)}
                    className={`w-full text-left p-4 rounded-xl border transition-all ${selectedCompanyId === c.id ? 'border-indigo-600 bg-indigo-50 shadow-sm' : 'border-slate-100 bg-slate-50 hover:bg-slate-100'}`}
                  >
                    <div className="flex justify-between items-start">
                      <h4 className="font-bold text-slate-800">{c.name}</h4>
                      <ChevronRight className={`h-4 w-4 transition-transform ${selectedCompanyId === c.id ? 'rotate-90 text-indigo-600' : 'text-slate-400'}`} />
                    </div>
                    <div className="flex items-center justify-between mt-2">
                      <p className="text-xs text-slate-500">{c.contactEmail}</p>
                      <span className="bg-white px-2 py-0.5 rounded text-[10px] font-bold text-slate-600 shadow-xs">{companyMRCount} MRs</span>
                    </div>
                  </button>
                );
              })}
            </div>

            <div className="lg:col-span-2">
              {selectedCompanyId ? (
                <div className="bg-slate-50 rounded-2xl border border-slate-100 overflow-hidden animate-in fade-in slide-in-from-right duration-300">
                  <div className="bg-white p-4 border-b border-slate-100 flex justify-between items-center">
                    <h4 className="font-bold text-slate-800">
                      MR List: {companies.find(c => c.id === selectedCompanyId)?.name}
                    </h4>
                    <button 
                      onClick={() => { setEditingCompany(companies.find(c => c.id === selectedCompanyId)); setIsCompanyModalOpen(true); }}
                      className="text-xs font-bold text-indigo-600 hover:underline flex items-center gap-1"
                    >
                      <Edit3 className="h-3 w-3" /> Edit Company
                    </button>
                  </div>
                  <div className="p-4 overflow-x-auto">
                    <table className="w-full text-left text-xs">
                      <thead className="text-slate-500 uppercase font-black text-[9px] tracking-widest">
                        <tr>
                          <th className="px-4 py-2">Name</th>
                          <th className="px-4 py-2">MR ID</th>
                          <th className="px-4 py-2">Mobile</th>
                          <th className="px-4 py-2">Status</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-200">
                        {mrs.filter(m => m.companyName === companies.find(c => c.id === selectedCompanyId)?.name).map(mr => (
                          <tr key={mr.id} className="hover:bg-white transition-colors">
                            <td className="px-4 py-3 font-bold text-slate-800">{mr.fullName}</td>
                            <td className="px-4 py-3 text-slate-600 font-mono">{mr.mrId}</td>
                            <td className="px-4 py-3 text-slate-600">{mr.mobileNumber}</td>
                            <td className="px-4 py-3">
                              <span className={`px-2 py-0.5 rounded-full text-[9px] font-bold ${mr.status === 'active' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                                {mr.status.toUpperCase()}
                              </span>
                            </td>
                          </tr>
                        ))}
                        {mrs.filter(m => m.companyName === companies.find(c => c.id === selectedCompanyId)?.name).length === 0 && (
                          <tr>
                            <td colSpan={4} className="px-4 py-8 text-center text-slate-400 italic">No representatives registered for this company.</td>
                          </tr>
                        )}
                      </tbody>
                    </table>
                  </div>
                </div>
              ) : (
                <div className="h-full flex flex-col items-center justify-center p-12 bg-slate-50 rounded-2xl border border-dashed border-slate-200 text-slate-400">
                  <Briefcase className="h-12 w-12 mb-4 opacity-20" />
                  <p className="text-sm">Select a company to view its representatives and details.</p>
                </div>
              )}
            </div>
          </div>
        </section>
      )}

      {/* Hospital Config Modal */}
      {isHospitalModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-lg rounded-3xl shadow-2xl overflow-hidden animate-in slide-in-from-bottom-4 duration-300">
            <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-bold text-slate-800">{editingHospital?.id ? 'Edit Hospital' : 'Add New Hospital'}</h3>
              <button onClick={() => setIsHospitalModalOpen(false)} className="p-2 hover:bg-slate-200 rounded-full transition-all"><X className="h-5 w-5 text-slate-400" /></button>
            </div>
            <form onSubmit={handleSaveHospital} className="p-6 space-y-6">
              <div className="space-y-4">
                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Hospital Name</label>
                  <input 
                    required 
                    type="text" 
                    value={editingHospital?.name || ''} 
                    onChange={e => setEditingHospital({...editingHospital, name: e.target.value})} 
                    placeholder="e.g. Apollo Hospital" 
                    className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                  />
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Window Start</label>
                    <input 
                      type="time" 
                      value={editingHospital?.bookingWindowStart || '00:00'} 
                      onChange={e => setEditingHospital({...editingHospital, bookingWindowStart: e.target.value})} 
                      className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none"
                    />
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Window End</label>
                    <input 
                      type="time" 
                      value={editingHospital?.bookingWindowEnd || '23:59'} 
                      onChange={e => setEditingHospital({...editingHospital, bookingWindowEnd: e.target.value})} 
                      className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none"
                    />
                  </div>
                </div>

                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Supported Sessions & Limits</label>
                  <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                    {(['MORNING', 'EVENING', 'FULL_DAY'] as SessionType[]).map(s => {
                      const isSelected = editingHospital?.supportedSessions?.includes(s);
                      return (
                        <div key={s} className={`p-3 border rounded-xl transition-all ${isSelected ? 'border-indigo-200 bg-indigo-50' : 'border-slate-100 bg-slate-50 opacity-60'}`}>
                          <div className="flex items-center gap-2 mb-2">
                            <input 
                              type="checkbox" 
                              checked={isSelected} 
                              onChange={e => {
                                const sessions = editingHospital?.supportedSessions || [];
                                const newSessions = e.target.checked ? [...sessions, s] : sessions.filter(x => x !== s);
                                setEditingHospital({...editingHospital, supportedSessions: newSessions});
                              }}
                              className="w-4 h-4 rounded text-indigo-600 focus:ring-indigo-500"
                            />
                            <span className="text-[10px] font-bold text-slate-700">{s}</span>
                          </div>
                          <input 
                            type="number" 
                            disabled={!isSelected}
                            value={editingHospital?.passLimits?.[s] || 0}
                            onChange={e => {
                              const limits = editingHospital?.passLimits || {};
                              setEditingHospital({...editingHospital, passLimits: {...limits, [s]: parseInt(e.target.value) || 0}});
                            }}
                            className="w-full px-2 py-1 bg-white border border-slate-200 rounded text-xs outline-none disabled:opacity-50"
                          />
                        </div>
                      );
                    })}
                  </div>
                </div>
              </div>

              <div className="flex gap-3 pt-4">
                <button type="button" onClick={() => setIsHospitalModalOpen(false)} className="flex-1 px-6 py-3 border border-slate-200 text-slate-600 font-bold rounded-xl hover:bg-slate-50 transition-all">Cancel</button>
                <button type="submit" className="flex-1 bg-indigo-600 text-white font-bold py-3 rounded-xl shadow-lg hover:bg-indigo-700 transition-all active:scale-95">Save Changes</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Company Modal */}
      {isCompanyModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden animate-in slide-in-from-bottom-4 duration-300">
            <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-bold text-slate-800">{editingCompany?.id ? 'Edit Company' : 'Register Company'}</h3>
              <button onClick={() => setIsCompanyModalOpen(false)} className="p-2 hover:bg-slate-200 rounded-full transition-all"><X className="h-5 w-5 text-slate-400" /></button>
            </div>
            <form onSubmit={handleSaveCompany} className="p-6 space-y-4">
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Company Name</label>
                <input 
                  required 
                  type="text" 
                  value={editingCompany?.name || ''} 
                  onChange={e => setEditingCompany({...editingCompany, name: e.target.value})} 
                  placeholder="e.g. Pfizer Lanka" 
                  className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                />
              </div>
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Contact Email</label>
                <input 
                  required 
                  type="email" 
                  value={editingCompany?.contactEmail || ''} 
                  onChange={e => setEditingCompany({...editingCompany, contactEmail: e.target.value})} 
                  placeholder="finance@pfizer.lk" 
                  className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                />
              </div>
              <div className="flex gap-3 pt-4">
                <button type="button" onClick={() => setIsCompanyModalOpen(false)} className="flex-1 px-6 py-3 border border-slate-200 text-slate-600 font-bold rounded-xl hover:bg-slate-50 transition-all">Cancel</button>
                <button type="submit" className="flex-1 bg-indigo-600 text-white font-bold py-3 rounded-xl shadow-lg hover:bg-indigo-700 transition-all active:scale-95">Save Company</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {activeTab === 'billing' && (
        <section className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
          <div className="flex justify-between items-center mb-6">
            <div>
              <h3 className="text-lg font-bold">Billing & Quotations</h3>
              <p className="text-sm text-slate-500">Calculate charges based on active MR count (LKR 250 per MR).</p>
            </div>
            <button onClick={calculateBilling} className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-sm font-bold flex items-center gap-2 hover:bg-indigo-700 transition-all shadow-md"><FileText className="h-4 w-4" /> Generate Quotes</button>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
              <thead className="bg-slate-50 text-slate-500 uppercase text-[10px] tracking-widest font-black">
                <tr>
                  <th className="px-4 py-3">Company</th>
                  <th className="px-4 py-3">Active MRs</th>
                  <th className="px-4 py-3">Quote (LKR)</th>
                  <th className="px-4 py-3">Status</th>
                  <th className="px-4 py-3">Issued Date</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {invoices.sort((a,b) => b.date.localeCompare(a.date)).map(inv => (
                  <tr key={inv.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-4 py-3 font-bold text-slate-800">{companies.find(c => c.id === inv.companyId)?.name}</td>
                    <td className="px-4 py-3">{inv.activeMRCount}</td>
                    <td className="px-4 py-3 font-black text-indigo-700">LKR {inv.amount.toLocaleString()}</td>
                    <td className="px-4 py-3">
                      <span className={`px-2 py-1 rounded-full text-[9px] font-bold ${inv.status === 'paid' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>{inv.status.toUpperCase()}</span>
                    </td>
                    <td className="px-4 py-3 text-slate-500 font-mono text-xs">{inv.date}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </section>
      )}

      {activeTab === 'monitoring' && (
        <section className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm text-center">
            <Activity className="h-8 w-8 text-indigo-500 mx-auto mb-3" />
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Active MRs</p>
            <p className="text-3xl font-black text-slate-800 mt-1">{mrs.filter(m => m.status === 'active').length}</p>
          </div>
          <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm text-center">
            <Building2 className="h-8 w-8 text-green-500 mx-auto mb-3" />
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Hospitals</p>
            <p className="text-3xl font-black text-slate-800 mt-1">{hospitals.filter(h => h.isActive).length}</p>
          </div>
          <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm text-center">
            <Check className="h-8 w-8 text-blue-500 mx-auto mb-3" />
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Applications Today</p>
            <p className="text-3xl font-black text-slate-800 mt-1">{storageService.getApplications().filter(a => a.applicationDate === new Date().toISOString().split('T')[0]).length}</p>
          </div>
          <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm text-center">
            <DollarSign className="h-8 w-8 text-amber-500 mx-auto mb-3" />
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Total Revenue Pot.</p>
            <p className="text-3xl font-black text-slate-800 mt-1">LKR {(mrs.filter(m => m.status === 'active').length * 250).toLocaleString()}</p>
          </div>
        </section>
      )}
    </div>
  );
};

export default SuperAdminDashboard;

export type MRStatus = 'active' | 'suspended';
export type ApplicationStatus = 'applied' | 'selected' | 'waitlisted' | 'rejected';
export type EntryStatus = 'not_entered' | 'entered' | 'expired';
export type UserRole = 'MR' | 'ADMIN' | 'SECURITY' | 'SUPER_ADMIN';
export type ApprovalStatus = 'pending' | 'approved' | 'rejected';
export type SessionType = 'MORNING' | 'EVENING' | 'FULL_DAY';

export interface MedicalRep {
  id: string;
  fullName: string;
  companyName: string; // Used for PharmaCompany linking
  mrId: string;
  mobileNumber: string;
  status: MRStatus;
  createdAt: string;
}

export interface Hospital {
  id: string;
  name: string;
  supportedSessions: SessionType[];
  passLimits: Record<string, number>; // e.g., { 'MORNING': 15, 'EVENING': 10 }
  bookingWindowStart: string;
  bookingWindowEnd: string;
  isActive: boolean;
}

export interface MRHospitalApproval {
  id: string;
  mrId: string;
  hospitalId: string;
  status: ApprovalStatus;
  updatedAt: string;
}

export interface PassApplication {
  id: string;
  mrId: string;
  hospitalId: string;
  session: SessionType;
  applicationDate: string;
  priorityScore: number;
  status: ApplicationStatus;
  createdAt: string;
}

export interface IssuedPass {
  id: string;
  mrId: string;
  hospitalId: string;
  session: SessionType;
  passDate: string;
  timeSlot: string;
  qrCode: string;
  entryStatus: EntryStatus;
}

export interface PharmaCompany {
  id: string;
  name: string;
  contactEmail: string;
}

export interface Invoice {
  id: string;
  companyId: string;
  amount: number;
  activeMRCount: number;
  status: 'paid' | 'unpaid';
  date: string;
}

export interface EntryLog {
  id: string;
  issuedPassId: string;
  entryTime: string;
  verifiedBy: string;
}

import React, { useState, useEffect } from 'react';
import { Building2, Users, FileText, Settings, Plus, DollarSign, Power, Activity, Edit3, Trash2, Check, X, ChevronRight, Briefcase } from 'lucide-react';
import { storageService } from '../services/storageService';
import { Hospital, PharmaCompany, Invoice, MedicalRep, SessionType } from '../types';

const SuperAdminDashboard: React.FC = () => {
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [companies, setCompanies] = useState<PharmaCompany[]>([]);
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [activeTab, setActiveTab] = useState<'hospitals' | 'companies' | 'billing' | 'monitoring'>('hospitals');

  // Hospital Config State
  const [isHospitalModalOpen, setIsHospitalModalOpen] = useState(false);
  const [editingHospital, setEditingHospital] = useState<Partial<Hospital> | null>(null);

  // Company State
  const [isCompanyModalOpen, setIsCompanyModalOpen] = useState(false);
  const [editingCompany, setEditingCompany] = useState<Partial<PharmaCompany> | null>(null);
  const [selectedCompanyId, setSelectedCompanyId] = useState<string | null>(null);

  useEffect(() => {
    refreshData();
  }, []);

  const refreshData = () => {
    setHospitals(storageService.getHospitals());
    setCompanies(storageService.getCompanies());
    setInvoices(storageService.getInvoices());
    setMrs(storageService.getMRs());
  };

  const handleSaveHospital = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingHospital?.name) return;

    const currentHospitals = storageService.getHospitals();
    let updated: Hospital[];

    if (editingHospital.id) {
      updated = currentHospitals.map(h => h.id === editingHospital.id ? (editingHospital as Hospital) : h);
    } else {
      const newH: Hospital = {
        ...(editingHospital as Hospital),
        id: 'h' + Date.now(),
        isActive: true,
        supportedSessions: editingHospital.supportedSessions || ['MORNING'],
        passLimits: editingHospital.passLimits || { 'MORNING': 10 },
        bookingWindowStart: editingHospital.bookingWindowStart || '09:00',
        bookingWindowEnd: editingHospital.bookingWindowEnd || '10:00',
      };
      updated = [...currentHospitals, newH];
    }

    storageService.saveHospitals(updated);
    setHospitals(updated);
    setIsHospitalModalOpen(false);
    setEditingHospital(null);
  };

  const toggleHospitalStatus = (id: string) => {
    const updated = hospitals.map(h => h.id === id ? { ...h, isActive: !h.isActive } : h);
    storageService.saveHospitals(updated);
    setHospitals(updated);
  };

  const handleSaveCompany = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingCompany?.name) return;

    const currentCompanies = storageService.getCompanies();
    let updated: PharmaCompany[];

    if (editingCompany.id) {
      updated = currentCompanies.map(c => c.id === editingCompany.id ? (editingCompany as PharmaCompany) : c);
    } else {
      const newC: PharmaCompany = {
        ...(editingCompany as PharmaCompany),
        id: 'c' + Date.now(),
      };
      updated = [...currentCompanies, newC];
    }

    storageService.saveCompanies(updated);
    setCompanies(updated);
    setIsCompanyModalOpen(false);
    setEditingCompany(null);
  };

  const calculateBilling = () => {
    const today = new Date().toISOString().split('T')[0];
    const newInvoices: Invoice[] = companies.map(company => {
      const activeMRs = mrs.filter(m => m.companyName === company.name && m.status === 'active').length;
      return {
        id: 'INV-' + Math.random().toString(36).substr(2, 6).toUpperCase(),
        companyId: company.id,
        amount: activeMRs * 250,
        activeMRCount: activeMRs,
        status: 'unpaid',
        date: today
      };
    });
    const updatedInvoices = [...invoices, ...newInvoices];
    storageService.saveInvoices(updatedInvoices);
    setInvoices(updatedInvoices);
    alert("Quotations generated for all companies.");
  };

  return (
    <div className="space-y-6">
      <div className="flex bg-white p-1 rounded-xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => {setActiveTab('hospitals'); setSelectedCompanyId(null);}} className={`px-4 md:px-6 py-2 rounded-lg text-sm font-bold flex items-center gap-2 whitespace-nowrap ${activeTab === 'hospitals' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Building2 className="h-4 w-4" /> Hospitals</button>
        <button onClick={() => setActiveTab('companies')} className={`px-4 md:px-6 py-2 rounded-lg text-sm font-bold flex items-center gap-2 whitespace-nowrap ${activeTab === 'companies' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Briefcase className="h-4 w-4" /> Companies</button>
        <button onClick={() => setActiveTab('billing')} className={`px-4 md:px-6 py-2 rounded-lg text-sm font-bold flex items-center gap-2 whitespace-nowrap ${activeTab === 'billing' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><DollarSign className="h-4 w-4" /> Billing</button>
        <button onClick={() => setActiveTab('monitoring')} className={`px-4 md:px-6 py-2 rounded-lg text-sm font-bold flex items-center gap-2 whitespace-nowrap ${activeTab === 'monitoring' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Activity className="h-4 w-4" /> Monitoring</button>
      </div>

      {activeTab === 'hospitals' && (
        <section className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
          <div className="flex justify-between items-center mb-6">
            <div>
              <h3 className="text-lg font-bold">Hospital Network Control</h3>
              <p className="text-sm text-slate-500">Configure hospital sessions, limits and access windows.</p>
            </div>
            <button 
              onClick={() => { setEditingHospital({ supportedSessions: ['MORNING'], passLimits: { 'MORNING': 10 }, bookingWindowStart: '00:00', bookingWindowEnd: '23:59' }); setIsHospitalModalOpen(true); }}
              className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-sm font-bold flex items-center gap-2 hover:bg-indigo-700 transition-all shadow-md active:scale-95"
            >
              <Plus className="h-4 w-4" /> Add Hospital
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {hospitals.map(h => (
              <div key={h.id} className="group p-5 border border-slate-100 bg-slate-50 rounded-2xl hover:shadow-lg transition-all relative overflow-hidden">
                <div className={`absolute top-0 right-0 w-1 h-full ${h.isActive ? 'bg-green-500' : 'bg-red-500'}`}></div>
                <div className="flex justify-between items-start mb-4">
                  <div>
                    <h4 className="font-bold text-slate-800 text-lg">{h.name}</h4>
                    <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${h.isActive ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                      {h.isActive ? 'ACTIVE' : 'INACTIVE'}
                    </span>
                  </div>
                  <button 
                    onClick={() => { setEditingHospital(h); setIsHospitalModalOpen(true); }}
                    className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all"
                  >
                    <Edit3 className="h-4 w-4" />
                  </button>
                </div>

                <div className="space-y-3">
                  <div className="flex items-center justify-between text-xs text-slate-500">
                    <span className="flex items-center gap-1"><Settings className="h-3 w-3" /> Sessions:</span>
                    <span className="font-bold text-slate-700">{h.supportedSessions.join(', ')}</span>
                  </div>
                  <div className="flex items-center justify-between text-xs text-slate-500">
                    <span className="flex items-center gap-1"><Users className="h-3 w-3" /> Daily Limit:</span>
                    {/* Fix: Explicitly typed reduce parameters to fix unknown type operator error */}
                    <span className="font-bold text-slate-700">{Object.values(h.passLimits).reduce((a: number, b: number) => a + b, 0)} Passes</span>
                  </div>
                  <div className="flex items-center justify-between text-xs text-slate-500">
                    <span className="flex items-center gap-1"><FileText className="h-3 w-3" /> Window:</span>
                    <span className="font-bold text-slate-700">{h.bookingWindowStart} - {h.bookingWindowEnd}</span>
                  </div>
                </div>

                <div className="mt-6 flex gap-2">
                  <button 
                    onClick={() => toggleHospitalStatus(h.id)}
                    className={`flex-1 py-2 rounded-xl text-xs font-bold transition-all border ${h.isActive ? 'border-red-200 text-red-600 hover:bg-red-50' : 'border-green-200 text-green-600 hover:bg-green-50'}`}
                  >
                    {h.isActive ? 'Suspend' : 'Activate'}
                  </button>
                </div>
              </div>
            ))}
          </div>
        </section>
      )}

      {activeTab === 'companies' && (
        <section className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
          <div className="flex justify-between items-center mb-6">
            <div>
              <h3 className="text-lg font-bold">Pharma Companies</h3>
              <p className="text-sm text-slate-500">Manage registered pharmaceutical companies and their representatives.</p>
            </div>
            <button 
              onClick={() => { setEditingCompany({}); setIsCompanyModalOpen(true); }}
              className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-sm font-bold flex items-center gap-2 hover:bg-indigo-700 transition-all shadow-md active:scale-95"
            >
              <Plus className="h-4 w-4" /> Add Company
            </button>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-1 space-y-4">
              {companies.map(c => {
                const companyMRCount = mrs.filter(m => m.companyName === c.name).length;
                return (
                  <button 
                    key={c.id}
                    onClick={() => setSelectedCompanyId(c.id)}
                    className={`w-full text-left p-4 rounded-xl border transition-all ${selectedCompanyId === c.id ? 'border-indigo-600 bg-indigo-50 shadow-sm' : 'border-slate-100 bg-slate-50 hover:bg-slate-100'}`}
                  >
                    <div className="flex justify-between items-start">
                      <h4 className="font-bold text-slate-800">{c.name}</h4>
                      <ChevronRight className={`h-4 w-4 transition-transform ${selectedCompanyId === c.id ? 'rotate-90 text-indigo-600' : 'text-slate-400'}`} />
                    </div>
                    <div className="flex items-center justify-between mt-2">
                      <p className="text-xs text-slate-500">{c.contactEmail}</p>
                      <span className="bg-white px-2 py-0.5 rounded text-[10px] font-bold text-slate-600 shadow-xs">{companyMRCount} MRs</span>
                    </div>
                  </button>
                );
              })}
            </div>

            <div className="lg:col-span-2">
              {selectedCompanyId ? (
                <div className="bg-slate-50 rounded-2xl border border-slate-100 overflow-hidden animate-in fade-in slide-in-from-right duration-300">
                  <div className="bg-white p-4 border-b border-slate-100 flex justify-between items-center">
                    <h4 className="font-bold text-slate-800">
                      MR List: {companies.find(c => c.id === selectedCompanyId)?.name}
                    </h4>
                    <button 
                      onClick={() => { setEditingCompany(companies.find(c => c.id === selectedCompanyId)); setIsCompanyModalOpen(true); }}
                      className="text-xs font-bold text-indigo-600 hover:underline flex items-center gap-1"
                    >
                      <Edit3 className="h-3 w-3" /> Edit Company
                    </button>
                  </div>
                  <div className="p-4 overflow-x-auto">
                    <table className="w-full text-left text-xs">
                      <thead className="text-slate-500 uppercase font-black text-[9px] tracking-widest">
                        <tr>
                          <th className="px-4 py-2">Name</th>
                          <th className="px-4 py-2">MR ID</th>
                          <th className="px-4 py-2">Mobile</th>
                          <th className="px-4 py-2">Status</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-200">
                        {mrs.filter(m => m.companyName === companies.find(c => c.id === selectedCompanyId)?.name).map(mr => (
                          <tr key={mr.id} className="hover:bg-white transition-colors">
                            <td className="px-4 py-3 font-bold text-slate-800">{mr.fullName}</td>
                            <td className="px-4 py-3 text-slate-600 font-mono">{mr.mrId}</td>
                            <td className="px-4 py-3 text-slate-600">{mr.mobileNumber}</td>
                            <td className="px-4 py-3">
                              <span className={`px-2 py-0.5 rounded-full text-[9px] font-bold ${mr.status === 'active' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                                {mr.status.toUpperCase()}
                              </span>
                            </td>
                          </tr>
                        ))}
                        {mrs.filter(m => m.companyName === companies.find(c => c.id === selectedCompanyId)?.name).length === 0 && (
                          <tr>
                            <td colSpan={4} className="px-4 py-8 text-center text-slate-400 italic">No representatives registered for this company.</td>
                          </tr>
                        )}
                      </tbody>
                    </table>
                  </div>
                </div>
              ) : (
                <div className="h-full flex flex-col items-center justify-center p-12 bg-slate-50 rounded-2xl border border-dashed border-slate-200 text-slate-400">
                  <Briefcase className="h-12 w-12 mb-4 opacity-20" />
                  <p className="text-sm">Select a company to view its representatives and details.</p>
                </div>
              )}
            </div>
          </div>
        </section>
      )}

      {/* Hospital Config Modal */}
      {isHospitalModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-lg rounded-3xl shadow-2xl overflow-hidden animate-in slide-in-from-bottom-4 duration-300">
            <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-bold text-slate-800">{editingHospital?.id ? 'Edit Hospital' : 'Add New Hospital'}</h3>
              <button onClick={() => setIsHospitalModalOpen(false)} className="p-2 hover:bg-slate-200 rounded-full transition-all"><X className="h-5 w-5 text-slate-400" /></button>
            </div>
            <form onSubmit={handleSaveHospital} className="p-6 space-y-6">
              <div className="space-y-4">
                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Hospital Name</label>
                  <input 
                    required 
                    type="text" 
                    value={editingHospital?.name || ''} 
                    onChange={e => setEditingHospital({...editingHospital, name: e.target.value})} 
                    placeholder="e.g. Apollo Hospital" 
                    className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                  />
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Window Start</label>
                    <input 
                      type="time" 
                      value={editingHospital?.bookingWindowStart || '00:00'} 
                      onChange={e => setEditingHospital({...editingHospital, bookingWindowStart: e.target.value})} 
                      className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none"
                    />
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Window End</label>
                    <input 
                      type="time" 
                      value={editingHospital?.bookingWindowEnd || '23:59'} 
                      onChange={e => setEditingHospital({...editingHospital, bookingWindowEnd: e.target.value})} 
                      className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none"
                    />
                  </div>
                </div>

                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block">Supported Sessions & Limits</label>
                  <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                    {(['MORNING', 'EVENING', 'FULL_DAY'] as SessionType[]).map(s => {
                      const isSelected = editingHospital?.supportedSessions?.includes(s);
                      return (
                        <div key={s} className={`p-3 border rounded-xl transition-all ${isSelected ? 'border-indigo-200 bg-indigo-50' : 'border-slate-100 bg-slate-50 opacity-60'}`}>
                          <div className="flex items-center gap-2 mb-2">
                            <input 
                              type="checkbox" 
                              checked={isSelected} 
                              onChange={e => {
                                const sessions = editingHospital?.supportedSessions || [];
                                const newSessions = e.target.checked ? [...sessions, s] : sessions.filter(x => x !== s);
                                setEditingHospital({...editingHospital, supportedSessions: newSessions});
                              }}
                              className="w-4 h-4 rounded text-indigo-600 focus:ring-indigo-500"
                            />
                            <span className="text-[10px] font-bold text-slate-700">{s}</span>
                          </div>
                          <input 
                            type="number" 
                            disabled={!isSelected}
                            value={editingHospital?.passLimits?.[s] || 0}
                            onChange={e => {
                              const limits = editingHospital?.passLimits || {};
                              setEditingHospital({...editingHospital, passLimits: {...limits, [s]: parseInt(e.target.value) || 0}});
                            }}
                            className="w-full px-2 py-1 bg-white border border-slate-200 rounded text-xs outline-none disabled:opacity-50"
                          />
                        </div>
                      );
                    })}
                  </div>
                </div>
              </div>

              <div className="flex gap-3 pt-4">
                <button type="button" onClick={() => setIsHospitalModalOpen(false)} className="flex-1 px-6 py-3 border border-slate-200 text-slate-600 font-bold rounded-xl hover:bg-slate-50 transition-all">Cancel</button>
                <button type="submit" className="flex-1 bg-indigo-600 text-white font-bold py-3 rounded-xl shadow-lg hover:bg-indigo-700 transition-all active:scale-95">Save Changes</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Company Modal */}
      {isCompanyModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden animate-in slide-in-from-bottom-4 duration-300">
            <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-bold text-slate-800">{editingCompany?.id ? 'Edit Company' : 'Register Company'}</h3>
              <button onClick={() => setIsCompanyModalOpen(false)} className="p-2 hover:bg-slate-200 rounded-full transition-all"><X className="h-5 w-5 text-slate-400" /></button>
            </div>
            <form onSubmit={handleSaveCompany} className="p-6 space-y-4">
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Company Name</label>
                <input 
                  required 
                  type="text" 
                  value={editingCompany?.name || ''} 
                  onChange={e => setEditingCompany({...editingCompany, name: e.target.value})} 
                  placeholder="e.g. Pfizer Lanka" 
                  className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
