                                    setEditingHospital({...editingHospital, sessionWindows: {...windows, [s]: { ...currentWindow, end: e.target.value }}});
                                  }}
                                  className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg text-xs outline-none disabled:opacity-50"
                                />
                              </div>
                            </div>
                          </div>
                        </div>
                      );
                    })}
