import React, { useState, useEffect } from 'react';
import { Calendar, Clock, QrCode, AlertCircle, CheckCircle2, Info, Building2, PlusCircle, Sun, Moon, Maximize } from 'lucide-react';
import { storageService } from '../services/storageService';
import { MedicalRep, PassApplication, IssuedPass, Hospital, MRHospitalApproval, SessionType } from '../types';
import { getPriorityInsights } from '../services/geminiService';

interface MRDashboardProps {
  user: MedicalRep;
}

const MRDashboard: React.FC<MRDashboardProps> = ({ user }) => {
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [loading, setLoading] = useState(false);
  const [aiInsight, setAiInsight] = useState<string>('');

  useEffect(() => { refreshData(); }, []);

  const refreshData = async () => {
    const h = storageService.getHospitals();
    const apprvs = storageService.getApprovals();
    const a = storageService.getApplications().filter(ap => ap.mrId === user.id);
    const p = storageService.getPasses().filter(ps => ps.mrId === user.id);
    setHospitals(h); setApprovals(apprvs); setApps(a); setPasses(p);
    const insight = await getPriorityInsights(a.slice(-3).map(app => ({ date: app.applicationDate, status: app.status })));
    setAiInsight(insight);
  };

  const isSessionWindowOpen = (h: Hospital, session: SessionType) => {
    const window = h.sessionWindows?.[session];
    if (!window) return false;

    const now = new Date();
    const time = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
    return time >= window.start && time <= window.end;
  };

  const checkEligibility = (hospitalId: string, session: SessionType) => {
    const today = new Date();
    const recentPasses = passes.filter(p => p.hospitalId === hospitalId && p.entryStatus !== 'expired');

    for (const p of recentPasses) {
      const passDate = new Date(p.passDate);
      const diff = Math.floor((today.getTime() - passDate.getTime()) / (1000 * 3600 * 24));
      if (diff < 3) {
        if (p.session === 'FULL_DAY') return { eligible: false, reason: "Full Day pass blocks all applications for 3 days." };
        if (p.session === session) return { eligible: false, reason: `You already had a ${session} pass within the last 3 days.` };
      }
    }
    return { eligible: true };
  };

  const handleApply = async (hospitalId: string, session: SessionType) => {
    const { eligible, reason } = checkEligibility(hospitalId, session);
    if (!eligible) { alert(reason); return; }

    const todayStr = new Date().toISOString().split('T')[0];
    if (apps.some(a => a.hospitalId === hospitalId && a.applicationDate === todayStr && a.session === session)) {
      alert("Application already submitted for this session today."); return;
    }

    setLoading(true);
    const newApp: PassApplication = {
      id: Math.random().toString(36).substr(2, 9),
      mrId: user.id, hospitalId, session,
      applicationDate: todayStr, priorityScore: 0, status: 'applied',
      createdAt: new Date().toISOString()
    };
    storageService.saveApplications([...storageService.getApplications(), newApp]);
    setTimeout(() => { refreshData(); setLoading(false); }, 600);
  };

  const approvedHospitals = hospitals.filter(h => 
    approvals.some(a => a.mrId === user.id && a.hospitalId === h.id && a.status === 'approved')
  );

  return (
    <div className="space-y-8">
      <div className="bg-indigo-50 border border-indigo-100 p-4 rounded-xl flex items-start gap-3 shadow-sm">
        <Info className="h-5 w-5 text-indigo-500 mt-0.5" />
        <p className="text-sm text-indigo-800 leading-relaxed">{aiInsight || "Analyzing your profile and calculating your ranking factors..."}</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 md:col-span-2">
          <h3 className="text-lg font-bold mb-6 flex items-center gap-2 text-slate-800">
            <Building2 className="h-5 w-5 text-indigo-500" /> 
            Approved Hospitals
          </h3>
          <div className="grid gap-6 sm:grid-cols-2">
            {approvedHospitals.map(h => (
              <div key={h.id} className="p-5 bg-slate-50 rounded-2xl border border-slate-100 hover:shadow-md transition-shadow">
                <div className="mb-4">
                  <p className="font-bold text-slate-800 text-lg">{h.name}</p>
                </div>
                <div className="space-y-3">
                  {h.supportedSessions.map(sess => {
                    const open = isSessionWindowOpen(h, sess);
                    const window = h.sessionWindows?.[sess];
                    return (
                      <div key={sess} className="space-y-1">
                        <button
                          disabled={!open || loading}
                          onClick={() => handleApply(h.id, sess)}
                          className={`w-full py-3 px-4 rounded-xl text-xs font-black flex items-center justify-between transition-all group ${
                            open 
                              ? 'bg-white border-2 border-indigo-100 hover:border-indigo-400 text-indigo-700 shadow-sm active:scale-95' 
                              : 'bg-slate-200/50 text-slate-400 cursor-not-allowed grayscale'
                          }`}
                        >
                          <span className="flex items-center gap-2">
                            {sess === 'MORNING' ? <Sun className="h-4 w-4" /> : sess === 'EVENING' ? <Moon className="h-4 w-4" /> : <Maximize className="h-4 w-4" />}
                            {sess}
                          </span>
                          <span className="flex items-center gap-1">
                            {open ? 'APPLY NOW' : 'CLOSED'}
                            {open && <PlusCircle className="h-3 w-3 group-hover:scale-125 transition-transform" />}
                          </span>
                        </button>
                        <div className="flex justify-between px-1">
                          <span className="text-[9px] font-bold text-slate-400 uppercase tracking-tighter">Window: {window?.start} - {window?.end}</span>
                          {open && <span className="text-[9px] font-black text-green-500 animate-pulse">LIVE</span>}
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            ))}
            {approvedHospitals.length === 0 && (
              <div className="sm:col-span-2 p-12 text-center bg-slate-50 border-2 border-dashed border-slate-200 rounded-3xl">
                <div className="bg-white w-12 h-12 rounded-full flex items-center justify-center mx-auto mb-4 shadow-sm">
                  <Building2 className="h-6 w-6 text-slate-300" />
                </div>
                <p className="text-sm font-medium text-slate-500">No hospital access yet.</p>
                <p className="text-xs text-slate-400 mt-1">Please request access from the directory.</p>
              </div>
            )}
          </div>
        </section>

        <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <h3 className="text-lg font-bold mb-6 flex items-center gap-2 text-slate-800">
            <QrCode className="h-5 w-5 text-indigo-500" /> 
            Active Passes
          </h3>
          <div className="space-y-4">
            {passes.filter(p => p.entryStatus === 'not_entered').map(p => (
              <div key={p.id} className="p-4 bg-indigo-50 border-2 border-indigo-100 rounded-2xl shadow-sm hover:shadow-md transition-shadow">
                <div className="flex justify-between items-center mb-3">
                   <div className="flex items-center gap-1.5">
                    {p.session === 'MORNING' ? <Sun className="h-3 w-3 text-amber-500" /> : p.session === 'EVENING' ? <Moon className="h-3 w-3 text-indigo-400" /> : <Maximize className="h-3 w-3 text-indigo-500" />}
                    <span className="text-[10px] font-black uppercase text-indigo-600 tracking-widest">{p.session}</span>
                   </div>
                  <span className="text-[10px] font-bold text-slate-400 bg-white px-2 py-0.5 rounded shadow-xs">{p.passDate}</span>
                </div>
                <p className="font-bold text-slate-800 text-sm mb-4 leading-tight">{hospitals.find(h => h.id === p.hospitalId)?.name}</p>
                <div className="bg-white p-4 rounded-xl border border-indigo-100 flex justify-center shadow-inner">
                  <QrCode className="h-24 w-24 text-indigo-900" />
                </div>
                <div className="mt-3 text-center">
                  <p className="text-[9px] font-black text-indigo-300 uppercase tracking-[0.2em]">{p.id}</p>
                </div>
              </div>
            ))}
            {passes.filter(p => p.entryStatus === 'not_entered').length === 0 && (
              <div className="text-center py-12 text-slate-400">
                <div className="bg-slate-50 w-12 h-12 rounded-full flex items-center justify-center mx-auto mb-3">
                  <QrCode className="h-6 w-6 opacity-20" />
                </div>
                <p className="text-xs italic">No active passes found.</p>
              </div>
            )}
          </div>
        </section>
      </div>
    </div>
  );
};

export default MRDashboard;

import React, { useState, useEffect } from 'react';
import { Building2, Users, FileText, Settings, Plus, DollarSign, Power, Activity, Edit3, Trash2, Check, X, ChevronRight, Briefcase, Clock } from 'lucide-react';
import { storageService } from '../services/storageService';
import { Hospital, PharmaCompany, Invoice, MedicalRep, SessionType } from '../types';

const SuperAdminDashboard: React.FC = () => {
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [companies, setCompanies] = useState<PharmaCompany[]>([]);
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [activeTab, setActiveTab] = useState<'hospitals' | 'companies' | 'billing' | 'monitoring'>('hospitals');

  // Hospital Config State
  const [isHospitalModalOpen, setIsHospitalModalOpen] = useState(false);
  const [editingHospital, setEditingHospital] = useState<Partial<Hospital> | null>(null);

  // Company State
  const [isCompanyModalOpen, setIsCompanyModalOpen] = useState(false);
  const [editingCompany, setEditingCompany] = useState<Partial<PharmaCompany> | null>(null);
  const [selectedCompanyId, setSelectedCompanyId] = useState<string | null>(null);

  useEffect(() => {
    refreshData();
  }, []);

  const refreshData = () => {
    setHospitals(storageService.getHospitals());
    setCompanies(storageService.getCompanies());
    setInvoices(storageService.getInvoices());
    setMrs(storageService.getMRs());
  };

  const handleSaveHospital = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingHospital?.name) return;

    const currentHospitals = storageService.getHospitals();
    let updated: Hospital[];

    // Removed bookingWindowStart and bookingWindowEnd as they are not present in the Hospital type definition
    const hospitalData: Hospital = {
      id: editingHospital.id || 'h' + Date.now(),
      name: editingHospital.name || '',
      isActive: editingHospital.isActive ?? true,
      supportedSessions: editingHospital.supportedSessions || [],
      passLimits: editingHospital.passLimits || {},
      sessionWindows: editingHospital.sessionWindows || {},
    };

    if (editingHospital.id) {
      updated = currentHospitals.map(h => h.id === editingHospital.id ? hospitalData : h);
    } else {
      updated = [...currentHospitals, hospitalData];
    }

    storageService.saveHospitals(updated);
    setHospitals(updated);
    setIsHospitalModalOpen(false);
    setEditingHospital(null);
  };

  const toggleHospitalStatus = (id: string) => {
    const updated = hospitals.map(h => h.id === id ? { ...h, isActive: !h.isActive } : h);
    storageService.saveHospitals(updated);
    setHospitals(updated);
  };

  const handleSaveCompany = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingCompany?.name) return;

    const currentCompanies = storageService.getCompanies();
    let updated: PharmaCompany[];

    if (editingCompany.id) {
      updated = currentCompanies.map(c => c.id === editingCompany.id ? (editingCompany as PharmaCompany) : c);
    } else {
      const newC: PharmaCompany = {
        ...(editingCompany as PharmaCompany),
        id: 'c' + Date.now(),
      };
      updated = [...currentCompanies, newC];
    }

    storageService.saveCompanies(updated);
    setCompanies(updated);
    setIsCompanyModalOpen(false);
    setEditingCompany(null);
  };

  const calculateBilling = () => {
    const today = new Date().toISOString().split('T')[0];
    const newInvoices: Invoice[] = companies.map(company => {
      const activeMRs = mrs.filter(m => m.companyName === company.name && m.status === 'active').length;
      return {
        id: 'INV-' + Math.random().toString(36).substr(2, 6).toUpperCase(),
        companyId: company.id,
        amount: activeMRs * 250,
        activeMRCount: activeMRs,
        status: 'unpaid',
        date: today
      };
    });
    const updatedInvoices = [...invoices, ...newInvoices];
    storageService.saveInvoices(updatedInvoices);
    setInvoices(updatedInvoices);
    alert("Quotations generated for all companies.");
  };

  return (
    <div className="space-y-6">
      <div className="flex bg-white p-1 rounded-xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => {setActiveTab('hospitals'); setSelectedCompanyId(null);}} className={`px-4 md:px-6 py-2 rounded-lg text-sm font-bold flex items-center gap-2 whitespace-nowrap ${activeTab === 'hospitals' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Building2 className="h-4 w-4" /> Hospitals</button>
        <button onClick={() => setActiveTab('companies')} className={`px-4 md:px-6 py-2 rounded-lg text-sm font-bold flex items-center gap-2 whitespace-nowrap ${activeTab === 'companies' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Briefcase className="h-4 w-4" /> Companies</button>
        <button onClick={() => setActiveTab('billing')} className={`px-4 md:px-6 py-2 rounded-lg text-sm font-bold flex items-center gap-2 whitespace-nowrap ${activeTab === 'billing' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><DollarSign className="h-4 w-4" /> Billing</button>
        <button onClick={() => setActiveTab('monitoring')} className={`px-4 md:px-6 py-2 rounded-lg text-sm font-bold flex items-center gap-2 whitespace-nowrap ${activeTab === 'monitoring' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Activity className="h-4 w-4" /> Monitoring</button>
      </div>

      {activeTab === 'hospitals' && (
        <section className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
          <div className="flex justify-between items-center mb-6">
            <div>
              <h3 className="text-lg font-bold">Hospital Network Control</h3>
              <p className="text-sm text-slate-500">Configure hospital sessions, limits and per-session access windows.</p>
