import React, { useState, useEffect } from 'react';
import { Play, Sparkles, CheckCircle, Clock, UserPlus, Users, Settings, Save, X, Plus, Sun, Moon, Maximize } from 'lucide-react';
import { storageService } from '../services/storageService';
import { MedicalRep, Hospital, PassApplication, IssuedPass, MRHospitalApproval, SessionType } from '../types';
import { PRIORITY_WEIGHTS, TIME_SLOTS } from '../constants';
import { getAdminBriefing } from '../services/geminiService';

const AdminDashboard: React.FC = () => {
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [activeTab, setActiveTab] = useState<'lottery' | 'approvals' | 'config'>('lottery');
  const [brief, setBrief] = useState('');

  // Hospital specific config state (assuming first hospital for demo)
  const [editingHospital, setEditingHospital] = useState<Hospital | null>(null);

  useEffect(() => { refreshData(); }, []);

  const refreshData = async () => {
    const h = storageService.getHospitals();
    setMrs(storageService.getMRs()); 
    setHospitals(h);
    setApps(storageService.getApplications()); 
    setPasses(storageService.getPasses());
    setApprovals(storageService.getApprovals());
    setEditingHospital(h[0]); // Demo hospital context
    setBrief(await getAdminBriefing(storageService.getApplications(), storageService.getPasses()));
  };

  const runLottery = (session: SessionType) => {
    const today = new Date().toISOString().split('T')[0];
    const hospital = hospitals[0]; // Demo
    const sessionApps = apps.filter(a => a.hospitalId === hospital.id && a.applicationDate === today && a.session === session && a.status === 'applied');

    if (sessionApps.length === 0) { alert(`No ${session} applications for today.`); return; }

    const scored = sessionApps.map(a => ({ ...a, score: calculatePriority(a.mrId) })).sort((a,b) => b.score - a.score);
    const limit = hospital.passLimits[session] || 0;
    const selected = scored.slice(0, limit);
    const waitlisted = scored.slice(limit);

    const newPasses: IssuedPass[] = selected.map((s, i) => ({
      id: `PASS-${Math.random().toString(36).substr(2, 6).toUpperCase()}`,
      mrId: s.mrId, hospitalId: s.hospitalId, session, passDate: today,
      timeSlot: TIME_SLOTS[i % TIME_SLOTS.length], qrCode: `QR-${s.id}`, entryStatus: 'not_entered'
    }));

    const updatedApps = apps.map(original => {
      if (selected.find(x => x.id === original.id)) return { ...original, status: 'selected' as const };
      if (waitlisted.find(x => x.id === original.id)) return { ...original, status: 'waitlisted' as const };
      return original;
    });

    storageService.saveApplications(updatedApps);
    storageService.savePasses([...passes, ...newPasses]);
    refreshData();
    alert(`Lottery complete for ${session}! Issued ${selected.length} passes.`);
  };

  const calculatePriority = (mrId: string) => {
    let s = 0; const now = new Date();
    const entered = passes.filter(p => p.mrId === mrId && p.entryStatus === 'entered');
    if (entered.length > 0) {
      const last = new Date(entered[entered.length - 1].passDate);
      const diff = Math.floor((now.getTime() - last.getTime()) / (1000 * 3600 * 24));
      if (diff >= 14) s += PRIORITY_WEIGHTS.NO_PASS_14_DAYS;
      else if (diff >= 7) s += PRIORITY_WEIGHTS.NO_PASS_7_DAYS;
    } else s += PRIORITY_WEIGHTS.NO_PASS_14_DAYS;
    return s;
  };

  const updateApproval = (id: string, status: 'approved' | 'rejected') => {
    const updated = approvals.map(a => a.id === id ? { ...a, status, updatedAt: new Date().toISOString() } : a);
    storageService.saveApprovals(updated); refreshData();
  };

  const handleSaveConfig = () => {
    if (!editingHospital) return;
    const allHospitals = storageService.getHospitals();
    const updated = allHospitals.map(h => h.id === editingHospital.id ? editingHospital : h);
    storageService.saveHospitals(updated);
    setHospitals(updated);
    alert("Hospital session configuration updated successfully.");
  };

  return (
    <div className="space-y-6">
      <div className="bg-indigo-600 rounded-3xl p-6 text-white shadow-lg flex items-center gap-4 border border-indigo-400/30">
        <Sparkles className="h-6 w-6 text-indigo-200" />
        <p className="text-sm font-medium leading-relaxed">{brief || "Scanning daily activity and calculating rankings..."}</p>
      </div>

      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto">
        <button onClick={() => setActiveTab('lottery')} className={`px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'lottery' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Play className="h-4 w-4" /> Lottery Run</button>
        <button onClick={() => setActiveTab('approvals')} className={`px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'approvals' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><UserPlus className="h-4 w-4" /> Access Approvals</button>
        <button onClick={() => setActiveTab('config')} className={`px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'config' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Settings className="h-4 w-4" /> Configuration</button>
      </div>

      {activeTab === 'lottery' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 space-y-6 bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-4">
              <h3 className="text-lg font-bold text-slate-800">Applications Received Today</h3>
              <div className="flex flex-wrap gap-2">
                <button onClick={() => runLottery('MORNING')} className="text-[10px] font-black uppercase tracking-widest bg-indigo-50 text-indigo-600 px-4 py-2 rounded-xl hover:bg-indigo-100 border border-indigo-200 transition-colors flex items-center gap-1.5 shadow-xs"><Sun className="h-3.5 w-3.5" /> Morning Lottery</button>
                <button onClick={() => runLottery('EVENING')} className="text-[10px] font-black uppercase tracking-widest bg-indigo-50 text-indigo-600 px-4 py-2 rounded-xl hover:bg-indigo-100 border border-indigo-200 transition-colors flex items-center gap-1.5 shadow-xs"><Moon className="h-3.5 w-3.5" /> Evening Lottery</button>
              </div>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-left text-xs">
                <thead>
                  <tr className="bg-slate-50 text-slate-400 uppercase font-black text-[9px] tracking-widest">
                    <th className="px-4 py-3">Medical Representative</th>
                    <th className="px-4 py-3">Session</th>
                    <th className="px-4 py-3">Score</th>
                    <th className="px-4 py-3 text-right">Status</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {apps.filter(a => a.applicationDate === new Date().toISOString().split('T')[0]).map(app => (
                    <tr key={app.id} className="hover:bg-slate-50/50 transition-colors">
                      <td className="px-4 py-4 font-bold text-slate-700">{mrs.find(m => m.id === app.mrId)?.fullName} <span className="block text-[10px] text-slate-400 font-medium">{mrs.find(m => m.id === app.mrId)?.companyName}</span></td>
                      <td className="px-4 py-4"><span className="bg-white border border-slate-200 px-2 py-1 rounded-lg font-bold text-slate-600">{app.session}</span></td>
                      <td className="px-4 py-4 font-mono font-bold text-indigo-600">+{calculatePriority(app.mrId)}</td>
                      <td className="px-4 py-4 text-right"><span className={`inline-block px-2 py-1 rounded-lg uppercase font-black text-[8px] tracking-tighter ${app.status === 'selected' ? 'bg-green-100 text-green-700' : 'bg-slate-100 text-slate-500'}`}>{app.status}</span></td>
                    </tr>
                  ))}
                  {apps.filter(a => a.applicationDate === new Date().toISOString().split('T')[0]).length === 0 && (
                    <tr><td colSpan={4} className="px-4 py-12 text-center text-slate-400 italic">No applications recorded for today yet.</td></tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
          <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm h-fit">
            <h4 className="font-bold text-slate-800 mb-6">Real-time Stats</h4>
            <div className="space-y-4">
              <div className="p-5 bg-green-50 rounded-2xl border border-green-100"><p className="text-[10px] font-black text-green-600 uppercase tracking-widest mb-1">Passes Issued</p><p className="text-3xl font-black text-green-700">{passes.filter(p => p.passDate === new Date().toISOString().split('T')[0]).length}</p></div>
              <div className="p-5 bg-indigo-50 rounded-2xl border border-indigo-100"><p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest mb-1">Today's Pool</p><p className="text-3xl font-black text-indigo-700">{apps.filter(a => a.applicationDate === new Date().toISOString().split('T')[0]).length}</p></div>
              <div className="p-5 bg-slate-50 rounded-2xl border border-slate-200"><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Pending Pool</p><p className="text-3xl font-black text-slate-600">{apps.filter(a => a.status === 'applied').length}</p></div>
            </div>
          </div>
        </div>
      )}

      {activeTab === 'approvals' && (
        <section className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
          <h3 className="text-lg font-bold mb-6 text-slate-800">Pending Access Requests</h3>
          <div className="space-y-4">
            {approvals.filter(a => a.status === 'pending').map(req => (
              <div key={req.id} className="flex flex-col sm:flex-row justify-between items-start sm:items-center p-5 bg-slate-50 rounded-2xl border border-slate-100 gap-4 transition-all hover:shadow-md">
                <div className="flex items-center gap-4">
                  <div className="bg-white p-3 rounded-xl shadow-xs"><Users className="h-6 w-6 text-indigo-600" /></div>
                  <div>
                    <p className="font-bold text-slate-800">{mrs.find(m => m.id === req.mrId)?.fullName}</p>
                    <p className="text-xs text-slate-500 font-medium">{mrs.find(m => m.id === req.mrId)?.companyName}</p>
                  </div>
                </div>
                <div className="flex gap-2 w-full sm:w-auto">
                  <button onClick={() => updateApproval(req.id, 'approved')} className="flex-1 bg-green-600 text-white text-xs px-6 py-2.5 rounded-xl font-bold shadow-md hover:bg-green-700 active:scale-95 transition-all">Approve</button>
                  <button onClick={() => updateApproval(req.id, 'rejected')} className="flex-1 bg-white border border-red-100 text-red-600 text-xs px-6 py-2.5 rounded-xl font-bold hover:bg-red-50 active:scale-95 transition-all">Reject</button>
                </div>
              </div>
            ))}
            {approvals.filter(a => a.status === 'pending').length === 0 && (
              <div className="text-center py-16 text-slate-400">
                <Users className="h-12 w-12 mx-auto mb-4 opacity-10" />
                <p className="italic text-sm">No pending access requests at the moment.</p>
              </div>
            )}
          </div>
        </section>
      )}

      {activeTab === 'config' && editingHospital && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm max-w-3xl">
          <div className="flex items-center justify-between mb-8 pb-6 border-b border-slate-100">
            <div>
              <h3 className="text-2xl font-black text-slate-800 tracking-tight">Hospital Configuration</h3>
              <p className="text-sm text-slate-400">Manage sessions, pass limits, and booking windows.</p>
            </div>
            <Settings className="h-8 w-8 text-indigo-600 opacity-20" />
