          <div className="space-y-8">
            <div className="space-y-4">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Active Sessions & Daily Pass Limits</label>
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                {(['MORNING', 'EVENING', 'FULL_DAY'] as SessionType[]).map(s => {
                  const isSelected = editingHospital.supportedSessions.includes(s);
                  const currentWindow = editingHospital.sessionWindows[s] || { start: '00:00', end: '23:59' };

                  return (
