                                const windows = { ...editingHospital.sessionWindows };
                                windows[s] = { ...currentWindow, end: e.target.value };
                                setEditingHospital({...editingHospital, sessionWindows: windows});
                              }}
                              className="w-full px-2 py-1.5 bg-white border border-slate-200 rounded-lg text-[10px] font-bold outline-none disabled:opacity-50"
                            />
                          </div>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>

            <div className="pt-6 border-t border-slate-100 flex gap-4">
              <button 
                onClick={handleSaveConfig}
                className="flex-1 bg-indigo-600 text-white py-4 rounded-2xl font-black text-sm shadow-xl hover:bg-indigo-700 active:scale-[0.98] transition-all flex items-center justify-center gap-2"
              >
                <Save className="h-5 w-5" /> SAVE CONFIGURATION
              </button>
              <button 
                onClick={() => setEditingHospital(hospitals[0])}
                className="px-8 py-4 bg-slate-100 text-slate-500 rounded-2xl font-bold text-sm hover:bg-slate-200 transition-all"
              >
                Reset
              </button>
            </div>
          </div>
        </section>
      )}
    </div>
  );
};

export default AdminDashboard;

export type MRStatus = 'active' | 'suspended';
export type ApplicationStatus = 'applied' | 'selected' | 'waitlisted' | 'rejected';
export type EntryStatus = 'not_entered' | 'entered' | 'expired';
export type UserRole = 'MR' | 'ADMIN' | 'SECURITY' | 'SUPER_ADMIN';
export type ApprovalStatus = 'pending' | 'approved' | 'rejected';
export type SessionType = 'MORNING' | 'EVENING' | 'FULL_DAY';

export interface MedicalRep {
  id: string;
  fullName: string;
  companyName: string; // Used for PharmaCompany linking
  mrId: string;
  mobileNumber: string;
  identificationNumber: string; // Valid ID for signup
  status: MRStatus;
  createdAt: string;
}

export interface Hospital {
  id: string;
  name: string;
  supportedSessions: SessionType[];
  passLimits: Record<string, number>; // e.g., { 'MORNING': 15 }
  sessionWindows: Record<string, { start: string; end: string }>; // e.g., { 'MORNING': { start: '18:00', end: '18:10' } }
  isActive: boolean;
}

export interface MRHospitalApproval {
  id: string;
  mrId: string;
  hospitalId: string;
  status: ApprovalStatus;
  updatedAt: string;
}

export interface PassApplication {
  id: string;
  mrId: string;
  hospitalId: string;
  session: SessionType;
  applicationDate: string;
  priorityScore: number;
  status: ApplicationStatus;
  createdAt: string;
}

export interface IssuedPass {
  id: string;
  mrId: string;
  hospitalId: string;
  session: SessionType;
  passDate: string;
  timeSlot: string;
  qrCode: string;
  entryStatus: EntryStatus;
}

export interface PharmaCompany {
  id: string;
  name: string;
  contactEmail: string;
}

export interface Invoice {
  id: string;
  companyId: string;
  amount: number;
  activeMRCount: number;
  status: 'paid' | 'unpaid';
  date: string;
}

export interface EntryLog {
  id: string;
  issuedPassId: string;
  entryTime: string;
  verifiedBy: string;
}

// User in session
export interface AuthUser {
  id: string;
  role: UserRole;
  fullName: string;
  mobileNumber?: string;
  hospitalId?: string; // For hospital admins
  companyName?: string; // For MRs
}

