                  <p className="text-xs italic">No active passes for today.</p>
                </div>
              )}
            </div>
          </section>
        </div>
      )}

      {activeTab === 'directory' && (
        <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
            <h3 className="text-lg font-bold flex items-center gap-2 text-slate-800">
              <Search className="h-5 w-5 text-indigo-500" /> 
              Hospital Directory
            </h3>
            <div className="relative max-w-md w-full">
              <input 
                type="text" 
                placeholder="Search hospitals..." 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
              />
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
            </div>
          </div>

          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {availableHospitals.map(h => {
              const approval = approvals.find(a => a.mrId === user.id && a.hospitalId === h.id);
              const isPending = approval?.status === 'pending';
              const isRejected = approval?.status === 'rejected';

              return (
                <div key={h.id} className="p-5 border border-slate-100 bg-slate-50 rounded-2xl flex flex-col justify-between group hover:border-indigo-200 transition-colors">
                  <div>
                    <h4 className="font-bold text-slate-800 group-hover:text-indigo-600 transition-colors">{h.name}</h4>
                    <p className="text-[10px] text-slate-400 uppercase font-black tracking-widest mt-1">
                      {h.supportedSessions.join(' • ')}
                    </p>
                  </div>

                  <div className="mt-6">
                    {isPending ? (
                      <div className="w-full py-2.5 px-4 bg-amber-50 text-amber-600 rounded-xl text-xs font-bold flex items-center justify-center gap-2 border border-amber-100">
                        <Clock className="h-4 w-4" /> Pending
                      </div>
                    ) : isRejected ? (
                      <button 
                        onClick={() => requestApproval(h.id)}
                        className="w-full py-2.5 px-4 bg-white border border-red-200 text-red-600 rounded-xl text-xs font-bold hover:bg-red-50 transition-all flex items-center justify-center gap-2 shadow-sm"
                      >
                        <AlertCircle className="h-4 w-4" /> Try Again
                      </button>
                    ) : (
                      <button 
                        onClick={() => requestApproval(h.id)}
                        className="w-full py-2.5 px-4 bg-indigo-600 text-white rounded-xl text-xs font-bold hover:bg-indigo-700 transition-all flex items-center justify-center gap-2 shadow-md active:scale-95"
                      >
                        <Send className="h-4 w-4" /> Request Access
                      </button>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </section>
      )}

      {activeTab === 'profile' && (
        <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100 max-w-2xl mx-auto">
          <div className="text-center mb-8">
            <div className="w-24 h-24 bg-indigo-100 rounded-full flex items-center justify-center mx-auto mb-4 border-4 border-white shadow-md">
              <UserCircle className="h-14 w-14 text-indigo-600" />
            </div>
            <h3 className="text-2xl font-black text-slate-800">{user.fullName}</h3>
            <p className="text-indigo-600 font-bold text-sm tracking-wide uppercase">{user.companyName}</p>
          </div>

          <div className="grid gap-4 sm:grid-cols-2">
            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
              <div className="flex items-center gap-3 text-slate-400 mb-1">
                <Briefcase className="h-4 w-4" />
                <span className="text-[10px] font-black uppercase tracking-widest">Representative ID</span>
              </div>
              <p className="font-bold text-slate-800">{user.mrId}</p>
            </div>

            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
              <div className="flex items-center gap-3 text-slate-400 mb-1">
                <Phone className="h-4 w-4" />
                <span className="text-[10px] font-black uppercase tracking-widest">Mobile Number</span>
              </div>
              <p className="font-bold text-slate-800">{user.mobileNumber}</p>
            </div>

            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
              <div className="flex items-center gap-3 text-slate-400 mb-1">
                <CreditCard className="h-4 w-4" />
                <span className="text-[10px] font-black uppercase tracking-widest">ID Card (Verified)</span>
              </div>
              <p className="font-bold text-slate-800">{user.identificationNumber}</p>
            </div>

            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
              <div className="flex items-center gap-3 text-slate-400 mb-1">
                <CheckCircle className="h-4 w-4" />
                <span className="text-[10px] font-black uppercase tracking-widest">Member Since</span>
              </div>
              <p className="font-bold text-slate-800">{new Date(user.createdAt).toLocaleDateString()}</p>
            </div>
          </div>

          <div className="mt-8 pt-8 border-t border-slate-100 text-center">
            <p className="text-xs text-slate-400 italic">Please contact Super Admin to update your official profile details.</p>
          </div>
        </section>
      )}
    </div>
  );
};

export default MRDashboard;

import React, { useState, useEffect } from 'react';
import { Play, Sparkles, CheckCircle, Clock, UserPlus, Users, Settings, Save, X, Plus, Sun, Moon, Maximize, User, Info, Building } from 'lucide-react';
import { storageService } from '../services/storageService';
import { MedicalRep, Hospital, PassApplication, IssuedPass, MRHospitalApproval, SessionType } from '../types';
import { PRIORITY_WEIGHTS, TIME_SLOTS } from '../constants';
import { getAdminBriefing } from '../services/geminiService';

interface AdminDashboardProps {
  user: {
    id: string;
    role: string;
    fullName: string;
    hospitalId: string;
  };
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user }) => {
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [activeTab, setActiveTab] = useState<'lottery' | 'approvals' | 'mrs' | 'config'>('lottery');
  const [brief, setBrief] = useState('');
  const [selectedMR, setSelectedMR] = useState<MedicalRep | null>(null);

  const [editingHospital, setEditingHospital] = useState<Hospital | null>(null);

  useEffect(() => { refreshData(); }, []);

  const refreshData = async () => {
    const allHospitals = storageService.getHospitals();
    const currentHospital = allHospitals.find(h => h.id === user.hospitalId) || allHospitals[0];

    setMrs(storageService.getMRs()); 
    setHospitals(allHospitals);
    setApps(storageService.getApplications()); 
    setPasses(storageService.getPasses());
    setApprovals(storageService.getApprovals());
    setEditingHospital(currentHospital);
    setBrief(await getAdminBriefing(storageService.getApplications(), storageService.getPasses()));
  };

  const currentHospital = hospitals.find(h => h.id === user.hospitalId) || hospitals[0];

  const runLottery = (session: SessionType) => {
    const today = new Date().toISOString().split('T')[0];
    const hospital = currentHospital;
    const sessionApps = apps.filter(a => a.hospitalId === hospital.id && a.applicationDate === today && a.session === session && a.status === 'applied');

    if (sessionApps.length === 0) { alert(`No ${session} applications for today.`); return; }

    const scored = sessionApps.map(a => ({ ...a, score: calculatePriority(a.mrId) })).sort((a,b) => b.score - a.score);
    const limit = hospital.passLimits[session] || 0;
    const selected = scored.slice(0, limit);
    const waitlisted = scored.slice(limit);

    const newPasses: IssuedPass[] = selected.map((s, i) => ({
      id: `PASS-${Math.random().toString(36).substr(2, 6).toUpperCase()}`,
      mrId: s.mrId, hospitalId: s.hospitalId, session, passDate: today,
      timeSlot: TIME_SLOTS[i % TIME_SLOTS.length], qrCode: `QR-${s.id}`, entryStatus: 'not_entered'
    }));

    const updatedApps = apps.map(original => {
      if (selected.find(x => x.id === original.id)) return { ...original, status: 'selected' as const };
      if (waitlisted.find(x => x.id === original.id)) return { ...original, status: 'waitlisted' as const };
      return original;
    });

    storageService.saveApplications(updatedApps);
    storageService.savePasses([...passes, ...newPasses]);
    refreshData();
    alert(`Lottery complete for ${session}! Issued ${selected.length} passes.`);
  };

  const calculatePriority = (mrId: string) => {
    let s = 0; const now = new Date();
    const entered = passes.filter(p => p.mrId === mrId && p.entryStatus === 'entered');
    if (entered.length > 0) {
      const last = new Date(entered[entered.length - 1].passDate);
      const diff = Math.floor((now.getTime() - last.getTime()) / (1000 * 3600 * 24));
      if (diff >= 14) s += PRIORITY_WEIGHTS.NO_PASS_14_DAYS;
      else if (diff >= 7) s += PRIORITY_WEIGHTS.NO_PASS_7_DAYS;
    } else s += PRIORITY_WEIGHTS.NO_PASS_14_DAYS;
    return s;
  };

  const updateApproval = (id: string, status: 'approved' | 'rejected') => {
    const updated = approvals.map(a => a.id === id ? { ...a, status, updatedAt: new Date().toISOString() } : a);
    storageService.saveApprovals(updated); refreshData();
  };

  const handleSaveConfig = () => {
    if (!editingHospital) return;
    const allHospitals = storageService.getHospitals();
    const updated = allHospitals.map(h => h.id === editingHospital.id ? editingHospital : h);
    storageService.saveHospitals(updated);
    setHospitals(updated);
    alert("Hospital session configuration updated successfully.");
  };

  const approvedMRs = mrs.filter(mr => 
    approvals.some(apprv => apprv.hospitalId === user.hospitalId && apprv.mrId === mr.id && apprv.status === 'approved')
  );

  return (
    <div className="space-y-6">
      <div className="bg-indigo-600 rounded-3xl p-6 text-white shadow-lg flex items-center gap-4 border border-indigo-400/30">
        <Sparkles className="h-6 w-6 text-indigo-200" />
        <p className="text-sm font-medium leading-relaxed">{brief || "Scanning daily activity and calculating rankings..."}</p>
      </div>

      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('lottery')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all whitespace-nowrap ${activeTab === 'lottery' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Play className="h-4 w-4" /> Lottery</button>
        <button onClick={() => setActiveTab('approvals')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all whitespace-nowrap ${activeTab === 'approvals' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><UserPlus className="h-4 w-4" /> Requests</button>
        <button onClick={() => setActiveTab('mrs')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all whitespace-nowrap ${activeTab === 'mrs' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Users className="h-4 w-4" /> Approved MRs</button>
        <button onClick={() => setActiveTab('config')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all whitespace-nowrap ${activeTab === 'config' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Settings className="h-4 w-4" /> Config</button>
      </div>

      {activeTab === 'lottery' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 space-y-6 bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-4">
              <h3 className="text-lg font-bold text-slate-800">Applications: {currentHospital?.name}</h3>
              <div className="flex flex-wrap gap-2">
                <button onClick={() => runLottery('MORNING')} className="text-[10px] font-black uppercase tracking-widest bg-indigo-50 text-indigo-600 px-4 py-2 rounded-xl hover:bg-indigo-100 border border-indigo-200 transition-colors flex items-center gap-1.5 shadow-xs"><Sun className="h-3.5 w-3.5" /> Morning</button>
                <button onClick={() => runLottery('EVENING')} className="text-[10px] font-black uppercase tracking-widest bg-indigo-50 text-indigo-600 px-4 py-2 rounded-xl hover:bg-indigo-100 border border-indigo-200 transition-colors flex items-center gap-1.5 shadow-xs"><Moon className="h-3.5 w-3.5" /> Evening</button>
              </div>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-left text-xs">
                <thead>
                  <tr className="bg-slate-50 text-slate-400 uppercase font-black text-[9px] tracking-widest">
                    <th className="px-4 py-3">Medical Representative</th>
                    <th className="px-4 py-3">Session</th>
                    <th className="px-4 py-3">Score</th>
                    <th className="px-4 py-3 text-right">Status</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {apps.filter(a => a.hospitalId === user.hospitalId && a.applicationDate === new Date().toISOString().split('T')[0]).map(app => (
                    <tr key={app.id} className="hover:bg-slate-50/50 transition-colors">
                      <td className="px-4 py-4 font-bold text-slate-700">{mrs.find(m => m.id === app.mrId)?.fullName} <span className="block text-[10px] text-slate-400 font-medium">{mrs.find(m => m.id === app.mrId)?.companyName}</span></td>
                      <td className="px-4 py-4"><span className="bg-white border border-slate-200 px-2 py-1 rounded-lg font-bold text-slate-600">{app.session}</span></td>
                      <td className="px-4 py-4 font-mono font-bold text-indigo-600">+{calculatePriority(app.mrId)}</td>
                      <td className="px-4 py-4 text-right"><span className={`inline-block px-2 py-1 rounded-lg uppercase font-black text-[8px] tracking-tighter ${app.status === 'selected' ? 'bg-green-100 text-green-700' : 'bg-slate-100 text-slate-500'}`}>{app.status}</span></td>
                    </tr>
                  ))}
                  {apps.filter(a => a.hospitalId === user.hospitalId && a.applicationDate === new Date().toISOString().split('T')[0]).length === 0 && (
                    <tr><td colSpan={4} className="px-4 py-12 text-center text-slate-400 italic">No applications for this hospital today.</td></tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
          <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm h-fit">
            <h4 className="font-bold text-slate-800 mb-6 flex items-center gap-2"><Building className="h-4 w-4 text-slate-400" /> Stats: {currentHospital?.name}</h4>
            <div className="space-y-4">
              <div className="p-5 bg-green-50 rounded-2xl border border-green-100"><p className="text-[10px] font-black text-green-600 uppercase tracking-widest mb-1">Passes Issued</p><p className="text-3xl font-black text-green-700">{passes.filter(p => p.hospitalId === user.hospitalId && p.passDate === new Date().toISOString().split('T')[0]).length}</p></div>
              <div className="p-5 bg-indigo-50 rounded-2xl border border-indigo-100"><p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest mb-1">Today's Pool</p><p className="text-3xl font-black text-indigo-700">{apps.filter(a => a.hospitalId === user.hospitalId && a.applicationDate === new Date().toISOString().split('T')[0]).length}</p></div>
            </div>
          </div>
        </div>
      )}

      {activeTab === 'approvals' && (
        <section className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
          <h3 className="text-lg font-bold mb-6 text-slate-800">Pending Requests for {currentHospital?.name}</h3>
          <div className="space-y-4">
            {approvals.filter(a => a.hospitalId === user.hospitalId && a.status === 'pending').map(req => {
              const mr = mrs.find(m => m.id === req.mrId);
              return (
                <div key={req.id} className="flex flex-col sm:flex-row justify-between items-start sm:items-center p-5 bg-slate-50 rounded-2xl border border-slate-100 gap-4 transition-all hover:shadow-md">
                  <div className="flex items-center gap-4">
                    <div className="bg-white p-3 rounded-xl shadow-xs cursor-pointer" onClick={() => setSelectedMR(mr || null)}><User className="h-6 w-6 text-indigo-600" /></div>
                    <div>
                      <p className="font-bold text-slate-800 cursor-pointer hover:underline" onClick={() => setSelectedMR(mr || null)}>{mr?.fullName}</p>
                      <p className="text-xs text-slate-500 font-medium">{mr?.companyName}</p>
                    </div>
                  </div>
                  <div className="flex gap-2 w-full sm:w-auto">
                    <button onClick={() => updateApproval(req.id, 'approved')} className="flex-1 bg-green-600 text-white text-xs px-6 py-2.5 rounded-xl font-bold shadow-md hover:bg-green-700 active:scale-95 transition-all">Approve</button>
                    <button onClick={() => updateApproval(req.id, 'rejected')} className="flex-1 bg-white border border-red-100 text-red-600 text-xs px-6 py-2.5 rounded-xl font-bold hover:bg-red-50 active:scale-95 transition-all">Reject</button>
                  </div>
                </div>
              );
            })}
            {approvals.filter(a => a.hospitalId === user.hospitalId && a.status === 'pending').length === 0 && (
              <div className="text-center py-16 text-slate-400">
                <Users className="h-12 w-12 mx-auto mb-4 opacity-10" />
                <p className="italic text-sm">No pending access requests.</p>
              </div>
            )}
          </div>
        </section>
      )}

      {activeTab === 'mrs' && (
        <section className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
          <h3 className="text-lg font-bold mb-6 text-slate-800">Approved Representatives</h3>
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {approvedMRs.map(mr => (
              <div key={mr.id} onClick={() => setSelectedMR(mr)} className="p-5 border border-slate-100 bg-slate-50 rounded-2xl hover:border-indigo-400 cursor-pointer transition-all flex items-center gap-4">
                <div className="bg-white p-3 rounded-xl shadow-sm"><User className="h-6 w-6 text-slate-400" /></div>
                <div>
                  <p className="font-bold text-slate-800">{mr.fullName}</p>
                  <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest">{mr.companyName}</p>
                </div>
              </div>
            ))}
            {approvedMRs.length === 0 && (
              <div className="col-span-full py-12 text-center text-slate-400 italic">No approved MRs for this hospital yet.</div>
            )}
          </div>
        </section>
      )}

      {activeTab === 'config' && editingHospital && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm max-w-3xl">
          <div className="flex items-center justify-between mb-8 pb-6 border-b border-slate-100">
            <div>
              <h3 className="text-2xl font-black text-slate-800 tracking-tight">{currentHospital?.name}</h3>
              <p className="text-sm text-slate-400">Manage internal sessions and limits.</p>
            </div>
            <Settings className="h-8 w-8 text-indigo-600 opacity-20" />
          </div>

          <div className="space-y-8">
            <div className="space-y-4">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Active Sessions & Daily Limits</label>
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                {(['MORNING', 'EVENING', 'FULL_DAY'] as SessionType[]).map(s => {
                  const isSelected = editingHospital.supportedSessions.includes(s);
                  const currentWindow = editingHospital.sessionWindows[s] || { start: '00:00', end: '23:59' };

                  return (
                    <div key={s} className={`p-4 border-2 rounded-2xl transition-all ${isSelected ? 'border-indigo-100 bg-indigo-50 shadow-inner' : 'border-slate-50 bg-slate-50 opacity-50'}`}>
                      <div className="flex items-center gap-2 mb-3">
                        <input 
                          type="checkbox" 
                          checked={isSelected} 
                          onChange={e => {
                            const sessions = editingHospital.supportedSessions;
                            const newSessions = e.target.checked ? [...sessions, s] : sessions.filter(x => x !== s);
                            setEditingHospital({...editingHospital, supportedSessions: newSessions});
                          }}
                          className="w-5 h-5 rounded-lg text-indigo-600 focus:ring-indigo-500 cursor-pointer"
                        />
                        <span className="text-xs font-black text-slate-700 uppercase">{s}</span>
                      </div>

                      <div className="space-y-3">
                        <div className="space-y-1">
                          <label className="text-[9px] font-black text-slate-400 uppercase">Limit</label>
                          <input 
                            type="number" 
                            disabled={!isSelected}
                            value={editingHospital.passLimits[s] || 0}
                            onChange={e => {
                              const limits = { ...editingHospital.passLimits };
                              limits[s] = parseInt(e.target.value) || 0;
                              setEditingHospital({...editingHospital, passLimits: limits});
                            }}
                            className="w-full px-3 py-2 bg-white border border-slate-200 rounded-xl text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-500 disabled:opacity-50"
                          />
                        </div>
                        <div className="grid grid-cols-2 gap-2">
                           <div className="space-y-1">
                            <label className="text-[9px] font-black text-slate-400 uppercase tracking-tighter">Start</label>
                            <input 
                              type="time" 
                              disabled={!isSelected}
                              value={currentWindow.start}
                              onChange={e => {
                                const windows = { ...editingHospital.sessionWindows };
                                windows[s] = { ...currentWindow, start: e.target.value };
                                setEditingHospital({...editingHospital, sessionWindows: windows});
                              }}
                              className="w-full px-2 py-1.5 bg-white border border-slate-200 rounded-lg text-[10px] font-bold outline-none disabled:opacity-50"
