import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Simple in-memory cache to prevent redundant calls and handle 429s gracefully
 */
const responseCache: Record<string, string> = {
  priority: "",
  admin: ""
};

/**
 * Helper to call Gemini with exponential backoff for transient errors
 */
async function generateWithRetry(prompt: string, cacheKey: string, fallback: string, retries = 3, delay = 1000): Promise<string> {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });

    const text = response.text || "";
    if (text) {
      responseCache[cacheKey] = text;
      return text;
    }
    return responseCache[cacheKey] || fallback;
  } catch (error: any) {
    // Handle Rate Limit (429) specifically
    if (error?.status === 429 || error?.message?.includes("429") || error?.message?.includes("quota")) {
      console.warn(`Gemini Quota Exceeded for ${cacheKey}. Using fallback/cache.`);
      if (retries > 0) {
        await new Promise(resolve => setTimeout(resolve, delay));
        return generateWithRetry(prompt, cacheKey, fallback, retries - 1, delay * 2);
      }
      return responseCache[cacheKey] || fallback;
    }

    console.error(`Gemini API Error (${cacheKey}):`, error);
    return responseCache[cacheKey] || fallback;
  }
}

export const getPriorityInsights = async (history: any[]) => {
  const prompt = `Explain the priority score logic to a Medical Representative. 
      Their history: ${JSON.stringify(history)}. 
      Logic rules: 14 days no pass = +5, 7 days no pass = +3, pass in last 3 days = -5, missed entry = -10. 
      Summarize why their score is what it is in 2 friendly sentences.`;

  const defaultFallback = "Priority is calculated based on your recent activity to ensure everyone gets a fair turn. Apply regularly to improve your ranking.";

  return generateWithRetry(prompt, "priority", defaultFallback);
};

export const getAdminBriefing = async (apps: any[], passes: any[]) => {
  const prompt = `Analyze today's booking activity. Applications: ${apps.length}, Passes Issued: ${passes.length}. 
      Give a one-sentence recommendation for tomorrow's pass limit based on this demand.`;

  const defaultFallback = "Demand remains steady. Recommend maintaining current pass limits to ensure facility capacity is not exceeded.";

  return generateWithRetry(prompt, "admin", defaultFallback);
};

