            <div className="p-5 bg-slate-50 rounded-2xl border border-slate-100">
              <div className="flex items-center gap-3 text-slate-400 mb-2">
                <Mail className="h-4 w-4" />
                <span className="text-[10px] font-black uppercase tracking-widest">System Email</span>
              </div>
              <p className="font-bold text-slate-800">admin@{currentHospital?.name.toLowerCase().replace(/\s/g, '')}.gov.lk</p>
            </div>

            <div className="p-5 bg-slate-50 rounded-2xl border border-slate-100">
              <div className="flex items-center gap-3 text-slate-400 mb-2">
                <Clock className="h-4 w-4" />
                <span className="text-[10px] font-black uppercase tracking-widest">Total MR Authorizations</span>
              </div>
              <p className="font-bold text-slate-800">{approvedMRs.length} Approved Reps</p>
            </div>
          </div>

          <div className="mt-10 p-6 bg-indigo-50 rounded-3xl border border-indigo-100 flex items-start gap-4">
             <Info className="h-6 w-6 text-indigo-500 shrink-0" />
             <div>
               <p className="font-bold text-indigo-900 text-sm">Administration Policy</p>
               <p className="text-xs text-indigo-700 leading-relaxed mt-1">As a Hospital Admin, you are responsible for maintaining fair access. Ensure you review representative ID cards during their first physical visit to match the identification number provided in the system.</p>
             </div>
          </div>
        </section>
      )}

      {/* MR Details Modal */}
      {selectedMR && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden animate-in slide-in-from-bottom-4 duration-300">
            <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-bold text-slate-800">MR Profile Verification</h3>
              <button onClick={() => setSelectedMR(null)} className="p-2 hover:bg-slate-200 rounded-full transition-all"><X className="h-5 w-5 text-slate-400" /></button>
            </div>
            <div className="p-8 space-y-6">
              <div className="flex items-center gap-4">
                 <div className="w-16 h-16 bg-indigo-100 rounded-2xl flex items-center justify-center border-2 border-white shadow-sm">
                   <User className="h-8 w-8 text-indigo-600" />
                 </div>
                 <div>
                   <h4 className="text-xl font-black text-slate-800">{selectedMR.fullName}</h4>
                   <p className="text-indigo-600 font-bold text-xs uppercase tracking-widest">{selectedMR.companyName}</p>
                 </div>
              </div>

              <div className="grid grid-cols-1 gap-3">
                <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
                  <p className="text-[10px] font-black text-slate-400 uppercase mb-1 flex items-center gap-1.5"><Phone className="h-3 w-3" /> Mobile Number</p>
                  <p className="font-bold text-slate-700">{selectedMR.mobileNumber}</p>
                </div>
                <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
                  <p className="text-[10px] font-black text-slate-400 uppercase mb-1 flex items-center gap-1.5"><CreditCard className="h-3 w-3" /> Identification Card Number</p>
                  <p className="font-bold text-slate-700">{selectedMR.identificationNumber}</p>
                </div>
                <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
                  <p className="text-[10px] font-black text-slate-400 uppercase mb-1 flex items-center gap-1.5"><ShieldCheck className="h-3 w-3" /> System MR ID</p>
                  <p className="font-bold text-slate-700">{selectedMR.mrId}</p>
                </div>
              </div>

              {/* Context-aware actions: If there's a pending approval, show it here */}
              {approvals.find(a => a.hospitalId === user.hospitalId && a.mrId === selectedMR.id && a.status === 'pending') ? (
                <div className="pt-4 flex gap-3">
                  <button 
                    onClick={() => {
                      const req = approvals.find(a => a.hospitalId === user.hospitalId && a.mrId === selectedMR.id && a.status === 'pending');
                      if (req) updateApproval(req.id, 'approved');
                    }}
                    className="flex-1 bg-green-600 text-white font-bold py-4 rounded-2xl shadow-lg hover:bg-green-700 active:scale-95 transition-all flex items-center justify-center gap-2"
                  >
                    <CheckCircle className="h-5 w-5" /> APPROVE ACCESS
                  </button>
                  <button 
                    onClick={() => {
                      const req = approvals.find(a => a.hospitalId === user.hospitalId && a.mrId === selectedMR.id && a.status === 'pending');
                      if (req) updateApproval(req.id, 'rejected');
                    }}
                    className="flex-1 bg-white border-2 border-red-100 text-red-600 font-bold py-4 rounded-2xl hover:bg-red-50 active:scale-95 transition-all flex items-center justify-center gap-2"
                  >
                    <XCircle className="h-5 w-5" /> REJECT
                  </button>
                </div>
              ) : (
                <button onClick={() => setSelectedMR(null)} className="w-full bg-slate-800 text-white font-bold py-4 rounded-2xl hover:bg-slate-900 transition-all">Close Details</button>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const XCircle = ({ className }: { className?: string }) => (
  <svg className={className} xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <circle cx="12" cy="12" r="10" />
    <path d="m15 9-6 6" />
    <path d="m9 9 6 6" />
  </svg>
);

export default AdminDashboard;

import React, { useState, useEffect, useContext } from 'react';
import { Building2, Users, FileText, Settings, Plus, DollarSign, Power, Activity, Edit3, Trash2, Check, X, ChevronRight, Briefcase, Clock, User, Phone, CreditCard } from 'lucide-react';
import { storageService } from '../services/storageService';
import { Hospital, PharmaCompany, Invoice, MedicalRep, SessionType } from '../types';
import { FeedbackContext } from '../App';

const SuperAdminDashboard: React.FC = () => {
  const { showFeedback } = useContext(FeedbackContext);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [companies, setCompanies] = useState<PharmaCompany[]>([]);
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [activeTab, setActiveTab] = useState<'hospitals' | 'companies' | 'billing' | 'monitoring'>('hospitals');

  // Hospital Config State
  const [isHospitalModalOpen, setIsHospitalModalOpen] = useState(false);
  const [editingHospital, setEditingHospital] = useState<Partial<Hospital> | null>(null);

  // Company State
  const [isCompanyModalOpen, setIsCompanyModalOpen] = useState(false);
  const [editingCompany, setEditingCompany] = useState<Partial<PharmaCompany> | null>(null);
  const [selectedCompanyId, setSelectedCompanyId] = useState<string | null>(null);
  const [selectedMR, setSelectedMR] = useState<MedicalRep | null>(null);

  useEffect(() => {
    refreshData();
  }, []);

  const refreshData = () => {
    setHospitals(storageService.getHospitals());
    setCompanies(storageService.getCompanies());
    setInvoices(storageService.getInvoices());
    setMrs(storageService.getMRs());
  };

  const handleSaveHospital = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingHospital?.name) return;

    const currentHospitals = storageService.getHospitals();
    let updated: Hospital[];

    const hospitalData: Hospital = {
      id: editingHospital.id || 'h' + Date.now(),
      name: editingHospital.name || '',
      isActive: editingHospital.isActive ?? true,
      supportedSessions: editingHospital.supportedSessions || [],
      passLimits: editingHospital.passLimits || {},
      sessionWindows: editingHospital.sessionWindows || {},
    };

    if (editingHospital.id) {
      updated = currentHospitals.map(h => h.id === editingHospital.id ? hospitalData : h);
      showFeedback(`Updated hospital: ${hospitalData.name}`);
    } else {
      updated = [...currentHospitals, hospitalData];
      showFeedback(`Added new hospital: ${hospitalData.name}`);
    }

    storageService.saveHospitals(updated);
    setHospitals(updated);
    setIsHospitalModalOpen(false);
    setEditingHospital(null);
  };

  const toggleHospitalStatus = (id: string) => {
    const updated = hospitals.map(h => h.id === id ? { ...h, isActive: !h.isActive } : h);
    storageService.saveHospitals(updated);
    setHospitals(updated);
    const h = updated.find(x => x.id === id);
    showFeedback(`Hospital ${h?.name} is now ${h?.isActive ? 'active' : 'inactive'}`);
  };

  const handleSaveCompany = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingCompany?.name) return;

    const currentCompanies = storageService.getCompanies();
    let updated: PharmaCompany[];

    if (editingCompany.id) {
      updated = currentCompanies.map(c => c.id === editingCompany.id ? (editingCompany as PharmaCompany) : c);
      showFeedback(`Company ${editingCompany.name} updated.`);
    } else {
      const newC: PharmaCompany = {
        ...(editingCompany as PharmaCompany),
        id: 'c' + Date.now(),
      };
      updated = [...currentCompanies, newC];
      showFeedback(`Company ${newC.name} registered.`);
    }

    storageService.saveCompanies(updated);
    setCompanies(updated);
    setIsCompanyModalOpen(false);
    setEditingCompany(null);
  };

  const calculateBilling = () => {
    const today = new Date().toISOString().split('T')[0];
    const newInvoices: Invoice[] = companies.map(company => {
      const activeMRs = mrs.filter(m => m.companyName === company.name && m.status === 'active').length;
      return {
        id: 'INV-' + Math.random().toString(36).substr(2, 6).toUpperCase(),
        companyId: company.id,
        amount: activeMRs * 250,
        activeMRCount: activeMRs,
        status: 'unpaid',
        date: today
      };
    });
    const updatedInvoices = [...invoices, ...newInvoices];
    storageService.saveInvoices(updatedInvoices);
    setInvoices(updatedInvoices);
    showFeedback("Billing quotations generated for all companies.");
  };

  return (
    <div className="space-y-6">
      <div className="flex bg-white p-1 rounded-xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => {setActiveTab('hospitals'); setSelectedCompanyId(null);}} className={`px-4 md:px-6 py-2 rounded-lg text-sm font-bold flex items-center gap-2 whitespace-nowrap ${activeTab === 'hospitals' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Building2 className="h-4 w-4" /> Hospitals</button>
        <button onClick={() => setActiveTab('companies')} className={`px-4 md:px-6 py-2 rounded-lg text-sm font-bold flex items-center gap-2 whitespace-nowrap ${activeTab === 'companies' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Briefcase className="h-4 w-4" /> Companies</button>
        <button onClick={() => setActiveTab('billing')} className={`px-4 md:px-6 py-2 rounded-lg text-sm font-bold flex items-center gap-2 whitespace-nowrap ${activeTab === 'billing' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><DollarSign className="h-4 w-4" /> Billing</button>
        <button onClick={() => setActiveTab('monitoring')} className={`px-4 md:px-6 py-2 rounded-lg text-sm font-bold flex items-center gap-2 whitespace-nowrap ${activeTab === 'monitoring' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Activity className="h-4 w-4" /> Monitoring</button>
      </div>

      {activeTab === 'hospitals' && (
        <section className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
          <div className="flex justify-between items-center mb-6">
            <div>
              <h3 className="text-lg font-bold">Hospital Network Control</h3>
              <p className="text-sm text-slate-500">Configure global hospital network settings.</p>
            </div>
            <button 
              onClick={() => { setEditingHospital({ supportedSessions: ['MORNING'], passLimits: { 'MORNING': 10 }, sessionWindows: { 'MORNING': { start: '18:00', end: '18:10' } } }); setIsHospitalModalOpen(true); }}
              className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-sm font-bold flex items-center gap-2 hover:bg-indigo-700 transition-all shadow-md active:scale-95"
            >
              <Plus className="h-4 w-4" /> Add Hospital
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {hospitals.map(h => (
              <div key={h.id} className="group p-5 border border-slate-100 bg-slate-50 rounded-2xl hover:shadow-lg transition-all relative overflow-hidden">
                <div className={`absolute top-0 right-0 w-1 h-full ${h.isActive ? 'bg-green-500' : 'bg-red-500'}`}></div>
                <div className="flex justify-between items-start mb-4">
                  <div>
                    <h4 className="font-bold text-slate-800 text-lg">{h.name}</h4>
                    <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${h.isActive ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                      {h.isActive ? 'ACTIVE' : 'INACTIVE'}
                    </span>
                  </div>
                  <button 
                    onClick={() => { setEditingHospital(h); setIsHospitalModalOpen(true); }}
                    className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all"
                  >
                    <Edit3 className="h-4 w-4" />
                  </button>
                </div>

                <div className="space-y-4">
                  {h.supportedSessions.map(sess => (
                    <div key={sess} className="p-3 bg-white rounded-xl border border-slate-100 shadow-xs">
                      <div className="flex items-center justify-between mb-2">
                        <span className="text-[10px] font-black text-indigo-600 uppercase tracking-widest">{sess}</span>
                        <span className="text-[10px] font-bold text-slate-400">{h.passLimits[sess] || 0} Passes</span>
                      </div>
                      <div className="flex items-center gap-2 text-xs text-slate-500">
                        <Clock className="h-3 w-3" />
                        <span className="font-bold text-slate-700">
                          {h.sessionWindows?.[sess]?.start || 'N/A'} - {h.sessionWindows?.[sess]?.end || 'N/A'}
                        </span>
                      </div>
                    </div>
                  ))}
                </div>

                <div className="mt-6 flex gap-2">
                  <button 
                    onClick={() => toggleHospitalStatus(h.id)}
                    className={`flex-1 py-2 rounded-xl text-xs font-bold transition-all border ${h.isActive ? 'border-red-200 text-red-600 hover:bg-red-50' : 'border-green-200 text-green-600 hover:bg-green-50'}`}
                  >
                    {h.isActive ? 'Suspend' : 'Activate'}
                  </button>
                </div>
              </div>
            ))}
          </div>
        </section>
      )}

      {activeTab === 'companies' && (
        <section className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
          <div className="flex justify-between items-center mb-6">
            <div>
              <h3 className="text-lg font-bold">Pharma Companies</h3>
              <p className="text-sm text-slate-500">Registered pharmaceutical companies and their staff.</p>
            </div>
            <button 
              onClick={() => { setEditingCompany({}); setIsCompanyModalOpen(true); }}
              className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-sm font-bold flex items-center gap-2 hover:bg-indigo-700 transition-all shadow-md"
            >
              <Plus className="h-4 w-4" /> Add Company
            </button>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-1 space-y-4">
              {companies.map(c => {
                const companyMRCount = mrs.filter(m => m.companyName === c.name).length;
                return (
                  <button 
                    key={c.id}
                    onClick={() => setSelectedCompanyId(c.id)}
                    className={`w-full text-left p-4 rounded-xl border transition-all ${selectedCompanyId === c.id ? 'border-indigo-600 bg-indigo-50 shadow-sm' : 'border-slate-100 bg-slate-50 hover:bg-slate-100'}`}
                  >
                    <div className="flex justify-between items-start">
                      <h4 className="font-bold text-slate-800">{c.name}</h4>
                      <ChevronRight className={`h-4 w-4 transition-transform ${selectedCompanyId === c.id ? 'rotate-90 text-indigo-600' : 'text-slate-400'}`} />
                    </div>
                    <div className="flex items-center justify-between mt-2">
                      <p className="text-xs text-slate-500">{c.contactEmail}</p>
                      <span className="bg-white px-2 py-0.5 rounded text-[10px] font-bold text-slate-600 shadow-xs">{companyMRCount} MRs</span>
                    </div>
                  </button>
                );
              })}
            </div>

            <div className="lg:col-span-2">
              {selectedCompanyId ? (
                <div className="bg-slate-50 rounded-2xl border border-slate-100 overflow-hidden animate-in fade-in slide-in-from-right duration-300">
                  <div className="bg-white p-4 border-b border-slate-100 flex justify-between items-center">
                    <h4 className="font-bold text-slate-800">
                      Representatives: {companies.find(c => c.id === selectedCompanyId)?.name}
                    </h4>
                  </div>
                  <div className="p-4 overflow-x-auto">
                    <table className="w-full text-left text-xs">
                      <thead className="text-slate-500 uppercase font-black text-[9px] tracking-widest">
                        <tr>
                          <th className="px-4 py-2">Name</th>
                          <th className="px-4 py-2">ID Number</th>
                          <th className="px-4 py-2">Status</th>
                          <th className="px-4 py-2 text-right">Profile</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-200">
                        {mrs.filter(m => m.companyName === companies.find(c => c.id === selectedCompanyId)?.name).map(mr => (
                          <tr key={mr.id} className="hover:bg-white transition-colors">
                            <td className="px-4 py-3 font-bold text-slate-800">{mr.fullName}</td>
                            <td className="px-4 py-3 text-slate-600 font-mono">{mr.identificationNumber}</td>
                            <td className="px-4 py-3">
                              <span className={`px-2 py-0.5 rounded-full text-[9px] font-bold ${mr.status === 'active' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                                {mr.status.toUpperCase()}
                              </span>
                            </td>
                            <td className="px-4 py-3 text-right">
                               <button onClick={() => setSelectedMR(mr)} className="text-indigo-600 hover:text-indigo-800 font-bold">View Details</button>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              ) : (
                <div className="h-full flex flex-col items-center justify-center p-12 bg-slate-50 rounded-2xl border border-dashed border-slate-200 text-slate-400">
                  <Briefcase className="h-12 w-12 mb-4 opacity-20" />
                  <p className="text-sm">Select a company to view representatives.</p>
                </div>
              )}
            </div>
          </div>
        </section>
      )}

      {/* MR Details Modal */}
      {selectedMR && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden animate-in slide-in-from-bottom-4 duration-300">
            <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-bold text-slate-800">MR Detailed Profile</h3>
              <button onClick={() => setSelectedMR(null)} className="p-2 hover:bg-slate-200 rounded-full transition-all"><X className="h-5 w-5 text-slate-400" /></button>
            </div>
            <div className="p-8 space-y-6">
              <div className="flex flex-col items-center">
                 <div className="w-20 h-20 bg-indigo-100 rounded-full flex items-center justify-center border-4 border-slate-50 shadow-sm mb-4">
                   <User className="h-10 w-10 text-indigo-600" />
                 </div>
                 <h4 className="text-2xl font-black text-slate-800">{selectedMR.fullName}</h4>
                 <p className="text-indigo-600 font-bold text-xs uppercase tracking-widest">{selectedMR.companyName}</p>
              </div>

              <div className="grid grid-cols-1 gap-4">
                <div className="flex items-center gap-4 p-4 bg-slate-50 rounded-2xl">
                  <Phone className="h-5 w-5 text-slate-400" />
                  <div>
                    <p className="text-[10px] font-black text-slate-400 uppercase">Contact Mobile</p>
                    <p className="font-bold text-slate-700">{selectedMR.mobileNumber}</p>
                  </div>
                </div>
                <div className="flex items-center gap-4 p-4 bg-slate-50 rounded-2xl">
                  <CreditCard className="h-5 w-5 text-slate-400" />
                  <div>
                    <p className="text-[10px] font-black text-slate-400 uppercase">Identification ID</p>
                    <p className="font-bold text-slate-700">{selectedMR.identificationNumber}</p>
                  </div>
                </div>
                <div className="flex items-center gap-4 p-4 bg-slate-50 rounded-2xl">
                  <FileText className="h-5 w-5 text-slate-400" />
                  <div>
                    <p className="text-[10px] font-black text-slate-400 uppercase">MR Designation ID</p>
                    <p className="font-bold text-slate-700">{selectedMR.mrId}</p>
                  </div>
                </div>
              </div>

              <button onClick={() => setSelectedMR(null)} className="w-full bg-slate-800 text-white font-bold py-4 rounded-2xl hover:bg-slate-900 transition-all">Close Profile</button>
            </div>
          </div>
        </div>
      )}

      {/* Hospital Config Modal */}
      {isHospitalModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-2xl rounded-3xl shadow-2xl overflow-hidden animate-in slide-in-from-bottom-4 duration-300">
            <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-bold text-slate-800">{editingHospital?.id ? 'Edit Hospital' : 'Add New Hospital'}</h3>
              <button onClick={() => setIsHospitalModalOpen(false)} className="p-2 hover:bg-slate-200 rounded-full transition-all"><X className="h-5 w-5 text-slate-400" /></button>
            </div>
            <form onSubmit={handleSaveHospital} className="p-6 space-y-6">
              <div className="space-y-4">
                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Hospital Name</label>
                  <input 
                    required 
                    type="text" 
                    value={editingHospital?.name || ''} 
                    onChange={e => setEditingHospital({...editingHospital, name: e.target.value})} 
                    className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 transition-all"
                  />
                </div>

                <div className="space-y-4">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Configure Default Sessions</label>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    {(['MORNING', 'EVENING', 'FULL_DAY'] as SessionType[]).map(s => {
                      const isSelected = editingHospital?.supportedSessions?.includes(s);
                      return (
                        <div key={s} className={`p-4 border rounded-2xl transition-all ${isSelected ? 'border-indigo-100 bg-indigo-50' : 'border-slate-100 bg-slate-50 opacity-40'}`}>
                           <div className="flex items-center gap-3">
                              <input 
                                type="checkbox" 
                                checked={isSelected} 
                                onChange={e => {
                                  const sessions = editingHospital?.supportedSessions || [];
                                  const newSessions = e.target.checked ? [...sessions, s] : sessions.filter(x => x !== s);
                                  setEditingHospital({...editingHospital, supportedSessions: newSessions});
                                }}
                                className="w-5 h-5 rounded text-indigo-600"
                              />
