import React, { useState, useContext } from 'react';
import { ShieldCheck, Search, QrCode, User, CheckCircle, XCircle } from 'lucide-react';
import { storageService } from '../services/storageService';
import { IssuedPass, MedicalRep } from '../types';
import { FeedbackContext } from '../App';

const SecurityView: React.FC = () => {
  const { showFeedback } = useContext(FeedbackContext);
  const [passId, setPassId] = useState('');
  const [scannedPass, setScannedPass] = useState<IssuedPass | null>(null);
  const [mrDetails, setMrDetails] = useState<MedicalRep | null>(null);
  const [error, setError] = useState('');

  const handleScan = () => {
    setError('');
    const passes = storageService.getPasses();
    const pass = passes.find(p => p.id === passId || p.qrCode === passId);

    if (!pass) {
      setError("Pass not found or invalid.");
      showFeedback("Invalid Pass ID", 'error');
      setScannedPass(null);
      return;
    }

    const today = new Date().toISOString().split('T')[0];
    if (pass.passDate !== today) {
      setError(`Pass is for another date: ${pass.passDate}`);
      showFeedback(`Pass expired or for a different date: ${pass.passDate}`, 'error');
      setScannedPass(null);
      return;
    }

    if (pass.entryStatus === 'entered') {
      setError("Pass already used for entry.");
      showFeedback("Pass already used.", 'error');
      setScannedPass(null);
      return;
    }

    if (pass.entryStatus === 'expired') {
      setError("Pass has expired.");
      showFeedback("This pass has expired.", 'error');
      setScannedPass(null);
      return;
    }

    const mr = storageService.getMRs().find(m => m.id === pass.mrId);
    setScannedPass(pass);
    setMrDetails(mr || null);
    showFeedback("Pass verified. Please check representative identity.");
  };

  const confirmEntry = () => {
    if (!scannedPass) return;

    const allPasses = storageService.getPasses();
    const updatedPasses = allPasses.map(p => 
      p.id === scannedPass.id ? { ...p, entryStatus: 'entered' as const } : p
    );

    const log = {
      id: Math.random().toString(36).substr(2, 9),
      issuedPassId: scannedPass.id,
      entryTime: new Date().toISOString(),
      verifiedBy: 'Security-1'
    };

    const allLogs = storageService.getLogs();
    storageService.savePasses(updatedPasses);
    storageService.saveLogs([...allLogs, log]);

    showFeedback(`Entry confirmed for ${mrDetails?.fullName}`);
    setScannedPass(null);
    setMrDetails(null);
    setPassId('');
  };

  return (
    <div className="max-w-2xl mx-auto">
      <section className="bg-white p-8 rounded-3xl shadow-xl border border-slate-100 text-center">
        <div className="bg-indigo-100 p-4 rounded-full w-fit mx-auto mb-6">
          <ShieldCheck className="h-10 w-10 text-indigo-600" />
        </div>
        <h3 className="text-2xl font-bold text-slate-800 mb-2">Gate Verification</h3>
        <p className="text-slate-500 mb-8">Scan QR code or enter Pass ID manually</p>

        <div className="flex gap-2 mb-6">
          <div className="relative flex-1">
            <input 
              type="text" 
              value={passId}
              onChange={(e) => setPassId(e.target.value)}
              placeholder="Enter Pass ID (e.g., PASS-ABC123)"
              className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-indigo-500 transition-all font-mono"
            />
            <QrCode className="absolute left-4 top-1/2 -translate-y-1/2 h-6 w-6 text-slate-400" />
          </div>
          <button 
            onClick={handleScan}
            className="bg-indigo-600 text-white px-8 py-4 rounded-2xl font-bold hover:bg-indigo-700 active:scale-95 transition-all shadow-lg flex items-center gap-2"
          >
            <Search className="h-5 w-5" />
            Verify
          </button>
        </div>

        {error && (
          <div className="flex items-center gap-2 p-4 bg-red-50 text-red-700 rounded-xl mb-6">
            <XCircle className="h-5 w-5" />
            <p className="font-bold text-sm">{error}</p>
          </div>
        )}

        {scannedPass && mrDetails && (
          <div className="text-left border-2 border-green-100 bg-green-50/30 rounded-3xl p-6 animate-in fade-in zoom-in duration-300">
            <div className="flex items-center gap-4 mb-6 pb-6 border-b border-green-100">
              <div className="bg-white p-3 rounded-2xl shadow-sm">
                <User className="h-8 w-8 text-indigo-600" />
              </div>
              <div>
                <p className="text-sm font-bold text-indigo-600 uppercase tracking-wider">Representative</p>
                <p className="text-xl font-black text-slate-800">{mrDetails.fullName}</p>
                <p className="text-slate-500">{mrDetails.companyName}</p>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-6 mb-8">
              <div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Pass ID</p>
                <p className="font-mono text-lg font-bold text-slate-800">{scannedPass.id}</p>
              </div>
              <div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Time Slot</p>
                <p className="text-lg font-bold text-slate-800">{scannedPass.timeSlot}</p>
              </div>
            </div>

            <button 
              onClick={confirmEntry}
              className="w-full bg-green-600 text-white py-4 rounded-2xl font-black text-lg shadow-xl hover:bg-green-700 active:scale-[0.98] transition-all flex items-center justify-center gap-3"
            >
              <CheckCircle className="h-6 w-6" />
              ALLOW ENTRY
            </button>
          </div>
        )}
      </section>

      <div className="mt-8 grid grid-cols-2 gap-4">
        <div className="p-4 bg-slate-100 rounded-2xl text-xs text-slate-500">
          <p className="font-bold mb-1">Single Use Rule</p>
          Each pass is unique and can only be used once per day.
        </div>
        <div className="p-4 bg-slate-100 rounded-2xl text-xs text-slate-500">
          <p className="font-bold mb-1">ID Verification</p>
          Security must cross-verify the name with the MR's physical ID card.
        </div>
      </div>
    </div>
  );
};

export default SecurityView;

export type MRStatus = 'active' | 'suspended';
export type ApplicationStatus = 'applied' | 'selected' | 'waitlisted' | 'rejected';
export type EntryStatus = 'not_entered' | 'entered' | 'expired';
export type UserRole = 'MR' | 'ADMIN' | 'SECURITY' | 'SUPER_ADMIN';
export type ApprovalStatus = 'pending' | 'approved' | 'rejected';
export type SessionType = 'MORNING' | 'EVENING' | 'FULL_DAY';

export interface MedicalRep {
  id: string;
  fullName: string;
  companyName: string; // Used for PharmaCompany linking
  mrId: string;
  mobileNumber: string;
  identificationNumber: string; // Valid ID for signup
  status: MRStatus;
  createdAt: string;
}

export interface Hospital {
  id: string;
  name: string;
  supportedSessions: SessionType[];
  passLimits: Record<string, number>; // e.g., { 'MORNING': 15 }
  sessionWindows: Record<string, { start: string; end: string }>; // e.g., { 'MORNING': { start: '18:00', end: '18:10' } }
  isActive: boolean;
}

export interface HospitalUser {
  id: string;
  hospitalId: string;
  mobileNumber: string;
  role: 'ADMIN' | 'SECURITY';
  fullName: string;
}

export interface MRHospitalApproval {
  id: string;
  mrId: string;
  hospitalId: string;
  status: ApprovalStatus;
  updatedAt: string;
}

export interface PassApplication {
  id: string;
  mrId: string;
  hospitalId: string;
  session: SessionType;
  applicationDate: string;
  priorityScore: number;
  status: ApplicationStatus;
  createdAt: string;
}

export interface IssuedPass {
  id: string;
  mrId: string;
  hospitalId: string;
  session: SessionType;
  passDate: string;
  timeSlot: string;
  qrCode: string;
  entryStatus: EntryStatus;
}

export interface PharmaCompany {
  id: string;
  name: string;
  contactEmail: string;
}

export interface Invoice {
  id: string;
  companyId: string;
  amount: number;
  activeMRCount: number;
  status: 'paid' | 'unpaid';
  date: string;
}

export interface EntryLog {
  id: string;
  issuedPassId: string;
  entryTime: string;
  verifiedBy: string;
}

// User in session
export interface AuthUser {
  id: string;
  role: UserRole;
  fullName: string;
  mobileNumber?: string;
  hospitalId?: string; // For hospital admins
  companyName?: string; // For MRs
}

import { MedicalRep, Hospital, PassApplication, IssuedPass, EntryLog, MRHospitalApproval, PharmaCompany, Invoice, HospitalUser, AuthUser } from '../types';

