                        <input required type="text" value={adminData.mobileNumber} onChange={e => setAdminData({...adminData, mobileNumber: e.target.value})} className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg text-xs font-bold outline-none" placeholder="e.g., 0771234567" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[9px] font-black text-indigo-400 uppercase">Password</label>
                        <input required type="text" value={adminData.password} onChange={e => setAdminData({...adminData, password: e.target.value})} className="w-full px-3 py-2 bg-white border border-indigo-200 rounded-lg text-xs font-bold outline-none focus:ring-1 focus:ring-indigo-400" placeholder="Set password" />
