                  </div>
                  <div className="flex gap-2 w-full sm:w-auto">
                    <button onClick={() => setSelectedMR(mr || null)} className="flex-1 bg-white border border-slate-200 text-slate-600 text-xs px-6 py-2.5 rounded-xl font-bold hover:bg-slate-50 transition-all flex items-center justify-center gap-1.5">View Full Details <ChevronRight className="h-3 w-3" /></button>
