                    <div key={s} className={`p-4 border-2 rounded-2xl transition-all ${isSelected ? 'border-indigo-100 bg-indigo-50 shadow-inner' : 'border-slate-50 bg-slate-50 opacity-50'}`}>
                      <div className="flex items-center gap-2 mb-3">
                        <input 
                          type="checkbox" 
                          checked={isSelected} 
                          onChange={e => {
                            const sessions = editingHospital.supportedSessions;
                            const newSessions = e.target.checked ? [...sessions, s] : sessions.filter(x => x !== s);
                            setEditingHospital({...editingHospital, supportedSessions: newSessions});
                          }}
                          className="w-5 h-5 rounded-lg text-indigo-600 focus:ring-indigo-500 cursor-pointer"
                        />
                        <span className="text-xs font-black text-slate-700 uppercase">{s}</span>
                      </div>

                      <div className="space-y-3">
                        <div className="space-y-1">
                          <label className="text-[9px] font-black text-slate-400 uppercase">Limit</label>
                          <input 
                            type="number" 
                            disabled={!isSelected}
                            value={editingHospital.passLimits[s] || 0}
                            onChange={e => {
                              const limits = { ...editingHospital.passLimits };
                              limits[s] = parseInt(e.target.value) || 0;
                              setEditingHospital({...editingHospital, passLimits: limits});
                            }}
                            className="w-full px-3 py-2 bg-white border border-slate-200 rounded-xl text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-500 disabled:opacity-50"
                          />
                        </div>
                        <div className="grid grid-cols-2 gap-2">
                           <div className="space-y-1">
                            <label className="text-[9px] font-black text-slate-400 uppercase tracking-tighter">Start</label>
                            <input 
                              type="time" 
                              disabled={!isSelected}
                              value={currentWindow.start}
                              onChange={e => {
                                const windows = { ...editingHospital.sessionWindows };
                                windows[s] = { ...currentWindow, start: e.target.value };
                                setEditingHospital({...editingHospital, sessionWindows: windows});
                              }}
                              className="w-full px-2 py-1.5 bg-white border border-slate-200 rounded-lg text-[10px] font-bold outline-none disabled:opacity-50"
                            />
                          </div>
                          <div className="space-y-1">
                            <label className="text-[9px] font-black text-slate-400 uppercase tracking-tighter">End</label>
                            <input 
                              type="time" 
                              disabled={!isSelected}
                              value={currentWindow.end}
                              onChange={e => {
                                const windows = { ...editingHospital.sessionWindows };
                                windows[s] = { ...currentWindow, end: e.target.value };
                                setEditingHospital({...editingHospital, sessionWindows: windows});
                              }}
                              className="w-full px-2 py-1.5 bg-white border border-slate-200 rounded-lg text-[10px] font-bold outline-none disabled:opacity-50"
                            />
                          </div>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>

            <div className="pt-6 border-t border-slate-100 flex gap-4">
              <button 
                onClick={handleSaveConfig}
                className="flex-1 bg-indigo-600 text-white py-4 rounded-2xl font-black text-sm shadow-xl hover:bg-indigo-700 active:scale-[0.98] transition-all flex items-center justify-center gap-2"
              >
                <Save className="h-5 w-5" /> SAVE CONFIG
              </button>
            </div>
          </div>
        </section>
      )}

      {activeTab === 'profile' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm max-w-3xl mx-auto">
          <div className="text-center mb-10">
            <div className="w-24 h-24 bg-indigo-100 rounded-3xl flex items-center justify-center mx-auto mb-4 border-4 border-white shadow-lg rotate-3 group-hover:rotate-0 transition-transform">
              <Building className="h-12 w-12 text-indigo-600" />
            </div>
            <h3 className="text-3xl font-black text-slate-800 tracking-tight">{currentHospital?.name}</h3>
            <p className="text-indigo-600 font-bold text-sm tracking-widest uppercase mt-1">Hospital Administration</p>
          </div>

          <div className="grid gap-4 sm:grid-cols-2">
            <div className="p-5 bg-slate-50 rounded-2xl border border-slate-100">
              <div className="flex items-center gap-3 text-slate-400 mb-2">
                <ShieldCheck className="h-4 w-4" />
                <span className="text-[10px] font-black uppercase tracking-widest">Admin Name</span>
              </div>
              <p className="font-bold text-slate-800">{user.fullName}</p>
            </div>

            <div className="p-5 bg-slate-50 rounded-2xl border border-slate-100">
              <div className="flex items-center gap-3 text-slate-400 mb-2">
                <MapPin className="h-4 w-4" />
                <span className="text-[10px] font-black uppercase tracking-widest">Facility Status</span>
              </div>
              <p className="font-bold text-green-600 flex items-center gap-1.5">
                <CheckCircle className="h-4 w-4" /> Active Facility
              </p>
            </div>

            <div className="p-5 bg-slate-50 rounded-2xl border border-slate-100">
              <div className="flex items-center gap-3 text-slate-400 mb-2">
                <Mail className="h-4 w-4" />
                <span className="text-[10px] font-black uppercase tracking-widest">System Email</span>
              </div>
              <p className="font-bold text-slate-800">admin@{currentHospital?.name.toLowerCase().replace(/\s/g, '')}.gov.lk</p>
            </div>

            <div className="p-5 bg-slate-50 rounded-2xl border border-slate-100">
              <div className="flex items-center gap-3 text-slate-400 mb-2">
                <Clock className="h-4 w-4" />
                <span className="text-[10px] font-black uppercase tracking-widest">Authorized Reps</span>
              </div>
              <p className="font-bold text-slate-800">{approvedMRs.length} Approved Reps</p>
