          </div>

          <div className="mt-10 p-6 bg-indigo-50 rounded-3xl border border-indigo-100 flex items-start gap-4">
             <Info className="h-6 w-6 text-indigo-500 shrink-0" />
             <div>
               <p className="font-bold text-indigo-900 text-sm">Administration Policy</p>
               <p className="text-xs text-indigo-700 leading-relaxed mt-1">As a Hospital Admin, you are responsible for maintaining fair access. Ensure you review representative ID cards during their first physical visit to match the identification number provided in the system.</p>
             </div>
          </div>
        </section>
      )}

      {/* MR Details Modal */}
      {selectedMR && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden animate-in slide-in-from-bottom-4 duration-300">
            <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-bold text-slate-800">MR Profile Verification</h3>
              <button onClick={() => setSelectedMR(null)} className="p-2 hover:bg-slate-200 rounded-full transition-all"><X className="h-5 w-5 text-slate-400" /></button>
            </div>
            <div className="p-8 space-y-6">
              <div className="flex items-center gap-4">
                 <div className="w-16 h-16 bg-indigo-100 rounded-2xl flex items-center justify-center border-2 border-white shadow-sm">
                   <User className="h-8 w-8 text-indigo-600" />
                 </div>
                 <div>
                   <h4 className="text-xl font-black text-slate-800">{selectedMR.fullName}</h4>
                   <p className="text-indigo-600 font-bold text-xs uppercase tracking-widest">{selectedMR.companyName}</p>
                 </div>
              </div>

              <div className="grid grid-cols-1 gap-3">
                <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
                  <p className="text-[10px] font-black text-slate-400 uppercase mb-1 flex items-center gap-1.5"><Phone className="h-3 w-3" /> Mobile Number</p>
                  <p className="font-bold text-slate-700">{selectedMR.mobileNumber}</p>
                </div>
                <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
                  <p className="text-[10px] font-black text-slate-400 uppercase mb-1 flex items-center gap-1.5"><CreditCard className="h-3 w-3" /> Identification Card Number</p>
                  <p className="font-bold text-slate-700">{selectedMR.identificationNumber}</p>
                </div>
                <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
                  <p className="text-[10px] font-black text-slate-400 uppercase mb-1 flex items-center gap-1.5"><ShieldCheck className="h-3 w-3" /> System MR ID</p>
                  <p className="font-bold text-slate-700">{selectedMR.mrId}</p>
                </div>
              </div>

              {/* Context-aware actions: If there's a pending approval, show it here */}
              {approvals.find(a => a.hospitalId === user.hospitalId && a.mrId === selectedMR.id && a.status === 'pending') ? (
                <div className="pt-4 flex gap-3">
                  <button 
                    onClick={() => {
                      const req = approvals.find(a => a.hospitalId === user.hospitalId && a.mrId === selectedMR.id && a.status === 'pending');
                      if (req) updateApproval(req.id, 'approved');
                    }}
                    className="flex-1 bg-green-600 text-white font-bold py-4 rounded-2xl shadow-lg hover:bg-green-700 active:scale-95 transition-all flex items-center justify-center gap-2"
                  >
                    <CheckCircle className="h-5 w-5" /> APPROVE ACCESS
                  </button>
                  <button 
                    onClick={() => {
                      const req = approvals.find(a => a.hospitalId === user.hospitalId && a.mrId === selectedMR.id && a.status === 'pending');
                      if (req) updateApproval(req.id, 'rejected');
                    }}
                    className="flex-1 bg-white border-2 border-red-100 text-red-600 font-bold py-4 rounded-2xl hover:bg-red-50 active:scale-95 transition-all flex items-center justify-center gap-2"
                  >
                    <XCircle className="h-5 w-5" /> REJECT
                  </button>
                </div>
              ) : (
                <button onClick={() => setSelectedMR(null)} className="w-full bg-slate-800 text-white font-bold py-4 rounded-2xl hover:bg-slate-900 transition-all">Close Details</button>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const XCircle = ({ className }: { className?: string }) => (
  <svg className={className} xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <circle cx="12" cy="12" r="10" />
    <path d="m15 9-6 6" />
    <path d="m9 9 6 6" />
  </svg>
);

export default AdminDashboard;

import React, { useState, useEffect, useContext } from 'react';
import { Building2, Users, FileText, Settings, Plus, DollarSign, Power, Activity, Edit3, Trash2, Check, X, ChevronRight, Briefcase, Clock, User, Phone, CreditCard, ShieldCheck, Lock } from 'lucide-react';
import { storageService } from '../services/storageService';
import { Hospital, PharmaCompany, Invoice, MedicalRep, SessionType, HospitalUser } from '../types';
import { FeedbackContext } from '../App';

const SuperAdminDashboard: React.FC = () => {
  const { showFeedback } = useContext(FeedbackContext);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [companies, setCompanies] = useState<PharmaCompany[]>([]);
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [activeTab, setActiveTab] = useState<'hospitals' | 'companies' | 'billing' | 'monitoring'>('hospitals');

  // Hospital Config State
  const [isHospitalModalOpen, setIsHospitalModalOpen] = useState(false);
  const [editingHospital, setEditingHospital] = useState<Partial<Hospital> | null>(null);
  const [adminData, setAdminData] = useState({ fullName: '', mobileNumber: '', password: '' });
  const [securityData, setSecurityData] = useState({ fullName: '', mobileNumber: '', password: '' });

  // Company State
  const [isCompanyModalOpen, setIsCompanyModalOpen] = useState(false);
  const [editingCompany, setEditingCompany] = useState<Partial<PharmaCompany> | null>(null);
  const [selectedCompanyId, setSelectedCompanyId] = useState<string | null>(null);
  const [selectedMR, setSelectedMR] = useState<MedicalRep | null>(null);

  useEffect(() => {
    refreshData();
  }, []);

  const refreshData = () => {
    setHospitals(storageService.getHospitals());
    setCompanies(storageService.getCompanies());
    setInvoices(storageService.getInvoices());
    setMrs(storageService.getMRs());
  };

  const handleEditHospital = (h: Hospital) => {
    setEditingHospital(h);
    const users = storageService.getHospitalUsers();
    const admin = users.find(u => u.hospitalId === h.id && u.role === 'ADMIN');
    const security = users.find(u => u.hospitalId === h.id && u.role === 'SECURITY');
    setAdminData({ 
      fullName: admin?.fullName || '', 
      mobileNumber: admin?.mobileNumber || '', 
      password: admin?.password || '' 
    });
    setSecurityData({ 
      fullName: security?.fullName || '', 
      mobileNumber: security?.mobileNumber || '', 
      password: security?.password || '' 
    });
    setIsHospitalModalOpen(true);
  };

  const handleSaveHospital = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingHospital?.name) return;

    const currentHospitals = storageService.getHospitals();
    const currentUsers = storageService.getHospitalUsers();

    const hospitalId = editingHospital.id || 'h' + Date.now();

    const hospitalData: Hospital = {
      id: hospitalId,
      name: editingHospital.name || '',
      isActive: editingHospital.isActive ?? true,
      supportedSessions: editingHospital.supportedSessions || [],
      passLimits: editingHospital.passLimits || {},
      sessionWindows: editingHospital.sessionWindows || {},
    };

    // 1. Update/Save Hospital
    let updatedHospitals: Hospital[];
    if (editingHospital.id) {
      updatedHospitals = currentHospitals.map(h => h.id === editingHospital.id ? hospitalData : h);
    } else {
      updatedHospitals = [...currentHospitals, hospitalData];
    }
    storageService.saveHospitals(updatedHospitals);
    setHospitals(updatedHospitals);

    // 2. Update/Save Admin & Security Credentials
    const otherUsers = currentUsers.filter(u => u.hospitalId !== hospitalId);
    const newUsers: HospitalUser[] = [
      ...otherUsers,
      {
        id: `u-adm-${hospitalId}`,
        hospitalId: hospitalId,
        role: 'ADMIN',
        fullName: adminData.fullName,
        mobileNumber: adminData.mobileNumber,
        password: adminData.password
      },
      {
        id: `u-sec-${hospitalId}`,
        hospitalId: hospitalId,
        role: 'SECURITY',
        fullName: securityData.fullName,
        mobileNumber: securityData.mobileNumber,
        password: securityData.password
      }
    ];
    storageService.saveHospitalUsers(newUsers);

    showFeedback(`Facility configuration for ${hospitalData.name} saved successfully.`);
    setIsHospitalModalOpen(false);
    setEditingHospital(null);
    setAdminData({ fullName: '', mobileNumber: '', password: '' });
    setSecurityData({ fullName: '', mobileNumber: '', password: '' });
  };

  const handleSaveCompany = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingCompany?.name) return;

    const currentCompanies = storageService.getCompanies();
    let updated: PharmaCompany[];

    const companyData: PharmaCompany = {
      id: editingCompany.id || 'c' + Date.now(),
      name: editingCompany.name || '',
      contactEmail: editingCompany.contactEmail || '',
      isActive: editingCompany.isActive ?? true,
    };

    if (editingCompany.id) {
      updated = currentCompanies.map(c => c.id === editingCompany.id ? companyData : c);
      showFeedback(`Company ${companyData.name} updated.`);
    } else {
      updated = [...currentCompanies, companyData];
      showFeedback(`Company ${companyData.name} registered.`);
    }

    storageService.saveCompanies(updated);
    setCompanies(updated);
    setIsCompanyModalOpen(false);
    setEditingCompany(null);
  };

  const toggleCompanyStatus = (id: string) => {
    const updated = companies.map(c => c.id === id ? { ...c, isActive: !c.isActive } : c);
    storageService.saveCompanies(updated);
    setCompanies(updated);
    const c = updated.find(x => x.id === id);
    showFeedback(`Company ${c?.name} is now ${c?.isActive ? 'active' : 'deactivated'}`);
  };

  const calculateBilling = () => {
    const today = new Date().toISOString().split('T')[0];
    const newInvoices: Invoice[] = companies.filter(c => c.isActive).map(company => {
      const activeMRs = mrs.filter(m => m.companyName === company.name && m.status === 'active').length;
      return {
        id: 'INV-' + Math.random().toString(36).substr(2, 6).toUpperCase(),
        companyId: company.id,
        amount: activeMRs * 250,
        activeMRCount: activeMRs,
        status: 'unpaid',
        date: today
      };
    });
    const updatedInvoices = [...invoices, ...newInvoices];
    storageService.saveInvoices(updatedInvoices);
    setInvoices(updatedInvoices);
    showFeedback("Billing quotations generated for active companies.");
  };

  return (
    <div className="space-y-6">
      <div className="flex bg-white p-1 rounded-xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => {setActiveTab('hospitals'); setSelectedCompanyId(null);}} className={`px-4 md:px-6 py-2 rounded-lg text-sm font-bold flex items-center gap-2 whitespace-nowrap ${activeTab === 'hospitals' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Building2 className="h-4 w-4" /> Hospitals</button>
        <button onClick={() => setActiveTab('companies')} className={`px-4 md:px-6 py-2 rounded-lg text-sm font-bold flex items-center gap-2 whitespace-nowrap ${activeTab === 'companies' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Briefcase className="h-4 w-4" /> Companies</button>
        <button onClick={() => setActiveTab('billing')} className={`px-4 md:px-6 py-2 rounded-lg text-sm font-bold flex items-center gap-2 whitespace-nowrap ${activeTab === 'billing' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><DollarSign className="h-4 w-4" /> Billing</button>
        <button onClick={() => setActiveTab('monitoring')} className={`px-4 md:px-6 py-2 rounded-lg text-sm font-bold flex items-center gap-2 whitespace-nowrap ${activeTab === 'monitoring' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Activity className="h-4 w-4" /> Monitoring</button>
      </div>

      {activeTab === 'hospitals' && (
        <section className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
          <div className="flex justify-between items-center mb-6">
            <div>
              <h3 className="text-lg font-bold">Facility Management</h3>
              <p className="text-sm text-slate-500">Provision hospitals and staff credentials.</p>
            </div>
            <button 
              onClick={() => { setEditingHospital({ supportedSessions: ['MORNING'], passLimits: { 'MORNING': 10 }, sessionWindows: { 'MORNING': { start: '00:00', end: '23:59' } } }); setIsHospitalModalOpen(true); }}
              className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-sm font-bold flex items-center gap-2 hover:bg-indigo-700 transition-all shadow-md active:scale-95"
            >
              <Plus className="h-4 w-4" /> New Hospital
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {hospitals.map(h => (
              <div key={h.id} className="group p-5 border border-slate-100 bg-slate-50 rounded-2xl hover:shadow-lg transition-all relative overflow-hidden">
                <div className={`absolute top-0 right-0 w-1 h-full ${h.isActive ? 'bg-green-500' : 'bg-red-500'}`}></div>
                <div className="flex justify-between items-start mb-4">
                  <div>
                    <h4 className="font-bold text-slate-800 text-lg">{h.name}</h4>
                    <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${h.isActive ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                      {h.isActive ? 'ACTIVE' : 'INACTIVE'}
                    </span>
                  </div>
                  <button 
                    onClick={() => handleEditHospital(h)}
                    className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all"
                  >
                    <Edit3 className="h-4 w-4" />
                  </button>
                </div>

                <div className="pt-4 border-t border-slate-200">
                    <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-2">Login Accounts</p>
                    <div className="space-y-2">
                       <div className="p-2 bg-white rounded-lg border border-slate-100 flex items-center justify-between">
                          <div>
                            <p className="text-[8px] font-bold text-slate-400 uppercase">Admin</p>
                            <p className="text-[10px] font-bold text-slate-800">{storageService.getHospitalUsers().find(u => u.hospitalId === h.id && u.role === 'ADMIN')?.mobileNumber || 'None'}</p>
                          </div>
                          <Lock className="h-3 w-3 text-green-500 opacity-50" />
                       </div>
                       <div className="p-2 bg-white rounded-lg border border-slate-100 flex items-center justify-between">
                          <div>
                            <p className="text-[8px] font-bold text-slate-400 uppercase">Security</p>
                            <p className="text-[10px] font-bold text-slate-800">{storageService.getHospitalUsers().find(u => u.hospitalId === h.id && u.role === 'SECURITY')?.mobileNumber || 'None'}</p>
                          </div>
                          <Lock className="h-3 w-3 text-indigo-500 opacity-50" />
                       </div>
                    </div>
                </div>
              </div>
            ))}
          </div>
        </section>
      )}

      {activeTab === 'companies' && (
        <section className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
          <div className="flex justify-between items-center mb-6">
            <div>
              <h3 className="text-lg font-bold">Pharma Companies & Active Members</h3>
              <p className="text-sm text-slate-500">Manage pharma organizations and monitor their representative pool.</p>
            </div>
            <button 
              onClick={() => { setEditingCompany({ isActive: true }); setIsCompanyModalOpen(true); }}
              className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-sm font-bold flex items-center gap-2 hover:bg-indigo-700 transition-all shadow-md"
            >
              <Plus className="h-4 w-4" /> New Company
            </button>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-1 space-y-3">
              {companies.map(c => {
                const companyMRCount = mrs.filter(m => m.companyName === c.name && m.status === 'active').length;
                return (
                  <button 
                    key={c.id}
                    onClick={() => setSelectedCompanyId(c.id)}
                    className={`w-full text-left p-4 rounded-2xl border transition-all ${selectedCompanyId === c.id ? 'border-indigo-600 bg-indigo-50 shadow-sm' : 'border-slate-100 bg-slate-50 hover:bg-slate-100'}`}
                  >
                    <div className="flex justify-between items-center">
                      <h4 className="font-bold text-slate-800">{c.name}</h4>
                      <div className={`w-2 h-2 rounded-full ${c.isActive ? 'bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.5)]' : 'bg-slate-300'}`}></div>
                    </div>
                    <div className="flex items-center justify-between mt-3">
                      <p className="text-[10px] text-slate-500 font-medium truncate max-w-[120px]">{c.contactEmail}</p>
                      <span className="bg-white px-2 py-0.5 rounded text-[10px] font-black text-indigo-600 shadow-xs uppercase tracking-tighter">{companyMRCount} Active Members</span>
                    </div>
                  </button>
                );
              })}
            </div>

            <div className="lg:col-span-2">
              {selectedCompanyId ? (
                <div className="bg-slate-50 rounded-2xl border border-slate-100 overflow-hidden animate-in fade-in slide-in-from-right duration-300">
