export default SuperAdminDashboard;

export type MRStatus = 'active' | 'suspended';
export type ApplicationStatus = 'applied' | 'selected' | 'waitlisted' | 'rejected';
export type EntryStatus = 'not_entered' | 'entered' | 'expired';
export type UserRole = 'MR' | 'ADMIN' | 'SECURITY' | 'SUPER_ADMIN' | 'COMPANY_ADMIN';
export type ApprovalStatus = 'pending' | 'approved' | 'rejected';
export type SessionType = 'MORNING' | 'EVENING' | 'FULL_DAY';

export interface MedicalRep {
  id: string;
  fullName: string;
  email: string;
  companyName: string;
  mrId: string; // Internal system ID
  slcpiId: string;
  mobileNumber: string; // Personal mobile
  signupCode: string; // Company issued code
  identificationNumber: string; // NIC/ID Number
  status: MRStatus;
  createdAt: string;
}

export interface Hospital {
  id: string;
  name: string;
  supportedSessions: SessionType[];
  passLimits: Record<string, number>;
  sessionWindows: Record<string, { start: string; end: string }>;
  isActive: boolean;
}

export interface HospitalUser {
  id: string;
  hospitalId: string;
  mobileNumber: string;
  password: string;     
  role: 'ADMIN' | 'SECURITY';
  fullName: string;
}

export interface MRHospitalApproval {
  id: string;
  mrId: string;
  hospitalId: string;
  status: ApprovalStatus;
  updatedAt: string;
}

export interface PassApplication {
  id: string;
  mrId: string;
  hospitalId: string;
  session: SessionType;
  applicationDate: string;
  priorityScore: number;
  status: ApplicationStatus;
  createdAt: string;
}

export interface IssuedPass {
  id: string;
  mrId: string;
  hospitalId: string;
  session: SessionType;
  passDate: string;
  timeSlot: string;
  qrCode: string;
  entryStatus: EntryStatus;
}

export interface PharmaCompany {
  id: string;
  name: string;
  contactEmail: string;
  companyCode: string; // Unique code for MR signup
  adminMobile: string; // Admin login
  adminPassword: string; // Admin password
  isActive: boolean;
}

export interface Invoice {
  id: string;
  companyId: string;
  amount: number;
  activeMRCount: number;
  status: 'paid' | 'unpaid';
  date: string;
}

export interface EntryLog {
  id: string;
  issuedPassId: string;
  entryTime: string;
  verifiedBy: string;
}

export interface AuthUser {
  id: string;
  role: UserRole;
  fullName: string;
  mobileNumber?: string;
  hospitalId?: string;
  companyId?: string; // For Company Admins
  companyName?: string; // For MRs
}

