};

const App: React.FC = () => {
  const [user, setUser] = useState<any>(null);
  const [view, setView] = useState<'LOGIN' | 'REGISTER' | 'DASHBOARD'>('LOGIN');
  const [role, setRole] = useState<UserRole>('MR');
  const [mobile, setMobile] = useState('');
  const [password, setPassword] = useState('');
  const [feedback, setFeedback] = useState<{ message: string, type: 'success' | 'error' } | null>(null);

  const [signupData, setSignupData] = useState({
    fullName: '',
    email: '',
    mobileNumber: '',
    companyName: '',
    identificationNumber: '',
    slcpiId: '',
    signupCode: ''
  });

  useEffect(() => {
    const session = storageService.getCurrentUser();
    if (session) { setUser(session); setView('DASHBOARD'); }
  }, []);

  const showFeedback = (message: string, type: 'success' | 'error' = 'success') => {
    setFeedback({ message, type });
  };

  const performLogin = (targetRole: UserRole, targetMobile: string, targetPassword?: string) => {
    if (targetRole === 'MR') {
      const mrs = storageService.getMRs();
      const existing = mrs.find(m => m.mobileNumber === targetMobile || m.email === targetMobile);
      if (existing) {
        const u: AuthUser = { id: existing.id, fullName: existing.fullName, role: 'MR', companyName: existing.companyName, mobileNumber: existing.mobileNumber };
        storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
        showFeedback(`Welcome back, ${u.fullName}!`);
      } else {
        showFeedback("Representative not found.", 'error');
      }
    } else if (targetRole === 'COMPANY_ADMIN') {
      const companies = storageService.getCompanies();
      const found = companies.find(c => c.adminMobile === targetMobile);
      if (found && found.adminPassword === targetPassword) {
        const u: AuthUser = { id: found.id, role: 'COMPANY_ADMIN', fullName: `${found.name} Admin`, companyId: found.id };
        storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
        showFeedback(`Welcome, ${found.name} Administrator`);
      } else {
        showFeedback("Invalid Company Admin credentials.", 'error');
      }
    } else if (targetRole === 'ADMIN' || targetRole === 'SECURITY') {
      const hospitalUsers = storageService.getHospitalUsers();
      const found = hospitalUsers.find(u => u.mobileNumber === targetMobile && u.role === targetRole);
      if (found && found.password === targetPassword) {
        const u: AuthUser = { id: found.id, role: found.role, fullName: found.fullName, hospitalId: found.hospitalId, mobileNumber: found.mobileNumber };
        storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
        showFeedback(`Logged in as ${found.fullName}`);
      } else {
        showFeedback("Invalid credentials.", 'error');
      }
    } else if (targetRole === 'SUPER_ADMIN') {
      if (targetMobile === 'root' && targetPassword === 'root') {
        const u: AuthUser = { id: 'sa-1', role: 'SUPER_ADMIN', fullName: 'MedPass Authority' };
        storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
        showFeedback("Super Admin session started.");
      } else {
        showFeedback("Invalid Super Admin Credentials", 'error');
      }
    }
  };

  const handleLogin = (e?: React.FormEvent) => {
    e?.preventDefault();
    performLogin(role, mobile, password);
  };

  const quickLogin = (r: UserRole, m: string, p: string = '') => {
    setRole(r);
    setMobile(m);
    setPassword(p);
    performLogin(r, m, p);
  };

  const handleSignup = (e: React.FormEvent) => {
    e.preventDefault();
    const mrs = storageService.getMRs();
    const companies = storageService.getCompanies();
    const company = companies.find(c => c.name.toLowerCase() === signupData.companyName.toLowerCase() && c.companyCode === signupData.signupCode);

    if (!company) {
      showFeedback("Invalid Company Name or Registration Code.", "error");
      return;
    }
    if (!company.isActive) {
      showFeedback("Company account is inactive.", "error");
      return;
    }

    const newMR: MedicalRep = {
      id: 'mr-' + Date.now(),
      fullName: signupData.fullName,
      email: signupData.email,
      mobileNumber: signupData.mobileNumber,
      companyName: company.name,
      identificationNumber: signupData.identificationNumber,
      slcpiId: signupData.slcpiId,
      signupCode: signupData.signupCode,
      mrId: 'MR-' + Math.floor(1000 + Math.random() * 9000),
      status: 'active',
      createdAt: new Date().toISOString()
    };

    storageService.saveMRs([...mrs, newMR]);
    showFeedback("Registration complete! Please log in.");
    setView('LOGIN');
    setMobile(signupData.mobileNumber);
  };

  if (view === 'LOGIN' || view === 'REGISTER') {
    return (
      <FeedbackContext.Provider value={{ showFeedback }}>
        <div className="min-h-screen bg-indigo-600 flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-lg rounded-3xl shadow-2xl overflow-hidden">
            <div className="bg-slate-50 p-8 text-center border-b border-slate-100">
              <div className="bg-indigo-600 w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-4"><HospitalIcon className="h-10 w-10 text-white" /></div>
              <h1 className="text-2xl font-black text-slate-800 tracking-tighter">MedPass Engine</h1>
            </div>
            <div className="p-8">
              {view === 'LOGIN' ? (
                <>
                  <div className="mb-6 bg-indigo-50 rounded-xl p-4">
                    <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-2">Quick Access Keys</p>
                    <div className="grid grid-cols-2 gap-2">
                      <button onClick={() => quickLogin('MR', '0771234567')} className="p-2 bg-white border border-indigo-100 rounded text-[10px] font-bold text-slate-700 flex flex-col items-center"><User className="h-3 w-3 mb-1" /> MR John</button>
                      <button onClick={() => quickLogin('COMPANY_ADMIN', '0779', 'pfiz')} className="p-2 bg-indigo-50 border border-indigo-100 rounded text-[10px] font-bold text-indigo-700 flex flex-col items-center"><Briefcase className="h-3 w-3 mb-1" /> Pharma Admin</button>
                      <button onClick={() => quickLogin('ADMIN', '0771', 'admin')} className="p-2 bg-slate-50 border border-slate-100 rounded text-[10px] font-bold text-slate-700 flex flex-col items-center"><ShieldCheck className="h-3 w-3 mb-1" /> Hospital Admin</button>
                      <button onClick={() => quickLogin('SUPER_ADMIN', 'root', 'root')} className="p-2 bg-slate-800 border border-slate-700 rounded text-[10px] font-bold text-white flex flex-col items-center"><Crown className="h-3 w-3 mb-1" /> Super Root</button>
                    </div>
                  </div>
                  <div className="flex bg-slate-100 p-1 rounded-xl mb-6 overflow-x-auto scrollbar-hide">
                    {(['MR', 'COMPANY_ADMIN', 'ADMIN', 'SECURITY', 'SUPER_ADMIN'] as const).map(r => (
                      <button key={r} onClick={() => setRole(r)} className={`flex-1 min-w-[70px] py-1.5 text-[10px] font-black rounded-lg transition-all ${role === r ? 'bg-white text-indigo-600 shadow' : 'text-slate-400'}`}>{r}</button>
                    ))}
                  </div>
                  <form onSubmit={handleLogin} className="space-y-4">
                    <input type="text" value={mobile} onChange={e => setMobile(e.target.value)} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 font-bold" placeholder="Mobile / Email / ID" />
                    {role !== 'MR' && (
                      <div className="relative">
                        <input type="password" value={password} onChange={e => setPassword(e.target.value)} className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 font-bold" placeholder="••••••••" />
                        <Lock className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-300" />
                      </div>
                    )}
                    <button type="submit" className="w-full bg-indigo-600 text-white font-black py-4 rounded-xl shadow-lg hover:bg-indigo-700 transition-all flex items-center justify-center gap-2">LOG IN <ArrowRight className="h-5 w-5" /></button>
                  </form>
                  <div className="mt-6 text-center text-xs text-slate-500">
                    New MR? <button onClick={() => setView('REGISTER')} className="text-indigo-600 font-bold hover:underline">Register Account</button>
                  </div>
                </>
              ) : (
                <form onSubmit={handleSignup} className="space-y-4 max-h-[65vh] overflow-y-auto pr-1">
                  <input required type="text" value={signupData.fullName} onChange={e => setSignupData({...signupData, fullName: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold" placeholder="Full Legal Name" />
                  <input required type="email" value={signupData.email} onChange={e => setSignupData({...signupData, email: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold" placeholder="Email Address" />
                  <input required type="tel" value={signupData.mobileNumber} onChange={e => setSignupData({...signupData, mobileNumber: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold" placeholder="Personal Mobile" />
                  <input required type="text" value={signupData.companyName} onChange={e => setSignupData({...signupData, companyName: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold" placeholder="Pharma Company Name" />
                  <input required type="text" value={signupData.slcpiId} onChange={e => setSignupData({...signupData, slcpiId: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold" placeholder="SLCPI ID" />
                  <input required type="text" value={signupData.identificationNumber} onChange={e => setSignupData({...signupData, identificationNumber: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold" placeholder="NIC / ID Card Number" />
                  <input required type="text" value={signupData.signupCode} onChange={e => setSignupData({...signupData, signupCode: e.target.value})} className="w-full px-4 py-3 bg-indigo-50 border border-indigo-200 rounded-xl text-sm font-black text-indigo-700" placeholder="Company Registration Code" />
                  <div className="pt-4 flex flex-col gap-2">
                    <button type="submit" className="w-full bg-indigo-600 text-white font-black py-4 rounded-xl shadow-lg">CREATE ACCOUNT</button>
                    <button type="button" onClick={() => setView('LOGIN')} className="text-sm text-slate-500 font-bold">Back to Login</button>
                  </div>
                </form>
              )}
            </div>
          </div>
        </div>
        {feedback && <FeedbackToast message={feedback.message} type={feedback.type} onClose={() => setFeedback(null)} />}
      </FeedbackContext.Provider>
    );
  }

  return (
    <FeedbackContext.Provider value={{ showFeedback }}>
      <Layout user={user} onLogout={() => { storageService.clearSession(); setUser(null); setView('LOGIN'); showFeedback("Session ended"); }} title={`${user.fullName} Panel`}>
        {user.role === 'MR' && <MRDashboard user={user} />}
        {user.role === 'COMPANY_ADMIN' && <CompanyAdminDashboard user={user} />}
        {user.role === 'ADMIN' && <AdminDashboard user={user} />}
        {user.role === 'SUPER_ADMIN' && <SuperAdminDashboard />}
        {user.role === 'SECURITY' && <SecurityView />}
      </Layout>
      {feedback && <FeedbackToast message={feedback.message} type={feedback.type} onClose={() => setFeedback(null)} />}
    </FeedbackContext.Provider>
  );
};

export default App;

import React, { useState, useEffect, useContext } from 'react';
import { Building2, Users, FileText, Settings, Plus, DollarSign, Activity, Edit3, X, Briefcase, User, Phone, CreditCard, ShieldCheck, Lock, Mail, Key } from 'lucide-react';
import { storageService } from '../services/storageService';
import { Hospital, PharmaCompany, Invoice, MedicalRep, SessionType, HospitalUser } from '../types';
import { FeedbackContext } from '../App';

const SuperAdminDashboard: React.FC = () => {
  const { showFeedback } = useContext(FeedbackContext);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [companies, setCompanies] = useState<PharmaCompany[]>([]);
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [activeTab, setActiveTab] = useState<'hospitals' | 'companies' | 'billing' | 'monitoring'>('hospitals');

  const [isHospitalModalOpen, setIsHospitalModalOpen] = useState(false);
  const [editingHospital, setEditingHospital] = useState<Partial<Hospital> | null>(null);
  const [adminData, setAdminData] = useState({ fullName: '', mobileNumber: '', password: '' });
  const [securityData, setSecurityData] = useState({ fullName: '', mobileNumber: '', password: '' });

  const [isCompanyModalOpen, setIsCompanyModalOpen] = useState(false);
  const [editingCompany, setEditingCompany] = useState<Partial<PharmaCompany> | null>(null);
  const [selectedCompanyId, setSelectedCompanyId] = useState<string | null>(null);
  const [selectedMR, setSelectedMR] = useState<MedicalRep | null>(null);

  useEffect(() => { refreshData(); }, []);

  const refreshData = () => {
    setHospitals(storageService.getHospitals());
    setCompanies(storageService.getCompanies());
    setInvoices(storageService.getInvoices());
    setMrs(storageService.getMRs());
  };

  const handleEditHospital = (h: Hospital) => {
    setEditingHospital(h);
    const users = storageService.getHospitalUsers();
    const admin = users.find(u => u.hospitalId === h.id && u.role === 'ADMIN');
    const security = users.find(u => u.hospitalId === h.id && u.role === 'SECURITY');
    setAdminData({ fullName: admin?.fullName || '', mobileNumber: admin?.mobileNumber || '', password: admin?.password || '' });
    setSecurityData({ fullName: security?.fullName || '', mobileNumber: security?.mobileNumber || '', password: security?.password || '' });
    setIsHospitalModalOpen(true);
  };

  const handleSaveHospital = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingHospital?.name) return;
    const currentHospitals = storageService.getHospitals();
    const currentUsers = storageService.getHospitalUsers();
    const hospitalId = editingHospital.id || 'h' + Date.now();
    const hospitalData: Hospital = {
      id: hospitalId,
      name: editingHospital.name || '',
      isActive: editingHospital.isActive ?? true,
      supportedSessions: editingHospital.supportedSessions || [],
      passLimits: editingHospital.passLimits || {},
      sessionWindows: editingHospital.sessionWindows || {},
    };
    storageService.saveHospitals(editingHospital.id ? currentHospitals.map(h => h.id === editingHospital.id ? hospitalData : h) : [...currentHospitals, hospitalData]);
    const otherUsers = currentUsers.filter(u => u.hospitalId !== hospitalId);
    storageService.saveHospitalUsers([...otherUsers, { id: `u-adm-${hospitalId}`, hospitalId: hospitalId, role: 'ADMIN', fullName: adminData.fullName, mobileNumber: adminData.mobileNumber, password: adminData.password }, { id: `u-sec-${hospitalId}`, hospitalId: hospitalId, role: 'SECURITY', fullName: securityData.fullName, mobileNumber: securityData.mobileNumber, password: securityData.password }]);
    showFeedback(`Facility configuration for ${hospitalData.name} saved successfully.`);
    setIsHospitalModalOpen(false);
    refreshData();
  };

  const handleSaveCompany = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingCompany?.name) return;
    const currentCompanies = storageService.getCompanies();
    const companyData: PharmaCompany = { 
      id: editingCompany.id || 'c' + Date.now(), 
      name: editingCompany.name || '', 
      contactEmail: editingCompany.contactEmail || '', 
      companyCode: editingCompany.companyCode || Math.random().toString(36).substr(2, 6).toUpperCase(),
      adminMobile: editingCompany.adminMobile || '',
      adminPassword: editingCompany.adminPassword || '',
      isActive: editingCompany.isActive ?? true 
    };
    storageService.saveCompanies(editingCompany.id ? currentCompanies.map(c => c.id === editingCompany.id ? companyData : c) : [...currentCompanies, companyData]);
    showFeedback(`Company ${companyData.name} saved with code: ${companyData.companyCode}`);
    setIsCompanyModalOpen(false);
    refreshData();
  };

  const toggleCompanyStatus = (id: string) => {
    const updated = companies.map(c => c.id === id ? { ...c, isActive: !c.isActive } : c);
    storageService.saveCompanies(updated);
    setCompanies(updated);
    showFeedback(`Company status updated.`);
  };

  return (
    <div className="space-y-6">
      <div className="flex bg-white p-1 rounded-xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => {setActiveTab('hospitals'); setSelectedCompanyId(null);}} className={`px-4 md:px-6 py-2 rounded-lg text-sm font-bold flex items-center gap-2 whitespace-nowrap ${activeTab === 'hospitals' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Building2 className="h-4 w-4" /> Hospitals</button>
        <button onClick={() => setActiveTab('companies')} className={`px-4 md:px-6 py-2 rounded-lg text-sm font-bold flex items-center gap-2 whitespace-nowrap ${activeTab === 'companies' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Briefcase className="h-4 w-4" /> Companies</button>
        <button onClick={() => setActiveTab('billing')} className={`px-4 md:px-6 py-2 rounded-lg text-sm font-bold flex items-center gap-2 whitespace-nowrap ${activeTab === 'billing' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><DollarSign className="h-4 w-4" /> Billing</button>
        <button onClick={() => setActiveTab('monitoring')} className={`px-4 md:px-6 py-2 rounded-lg text-sm font-bold flex items-center gap-2 whitespace-nowrap ${activeTab === 'monitoring' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Activity className="h-4 w-4" /> Monitoring</button>
      </div>

      {activeTab === 'companies' && (
        <section className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-lg font-bold">Pharma Companies & Admin Credentials</h3>
            <button onClick={() => { setEditingCompany({ isActive: true }); setIsCompanyModalOpen(true); }} className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-sm font-bold flex items-center gap-2 shadow-md"><Plus className="h-4 w-4" /> New Company</button>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-1 space-y-3">
              {companies.map(c => (
                <button key={c.id} onClick={() => setSelectedCompanyId(c.id)} className={`w-full text-left p-4 rounded-2xl border transition-all ${selectedCompanyId === c.id ? 'border-indigo-600 bg-indigo-50 shadow-sm' : 'border-slate-100 bg-slate-50 hover:bg-slate-100'}`}>
                  <div className="flex justify-between items-center">
                    <h4 className="font-bold text-slate-800">{c.name}</h4>
                    <div className={`w-2 h-2 rounded-full ${c.isActive ? 'bg-green-500' : 'bg-slate-300'}`}></div>
                  </div>
                  <div className="flex items-center justify-between mt-3">
                    <p className="text-[10px] font-black text-indigo-500 tracking-widest uppercase">{c.companyCode}</p>
                    <span className="bg-white px-2 py-0.5 rounded text-[10px] font-black text-indigo-600 shadow-xs uppercase tracking-tighter">{mrs.filter(m => m.companyName === c.name).length} Reps</span>
                  </div>
                </button>
              ))}
            </div>

            <div className="lg:col-span-2">
              {selectedCompanyId ? (
                <div className="bg-slate-50 rounded-2xl border border-slate-100 overflow-hidden">
                  <div className="bg-white p-4 border-b border-slate-100 flex justify-between items-center">
                    <h4 className="font-bold text-slate-800 flex items-center gap-2"><Briefcase className="h-4 w-4" /> {companies.find(c => c.id === selectedCompanyId)?.name} Admin Panel</h4>
                    <div className="flex gap-2">
                       <button onClick={() => setEditingCompany(companies.find(c => c.id === selectedCompanyId))} className="text-[10px] font-bold text-slate-500 border border-slate-200 px-3 py-1 rounded-lg">Edit Details</button>
                       <button onClick={() => toggleCompanyStatus(selectedCompanyId)} className="text-[10px] font-bold text-red-600 border border-red-100 px-3 py-1 rounded-lg">Toggle Status</button>
                    </div>
                  </div>
                  <div className="p-6 grid grid-cols-1 sm:grid-cols-2 gap-4">
                     <div className="bg-white p-4 rounded-xl border border-slate-100 shadow-xs">
                        <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest mb-1">Admin ID / Login</p>
                        <p className="font-bold text-slate-700">{companies.find(c => c.id === selectedCompanyId)?.adminMobile}</p>
                     </div>
                     <div className="bg-white p-4 rounded-xl border border-slate-100 shadow-xs">
                        <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest mb-1">Signup/Registration Code</p>
                        <p className="font-black text-indigo-600 uppercase">{companies.find(c => c.id === selectedCompanyId)?.companyCode}</p>
                     </div>
                  </div>
                </div>
              ) : <div className="h-full min-h-[300px] flex items-center justify-center text-slate-400 italic">Select a pharmaceutical company to manage its administrative details.</div>}
            </div>
          </div>
        </section>
      )}

      {/* Pharma Company Modal */}
      {isCompanyModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden">
            <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-bold text-slate-800">{editingCompany?.id ? 'Provision Admin' : 'Register New Pharma'}</h3>
              <button onClick={() => setIsCompanyModalOpen(false)} className="p-2 hover:bg-slate-200 rounded-full transition-all"><X className="h-5 w-5 text-slate-400" /></button>
            </div>
            <form onSubmit={handleSaveCompany} className="p-8 space-y-4">
              <div className="space-y-4">
                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Pharma Name</label>
                  <input required type="text" value={editingCompany?.name || ''} onChange={e => setEditingCompany({...editingCompany, name: e.target.value})} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 font-bold" />
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="text-[10px] font-black text-indigo-500 uppercase tracking-widest mb-1 block">Admin Mobile ID</label>
                    <input required type="text" value={editingCompany?.adminMobile || ''} onChange={e => setEditingCompany({...editingCompany, adminMobile: e.target.value})} className="w-full px-4 py-2.5 bg-indigo-50 border border-indigo-100 rounded-xl font-bold" />
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-indigo-500 uppercase tracking-widest mb-1 block">Admin Password</label>
                    <input required type="text" value={editingCompany?.adminPassword || ''} onChange={e => setEditingCompany({...editingCompany, adminPassword: e.target.value})} className="w-full px-4 py-2.5 bg-indigo-50 border border-indigo-100 rounded-xl font-bold" />
                  </div>
                </div>
                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Company Code (Registration)</label>
                  <input type="text" value={editingCompany?.companyCode || ''} onChange={e => setEditingCompany({...editingCompany, companyCode: e.target.value})} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl font-mono text-sm" placeholder="Auto-generated if blank" />
                </div>
              </div>
              <div className="flex gap-3 pt-4">
                <button type="button" onClick={() => setIsCompanyModalOpen(false)} className="flex-1 px-6 py-3 text-slate-600 font-bold">Cancel</button>
                <button type="submit" className="flex-1 bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-xl active:scale-95 transition-all">SAVE PROFILE</button>
              </div>
            </form>
          </div>
        </div>
      )}
      {/* monitoring/hospitals/billing tabs remain functional as before */}
    </div>
  );
};

export default SuperAdminDashboard;

import React, { useState, useEffect, useContext } from 'react';
import { Users, UserPlus, Search, Briefcase, Mail, Phone, ShieldCheck, CreditCard, X, Edit3, Trash2, Power, User, Key, Building } from 'lucide-react';
import { storageService } from '../services/storageService';
import { MedicalRep, PharmaCompany, AuthUser } from '../types';
import { FeedbackContext } from '../App';

interface CompanyAdminDashboardProps {
  user: AuthUser;
}

const CompanyAdminDashboard: React.FC<CompanyAdminDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [company, setCompany] = useState<PharmaCompany | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [isAddMRModalOpen, setIsAddMRModalOpen] = useState(false);
  const [selectedMR, setSelectedMR] = useState<MedicalRep | null>(null);

  const [newMR, setNewMR] = useState<Partial<MedicalRep>>({
    fullName: '',
    email: '',
    mobileNumber: '',
    slcpiId: '',
    identificationNumber: ''
  });

  useEffect(() => {
    refreshData();
  }, []);

  const refreshData = () => {
    const allCompanies = storageService.getCompanies();
    const myCompany = allCompanies.find(c => c.id === user.companyId);
    if (myCompany) {
      setCompany(myCompany);
      const allMRs = storageService.getMRs();
      setMrs(allMRs.filter(m => m.companyName === myCompany.name));
    }
  };

  const handleAddMR = (e: React.FormEvent) => {
    e.preventDefault();
    if (!company) return;

    const allMRs = storageService.getMRs();
    const createdMR: MedicalRep = {
      id: 'mr-' + Date.now(),
      fullName: newMR.fullName || '',
      email: newMR.email || '',
      mobileNumber: newMR.mobileNumber || '',
      companyName: company.name,
      mrId: 'MR-' + Math.floor(1000 + Math.random() * 9000),
      slcpiId: newMR.slcpiId || '',
      signupCode: company.companyCode,
      identificationNumber: newMR.identificationNumber || '',
      status: 'active',
      createdAt: new Date().toISOString()
    };

    storageService.saveMRs([...allMRs, createdMR]);
    showFeedback(`Representative ${createdMR.fullName} provisioned successfully.`);
    setIsAddMRModalOpen(false);
    setNewMR({ fullName: '', email: '', mobileNumber: '', slcpiId: '', identificationNumber: '' });
    refreshData();
  };

  const toggleMRStatus = (id: string) => {
    const allMRs = storageService.getMRs();
    const updated = allMRs.map(m => 
      m.id === id ? { ...m, status: m.status === 'active' ? 'suspended' as const : 'active' as const } : m
    );
    storageService.saveMRs(updated);
    showFeedback("Representative status changed.");
    refreshData();
  };

  const filteredMRs = mrs.filter(m => 
    m.fullName.toLowerCase().includes(searchTerm.toLowerCase()) || 
    m.mrId.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-indigo-600 rounded-3xl p-6 text-white shadow-xl relative overflow-hidden">
          <Building className="absolute -right-4 -bottom-4 h-24 w-24 opacity-10" />
          <p className="text-xs font-black uppercase tracking-widest mb-1 opacity-80">Pharma Organization</p>
          <h3 className="text-2xl font-black truncate">{company?.name || "Company Admin"}</h3>
          <p className="text-[10px] font-bold mt-2 bg-indigo-500/50 w-fit px-2 py-0.5 rounded tracking-widest">REGISTRATION CODE: {company?.companyCode}</p>
        </div>
        <div className="bg-white rounded-3xl p-6 border border-slate-100 shadow-sm flex flex-col justify-between">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Active Pool</p>
          <h3 className="text-3xl font-black text-slate-800">{mrs.length} Representatives</h3>
          <p className="text-xs text-green-500 font-bold mt-2">Active: {mrs.filter(m => m.status === 'active').length}</p>
        </div>
        <div className="bg-white rounded-3xl p-6 border border-slate-100 shadow-sm flex items-center justify-center">
          <button 
            onClick={() => setIsAddMRModalOpen(true)}
            className="w-full bg-indigo-50 text-indigo-600 font-black py-4 rounded-2xl border-2 border-dashed border-indigo-200 hover:bg-indigo-100 transition-all flex items-center justify-center gap-2"
          >
            <UserPlus className="h-5 w-5" /> REGISTER NEW MR
          </button>
        </div>
      </div>

      <section className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-6">
          <h3 className="text-lg font-bold flex items-center gap-2">Member Management</h3>
          <div className="relative w-full sm:w-64">
             <input 
               type="text" 
               placeholder="Search name or MR ID..." 
               value={searchTerm}
               onChange={e => setSearchTerm(e.target.value)}
               className="w-full pl-9 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold focus:ring-2 focus:ring-indigo-500 outline-none"
             />
             <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-slate-400" />
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest">
                <th className="px-4 py-3">Representative</th>
                <th className="px-4 py-3">SLCPI ID</th>
                <th className="px-4 py-3">System ID</th>
                <th className="px-4 py-3">Status</th>
                <th className="px-4 py-3 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredMRs.map(mr => (
                <tr key={mr.id} className="hover:bg-slate-50/50 transition-colors">
                  <td className="px-4 py-4">
                    <div className="flex items-center gap-3">
                      <div className="bg-slate-100 p-2 rounded-lg"><User className="h-4 w-4 text-slate-500" /></div>
                      <div>
                        <p className="font-bold text-slate-800 text-sm">{mr.fullName}</p>
                        <p className="text-[10px] text-slate-400">{mr.email}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-4 py-4 font-mono text-xs font-bold text-slate-600">{mr.slcpiId}</td>
                  <td className="px-4 py-4 font-mono text-xs font-bold text-indigo-600">{mr.mrId}</td>
                  <td className="px-4 py-4">
                    <span className={`px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-tighter ${mr.status === 'active' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>{mr.status}</span>
                  </td>
                  <td className="px-4 py-4 text-right">
                    <div className="flex justify-end gap-2">
                       <button onClick={() => setSelectedMR(mr)} className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all"><Edit3 className="h-4 w-4" /></button>
                       <button onClick={() => toggleMRStatus(mr.id)} className={`p-2 rounded-lg transition-all ${mr.status === 'active' ? 'text-red-400 hover:text-red-600 hover:bg-red-50' : 'text-green-400 hover:text-green-600 hover:bg-green-50'}`}><Power className="h-4 w-4" /></button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>

      {isAddMRModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in duration-200">
            <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-bold text-slate-800">Add Representative</h3>
              <button onClick={() => setIsAddMRModalOpen(false)} className="p-2 hover:bg-slate-200 rounded-full transition-all"><X className="h-5 w-5 text-slate-400" /></button>
            </div>
            <form onSubmit={handleAddMR} className="p-8 space-y-4">
               <div className="space-y-4">
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Full Legal Name</label>
                    <input required type="text" value={newMR.fullName} onChange={e => setNewMR({...newMR, fullName: e.target.value})} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl font-bold text-sm" />
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Work Email</label>
                      <input required type="email" value={newMR.email} onChange={e => setNewMR({...newMR, email: e.target.value})} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm" />
                    </div>
                    <div>
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Mobile No</label>
                      <input required type="tel" value={newMR.mobileNumber} onChange={e => setNewMR({...newMR, mobileNumber: e.target.value})} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm" />
                    </div>
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">SLCPI ID Number</label>
                    <input required type="text" value={newMR.slcpiId} onChange={e => setNewMR({...newMR, slcpiId: e.target.value})} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm" />
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">NIC / National ID</label>
                    <input required type="text" value={newMR.identificationNumber} onChange={e => setNewMR({...newMR, identificationNumber: e.target.value})} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm" />
                  </div>
               </div>
               <div className="flex gap-4 pt-4">
                  <button type="button" onClick={() => setIsAddMRModalOpen(false)} className="flex-1 px-4 font-bold text-slate-500">Cancel</button>
                  <button type="submit" className="flex-1 bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-xl active:scale-95 transition-all">CREATE MR PROFILE</button>
               </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default CompanyAdminDashboard;

export type MRStatus = 'active' | 'suspended';
export type ApplicationStatus = 'applied' | 'selected' | 'waitlisted' | 'rejected';
export type EntryStatus = 'not_entered' | 'entered' | 'expired';
export type UserRole = 'MR' | 'ADMIN' | 'SECURITY' | 'SUPER_ADMIN' | 'COMPANY_ADMIN';
export type ApprovalStatus = 'pending' | 'approved' | 'rejected';
export type SessionType = 'MORNING' | 'EVENING' | 'FULL_DAY';

export interface MedicalRep {
  id: string;
  fullName: string;
  email?: string;
  companyName: string; // Used for PharmaCompany linking
  mrId: string;
  mobileNumber: string;
  identificationNumber: string; // Valid ID for signup
  slcpiId?: string;
  status: MRStatus;
  createdAt: string;
}

export interface Hospital {
  id: string;
  name: string;
  supportedSessions: SessionType[];
  passLimits: Record<string, number>; 
  sessionWindows: Record<string, { start: string; end: string }>; 
  isActive: boolean;
}

export interface HospitalUser {
  id: string;
  hospitalId: string;
  mobileNumber: string; // Used as Login ID
  password: string;     
  role: 'ADMIN' | 'SECURITY';
  fullName: string;
}

export interface MRHospitalApproval {
  id: string;
  mrId: string;
  hospitalId: string;
  status: ApprovalStatus;
  updatedAt: string;
}

export interface PassApplication {
  id: string;
  mrId: string;
  hospitalId: string;
  session: SessionType;
  applicationDate: string;
  priorityScore: number;
  status: ApplicationStatus;
  createdAt: string;
}

export interface IssuedPass {
  id: string;
  mrId: string;
  hospitalId: string;
  session: SessionType;
  passDate: string;
  timeSlot: string;
  qrCode: string;
  entryStatus: EntryStatus;
}

export interface PharmaCompany {
  id: string;
  name: string;
  contactEmail: string;
  companyCode: string; // Unique code for tracking
  adminMobile: string; // Login for Company Admin
  adminPassword: string; // Password for Company Admin
  isActive: boolean;
}

export interface Invoice {
  id: string;
  companyId: string;
  amount: number;
  activeMRCount: number;
  status: 'paid' | 'unpaid';
  date: string;
}

export interface EntryLog {
  id: string;
  issuedPassId: string;
  entryTime: string;
  verifiedBy: string;
}

// User in session
export interface AuthUser {
  id: string;
  role: UserRole;
  fullName: string;
  mobileNumber?: string;
  hospitalId?: string; // For hospital admins
  companyId?: string; // For company admins
  companyName?: string; // For MRs
}

import { MedicalRep, Hospital, PassApplication, IssuedPass, EntryLog, MRHospitalApproval, PharmaCompany, Invoice, HospitalUser, AuthUser } from '../types';

const KEYS = {
  MRS: 'medpass_mrs',
  HOSPITALS: 'medpass_hospitals',
  HOSPITAL_USERS: 'medpass_hospital_users',
  APPLICATIONS: 'medpass_applications',
  PASSES: 'medpass_passes',
  LOGS: 'medpass_logs',
  SESSION: 'medpass_session',
  APPROVALS: 'medpass_approvals',
  COMPANIES: 'medpass_companies',
  INVOICES: 'medpass_invoices'
};

export const storageService = {
  getMRs: (): MedicalRep[] => {
    const mrs = localStorage.getItem(KEYS.MRS);
    if (!mrs) {
      const initial: MedicalRep[] = [
        {
          id: 'mr-1',
          fullName: 'John Doe',
          companyName: 'Pfizer Lanka',
          mrId: 'MR-7890',
          mobileNumber: '0771234567',
          identificationNumber: '951234567V',
          status: 'active',
          createdAt: new Date().toISOString()
        }
      ];
      localStorage.setItem(KEYS.MRS, JSON.stringify(initial));
      return initial;
    }
    return JSON.parse(mrs);
  },
  saveMRs: (mrs: MedicalRep[]) => localStorage.setItem(KEYS.MRS, JSON.stringify(mrs)),

  getHospitals: (): Hospital[] => {
    const hospitals = localStorage.getItem(KEYS.HOSPITALS);
    if (!hospitals) {
      const initial: Hospital[] = [
        {
          id: 'h1',
          name: 'Colombo General Hospital',
          supportedSessions: ['MORNING', 'EVENING'],
          passLimits: { 'MORNING': 10, 'EVENING': 10 },
          sessionWindows: { 
            'MORNING': { start: '00:00', end: '23:59' }, 
            'EVENING': { start: '00:00', end: '23:59' } 
          },
          isActive: true
        }
      ];
      localStorage.setItem(KEYS.HOSPITALS, JSON.stringify(initial));
      return initial;
    }
    return JSON.parse(hospitals);
  },
  saveHospitals: (hospitals: Hospital[]) => localStorage.setItem(KEYS.HOSPITALS, JSON.stringify(hospitals)),

  getHospitalUsers: (): HospitalUser[] => {
    const users = localStorage.getItem(KEYS.HOSPITAL_USERS);
    if (!users) {
      const initial: HospitalUser[] = [
        { id: 'u1', hospitalId: 'h1', mobileNumber: '0771', password: 'admin', role: 'ADMIN', fullName: 'Colombo Admin' },
        { id: 'u2', hospitalId: 'h1', mobileNumber: '07711', password: 'guard', role: 'SECURITY', fullName: 'Colombo Security' },
      ];
      localStorage.setItem(KEYS.HOSPITAL_USERS, JSON.stringify(initial));
      return initial;
    }
    return JSON.parse(users);
  },
  saveHospitalUsers: (users: HospitalUser[]) => localStorage.setItem(KEYS.HOSPITAL_USERS, JSON.stringify(users)),

  getApprovals: (): MRHospitalApproval[] => JSON.parse(localStorage.getItem(KEYS.APPROVALS) || '[]'),
  saveApprovals: (apps: MRHospitalApproval[]) => localStorage.setItem(KEYS.APPROVALS, JSON.stringify(apps)),

  getApplications: (): PassApplication[] => JSON.parse(localStorage.getItem(KEYS.APPLICATIONS) || '[]'),
  saveApplications: (apps: PassApplication[]) => localStorage.setItem(KEYS.APPLICATIONS, JSON.stringify(apps)),

  getPasses: (): IssuedPass[] => JSON.parse(localStorage.getItem(KEYS.PASSES) || '[]'),
  savePasses: (passes: IssuedPass[]) => localStorage.setItem(KEYS.PASSES, JSON.stringify(passes)),

  getCompanies: (): PharmaCompany[] => {
    const companies = localStorage.getItem(KEYS.COMPANIES);
    if (!companies) {
      const initial: PharmaCompany[] = [{ 
        id: 'c1', 
        name: 'Pfizer Lanka', 
        contactEmail: 'admin@pfizer.lk', 
        companyCode: 'PFIZ-01',
        adminMobile: '0779', 
        adminPassword: 'pfiz', 
        isActive: true 
      }];
      localStorage.setItem(KEYS.COMPANIES, JSON.stringify(initial));
      return initial;
    }
    return JSON.parse(companies);
  },
  saveCompanies: (companies: PharmaCompany[]) => localStorage.setItem(KEYS.COMPANIES, JSON.stringify(companies)),

  getInvoices: (): Invoice[] => JSON.parse(localStorage.getItem(KEYS.INVOICES) || '[]'),
  saveInvoices: (invoices: Invoice[]) => localStorage.setItem(KEYS.INVOICES, JSON.stringify(invoices)),

  getLogs: (): EntryLog[] => JSON.parse(localStorage.getItem(KEYS.LOGS) || '[]'),
  saveLogs: (logs: EntryLog[]) => localStorage.setItem(KEYS.LOGS, JSON.stringify(logs)),

  setCurrentUser: (user: AuthUser) => localStorage.setItem(KEYS.SESSION, JSON.stringify(user)),
  getCurrentUser: (): AuthUser | null => {
    const session = localStorage.getItem(KEYS.SESSION);
    return session ? JSON.parse(session) : null;
  },
  clearSession: () => localStorage.removeItem(KEYS.SESSION)
};

import React, { useState, useEffect, createContext, useContext } from 'react';
import { storageService } from './services/storageService';
import Layout from './components/Layout';
import MRDashboard from './components/MRDashboard';
import AdminDashboard from './components/AdminDashboard';
import SuperAdminDashboard from './components/SuperAdminDashboard';
import SecurityView from './components/SecurityView';
import CompanyAdminDashboard from './components/CompanyAdminDashboard';
import { Shield, User, Key, ArrowRight, Hospital as HospitalIcon, Laptop, ShieldCheck, Crown, CheckCircle2, AlertCircle, X, Lock, Briefcase } from 'lucide-react';
import { UserRole, AuthUser } from './types';

// Simple context for global notifications
export const FeedbackContext = createContext<{
  showFeedback: (msg: string, type?: 'success' | 'error') => void;
}>({ showFeedback: () => {} });

const FeedbackToast = ({ message, type, onClose }: { message: string, type: 'success' | 'error', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 4000);
    return () => clearTimeout(timer);
  }, [onClose]);

  return (
    <div className="fixed bottom-6 right-6 z-[200] animate-in slide-in-from-right-10 fade-in duration-300">
      <div className={`flex items-center gap-3 px-6 py-4 rounded-2xl shadow-2xl border ${
        type === 'success' ? 'bg-white border-green-100 text-green-800' : 'bg-white border-red-100 text-red-800'
      }`}>
        {type === 'success' ? <CheckCircle2 className="h-6 w-6 text-green-500" /> : <AlertCircle className="h-6 w-6 text-red-500" />}
        <p className="font-bold text-sm">{message}</p>
        <button onClick={onClose} className="ml-2 p-1 hover:bg-slate-100 rounded-lg transition-all">
          <X className="h-4 w-4 text-slate-400" />
        </button>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [user, setUser] = useState<any>(null);
  const [view, setView] = useState<'LOGIN' | 'DASHBOARD'>('LOGIN');
  const [role, setRole] = useState<UserRole>('MR');
  const [mobile, setMobile] = useState('');
  const [password, setPassword] = useState('');
  const [feedback, setFeedback] = useState<{ message: string, type: 'success' | 'error' } | null>(null);

  useEffect(() => {
    const session = storageService.getCurrentUser();
    if (session) { setUser(session); setView('DASHBOARD'); }
  }, []);

  const showFeedback = (message: string, type: 'success' | 'error' = 'success') => {
    setFeedback({ message, type });
  };

  const handleLogin = (e?: React.FormEvent) => {
    e?.preventDefault();

    if (role === 'MR') {
      const mrs = storageService.getMRs();
      const existing = mrs.find(m => m.mobileNumber === mobile);
      if (existing) {
        if (existing.status === 'suspended') {
          showFeedback("Your account has been suspended by your company.", 'error');
          return;
        }
        const u: AuthUser = { id: existing.id, fullName: existing.fullName, role: 'MR', companyName: existing.companyName, mobileNumber: existing.mobileNumber };
        storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
        showFeedback(`Welcome back, ${u.fullName}!`);
      } else {
        showFeedback("Medical Representative not found.", 'error');
      }
    } else if (role === 'COMPANY_ADMIN') {
      const companies = storageService.getCompanies();
      const found = companies.find(c => c.adminMobile === mobile);
      if (found && found.adminPassword === password) {
        if (!found.isActive) {
          showFeedback("Company access is deactivated.", 'error');
          return;
        }
        const u: AuthUser = { 
          id: found.id, 
          role: 'COMPANY_ADMIN', 
          fullName: `${found.name} Admin`,
          companyId: found.id 
        };
        storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
        showFeedback(`Pharma Admin session: ${found.name}`);
      } else {
        showFeedback("Invalid Company Admin credentials.", 'error');
      }
    } else if (role === 'ADMIN' || role === 'SECURITY') {
      const hospitalUsers = storageService.getHospitalUsers();
      const found = hospitalUsers.find(u => u.mobileNumber === mobile && u.role === role);

      if (found) {
        if (found.password === password) {
          const u: AuthUser = { 
            id: found.id,
            role: found.role, 
            fullName: found.fullName, 
            hospitalId: found.hospitalId,
            mobileNumber: found.mobileNumber
          };
          storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
          showFeedback(`Logged in as ${found.fullName}`);
        } else {
          showFeedback("Invalid password for this account.", 'error');
        }
      } else {
        showFeedback(`${role} credentials not found. Check with Super Admin.`, 'error');
      }
    } else if (role === 'SUPER_ADMIN') {
      if (mobile === 'root' && password === 'root') {
        const u: AuthUser = { id: 'sa-1', role: 'SUPER_ADMIN', fullName: 'MedPass Authority' };
        storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
        showFeedback("Super Admin session started.");
      } else {
        showFeedback("Invalid Super Admin Credentials", 'error');
      }
    }
  };

  const quickLogin = (r: UserRole, phone = '', pass = '') => { 
    setRole(r); 
    setMobile(phone);
    setPassword(pass);
    setTimeout(() => handleLogin(), 100); 
  };

  if (view === 'LOGIN') {
    return (
      <FeedbackContext.Provider value={{ showFeedback }}>
        <div className="min-h-screen bg-indigo-600 flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden">
            <div className="bg-slate-50 p-8 text-center border-b border-slate-100">
              <div className="bg-indigo-600 w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-4"><HospitalIcon className="h-10 w-10 text-white" /></div>
              <h1 className="text-2xl font-black text-slate-800 tracking-tighter">MedPass Engine</h1>
            </div>
            <div className="p-8">
              <div className="mb-6 bg-indigo-50 rounded-xl p-4">
                <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-2">System Demo Credentials</p>
                <div className="grid grid-cols-2 gap-2">
                  <button onClick={() => quickLogin('MR', '0771234567')} className="p-2 bg-white border border-indigo-100 rounded text-[10px] font-bold text-slate-700 flex flex-col items-center">
                    <User className="h-3 w-3 mb-1" /> MR John
                  </button>
                  <button onClick={() => quickLogin('COMPANY_ADMIN', '0779', 'pfiz')} className="p-2 bg-indigo-50 border border-indigo-100 rounded text-[10px] font-bold text-indigo-700 flex flex-col items-center">
                     <Briefcase className="h-3 w-3 mb-1" /> Pharma Admin
                  </button>
                  <button onClick={() => quickLogin('ADMIN', '0771', 'admin')} className="p-2 bg-slate-50 border border-slate-100 rounded text-[10px] font-bold text-slate-700 flex flex-col items-center">
                     <ShieldCheck className="h-3 w-3 mb-1" /> Hospital Admin
                  </button>
                  <button onClick={() => quickLogin('SUPER_ADMIN', 'root', 'root')} className="p-2 bg-slate-800 border border-slate-700 rounded text-[10px] font-bold text-white flex flex-col items-center">
                     <Crown className="h-3 w-3 mb-1" /> Super Admin
                  </button>
                </div>
              </div>

              <div className="flex bg-slate-100 p-1 rounded-xl mb-6 overflow-x-auto scrollbar-hide">
                {(['MR', 'COMPANY_ADMIN', 'ADMIN', 'SECURITY', 'SUPER_ADMIN'] as const).map(r => (
                  <button key={r} onClick={() => setRole(r)} className={`flex-1 min-w-[80px] py-1.5 text-[10px] font-black rounded-lg transition-all ${role === r ? 'bg-white text-indigo-600 shadow' : 'text-slate-400'}`}>{r}</button>
                ))}
              </div>

              <form onSubmit={handleLogin} className="space-y-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Login ID / Mobile</label>
                  <input 
                    type="text" 
                    value={mobile} 
                    onChange={e => setMobile(e.target.value)} 
                    className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-bold" 
                    placeholder={role === 'MR' ? "0771234567" : role === 'SUPER_ADMIN' ? "root" : "Admin ID"}
                  />
                </div>
                {role !== 'MR' && (
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-500 uppercase">Password</label>
                    <div className="relative">
                      <input 
                        type="password" 
                        value={password} 
                        onChange={e => setPassword(e.target.value)} 
                        className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-bold" 
                        placeholder="••••••••"
                      />
                      <Lock className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-300" />
                    </div>
                  </div>
                )}
                <button type="submit" className="w-full bg-indigo-600 text-white font-black py-4 rounded-xl shadow-lg hover:bg-indigo-700 active:scale-95 transition-all flex items-center justify-center gap-2">
                  Enter System <ArrowRight className="h-5 w-5" />
                </button>
              </form>
            </div>
          </div>
          {feedback && <FeedbackToast message={feedback.message} type={feedback.type} onClose={() => setFeedback(null)} />}
        </div>
      </FeedbackContext.Provider>
    );
  }

  return (
    <FeedbackContext.Provider value={{ showFeedback }}>
      <Layout 
        user={user} 
        onLogout={() => { storageService.clearSession(); setUser(null); setView('LOGIN'); showFeedback("Logged out successfully"); }} 
        title={user.role === 'SUPER_ADMIN' ? 'Root Authority' : user.role === 'MR' ? 'MR Dashboard' : `${user.fullName} Panel`}
      >
        {user.role === 'MR' && <MRDashboard user={user} />}
        {user.role === 'COMPANY_ADMIN' && <CompanyAdminDashboard user={user} />}
        {user.role === 'ADMIN' && <AdminDashboard user={user} />}
        {user.role === 'SUPER_ADMIN' && <SuperAdminDashboard />}
        {user.role === 'SECURITY' && <SecurityView />}
      </Layout>
      {feedback && <FeedbackToast message={feedback.message} type={feedback.type} onClose={() => setFeedback(null)} />}
    </FeedbackContext.Provider>
  );
};

export default App;

import React, { useState, useEffect, useContext } from 'react';
import { Building2, Users, FileText, Settings, Plus, DollarSign, Power, Activity, Edit3, Trash2, Check, X, ChevronRight, Briefcase, Clock, User, Phone, CreditCard, ShieldCheck, Lock, Mail, Key } from 'lucide-react';
import { storageService } from '../services/storageService';
import { Hospital, PharmaCompany, Invoice, MedicalRep, SessionType, HospitalUser } from '../types';
import { FeedbackContext } from '../App';

const SuperAdminDashboard: React.FC = () => {
  const { showFeedback } = useContext(FeedbackContext);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [companies, setCompanies] = useState<PharmaCompany[]>([]);
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [activeTab, setActiveTab] = useState<'hospitals' | 'companies' | 'billing' | 'monitoring'>('hospitals');

  // Hospital Config State
  const [isHospitalModalOpen, setIsHospitalModalOpen] = useState(false);
  const [editingHospital, setEditingHospital] = useState<Partial<Hospital> | null>(null);
  const [adminData, setAdminData] = useState({ fullName: '', mobileNumber: '', password: '' });
  const [securityData, setSecurityData] = useState({ fullName: '', mobileNumber: '', password: '' });

  // Company State
  const [isCompanyModalOpen, setIsCompanyModalOpen] = useState(false);
  const [editingCompany, setEditingCompany] = useState<Partial<PharmaCompany> | null>(null);
  const [selectedCompanyId, setSelectedCompanyId] = useState<string | null>(null);
  const [selectedMR, setSelectedMR] = useState<MedicalRep | null>(null);

  useEffect(() => {
    refreshData();
  }, []);

  const refreshData = () => {
    setHospitals(storageService.getHospitals());
    setCompanies(storageService.getCompanies());
    setInvoices(storageService.getInvoices());
    setMrs(storageService.getMRs());
  };

  const handleEditHospital = (h: Hospital) => {
    setEditingHospital(h);
    const users = storageService.getHospitalUsers();
    const admin = users.find(u => u.hospitalId === h.id && u.role === 'ADMIN');
    const security = users.find(u => u.hospitalId === h.id && u.role === 'SECURITY');
    setAdminData({ 
      fullName: admin?.fullName || '', 
      mobileNumber: admin?.mobileNumber || '', 
      password: admin?.password || '' 
    });
    setSecurityData({ 
      fullName: security?.fullName || '', 
      mobileNumber: security?.mobileNumber || '', 
      password: security?.password || '' 
    });
    setIsHospitalModalOpen(true);
  };

  const handleSaveHospital = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingHospital?.name) return;

    const currentHospitals = storageService.getHospitals();
    const currentUsers = storageService.getHospitalUsers();

    const hospitalId = editingHospital.id || 'h' + Date.now();

    const hospitalData: Hospital = {
      id: hospitalId,
      name: editingHospital.name || '',
      isActive: editingHospital.isActive ?? true,
      supportedSessions: editingHospital.supportedSessions || [],
      passLimits: editingHospital.passLimits || {},
      sessionWindows: editingHospital.sessionWindows || {},
    };

    // 1. Update/Save Hospital
    let updatedHospitals: Hospital[];
    if (editingHospital.id) {
      updatedHospitals = currentHospitals.map(h => h.id === editingHospital.id ? hospitalData : h);
    } else {
      updatedHospitals = [...currentHospitals, hospitalData];
    }
    storageService.saveHospitals(updatedHospitals);
    setHospitals(updatedHospitals);

    // 2. Update/Save Admin & Security Credentials
    const otherUsers = currentUsers.filter(u => u.hospitalId !== hospitalId);
    const newUsers: HospitalUser[] = [
      ...otherUsers,
      {
        id: `u-adm-${hospitalId}`,
        hospitalId: hospitalId,
        role: 'ADMIN',
        fullName: adminData.fullName,
        mobileNumber: adminData.mobileNumber,
        password: adminData.password
      },
      {
        id: `u-sec-${hospitalId}`,
        hospitalId: hospitalId,
        role: 'SECURITY',
        fullName: securityData.fullName,
        mobileNumber: securityData.mobileNumber,
        password: securityData.password
      }
    ];
    storageService.saveHospitalUsers(newUsers);

    showFeedback(`Facility configuration for ${hospitalData.name} saved successfully.`);
    setIsHospitalModalOpen(false);
    setEditingHospital(null);
    setAdminData({ fullName: '', mobileNumber: '', password: '' });
    setSecurityData({ fullName: '', mobileNumber: '', password: '' });
  };

  const handleSaveCompany = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingCompany?.name || !editingCompany?.companyCode) return;

    const currentCompanies = storageService.getCompanies();
    let updated: PharmaCompany[];

    const companyData: PharmaCompany = {
      id: editingCompany.id || 'c' + Date.now(),
      name: editingCompany.name || '',
      companyCode: editingCompany.companyCode || '',
      adminMobile: editingCompany.adminMobile || '',
      adminPassword: editingCompany.adminPassword || '',
      contactEmail: editingCompany.contactEmail || '',
      isActive: editingCompany.isActive ?? true,
    };

    if (editingCompany.id) {
      updated = currentCompanies.map(c => c.id === editingCompany.id ? companyData : c);
      showFeedback(`Company ${companyData.name} updated.`);
    } else {
      updated = [...currentCompanies, companyData];
      showFeedback(`Company ${companyData.name} registered successfully.`);
    }

    storageService.saveCompanies(updated);
    setCompanies(updated);
    setIsCompanyModalOpen(false);
    setEditingCompany(null);
