                  <td className="px-4 py-4 text-right">
                    <div className="flex justify-end gap-2">
                       <button onClick={() => setSummaryMR(mr)} className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all" title="View Summary"><BarChart3 className="h-4 w-4" /></button>
                       <button onClick={() => setResetMR(mr)} className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all" title="Manage Password"><Key className="h-4 w-4" /></button>
                       <button onClick={() => { setEditingMR(mr); setIsMRModalOpen(true); }} className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all" title="Edit Profile"><Edit3 className="h-4 w-4" /></button>
                       <button onClick={() => toggleMRStatus(mr.id)} className={`p-2 rounded-lg transition-all ${mr.status === 'active' ? 'text-red-400 hover:bg-red-50' : 'text-green-500 hover:bg-green-50'}`} title={mr.status === 'active' ? 'Suspend' : 'Activate'}>
                         <Power className="h-4 w-4" />
                       </button>
                    </div>
                  </td>
                </tr>
              ))}
              {filteredMRs.length === 0 && (
                <tr><td colSpan={4} className="py-12 text-center text-slate-400 italic text-sm">No representatives registered yet.</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </section>

      {/* MR Registration / Edit Modal */}
      {isMRModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden animate-in slide-in-from-bottom-4 duration-300">
            <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-bold text-slate-800">{editingMR?.id ? 'Update Representative' : 'Register New Representative'}</h3>
              <button onClick={() => setIsMRModalOpen(false)} className="p-2 hover:bg-slate-200 rounded-full transition-all"><X className="h-5 w-5 text-slate-400" /></button>
            </div>
            <form onSubmit={handleSaveMR} className="p-8 space-y-5">
              <div className="space-y-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Full Legal Name</label>
                  <input required type="text" value={editingMR?.fullName || ''} onChange={e => setEditingMR({...editingMR, fullName: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold outline-none focus:ring-2 focus:ring-indigo-500" />
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Mobile (Login ID)</label>
                    <input required type="text" value={editingMR?.mobileNumber || ''} onChange={e => setEditingMR({...editingMR, mobileNumber: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold text-sm" placeholder="077XXXXXXX" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Password</label>
                    <input required type="text" value={editingMR?.password || ''} onChange={e => setEditingMR({...editingMR, password: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold text-sm" />
                  </div>
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">NIC / National ID Number</label>
                  <input required type="text" value={editingMR?.identificationNumber || ''} onChange={e => setEditingMR({...editingMR, identificationNumber: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold text-sm" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">SLCPI Registered ID</label>
                  <input required type="text" value={editingMR?.slcpiId || ''} onChange={e => setEditingMR({...editingMR, slcpiId: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold text-sm" placeholder="SLCPI-XXX" />
                </div>
              </div>

              <div className="pt-4 flex gap-3">
                <button type="button" onClick={() => setIsMRModalOpen(false)} className="flex-1 font-bold text-slate-500 py-3">Cancel</button>
                <button type="submit" className="flex-1 bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-xl active:scale-95 transition-all">
                  {editingMR?.id ? 'UPDATE' : 'REGISTER'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Password Reset Modal */}
      {resetMR && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-sm rounded-3xl shadow-2xl overflow-hidden animate-in slide-in-from-bottom-4 duration-300">
            <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
              <h3 className="text-lg font-bold text-slate-800">Change Password</h3>
              <button onClick={() => setResetMR(null)} className="p-2 hover:bg-slate-200 rounded-full transition-all"><X className="h-5 w-5 text-slate-400" /></button>
            </div>
            <form onSubmit={handleResetPassword} className="p-8 space-y-6">
              <div className="text-center">
                <p className="text-sm text-slate-500 mb-1">Set new login password for</p>
                <p className="font-bold text-slate-800">{resetMR.fullName}</p>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">New Password</label>
                <input 
                  required 
                  type="text" 
                  value={newPassword} 
                  onChange={e => setNewPassword(e.target.value)} 
                  placeholder="Enter new password..."
                  className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold outline-none focus:ring-2 focus:ring-indigo-500"
                />
              </div>
              <button type="submit" className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-xl active:scale-95 transition-all">
                UPDATE PASSWORD
              </button>
            </form>
          </div>
        </div>
      )}

      {/* Working Summary Modal */}
      {summaryMR && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-lg rounded-3xl shadow-2xl overflow-hidden animate-in slide-in-from-bottom-4 duration-300">
            <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-bold text-slate-800">Working Summary</h3>
              <button onClick={() => setSummaryMR(null)} className="p-2 hover:bg-slate-200 rounded-full transition-all"><X className="h-5 w-5 text-slate-400" /></button>
            </div>
            <div className="p-8 space-y-8">
              <div className="flex items-center gap-4">
                 <div className="w-16 h-16 bg-indigo-100 rounded-2xl flex items-center justify-center border-2 border-white shadow-sm">
                   <User className="h-8 w-8 text-indigo-600" />
                 </div>
                 <div>
                   <h4 className="text-xl font-black text-slate-800">{summaryMR.fullName}</h4>
                   <p className="text-indigo-600 font-bold text-xs uppercase tracking-widest">{summaryMR.mrId}</p>
                 </div>
              </div>

              {/* Stats Grid */}
              <div className="grid grid-cols-2 gap-4">
                {(() => {
                  const stats = getMRStats(summaryMR.id);
                  return (
                    <>
                      <div className="p-5 bg-slate-50 rounded-2xl border border-slate-100 flex flex-col justify-between h-32">
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-1.5"><Clock className="h-3 w-3" /> Total Apps</p>
                        <p className="text-3xl font-black text-slate-800">{stats.totalApps}</p>
                        <p className="text-[10px] text-slate-400 font-bold">Lifetime Submissions</p>
                      </div>
                      <div className="p-5 bg-indigo-50 rounded-2xl border border-indigo-100 flex flex-col justify-between h-32">
                        <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest flex items-center gap-1.5"><CheckCircle2 className="h-3 w-3" /> Entry Rate</p>
                        <p className="text-3xl font-black text-indigo-600">{stats.entryRate}%</p>
                        <p className="text-[10px] text-indigo-400 font-bold">Successful Visits</p>
                      </div>
                      <div className="p-5 bg-green-50 rounded-2xl border border-green-100 flex flex-col justify-between h-32">
                        <p className="text-[10px] font-black text-green-500 uppercase tracking-widest flex items-center gap-1.5"><ShieldCheck className="h-3 w-3" /> Confirmed</p>
                        <p className="text-3xl font-black text-green-600">{stats.entries}</p>
                        <p className="text-[10px] text-green-400 font-bold">Physical Entries</p>
                      </div>
                      <div className="p-5 bg-amber-50 rounded-2xl border border-amber-100 flex flex-col justify-between h-32">
                        <p className="text-[10px] font-black text-amber-500 uppercase tracking-widest flex items-center gap-1.5"><Activity className="h-3 w-3" /> Lottery Wins</p>
                        <p className="text-3xl font-black text-amber-600">{stats.selected}</p>
                        <p className="text-[10px] text-amber-400 font-bold">Passes Issued</p>
                      </div>
                    </>
                  );
                })()}
              </div>

              <div className="p-4 bg-slate-100 rounded-2xl text-[10px] font-bold text-slate-500 leading-relaxed uppercase tracking-wider">
                This summary represents the pharmaceutical activity metrics for the hospital booking ecosystem. Metrics are updated in real-time based on system-wide pass issuance and gate security logs.
              </div>

              <button onClick={() => setSummaryMR(null)} className="w-full bg-slate-800 text-white font-bold py-4 rounded-2xl hover:bg-slate-900 transition-all">
                CLOSE SUMMARY
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CompanyAdminDashboard;

export type MRStatus = 'active' | 'suspended';
export type ApplicationStatus = 'applied' | 'selected' | 'waitlisted' | 'rejected';
export type EntryStatus = 'not_entered' | 'entered' | 'expired';
export type UserRole = 'MR' | 'ADMIN' | 'SECURITY' | 'SUPER_ADMIN' | 'COMPANY_ADMIN';
export type ApprovalStatus = 'pending' | 'approved' | 'rejected';
export type SessionType = 'MORNING' | 'EVENING' | 'FULL_DAY';

export interface MedicalRep {
  id: string;
  fullName: string;
  email?: string;
  companyName: string;
  mrId: string;
  mobileNumber: string;
  password?: string; // Managed by Company Admin
  identificationNumber: string;
  slcpiId?: string;
  status: MRStatus;
  createdAt: string;
}

export interface Hospital {
  id: string;
  name: string;
  supportedSessions: SessionType[];
  passLimits: Record<string, number>; 
  sessionWindows: Record<string, { start: string; end: string }>; 
  isActive: boolean;
}

export interface HospitalUser {
  id: string;
  hospitalId: string;
  mobileNumber: string; // Login ID
  password: string;     
  role: 'ADMIN' | 'SECURITY';
  fullName: string;
}

export interface MRHospitalApproval {
  id: string;
  mrId: string;
  hospitalId: string;
  status: ApprovalStatus;
  updatedAt: string;
}

export interface PassApplication {
  id: string;
  mrId: string;
  hospitalId: string;
  session: SessionType;
  applicationDate: string;
  priorityScore: number;
  status: ApplicationStatus;
  createdAt: string;
}

export interface IssuedPass {
  id: string;
  mrId: string;
  hospitalId: string;
  session: SessionType;
  passDate: string;
  timeSlot: string;
  qrCode: string;
  entryStatus: EntryStatus;
}

export interface PharmaCompany {
  id: string;
  name: string;
  contactEmail: string;
  companyCode: string;
  adminMobile: string; // Login
  adminPassword: string; // Password
  isActive: boolean;
}

export interface Invoice {
  id: string;
  companyId: string;
  amount: number;
  activeMRCount: number;
  status: 'paid' | 'unpaid';
  date: string;
}

export interface EntryLog {
  id: string;
  issuedPassId: string;
  entryTime: string;
  verifiedBy: string;
}

export interface AuthUser {
  id: string;
  role: UserRole;
  fullName: string;
  mobileNumber?: string;
  hospitalId?: string;
  companyId?: string;
  companyName?: string;
}

import React, { useState, useEffect, useContext } from 'react';
import { Building2, Users, Settings, Plus, DollarSign, Activity, Edit3, X, Briefcase, User, ShieldCheck, Lock, Shield, CreditCard, ChevronRight } from 'lucide-react';
import { storageService } from '../services/storageService';
import { Hospital, PharmaCompany, MedicalRep, HospitalUser } from '../types';
import { FeedbackContext } from '../App';

const SuperAdminDashboard: React.FC = () => {
  const { showFeedback } = useContext(FeedbackContext);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [companies, setCompanies] = useState<PharmaCompany[]>([]);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [activeTab, setActiveTab] = useState<'hospitals' | 'companies' | 'monitoring'>('hospitals');

  // Hospital Form State
  const [isHospitalModalOpen, setIsHospitalModalOpen] = useState(false);
  const [editingHospital, setEditingHospital] = useState<Partial<Hospital> | null>(null);
  const [adminData, setAdminData] = useState({ fullName: '', mobileNumber: '', password: '' });
  const [securityData, setSecurityData] = useState({ fullName: '', mobileNumber: '', password: '' });

  // Company Form State
  const [isCompanyModalOpen, setIsCompanyModalOpen] = useState(false);
  const [editingCompany, setEditingCompany] = useState<Partial<PharmaCompany> | null>(null);

  useEffect(() => { refreshData(); }, []);

  const refreshData = () => {
    setHospitals(storageService.getHospitals());
    setCompanies(storageService.getCompanies());
    setMrs(storageService.getMRs());
  };

  const handleEditHospital = (h: Hospital) => {
    setEditingHospital(h);
    const users = storageService.getHospitalUsers();
    const admin = users.find(u => u.hospitalId === h.id && u.role === 'ADMIN');
    const security = users.find(u => u.hospitalId === h.id && u.role === 'SECURITY');
    setAdminData({ 
      fullName: admin?.fullName || '', 
      mobileNumber: admin?.mobileNumber || '', 
      password: admin?.password || '' 
    });
    setSecurityData({ 
      fullName: security?.fullName || '', 
      mobileNumber: security?.mobileNumber || '', 
      password: security?.password || '' 
    });
    setIsHospitalModalOpen(true);
  };

  const handleSaveHospital = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingHospital?.name) return;

    const currentHospitals = storageService.getHospitals();
    const currentUsers = storageService.getHospitalUsers();
    const hospitalId = editingHospital.id || 'h' + Date.now();

    const hospitalData: Hospital = {
      id: hospitalId,
      name: editingHospital.name || '',
      isActive: editingHospital.isActive ?? true,
      supportedSessions: editingHospital.supportedSessions || ['MORNING', 'EVENING'],
      passLimits: editingHospital.passLimits || { 'MORNING': 10, 'EVENING': 10 },
      sessionWindows: editingHospital.sessionWindows || { 
        'MORNING': { start: '00:00', end: '23:59' }, 
        'EVENING': { start: '00:00', end: '23:59' } 
      },
    };

    let updatedHospitals = editingHospital.id 
      ? currentHospitals.map(h => h.id === editingHospital.id ? hospitalData : h)
      : [...currentHospitals, hospitalData];

    storageService.saveHospitals(updatedHospitals);

    const otherUsers = currentUsers.filter(u => u.hospitalId !== hospitalId);
    storageService.saveHospitalUsers([
      ...otherUsers,
      { id: `u-adm-${hospitalId}`, hospitalId, role: 'ADMIN', fullName: adminData.fullName, mobileNumber: adminData.mobileNumber, password: adminData.password },
      { id: `u-sec-${hospitalId}`, hospitalId, role: 'SECURITY', fullName: securityData.fullName, mobileNumber: securityData.mobileNumber, password: securityData.password }
    ]);

    showFeedback(`Hospital "${hospitalData.name}" and admin accounts saved.`);
    setIsHospitalModalOpen(false);
    refreshData();
  };

  const handleSaveCompany = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingCompany?.name || !editingCompany?.companyCode) return;

    const currentCompanies = storageService.getCompanies();
    const companyData: PharmaCompany = {
      id: editingCompany.id || 'c' + Date.now(),
      name: editingCompany.name || '',
      companyCode: editingCompany.companyCode || '',
      adminMobile: editingCompany.adminMobile || '',
      adminPassword: editingCompany.adminPassword || '',
      contactEmail: editingCompany.contactEmail || '',
      isActive: editingCompany.isActive ?? true,
    };

    let updated = editingCompany.id 
      ? currentCompanies.map(c => c.id === editingCompany.id ? companyData : c)
      : [...currentCompanies, companyData];

    storageService.saveCompanies(updated);
    showFeedback(`Pharma Company "${companyData.name}" saved.`);
    setIsCompanyModalOpen(false);
    refreshData();
  };

  return (
    <div className="space-y-6">
      <div className="flex bg-white p-1 rounded-xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('hospitals')} className={`px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 ${activeTab === 'hospitals' ? 'bg-indigo-600 text-white shadow' : 'text-slate-500 hover:bg-slate-50'}`}><Building2 className="h-4 w-4" /> Hospitals</button>
        <button onClick={() => setActiveTab('companies')} className={`px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 ${activeTab === 'companies' ? 'bg-indigo-600 text-white shadow' : 'text-slate-500 hover:bg-slate-50'}`}><Briefcase className="h-4 w-4" /> Companies</button>
        <button onClick={() => setActiveTab('monitoring')} className={`px-4 py-2 rounded-lg text-sm font-bold flex items-center gap-2 ${activeTab === 'monitoring' ? 'bg-indigo-600 text-white shadow' : 'text-slate-500 hover:bg-slate-50'}`}><Activity className="h-4 w-4" /> Monitoring</button>
      </div>

      {activeTab === 'hospitals' && (
        <section className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-lg font-bold">Facility & Admin Management</h3>
            <button onClick={() => { setEditingHospital({ isActive: true }); setAdminData({fullName:'', mobileNumber:'', password:''}); setSecurityData({fullName:'', mobileNumber:'', password:''}); setIsHospitalModalOpen(true); }} className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-sm font-bold flex items-center gap-2 shadow-md hover:bg-indigo-700 transition-all"><Plus className="h-4 w-4" /> Add Hospital</button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {hospitals.map(h => (
              <div key={h.id} className="p-5 border border-slate-100 bg-slate-50 rounded-2xl relative overflow-hidden group">
                <div className={`absolute top-0 right-0 w-1.5 h-full ${h.isActive ? 'bg-green-500' : 'bg-red-500'}`}></div>
                <div className="flex justify-between items-start mb-4">
                  <h4 className="font-bold text-slate-800 text-lg">{h.name}</h4>
                  <button onClick={() => handleEditHospital(h)} className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg"><Edit3 className="h-4 w-4" /></button>
                </div>
                <div className="space-y-2 pt-3 border-t border-slate-200">
                  <div className="flex items-center justify-between text-[10px] font-black uppercase text-slate-400"><span>Staff Accounts</span></div>
                  <div className="flex justify-between text-xs font-bold text-slate-600"><span>Admin:</span><span>{storageService.getHospitalUsers().find(u => u.hospitalId === h.id && u.role === 'ADMIN')?.mobileNumber || 'N/A'}</span></div>
                  <div className="flex justify-between text-xs font-bold text-slate-600"><span>Security:</span><span>{storageService.getHospitalUsers().find(u => u.hospitalId === h.id && u.role === 'SECURITY')?.mobileNumber || 'N/A'}</span></div>
                </div>
              </div>
            ))}
          </div>
        </section>
      )}

      {activeTab === 'companies' && (
        <section className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-lg font-bold">Pharmaceutical Partners</h3>
            <button onClick={() => { setEditingCompany({ isActive: true }); setIsCompanyModalOpen(true); }} className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-sm font-bold flex items-center gap-2 shadow-md hover:bg-indigo-700 transition-all"><Plus className="h-4 w-4" /> Add Company</button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {companies.map(c => (
              <div key={c.id} className="p-5 border border-slate-100 bg-slate-50 rounded-2xl relative">
                <div className="flex justify-between items-start mb-4">
                  <div>
                    <h4 className="font-bold text-slate-800 text-lg">{c.name}</h4>
                    <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest">{c.companyCode}</p>
                  </div>
                  <button onClick={() => { setEditingCompany(c); setIsCompanyModalOpen(true); }} className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg"><Edit3 className="h-4 w-4" /></button>
                </div>
                <div className="space-y-1 pt-3 border-t border-slate-200">
                  <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Admin Credentials</p>
                  <p className="text-xs font-bold text-slate-700 flex justify-between"><span>Login:</span><span>{c.adminMobile}</span></p>
                  <p className="text-xs font-bold text-slate-700 flex justify-between"><span>Pass:</span><span>{c.adminPassword}</span></p>
                </div>
              </div>
            ))}
          </div>
        </section>
      )}

      {/* Hospital Modal */}
      {isHospitalModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white w-full max-w-2xl rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in duration-200">
            <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-bold text-slate-800">{editingHospital?.id ? 'Edit Hospital' : 'Provision New Hospital'}</h3>
              <button onClick={() => setIsHospitalModalOpen(false)} className="p-2 hover:bg-slate-200 rounded-full"><X className="h-5 w-5 text-slate-400" /></button>
            </div>
            <form onSubmit={handleSaveHospital} className="p-8 space-y-6 max-h-[80vh] overflow-y-auto">
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Hospital Name</label>
                <input required type="text" value={editingHospital?.name || ''} onChange={e => setEditingHospital({...editingHospital, name: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold focus:ring-2 focus:ring-indigo-500" />
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                <div className="p-5 bg-indigo-50/50 rounded-2xl border border-indigo-100 space-y-4">
                  <p className="text-xs font-black text-indigo-900 uppercase">Hospital Admin</p>
                  <input required type="text" value={adminData.fullName} onChange={e => setAdminData({...adminData, fullName: e.target.value})} className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg text-xs font-bold" placeholder="Full Name" />
                  <input required type="text" value={adminData.mobileNumber} onChange={e => setAdminData({...adminData, mobileNumber: e.target.value})} className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg text-xs font-bold" placeholder="Mobile / Login ID" />
                  <input required type="text" value={adminData.password} onChange={e => setAdminData({...adminData, password: e.target.value})} className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg text-xs font-bold" placeholder="Password" />
                </div>
                <div className="p-5 bg-slate-50 rounded-2xl border border-slate-100 space-y-4">
                  <p className="text-xs font-black text-slate-800 uppercase">Hospital Security</p>
                  <input required type="text" value={securityData.fullName} onChange={e => setSecurityData({...securityData, fullName: e.target.value})} className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg text-xs font-bold" placeholder="Full Name" />
                  <input required type="text" value={securityData.mobileNumber} onChange={e => setSecurityData({...securityData, mobileNumber: e.target.value})} className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg text-xs font-bold" placeholder="Mobile / Login ID" />
                  <input required type="text" value={securityData.password} onChange={e => setSecurityData({...securityData, password: e.target.value})} className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg text-xs font-bold" placeholder="Password" />
                </div>
              </div>
              <div className="flex gap-4">
                <button type="button" onClick={() => setIsHospitalModalOpen(false)} className="flex-1 font-bold text-slate-500">Cancel</button>
                <button type="submit" className="flex-1 bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-xl active:scale-95 transition-all">SAVE FACILITY</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Company Modal */}
      {isCompanyModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in duration-200">
            <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-bold text-slate-800">{editingCompany?.id ? 'Edit Company' : 'New Pharma Company'}</h3>
              <button onClick={() => setIsCompanyModalOpen(false)} className="p-2 hover:bg-slate-200 rounded-full"><X className="h-5 w-5 text-slate-400" /></button>
            </div>
            <form onSubmit={handleSaveCompany} className="p-8 space-y-4">
              <div className="space-y-4">
                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 block">Company Name</label>
                  <input required type="text" value={editingCompany?.name || ''} onChange={e => setEditingCompany({...editingCompany, name: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold focus:ring-2 focus:ring-indigo-500" />
                </div>
                <div>
                  <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-1 block">Internal Registration Code</label>
                  <input required type="text" value={editingCompany?.companyCode || ''} onChange={e => setEditingCompany({...editingCompany, companyCode: e.target.value})} className="w-full px-4 py-3 bg-indigo-50 border border-indigo-200 rounded-xl font-mono font-black text-indigo-700" placeholder="e.g. PFIZ-01" />
                </div>
                <div className="grid grid-cols-2 gap-4 pt-4 border-t border-slate-100">
                  <div className="col-span-2 text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-1">Company Admin Login</div>
                  <input required type="text" value={editingCompany?.adminMobile || ''} onChange={e => setEditingCompany({...editingCompany, adminMobile: e.target.value})} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold" placeholder="Mobile / Login" />
                  <input required type="text" value={editingCompany?.adminPassword || ''} onChange={e => setEditingCompany({...editingCompany, adminPassword: e.target.value})} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold" placeholder="Password" />
                </div>
              </div>
              <div className="flex gap-4 pt-4">
                <button type="button" onClick={() => setIsCompanyModalOpen(false)} className="flex-1 font-bold text-slate-500">Cancel</button>
                <button type="submit" className="flex-1 bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-xl active:scale-95 transition-all">SAVE COMPANY</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default SuperAdminDashboard;

import React, { useState, useEffect, useContext } from 'react';
import { UserPlus, Search, Briefcase, X, Edit3, Power, User, Users, Key, BarChart3, Clock, CheckCircle2, TrendingUp, ShieldCheck, Activity } from 'lucide-react';
import { storageService } from '../services/storageService';
import { MedicalRep, PharmaCompany, AuthUser, PassApplication, IssuedPass } from '../types';
import { FeedbackContext } from '../App';

interface CompanyAdminDashboardProps {
  user: AuthUser;
}

const CompanyAdminDashboard: React.FC<CompanyAdminDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [allApps, setAllApps] = useState<PassApplication[]>([]);
  const [allPasses, setAllPasses] = useState<IssuedPass[]>([]);
  const [company, setCompany] = useState<PharmaCompany | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [isMRModalOpen, setIsMRModalOpen] = useState(false);
  const [editingMR, setEditingMR] = useState<Partial<MedicalRep> | null>(null);

  const [summaryMR, setSummaryMR] = useState<MedicalRep | null>(null);
  const [resetMR, setResetMR] = useState<MedicalRep | null>(null);
  const [newPassword, setNewPassword] = useState('');

  useEffect(() => { refreshData(); }, []);

  const refreshData = () => {
    const allCompanies = storageService.getCompanies();
    const myCompany = allCompanies.find(c => c.id === user.companyId);
    if (myCompany) {
      setCompany(myCompany);
      const allMRs = storageService.getMRs();
      setMrs(allMRs.filter(m => m.companyName === myCompany.name));
    }
    setAllApps(storageService.getApplications());
    setAllPasses(storageService.getPasses());
  };

  const handleSaveMR = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingMR?.fullName || !editingMR?.mobileNumber || !company) return;

    const allMRs = storageService.getMRs();
    const mrData: MedicalRep = {
      id: editingMR.id || 'mr-' + Date.now(),
      fullName: editingMR.fullName || '',
      companyName: company.name,
      mrId: editingMR.mrId || `MR-${Math.floor(1000 + Math.random() * 9000)}`,
      mobileNumber: editingMR.mobileNumber || '',
      password: editingMR.password || 'mr123',
      identificationNumber: editingMR.identificationNumber || '',
      slcpiId: editingMR.slcpiId || '',
      status: editingMR.status || 'active',
      createdAt: editingMR.createdAt || new Date().toISOString()
    };

    let updated = editingMR.id 
      ? allMRs.map(m => m.id === editingMR.id ? mrData : m)
      : [...allMRs, mrData];

    storageService.saveMRs(updated);
    showFeedback(`Representative ${mrData.fullName} saved.`);
    setIsMRModalOpen(false);
    setEditingMR(null);
    refreshData();
  };

  const handleResetPassword = (e: React.FormEvent) => {
    e.preventDefault();
    if (!resetMR || !newPassword) return;

    const allMRs = storageService.getMRs();
    const updated = allMRs.map(m => m.id === resetMR.id ? { ...m, password: newPassword } : m);
    storageService.saveMRs(updated);
    showFeedback(`Password updated for ${resetMR.fullName}.`);
    setResetMR(null);
    setNewPassword('');
    refreshData();
  };

  const toggleMRStatus = (id: string) => {
    const allMRs = storageService.getMRs();
    const updated = allMRs.map(m => {
      if (m.id === id) {
        const newStatus = m.status === 'active' ? 'suspended' : 'active';
        showFeedback(`${m.fullName} is now ${newStatus}`);
        return { ...m, status: newStatus as any };
      }
      return m;
    });
    storageService.saveMRs(updated);
    refreshData();
  };

  const getMRStats = (mrId: string) => {
    const mrApps = allApps.filter(a => a.mrId === mrId);
    const mrPasses = allPasses.filter(p => p.mrId === mrId);
    const successfulEntries = mrPasses.filter(p => p.entryStatus === 'entered').length;
    return {
      totalApps: mrApps.length,
      selected: mrApps.filter(a => a.status === 'selected').length,
      waitlisted: mrApps.filter(a => a.status === 'waitlisted').length,
      entries: successfulEntries,
      entryRate: mrPasses.length > 0 ? ((successfulEntries / mrPasses.length) * 100).toFixed(0) : 0
    };
  };

  const teamStats = mrs.reduce((acc, mr) => {
    const stats = getMRStats(mr.id);
    acc.apps += stats.totalApps;
    acc.entries += stats.entries;
    return acc;
  }, { apps: 0, entries: 0 });

  const filteredMRs = mrs.filter(m => 
    m.fullName.toLowerCase().includes(searchTerm.toLowerCase()) || 
    m.mrId.toLowerCase().includes(searchTerm.toLowerCase()) ||
    m.mobileNumber.includes(searchTerm)
  );

  return (
    <div className="space-y-6">
      {/* Header Stat Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="bg-indigo-600 rounded-3xl p-5 text-white shadow-xl flex flex-col justify-between relative overflow-hidden md:col-span-1">
          <Briefcase className="absolute -right-4 -bottom-4 h-20 w-20 opacity-10" />
          <p className="text-[10px] font-black uppercase tracking-widest opacity-80 mb-1">Company</p>
          <h3 className="text-xl font-black truncate">{company?.name || "Pharma Admin"}</h3>
          <p className="text-[10px] mt-2 font-bold bg-white/20 px-2 py-0.5 rounded w-fit uppercase tracking-tighter">REG: {company?.companyCode}</p>
        </div>
        <div className="bg-white rounded-3xl p-5 border border-slate-100 shadow-sm">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Team Size</p>
          <h3 className="text-2xl font-black text-slate-800">{mrs.length} MRs</h3>
          <p className="text-[10px] text-green-500 font-bold mt-1">Active: {mrs.filter(m => m.status === 'active').length}</p>
        </div>
        <div className="bg-white rounded-3xl p-5 border border-slate-100 shadow-sm">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Company Success</p>
          <h3 className="text-2xl font-black text-indigo-600">{teamStats.entries} <span className="text-xs text-slate-400 font-medium">Entries</span></h3>
          <p className="text-[10px] text-slate-400 font-bold mt-1">From {teamStats.apps} Applications</p>
        </div>
        <div className="bg-white rounded-3xl p-5 border border-slate-100 shadow-sm flex items-center justify-center">
          <button 
            onClick={() => { setEditingMR({ status: 'active', password: 'mr' + Math.floor(100+Math.random()*899) }); setIsMRModalOpen(true); }}
            className="w-full h-full bg-indigo-50 text-indigo-600 rounded-2xl border-2 border-dashed border-indigo-200 font-black text-xs hover:bg-indigo-100 transition-all flex items-center justify-center gap-2"
          >
            <UserPlus className="h-4 w-4" /> ADD NEW MR
          </button>
        </div>
      </div>

      {/* Directory with Working Summary Actions */}
      <section className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-6">
          <h3 className="text-lg font-bold flex items-center gap-2"><Users className="h-5 w-5 text-indigo-500" /> MR Workforce Management</h3>
          <div className="relative w-full sm:w-64">
             <input type="text" placeholder="Search name, ID or mobile..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-9 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-500" />
             <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-slate-400" />
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-100">
                <th className="px-4 py-4">Medical Representative</th>
                <th className="px-4 py-4">Login (Mobile)</th>
                <th className="px-4 py-4">Status</th>
                <th className="px-4 py-4 text-right">Managed Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredMRs.map(mr => (
                <tr key={mr.id} className="hover:bg-slate-50/50 transition-colors group">
                  <td className="px-4 py-4">
                    <div className="flex items-center gap-3">
                      <div className="bg-slate-100 p-2 rounded-lg"><User className="h-4 w-4 text-slate-500" /></div>
                      <div>
                        <p className="font-bold text-slate-800 text-sm">{mr.fullName}</p>
                        <p className="text-[10px] text-slate-400 font-medium">ID: {mr.mrId}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-4 py-4 font-mono text-xs font-bold text-indigo-600">{mr.mobileNumber}</td>
                  <td className="px-4 py-4">
                    <span className={`px-2 py-0.5 rounded-lg text-[9px] font-black uppercase tracking-tighter ${mr.status === 'active' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>{mr.status}</span>
                  </td>
                  <td className="px-4 py-4 text-right">
                    <div className="flex justify-end gap-1.5">
                       <button onClick={() => setSummaryMR(mr)} className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all" title="View Summary"><BarChart3 className="h-4 w-4" /></button>
                       <button onClick={() => setResetMR(mr)} className="p-2 text-slate-400 hover:text-amber-600 hover:bg-amber-50 rounded-lg transition-all" title="Reset Password"><Key className="h-4 w-4" /></button>
                       <button onClick={() => { setEditingMR(mr); setIsMRModalOpen(true); }} className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all" title="Edit Profile"><Edit3 className="h-4 w-4" /></button>
                       <button onClick={() => toggleMRStatus(mr.id)} className={`p-2 rounded-lg transition-all ${mr.status === 'active' ? 'text-red-400 hover:bg-red-50' : 'text-green-500 hover:bg-green-50'}`} title={mr.status === 'active' ? 'Suspend' : 'Activate'}><Power className="h-4 w-4" /></button>
                    </div>
                  </td>
                </tr>
              ))}
              {filteredMRs.length === 0 && (
                <tr><td colSpan={4} className="py-12 text-center text-slate-400 italic text-sm">No matching representatives found.</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </section>

      {/* MR Management Modal */}
      {isMRModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in zoom-in duration-200">
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden">
            <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-bold text-slate-800">{editingMR?.id ? 'Update Representative' : 'Add New Representative'}</h3>
              <button onClick={() => setIsMRModalOpen(false)} className="p-2 hover:bg-slate-200 rounded-full"><X className="h-5 w-5 text-slate-400" /></button>
            </div>
            <form onSubmit={handleSaveMR} className="p-8 space-y-4">
              <div className="space-y-4">
                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Full Legal Name</label>
                  <input required type="text" value={editingMR?.fullName || ''} onChange={e => setEditingMR({...editingMR, fullName: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold focus:ring-2 focus:ring-indigo-500 outline-none" />
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Login Mobile</label>
                    <input required type="text" value={editingMR?.mobileNumber || ''} onChange={e => setEditingMR({...editingMR, mobileNumber: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold text-sm" placeholder="077XXXXXXX" />
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest block mb-1">Initial Password</label>
                    <input required type="text" value={editingMR?.password || ''} onChange={e => setEditingMR({...editingMR, password: e.target.value})} className="w-full px-4 py-3 bg-indigo-50 border border-indigo-200 rounded-xl font-bold text-sm" />
                  </div>
                </div>
                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">National ID / NIC</label>
                  <input required type="text" value={editingMR?.identificationNumber || ''} onChange={e => setEditingMR({...editingMR, identificationNumber: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold text-sm" />
                </div>
                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">SLCPI Registration</label>
                  <input required type="text" value={editingMR?.slcpiId || ''} onChange={e => setEditingMR({...editingMR, slcpiId: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold text-sm" placeholder="SLCPI-XXX" />
                </div>
              </div>
              <div className="flex gap-4 pt-4">
                <button type="button" onClick={() => setIsMRModalOpen(false)} className="flex-1 font-bold text-slate-500">Cancel</button>
                <button type="submit" className="flex-1 bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-xl active:scale-95 transition-all uppercase text-xs">Register MR</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Password Reset Modal */}
      {resetMR && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in">
          <div className="bg-white w-full max-w-sm rounded-3xl shadow-2xl overflow-hidden p-8">
            <div className="flex justify-between items-center mb-6">
              <h4 className="text-xl font-black text-slate-800 tracking-tight">Manage Credentials</h4>
              <button onClick={() => setResetMR(null)} className="p-2 hover:bg-slate-100 rounded-full"><X className="h-5 w-5 text-slate-400" /></button>
            </div>
            <div className="text-center mb-8">
               <div className="w-16 h-16 bg-amber-100 rounded-2xl flex items-center justify-center mx-auto mb-3"><Key className="h-8 w-8 text-amber-600" /></div>
               <p className="text-sm text-slate-500 leading-tight">Changing password for <span className="font-black text-slate-800">{resetMR.fullName}</span></p>
               <p className="text-[10px] text-slate-400 font-bold mt-1">ID: {resetMR.mobileNumber}</p>
            </div>
            <form onSubmit={handleResetPassword} className="space-y-4">
               <input required type="text" value={newPassword} onChange={e => setNewPassword(e.target.value)} placeholder="New Password" className="w-full px-4 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-black text-center focus:border-indigo-500 outline-none transition-all" />
               <button type="submit" className="w-full bg-slate-800 text-white font-black py-4 rounded-2xl shadow-xl active:scale-95 transition-all">UPDATE CREDENTIALS</button>
            </form>
          </div>
        </div>
      )}

      {/* MR Working Summary Modal */}
      {summaryMR && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in slide-in-from-bottom-4">
          <div className="bg-white w-full max-w-lg rounded-3xl shadow-2xl overflow-hidden">
            <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-bold text-slate-800">Working Summary</h3>
              <button onClick={() => setSummaryMR(null)} className="p-2 hover:bg-slate-200 rounded-full"><X className="h-5 w-5 text-slate-400" /></button>
            </div>
            <div className="p-8 space-y-8">
              <div className="flex items-center gap-4">
                 <div className="w-16 h-16 bg-indigo-100 rounded-2xl flex items-center justify-center border-2 border-white shadow-sm"><User className="h-8 w-8 text-indigo-600" /></div>
                 <div>
                   <h4 className="text-xl font-black text-slate-800">{summaryMR.fullName}</h4>
                   <p className="text-indigo-600 font-bold text-xs uppercase tracking-widest">{summaryMR.mrId}</p>
                 </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                {(() => {
                  const stats = getMRStats(summaryMR.id);
                  return (
                    <>
                      <div className="p-5 bg-slate-50 rounded-2xl border border-slate-100 flex flex-col justify-between h-32">
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-1.5"><Clock className="h-3 w-3" /> Applications</p>
                        <p className="text-3xl font-black text-slate-800">{stats.totalApps}</p>
                        <p className="text-[10px] text-slate-400 font-bold uppercase">Lifetime Demand</p>
                      </div>
                      <div className="p-5 bg-indigo-50 rounded-2xl border border-indigo-100 flex flex-col justify-between h-32">
                        <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest flex items-center gap-1.5"><CheckCircle2 className="h-3 w-3" /> Success Rate</p>
                        <p className="text-3xl font-black text-indigo-600">{stats.entryRate}%</p>
                        <p className="text-[10px] text-indigo-400 font-bold uppercase">Conversion</p>
                      </div>
                      <div className="p-5 bg-green-50 rounded-2xl border border-green-100 flex flex-col justify-between h-32">
                        <p className="text-[10px] font-black text-green-500 uppercase tracking-widest flex items-center gap-1.5"><ShieldCheck className="h-3 w-3" /> Physical Visits</p>
                        <p className="text-3xl font-black text-green-600">{stats.entries}</p>
                        <p className="text-[10px] text-green-400 font-bold uppercase">Confirmed Entries</p>
                      </div>
                      <div className="p-5 bg-amber-50 rounded-2xl border border-amber-100 flex flex-col justify-between h-32">
                        <p className="text-[10px] font-black text-amber-500 uppercase tracking-widest flex items-center gap-1.5"><TrendingUp className="h-3 w-3" /> Pass Issuance</p>
                        <p className="text-3xl font-black text-amber-600">{stats.selected}</p>
                        <p className="text-[10px] text-amber-400 font-bold uppercase">Lottery Victories</p>
                      </div>
                    </>
                  );
                })()}
              </div>
              <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100 text-[10px] font-bold text-slate-500 leading-relaxed uppercase tracking-wider">
                This summary shows activity across the entire ecosystem. Data includes pass issuance and gate security confirmation logs.
              </div>
              <button onClick={() => setSummaryMR(null)} className="w-full bg-slate-800 text-white font-black py-4 rounded-2xl shadow-xl active:scale-95 transition-all">CLOSE SUMMARY</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CompanyAdminDashboard;

export type MRStatus = 'active' | 'suspended';
export type ApplicationStatus = 'applied' | 'selected' | 'waitlisted' | 'rejected';
export type EntryStatus = 'not_entered' | 'entered' | 'expired';
export type UserRole = 'MR' | 'ADMIN' | 'SECURITY' | 'SUPER_ADMIN' | 'COMPANY_ADMIN';
export type ApprovalStatus = 'pending' | 'approved' | 'rejected';
export type SessionType = 'MORNING' | 'EVENING' | 'FULL_DAY';

export interface MedicalRep {
  id: string;
  fullName: string;
  email?: string;
  companyName: string; // Used for PharmaCompany linking
  mrId: string;
  mobileNumber: string;
  password?: string; // Credentials managed by Company Admin
  identificationNumber: string; // Valid ID for signup
  slcpiId?: string;
  status: MRStatus;
  createdAt: string;
}

export interface Hospital {
  id: string;
  name: string;
  supportedSessions: SessionType[];
  passLimits: Record<string, number>; 
  sessionWindows: Record<string, { start: string; end: string }>; 
  isActive: boolean;
}

export interface HospitalUser {
  id: string;
  hospitalId: string;
  mobileNumber: string; // Used as Login ID
  password: string;     
  role: 'ADMIN' | 'SECURITY';
  fullName: string;
}

export interface MRHospitalApproval {
  id: string;
  mrId: string;
  hospitalId: string;
  status: ApprovalStatus;
  updatedAt: string;
}

export interface PassApplication {
  id: string;
  mrId: string;
  hospitalId: string;
  session: SessionType;
  applicationDate: string;
  priorityScore: number;
  status: ApplicationStatus;
  createdAt: string;
}

export interface IssuedPass {
  id: string;
  mrId: string;
  hospitalId: string;
  session: SessionType;
  passDate: string;
  timeSlot: string;
  qrCode: string;
  entryStatus: EntryStatus;
}

export interface PharmaCompany {
  id: string;
  name: string;
  contactEmail: string;
  companyCode: string; // Unique code for tracking
  adminMobile: string; // Login for Company Admin
  adminPassword: string; // Password for Company Admin
  isActive: boolean;
}

export interface Invoice {
  id: string;
  companyId: string;
  amount: number;
  activeMRCount: number;
  status: 'paid' | 'unpaid';
  date: string;
}

export interface EntryLog {
  id: string;
  issuedPassId: string;
  entryTime: string;
  verifiedBy: string;
}

// User in session
export interface AuthUser {
  id: string;
  role: UserRole;
  fullName: string;
  mobileNumber?: string;
  hospitalId?: string; // For hospital admins
  companyId?: string; // For company admins
  companyName?: string; // For MRs
}

import { MedicalRep, Hospital, PassApplication, IssuedPass, EntryLog, MRHospitalApproval, PharmaCompany, Invoice, HospitalUser, AuthUser } from '../types';

const KEYS = {
  MRS: 'medpass_mrs',
  HOSPITALS: 'medpass_hospitals',
  HOSPITAL_USERS: 'medpass_hospital_users',
  APPLICATIONS: 'medpass_applications',
  PASSES: 'medpass_passes',
  LOGS: 'medpass_logs',
  SESSION: 'medpass_session',
  APPROVALS: 'medpass_approvals',
  COMPANIES: 'medpass_companies',
  INVOICES: 'medpass_invoices'
};

export const storageService = {
  getMRs: (): MedicalRep[] => {
    const mrs = localStorage.getItem(KEYS.MRS);
    if (!mrs) {
      const initial: MedicalRep[] = [
        {
          id: 'mr-1',
          fullName: 'John Doe',
          companyName: 'Pfizer Lanka',
          mrId: 'MR-7890',
          mobileNumber: '0771234567',
          password: 'pass', // Default password for demo
          identificationNumber: '951234567V',
          status: 'active',
          createdAt: new Date().toISOString()
        }
      ];
      localStorage.setItem(KEYS.MRS, JSON.stringify(initial));
      return initial;
    }
    return JSON.parse(mrs);
  },
  saveMRs: (mrs: MedicalRep[]) => localStorage.setItem(KEYS.MRS, JSON.stringify(mrs)),

  getHospitals: (): Hospital[] => {
    const hospitals = localStorage.getItem(KEYS.HOSPITALS);
    if (!hospitals) {
      const initial: Hospital[] = [
        {
          id: 'h1',
          name: 'Colombo General Hospital',
          supportedSessions: ['MORNING', 'EVENING'],
          passLimits: { 'MORNING': 10, 'EVENING': 10 },
          sessionWindows: { 
            'MORNING': { start: '00:00', end: '23:59' }, 
            'EVENING': { start: '00:00', end: '23:59' } 
          },
          isActive: true
        }
      ];
      localStorage.setItem(KEYS.HOSPITALS, JSON.stringify(initial));
      return initial;
    }
    return JSON.parse(hospitals);
  },
  saveHospitals: (hospitals: Hospital[]) => localStorage.setItem(KEYS.HOSPITALS, JSON.stringify(hospitals)),

  getHospitalUsers: (): HospitalUser[] => {
    const users = localStorage.getItem(KEYS.HOSPITAL_USERS);
    if (!users) {
      const initial: HospitalUser[] = [
        { id: 'u1', hospitalId: 'h1', mobileNumber: '0771', password: 'admin', role: 'ADMIN', fullName: 'Colombo Admin' },
        { id: 'u2', hospitalId: 'h1', mobileNumber: '07711', password: 'guard', role: 'SECURITY', fullName: 'Colombo Security' },
      ];
      localStorage.setItem(KEYS.HOSPITAL_USERS, JSON.stringify(initial));
      return initial;
    }
    return JSON.parse(users);
  },
  saveHospitalUsers: (users: HospitalUser[]) => localStorage.setItem(KEYS.HOSPITAL_USERS, JSON.stringify(users)),

  getApprovals: (): MRHospitalApproval[] => JSON.parse(localStorage.getItem(KEYS.APPROVALS) || '[]'),
  saveApprovals: (apps: MRHospitalApproval[]) => localStorage.setItem(KEYS.APPROVALS, JSON.stringify(apps)),

  getApplications: (): PassApplication[] => JSON.parse(localStorage.getItem(KEYS.APPLICATIONS) || '[]'),
  saveApplications: (apps: PassApplication[]) => localStorage.setItem(KEYS.APPLICATIONS, JSON.stringify(apps)),

  getPasses: (): IssuedPass[] => JSON.parse(localStorage.getItem(KEYS.PASSES) || '[]'),
  savePasses: (passes: IssuedPass[]) => localStorage.setItem(KEYS.PASSES, JSON.stringify(passes)),

  getCompanies: (): PharmaCompany[] => {
    const companies = localStorage.getItem(KEYS.COMPANIES);
    if (!companies) {
      const initial: PharmaCompany[] = [{ 
        id: 'c1', 
        name: 'Pfizer Lanka', 
        contactEmail: 'admin@pfizer.lk', 
        companyCode: 'PFIZ-01',
        adminMobile: '0779', 
        adminPassword: 'pfiz', 
        isActive: true 
      }];
      localStorage.setItem(KEYS.COMPANIES, JSON.stringify(initial));
      return initial;
    }
    return JSON.parse(companies);
  },
  saveCompanies: (companies: PharmaCompany[]) => localStorage.setItem(KEYS.COMPANIES, JSON.stringify(companies)),

  getInvoices: (): Invoice[] => JSON.parse(localStorage.getItem(KEYS.INVOICES) || '[]'),
  saveInvoices: (invoices: Invoice[]) => localStorage.setItem(KEYS.INVOICES, JSON.stringify(invoices)),

  getLogs: (): EntryLog[] => JSON.parse(localStorage.getItem(KEYS.LOGS) || '[]'),
  saveLogs: (logs: EntryLog[]) => localStorage.setItem(KEYS.LOGS, JSON.stringify(logs)),

  setCurrentUser: (user: AuthUser) => localStorage.setItem(KEYS.SESSION, JSON.stringify(user)),
  getCurrentUser: (): AuthUser | null => {
    const session = localStorage.getItem(KEYS.SESSION);
    return session ? JSON.parse(session) : null;
  },
  clearSession: () => localStorage.removeItem(KEYS.SESSION)
};

import React, { useState, useEffect, createContext, useContext } from 'react';
import { storageService } from './services/storageService';
import Layout from './components/Layout';
import MRDashboard from './components/MRDashboard';
import AdminDashboard from './components/AdminDashboard';
import SuperAdminDashboard from './components/SuperAdminDashboard';
import SecurityView from './components/SecurityView';
import CompanyAdminDashboard from './components/CompanyAdminDashboard';
import { Shield, User, Key, ArrowRight, Hospital as HospitalIcon, Laptop, ShieldCheck, Crown, CheckCircle2, AlertCircle, X, Lock, Briefcase } from 'lucide-react';
import { UserRole, AuthUser } from './types';

// Simple context for global notifications
export const FeedbackContext = createContext<{
  showFeedback: (msg: string, type?: 'success' | 'error') => void;
}>({ showFeedback: () => {} });

const FeedbackToast = ({ message, type, onClose }: { message: string, type: 'success' | 'error', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 4000);
    return () => clearTimeout(timer);
  }, [onClose]);

  return (
    <div className="fixed bottom-6 right-6 z-[200] animate-in slide-in-from-right-10 fade-in duration-300">
      <div className={`flex items-center gap-3 px-6 py-4 rounded-2xl shadow-2xl border ${
        type === 'success' ? 'bg-white border-green-100 text-green-800' : 'bg-white border-red-100 text-red-800'
      }`}>
        {type === 'success' ? <CheckCircle2 className="h-6 w-6 text-green-500" /> : <AlertCircle className="h-6 w-6 text-red-500" />}
        <p className="font-bold text-sm">{message}</p>
        <button onClick={onClose} className="ml-2 p-1 hover:bg-slate-100 rounded-lg transition-all">
          <X className="h-4 w-4 text-slate-400" />
        </button>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [user, setUser] = useState<any>(null);
  const [view, setView] = useState<'LOGIN' | 'DASHBOARD'>('LOGIN');
  const [role, setRole] = useState<UserRole>('MR');
  const [mobile, setMobile] = useState('');
  const [password, setPassword] = useState('');
  const [feedback, setFeedback] = useState<{ message: string, type: 'success' | 'error' } | null>(null);

  useEffect(() => {
    const session = storageService.getCurrentUser();
    if (session) { setUser(session); setView('DASHBOARD'); }
  }, []);

  const showFeedback = (message: string, type: 'success' | 'error' = 'success') => {
    setFeedback({ message, type });
  };

  const handleLogin = (e?: React.FormEvent) => {
    e?.preventDefault();

    if (role === 'MR') {
      const mrs = storageService.getMRs();
      const existing = mrs.find(m => m.mobileNumber === mobile);
      if (existing) {
        if (existing.status === 'suspended') {
          showFeedback("Your account has been suspended by your company.", 'error');
          return;
        }
        // Verify password
        if (existing.password && existing.password !== password) {
          showFeedback("Invalid credentials.", 'error');
          return;
        }
        const u: AuthUser = { id: existing.id, fullName: existing.fullName, role: 'MR', companyName: existing.companyName, mobileNumber: existing.mobileNumber };
        storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
        showFeedback(`Welcome back, ${u.fullName}!`);
      } else {
        showFeedback("Medical Representative not found.", 'error');
      }
    } else if (role === 'COMPANY_ADMIN') {
      const companies = storageService.getCompanies();
      const found = companies.find(c => c.adminMobile === mobile);
      if (found && found.adminPassword === password) {
        if (!found.isActive) {
          showFeedback("Company access is deactivated.", 'error');
          return;
        }
        const u: AuthUser = { 
          id: found.id, 
          role: 'COMPANY_ADMIN', 
          fullName: `${found.name} Admin`,
          companyId: found.id 
        };
        storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
        showFeedback(`Pharma Admin session: ${found.name}`);
      } else {
        showFeedback("Invalid Company Admin credentials.", 'error');
      }
    } else if (role === 'ADMIN' || role === 'SECURITY') {
      const hospitalUsers = storageService.getHospitalUsers();
      const found = hospitalUsers.find(u => u.mobileNumber === mobile && u.role === role);

      if (found) {
        if (found.password === password) {
          const u: AuthUser = { 
            id: found.id,
            role: found.role, 
            fullName: found.fullName, 
            hospitalId: found.hospitalId,
            mobileNumber: found.mobileNumber
          };
          storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
          showFeedback(`Logged in as ${found.fullName}`);
        } else {
          showFeedback("Invalid password for this account.", 'error');
        }
      } else {
        showFeedback(`${role} credentials not found. Check with Super Admin.`, 'error');
      }
    } else if (role === 'SUPER_ADMIN') {
      if (mobile === 'root' && password === 'root') {
        const u: AuthUser = { id: 'sa-1', role: 'SUPER_ADMIN', fullName: 'MedPass Authority' };
        storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
        showFeedback("Super Admin session started.");
      } else {
        showFeedback("Invalid Super Admin Credentials", 'error');
      }
    }
  };

  const quickLogin = (r: UserRole, phone = '', pass = '') => { 
    setRole(r); 
    setMobile(phone);
    setPassword(pass);
    setTimeout(() => handleLogin(), 100); 
  };

  if (view === 'LOGIN') {
    return (
      <FeedbackContext.Provider value={{ showFeedback }}>
        <div className="min-h-screen bg-indigo-600 flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden">
            <div className="bg-slate-50 p-8 text-center border-b border-slate-100">
              <div className="bg-indigo-600 w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-4"><HospitalIcon className="h-10 w-10 text-white" /></div>
              <h1 className="text-2xl font-black text-slate-800 tracking-tighter">MedPass Engine</h1>
            </div>
            <div className="p-8">
              <div className="mb-6 bg-indigo-50 rounded-xl p-4">
                <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-2">System Demo Credentials</p>
                <div className="grid grid-cols-2 gap-2">
                  <button onClick={() => quickLogin('MR', '0771234567', 'pass')} className="p-2 bg-white border border-indigo-100 rounded text-[10px] font-bold text-slate-700 flex flex-col items-center">
                    <User className="h-3 w-3 mb-1" /> MR John
                  </button>
                  <button onClick={() => quickLogin('COMPANY_ADMIN', '0779', 'pfiz')} className="p-2 bg-indigo-50 border border-indigo-100 rounded text-[10px] font-bold text-indigo-700 flex flex-col items-center">
                     <Briefcase className="h-3 w-3 mb-1" /> Pharma Admin
                  </button>
                  <button onClick={() => quickLogin('ADMIN', '0771', 'admin')} className="p-2 bg-slate-50 border border-slate-100 rounded text-[10px] font-bold text-slate-700 flex flex-col items-center">
                     <ShieldCheck className="h-3 w-3 mb-1" /> Hospital Admin
                  </button>
                  <button onClick={() => quickLogin('SUPER_ADMIN', 'root', 'root')} className="p-2 bg-slate-800 border border-slate-700 rounded text-[10px] font-bold text-white flex flex-col items-center">
                     <Crown className="h-3 w-3 mb-1" /> Super Admin
                  </button>
                </div>
              </div>

              <div className="flex bg-slate-100 p-1 rounded-xl mb-6 overflow-x-auto scrollbar-hide">
                {(['MR', 'COMPANY_ADMIN', 'ADMIN', 'SECURITY', 'SUPER_ADMIN'] as const).map(r => (
                  <button key={r} onClick={() => setRole(r)} className={`flex-1 min-w-[80px] py-1.5 text-[10px] font-black rounded-lg transition-all ${role === r ? 'bg-white text-indigo-600 shadow' : 'text-slate-400'}`}>{r}</button>
                ))}
              </div>

              <form onSubmit={handleLogin} className="space-y-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Login ID / Mobile</label>
                  <input 
                    type="text" 
                    value={mobile} 
                    onChange={e => setMobile(e.target.value)} 
                    className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-bold" 
                    placeholder={role === 'MR' ? "0771234567" : role === 'SUPER_ADMIN' ? "root" : "Admin ID"}
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Password</label>
                  <div className="relative">
                    <input 
                      type="password" 
                      value={password} 
                      onChange={e => setPassword(e.target.value)} 
                      className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-bold" 
                      placeholder="••••••••"
                    />
                    <Lock className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-300" />
                  </div>
                </div>
                <button type="submit" className="w-full bg-indigo-600 text-white font-black py-4 rounded-xl shadow-lg hover:bg-indigo-700 active:scale-95 transition-all flex items-center justify-center gap-2">
                  Enter System <ArrowRight className="h-5 w-5" />
                </button>
              </form>
            </div>
          </div>
          {feedback && <FeedbackToast message={feedback.message} type={feedback.type} onClose={() => setFeedback(null)} />}
        </div>
      </FeedbackContext.Provider>
    );
  }

  return (
    <FeedbackContext.Provider value={{ showFeedback }}>
      <Layout 
        user={user} 
        onLogout={() => { storageService.clearSession(); setUser(null); setView('LOGIN'); showFeedback("Logged out successfully"); }} 
        title={user.role === 'SUPER_ADMIN' ? 'Root Authority' : user.role === 'MR' ? 'MR Dashboard' : `${user.fullName} Panel`}
      >
        {user.role === 'MR' && <MRDashboard user={user} />}
        {user.role === 'COMPANY_ADMIN' && <CompanyAdminDashboard user={user} />}
        {user.role === 'ADMIN' && <AdminDashboard user={user} />}
        {user.role === 'SUPER_ADMIN' && <SuperAdminDashboard />}
        {user.role === 'SECURITY' && <SecurityView />}
      </Layout>
      {feedback && <FeedbackToast message={feedback.message} type={feedback.type} onClose={() => setFeedback(null)} />}
    </FeedbackContext.Provider>
  );
};

export default App;

import React, { useState, useEffect, useContext } from 'react';
import { UserPlus, Search, Briefcase, Mail, Phone, CreditCard, X, Edit3, Trash2, Power, User, ShieldCheck, Activity, Users, Plus, Key, BarChart3, Clock, CheckCircle2 } from 'lucide-react';
import { storageService } from '../services/storageService';
import { MedicalRep, PharmaCompany, AuthUser, PassApplication, IssuedPass } from '../types';
import { FeedbackContext } from '../App';

interface CompanyAdminDashboardProps {
  user: AuthUser;
}

const CompanyAdminDashboard: React.FC<CompanyAdminDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [allApps, setAllApps] = useState<PassApplication[]>([]);
  const [allPasses, setAllPasses] = useState<IssuedPass[]>([]);
  const [company, setCompany] = useState<PharmaCompany | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [isMRModalOpen, setIsMRModalOpen] = useState(false);
  const [editingMR, setEditingMR] = useState<Partial<MedicalRep> | null>(null);

  // Working Summary state
  const [summaryMR, setSummaryMR] = useState<MedicalRep | null>(null);

  // Password Reset state
  const [resetMR, setResetMR] = useState<MedicalRep | null>(null);
  const [newPassword, setNewPassword] = useState('');

  useEffect(() => {
    refreshData();
  }, []);

  const refreshData = () => {
    const allCompanies = storageService.getCompanies();
    const myCompany = allCompanies.find(c => c.id === user.companyId);
    if (myCompany) {
      setCompany(myCompany);
      const allMRs = storageService.getMRs();
      setMrs(allMRs.filter(m => m.companyName === myCompany.name));
    }
    setAllApps(storageService.getApplications());
    setAllPasses(storageService.getPasses());
  };

  const handleSaveMR = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingMR?.fullName || !editingMR?.mobileNumber || !company) return;

    const allMRs = storageService.getMRs();
    let updated: MedicalRep[];

    const mrData: MedicalRep = {
      id: editingMR.id || 'mr-' + Date.now(),
      fullName: editingMR.fullName,
      companyName: company.name,
      mrId: editingMR.mrId || `MR-${Math.floor(1000 + Math.random() * 9000)}`,
      mobileNumber: editingMR.mobileNumber,
      password: editingMR.password || 'mr123', // Default if new
      identificationNumber: editingMR.identificationNumber || '',
      slcpiId: editingMR.slcpiId || '',
      status: editingMR.status || 'active',
      createdAt: editingMR.createdAt || new Date().toISOString()
    };

    if (editingMR.id) {
      updated = allMRs.map(m => m.id === editingMR.id ? mrData : m);
      showFeedback(`Profile updated for ${mrData.fullName}`);
    } else {
      updated = [...allMRs, mrData];
      showFeedback(`Representative ${mrData.fullName} registered successfully.`);
    }

    storageService.saveMRs(updated);
    setMrs(updated.filter(m => m.companyName === company.name));
    setIsMRModalOpen(false);
    setEditingMR(null);
  };

  const handleResetPassword = (e: React.FormEvent) => {
    e.preventDefault();
    if (!resetMR || !newPassword) return;

    const allMRs = storageService.getMRs();
    const updated = allMRs.map(m => 
      m.id === resetMR.id ? { ...m, password: newPassword } : m
    );
    storageService.saveMRs(updated);
    showFeedback(`Password changed successfully for ${resetMR.fullName}`);
    setResetMR(null);
    setNewPassword('');
    refreshData();
  };

  const toggleMRStatus = (id: string) => {
    const allMRs = storageService.getMRs();
    const updated = allMRs.map(m => {
      if (m.id === id) {
        const newStatus = m.status === 'active' ? 'suspended' : 'active';
        showFeedback(`${m.fullName} is now ${newStatus}`);
        return { ...m, status: newStatus as any };
      }
      return m;
    });
    storageService.saveMRs(updated);
    setMrs(updated.filter(m => m.companyName === company?.name));
  };

  const getMRStats = (mrId: string) => {
    const mrApps = allApps.filter(a => a.mrId === mrId);
    const mrPasses = allPasses.filter(p => p.mrId === mrId);
    const successVisits = mrPasses.filter(p => p.entryStatus === 'entered').length;

    return {
      totalApps: mrApps.length,
      granted: mrPasses.length,
      visits: successVisits,
      conversion: mrApps.length > 0 ? ((successVisits / mrApps.length) * 100).toFixed(0) : 0
    };
  };

  const filteredMRs = mrs.filter(m => 
    m.fullName.toLowerCase().includes(searchTerm.toLowerCase()) || 
    m.mrId.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="space-y-6">
      {/* Header Stat Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-indigo-600 rounded-3xl p-6 text-white shadow-xl flex flex-col justify-between relative overflow-hidden">
          <Briefcase className="absolute -right-4 -bottom-4 h-24 w-24 opacity-10" />
          <p className="text-[10px] font-black uppercase tracking-widest opacity-80 mb-1">Active Company</p>
          <h3 className="text-2xl font-black truncate">{company?.name || "Loading..."}</h3>
          <p className="text-xs mt-2 font-bold bg-white/20 px-2 py-1 rounded w-fit tracking-wider">CODE: {company?.companyCode}</p>
        </div>

        <div className="bg-white rounded-3xl p-6 border border-slate-100 shadow-sm flex flex-col justify-between">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Total Pool</p>
          <h3 className="text-3xl font-black text-slate-800">{mrs.length} Reps</h3>
          <div className="flex gap-4 mt-2">
            <span className="text-[10px] font-bold text-green-500 uppercase">Active: {mrs.filter(m => m.status === 'active').length}</span>
            <span className="text-[10px] font-bold text-red-400 uppercase">Suspended: {mrs.filter(m => m.status === 'suspended').length}</span>
          </div>
        </div>

        <div className="bg-white rounded-3xl p-6 border border-slate-100 shadow-sm flex items-center justify-center">
          <button 
            onClick={() => { setEditingMR({ status: 'active', password: 'mr' + Math.floor(100+Math.random()*900) }); setIsMRModalOpen(true); }}
