          <Briefcase className="absolute -right-4 -bottom-4 h-24 w-24 opacity-10" />
          <p className="text-[10px] font-black uppercase tracking-widest opacity-80 mb-1">Active Company</p>
          <h3 className="text-2xl font-black truncate">{company?.name || "Loading..."}</h3>
          <p className="text-xs mt-2 font-bold bg-white/20 px-2 py-1 rounded w-fit tracking-wider">CODE: {company?.companyCode}</p>
        </div>

        <div className="bg-white rounded-3xl p-6 border border-slate-100 shadow-sm flex flex-col justify-between">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Total Pool</p>
          <h3 className="text-3xl font-black text-slate-800">{mrs.length} Reps</h3>
          <div className="flex gap-4 mt-2">
            <span className="text-[10px] font-bold text-green-500 uppercase">Active: {mrs.filter(m => m.status === 'active').length}</span>
            <span className="text-[10px] font-bold text-red-400 uppercase">Suspended: {mrs.filter(m => m.status === 'suspended').length}</span>
          </div>
        </div>

        <div className="bg-white rounded-3xl p-6 border border-slate-100 shadow-sm flex items-center justify-center">
          <button 
            onClick={() => { setEditingMR({ status: 'active', loginId: '', mobileNumber: '', password: 'mr' + Math.floor(100+Math.random()*900) }); setIsMRModalOpen(true); }}
            className="w-full bg-indigo-50 text-indigo-600 py-4 rounded-2xl border-2 border-dashed border-indigo-200 font-black text-sm flex items-center justify-center gap-2 hover:bg-indigo-100 transition-all active:scale-95"
          >
            <UserPlus className="h-5 w-5" /> REGISTER NEW MR
          </button>
        </div>
      </div>

      {/* MR Management Section */}
      <section className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-6">
          <h3 className="text-lg font-bold flex items-center gap-2 text-slate-800">
             <Users className="h-5 w-5 text-indigo-500" />
             Representative Directory
          </h3>
          <div className="relative w-full sm:w-64">
             <input 
               type="text" 
               placeholder="Search by name or ID..." 
               value={searchTerm}
               onChange={e => setSearchTerm(e.target.value)}
               className="w-full pl-9 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
             />
             <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-100">
                <th className="px-4 py-4">Full Name</th>
                <th className="px-4 py-4">Login ID</th>
                <th className="px-4 py-4">Status</th>
                <th className="px-4 py-4 text-right">Managed Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredMRs.map(mr => (
                <tr key={mr.id} className="hover:bg-slate-50/50 transition-colors group">
                  <td className="px-4 py-4">
                    <div className="flex items-center gap-3">
                      <div className="bg-slate-100 p-2 rounded-lg group-hover:bg-indigo-50 transition-colors">
                        <User className="h-4 w-4 text-slate-500 group-hover:text-indigo-600" />
                      </div>
                      <div>
                        <p className="font-bold text-slate-800 text-sm">{mr.fullName}</p>
                        <p className="text-[10px] text-slate-400 font-medium">System ID: {mr.mrId}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-4 py-4 font-mono font-bold text-indigo-600 text-xs">
                    {mr.loginId}
                  </td>
                  <td className="px-4 py-4">
                    <span className={`px-2 py-0.5 rounded-lg text-[9px] font-black uppercase tracking-tighter ${mr.status === 'active' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                      {mr.status}
                    </span>
                  </td>
                  <td className="px-4 py-4 text-right">
                    <div className="flex justify-end gap-1.5">
                       <button onClick={() => setSummaryMR(mr)} className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all" title="View Summary"><BarChart3 className="h-4 w-4" /></button>
                       <button onClick={() => setResetMR(mr)} className="p-2 text-slate-400 hover:text-amber-600 hover:bg-amber-50 rounded-lg transition-all" title="Reset Password"><Key className="h-4 w-4" /></button>
                       <button onClick={() => { setEditingMR(mr); setIsMRModalOpen(true); }} className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all" title="Edit Profile"><Edit3 className="h-4 w-4" /></button>
                       <button onClick={() => toggleMRStatus(mr.id)} className={`p-2 rounded-lg transition-all ${mr.status === 'active' ? 'text-red-400 hover:bg-red-50' : 'text-green-500 hover:bg-green-50'}`} title={mr.status === 'active' ? 'Suspend' : 'Activate'}>
                         <Power className="h-4 w-4" />
                       </button>
                    </div>
                  </td>
                </tr>
              ))}
              {filteredMRs.length === 0 && (
                <tr><td colSpan={4} className="py-12 text-center text-slate-400 italic text-sm">No representatives registered yet.</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </section>

      {/* Password Reset Modal */}
      {resetMR && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-sm rounded-3xl shadow-2xl overflow-hidden p-8">
            <div className="flex justify-between items-center mb-6">
               <h4 className="text-xl font-black text-slate-800">Managed Credentials</h4>
               <button onClick={() => setResetMR(null)} className="p-2 hover:bg-slate-100 rounded-full"><X className="h-5 w-5 text-slate-400" /></button>
            </div>
            <p className="text-sm text-slate-500 mb-6 leading-tight">Setting new access password for <span className="font-black text-slate-800">{resetMR.fullName}</span>. This will override their current login key.</p>
            <form onSubmit={handleResetPassword} className="space-y-4">
              <div className="relative">
                <input 
                  required 
                  type="text" 
                  value={newPassword} 
                  onChange={e => setNewPassword(e.target.value)} 
                  placeholder="Enter new password..."
                  className="w-full px-4 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-black text-center focus:border-indigo-500 outline-none transition-all"
                />
              </div>
              <button type="submit" className="w-full bg-slate-800 text-white font-black py-4 rounded-2xl shadow-xl active:scale-95 transition-all">UPDATE CREDENTIALS</button>
            </form>
          </div>
        </div>
      )}

      {/* Working Summary Modal */}
      {summaryMR && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in zoom-in duration-200">
          <div className="bg-white w-full max-w-lg rounded-3xl shadow-2xl overflow-hidden">
            <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-bold text-slate-800">Working Summary</h3>
              <button onClick={() => setSummaryMR(null)} className="p-2 hover:bg-slate-200 rounded-full"><X className="h-5 w-5 text-slate-400" /></button>
            </div>
            <div className="p-8 space-y-6">
              <div className="flex items-center gap-4">
                 <div className="w-16 h-16 bg-indigo-100 rounded-2xl flex items-center justify-center border-2 border-white shadow-sm">
                   <User className="h-8 w-8 text-indigo-600" />
                 </div>
                 <div>
                   <h4 className="text-xl font-black text-slate-800">{summaryMR.fullName}</h4>
                   <p className="text-indigo-600 font-bold text-xs uppercase tracking-widest">{summaryMR.mrId}</p>
                 </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                {(() => {
                  const stats = getMRStats(summaryMR.id);
                  return (
                    <>
                      <div className="p-5 bg-slate-50 rounded-2xl border border-slate-100 flex flex-col justify-between">
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-1.5"><Clock className="h-3 w-3" /> Applications</p>
                        <p className="text-3xl font-black text-slate-800 mt-2">{stats.totalApps}</p>
                      </div>
                      <div className="p-5 bg-indigo-50 rounded-2xl border border-indigo-100 flex flex-col justify-between">
                        <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest flex items-center gap-1.5"><Activity className="h-3 w-3" /> Conversion</p>
                        <p className="text-3xl font-black text-indigo-600 mt-2">{stats.conversion}%</p>
                      </div>
                      <div className="p-5 bg-green-50 rounded-2xl border border-green-100 flex flex-col justify-between">
                        <p className="text-[10px] font-black text-green-500 uppercase tracking-widest flex items-center gap-1.5"><CheckCircle2 className="h-3 w-3" /> Confirmed Visits</p>
                        <p className="text-3xl font-black text-green-600 mt-2">{stats.visits}</p>
                      </div>
                      <div className="p-5 bg-slate-800 rounded-2xl border border-slate-700 flex flex-col justify-between">
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-1.5"><ShieldCheck className="h-3 w-3" /> Passes Issued</p>
                        <p className="text-3xl font-black text-white mt-2">{stats.granted}</p>
                      </div>
                    </>
                  );
                })()}
              </div>

              <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100 space-y-3">
                 <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Verification Documents</p>
                 <div className="flex items-center gap-3 bg-white p-3 rounded-xl border border-slate-200">
                    <FileText className="h-5 w-5 text-indigo-500" />
                    <div>
                      <p className="text-xs font-bold text-slate-800">SLCPI Certificate</p>
                      <p className="text-[10px] text-slate-500">{summaryMR.slcpiId || 'Not provided'}</p>
                    </div>
                 </div>
                 {summaryMR.slcpiPhoto && (
                   <div className="mt-2 rounded-xl overflow-hidden border border-slate-200 aspect-video relative">
                     <img src={summaryMR.slcpiPhoto} alt="SLCPI ID" className="w-full h-full object-cover" />
                     <div className="absolute inset-0 bg-slate-900/40 flex items-center justify-center opacity-0 hover:opacity-100 transition-opacity">
                        <p className="text-white text-[10px] font-black uppercase tracking-widest">View Full ID</p>
                     </div>
                   </div>
                 )}
              </div>

              <button onClick={() => setSummaryMR(null)} className="w-full bg-slate-800 text-white font-bold py-4 rounded-2xl hover:bg-slate-900 transition-all">CLOSE SUMMARY</button>
            </div>
          </div>
        </div>
      )}

      {/* MR Registration / Edit Modal */}
      {isMRModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden animate-in slide-in-from-bottom-4 duration-300">
            <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-bold text-slate-800">{editingMR?.id ? 'Update Representative' : 'Register New Representative'}</h3>
