                   </div>
                 )}
              </div>

              <div className="flex gap-4">
                {activeTab === 'approvals' && (
                  <>
                    <button onClick={() => updateApproval(approvals.find(a => a.mrId === selectedMR.id && a.hospitalId === user.hospitalId)?.id || '', 'approved')} className="flex-1 bg-green-600 text-white font-black py-4 rounded-2xl shadow-xl hover:bg-green-700 transition-all active:scale-95 uppercase text-xs">Confirm Access</button>
