        id: 'c1', 
        name: 'Pfizer Lanka', 
        contactEmail: 'admin@pfizer.lk', 
        companyCode: 'PFIZ-01',
        adminMobile: '0779', 
        adminPassword: 'pfiz', 
        isActive: true 
      }];
      localStorage.setItem(KEYS.COMPANIES, JSON.stringify(initial));
      return initial;
    }
    return JSON.parse(companies);
  },
  saveCompanies: (companies: PharmaCompany[]) => localStorage.setItem(KEYS.COMPANIES, JSON.stringify(companies)),

  getInvoices: (): Invoice[] => JSON.parse(localStorage.getItem(KEYS.INVOICES) || '[]'),
  saveInvoices: (invoices: Invoice[]) => localStorage.setItem(KEYS.INVOICES, JSON.stringify(invoices)),

  getLogs: (): EntryLog[] => JSON.parse(localStorage.getItem(KEYS.LOGS) || '[]'),
  saveLogs: (logs: EntryLog[]) => localStorage.setItem(KEYS.LOGS, JSON.stringify(logs)),

  setCurrentUser: (user: AuthUser) => localStorage.setItem(KEYS.SESSION, JSON.stringify(user)),
  getCurrentUser: (): AuthUser | null => {
    const session = localStorage.getItem(KEYS.SESSION);
    return session ? JSON.parse(session) : null;
