                       <button onClick={() => toggleMRStatus(mr.id)} className={`p-2 rounded-lg transition-all ${mr.status === 'active' ? 'text-red-400 hover:bg-red-50' : 'text-green-500 hover:bg-green-50'}`}>
                         <Power className="h-4 w-4" />
                       </button>
