                <div className="grid grid-cols-2 gap-3">
                  <input required type="text" value={securityData.fullName} onChange={e => setSecurityData({...securityData, fullName: e.target.value})} className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg text-xs" placeholder="Full Name" />
                  <input required type="text" value={securityData.mobileNumber} onChange={e => setSecurityData({...securityData, mobileNumber: e.target.value})} className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg text-xs" placeholder="Login ID / Mobile" />
                  <input required type="text" value={securityData.password} onChange={e => setSecurityData({...securityData, password: e.target.value})} className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg text-xs col-span-2" placeholder="Secure Password" />
                </div>
              </div>
              <button type="submit" className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-xl active:scale-95 transition-all">PROVISION FACILITY & ACCOUNTS</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default SuperAdminDashboard;

import React, { useState, useEffect, useContext } from 'react';
import { 
  Building2, Users, Settings, Plus, Power, Activity, Edit3, Trash2, X, 
  Briefcase, Clock, User, ShieldCheck, Lock, Key, Image as ImageIcon, 
  CheckCircle, TrendingUp, AlertTriangle, Info, Calendar, Mail, Phone 
} from 'lucide-react';
import { storageService } from '../services/storageService';
import { Hospital, PharmaCompany, MedicalRep, HospitalUser, PassApplication, IssuedPass } from '../types';
import { FeedbackContext } from '../App';

const SuperAdminDashboard: React.FC = () => {
  const { showFeedback } = useContext(FeedbackContext);

  // Data States
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [companies, setCompanies] = useState<PharmaCompany[]>([]);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);

  // UI States
  const [activeTab, setActiveTab] = useState<'hospitals' | 'companies' | 'monitoring'>('hospitals');

  // Hospital Modal States
  const [isHospitalModalOpen, setIsHospitalModalOpen] = useState(false);
  const [editingHospital, setEditingHospital] = useState<Partial<Hospital> | null>(null);
  const [adminData, setAdminData] = useState({ fullName: '', mobileNumber: '', password: '' });
  const [securityData, setSecurityData] = useState({ fullName: '', mobileNumber: '', password: '' });

  // Company Modal States
  const [isCompanyModalOpen, setIsCompanyModalOpen] = useState(false);
  const [editingCompany, setEditingCompany] = useState<Partial<PharmaCompany> | null>(null);
  const [selectedCompanyId, setSelectedCompanyId] = useState<string | null>(null);
  const [selectedMR, setSelectedMR] = useState<MedicalRep | null>(null);

  useEffect(() => {
    refreshData();
  }, []);

  const refreshData = () => {
    setHospitals(storageService.getHospitals());
    setCompanies(storageService.getCompanies());
    setMrs(storageService.getMRs());
    setApps(storageService.getApplications());
    setPasses(storageService.getPasses());
  };

  const handleSaveHospital = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingHospital?.name) return;

    const hospitalId = editingHospital.id || 'h' + Date.now();

    const hospitalData: Hospital = {
      id: hospitalId,
      name: editingHospital.name || '',
      isActive: editingHospital.isActive ?? true,
      supportedSessions: editingHospital.supportedSessions || ['MORNING', 'EVENING', 'FULL_DAY'],
      passLimits: editingHospital.passLimits || { 'MORNING': 10, 'EVENING': 10, 'FULL_DAY': 5 },
      sessionWindows: editingHospital.sessionWindows || { 
        'MORNING': { start: '08:00', end: '10:00' },
        'EVENING': { start: '16:00', end: '18:00' },
        'FULL_DAY': { start: '08:00', end: '18:00' }
      },
    };

    const currentHospitals = storageService.getHospitals();
    const updatedHospitals = editingHospital.id 
      ? currentHospitals.map(h => h.id === hospitalId ? hospitalData : h)
      : [...currentHospitals, hospitalData];

    storageService.saveHospitals(updatedHospitals);

    // Save Hospital User Accounts
    const u: HospitalUser[] = [
      { id: `u-a-${hospitalId}`, hospitalId, role: 'ADMIN', fullName: adminData.fullName, mobileNumber: adminData.mobileNumber, password: adminData.password },
      { id: `u-s-${hospitalId}`, hospitalId, role: 'SECURITY', fullName: securityData.fullName, mobileNumber: securityData.mobileNumber, password: securityData.password }
    ];

    const currentUsers = storageService.getHospitalUsers().filter(user => user.hospitalId !== hospitalId);
    storageService.saveHospitalUsers([...currentUsers, ...u]);

    refreshData();
    setIsHospitalModalOpen(false);
    setEditingHospital(null);
    setAdminData({ fullName: '', mobileNumber: '', password: '' });
    setSecurityData({ fullName: '', mobileNumber: '', password: '' });
    showFeedback("Hospital facility provisioned successfully.");
  };

  const handleSaveCompany = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingCompany?.name || !editingCompany?.companyCode) {
      showFeedback("Company name and code are required.", "error");
      return;
    }

    const companyId = editingCompany.id || 'c' + Date.now();
    const companyData: PharmaCompany = {
      id: companyId,
      name: editingCompany.name || '',
      companyCode: editingCompany.companyCode || '',
      adminMobile: editingCompany.adminMobile || '',
      adminPassword: editingCompany.adminPassword || '',
      contactEmail: editingCompany.contactEmail || '',
      isActive: editingCompany.isActive ?? true,
    };

    const currentCompanies = storageService.getCompanies();
    const updated = editingCompany.id 
      ? currentCompanies.map(c => c.id === companyId ? companyData : c)
      : [...currentCompanies, companyData];

    storageService.saveCompanies(updated);
    refreshData();
    setIsCompanyModalOpen(false);
    setEditingCompany(null);
    showFeedback(`Pharmaceutical company ${companyData.name} registered.`);
  };

  const toggleCompanyStatus = (id: string) => {
    const updated = companies.map(c => c.id === id ? { ...c, isActive: !c.isActive } : c);
    storageService.saveCompanies(updated);
    setCompanies(updated);
    const c = updated.find(x => x.id === id);
    showFeedback(`Company ${c?.name} is now ${c?.isActive ? 'active' : 'deactivated'}`);
  };

  return (
    <div className="space-y-6">
      {/* Tab Navigation */}
      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('hospitals')} className={`px-4 md:px-6 py-2 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'hospitals' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Building2 className="h-4 w-4" /> Hospitals</button>
        <button onClick={() => setActiveTab('companies')} className={`px-4 md:px-6 py-2 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'companies' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Briefcase className="h-4 w-4" /> Companies</button>
        <button onClick={() => setActiveTab('monitoring')} className={`px-4 md:px-6 py-2 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'monitoring' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Activity className="h-4 w-4" /> Monitoring</button>
      </div>

      {/* Hospitals Management */}
      {activeTab === 'hospitals' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
