                 </div>
                 <h4 className="text-2xl font-black text-slate-800">{selectedMR.fullName}</h4>
                 <p className="text-indigo-600 font-bold text-xs uppercase tracking-widest mb-1">{selectedMR.companyName}</p>
                 <div className="bg-green-50 px-3 py-1 rounded-full text-[10px] font-black text-green-700 uppercase">
                    SLCPI NUMBER: {selectedMR.slcpiId || 'PENDING'}
                 </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Contact Number</p>
                  <p className="font-bold text-slate-800">{selectedMR.mobileNumber}</p>
                </div>
                <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">National ID (NIC)</p>
                  <p className="font-bold text-slate-800">{selectedMR.identificationNumber}</p>
                </div>
                <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100 col-span-2">
                  <div className="flex justify-between items-center mb-1">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">SLCPI Expiry Date</p>
                    <Calendar className="h-3 w-3 text-slate-300" />
                  </div>
                  <p className="font-bold text-slate-800">{selectedMR.slcpiExpiry || 'NOT PROVIDED'}</p>
                </div>
              </div>

              <div className="space-y-3">
                 <h5 className="text-[10px] font-black uppercase tracking-widest text-slate-400">SLCPI Verification Document</h5>
                 {selectedMR.slcpiPhoto ? (
                   <div className="rounded-2xl overflow-hidden border border-slate-200 bg-white aspect-video relative shadow-inner">
                      <img src={selectedMR.slcpiPhoto} className="w-full h-full object-contain" alt="SLCPI Photo" />
                   </div>
                 ) : (
                   <div className="p-10 text-center bg-slate-50 rounded-2xl border-2 border-dashed border-slate-200">
                      <ImageIcon className="h-8 w-8 text-slate-200 mx-auto mb-2" />
                      <p className="text-xs font-bold text-slate-400 italic">No SLCPI document photo available.</p>
                   </div>
                 )}
              </div>

              <div className="flex gap-4 pt-4 border-t border-slate-100">
                {pendingApprovals.some(a => a.mrId === selectedMR.id) ? (
                  <>
                    <button onClick={() => { const approval = pendingApprovals.find(a => a.mrId === selectedMR.id); if (approval) updateApproval(approval.id, 'approved'); }} className="flex-1 bg-green-600 text-white font-black py-4 rounded-2xl shadow-xl hover:bg-green-700 transition-all active:scale-95 uppercase text-xs">Verify & Approve</button>
                    <button onClick={() => { const approval = pendingApprovals.find(a => a.mrId === selectedMR.id); if (approval) updateApproval(approval.id, 'rejected'); }} className="flex-1 bg-white border border-red-100 text-red-500 font-black py-4 rounded-2xl hover:bg-red-50 transition-all uppercase text-xs">Reject</button>
                  </>
                ) : (
                  <button onClick={() => setSelectedMR(null)} className="w-full bg-slate-800 text-white font-bold py-4 rounded-2xl hover:bg-slate-900 transition-all">Close Verification</button>
                )}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect, useContext } from 'react';
import { 
  Building2, Users, Settings, Plus, Power, Activity, Edit3, Trash2, X, 
  Briefcase, Clock, User, ShieldCheck, Lock, Key, Image as ImageIcon, 
  CheckCircle, TrendingUp, AlertTriangle, Info, Calendar, Mail, Phone 
} from 'lucide-react';
import { storageService } from '../services/storageService';
import { Hospital, PharmaCompany, MedicalRep, HospitalUser, PassApplication, IssuedPass } from '../types';
import { FeedbackContext } from '../App';

const SuperAdminDashboard: React.FC = () => {
  const { showFeedback } = useContext(FeedbackContext);

  // Data States
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [companies, setCompanies] = useState<PharmaCompany[]>([]);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);

  // UI States
  const [activeTab, setActiveTab] = useState<'hospitals' | 'companies' | 'monitoring'>('hospitals');

  // Hospital Modal States
  const [isHospitalModalOpen, setIsHospitalModalOpen] = useState(false);
  const [editingHospital, setEditingHospital] = useState<Partial<Hospital> | null>(null);
  const [adminData, setAdminData] = useState({ fullName: '', mobileNumber: '', password: '' });
  const [securityData, setSecurityData] = useState({ fullName: '', mobileNumber: '', password: '' });

  // Company Modal States
  const [isCompanyModalOpen, setIsCompanyModalOpen] = useState(false);
  const [editingCompany, setEditingCompany] = useState<Partial<PharmaCompany> | null>(null);
  const [selectedCompanyId, setSelectedCompanyId] = useState<string | null>(null);
  const [selectedMR, setSelectedMR] = useState<MedicalRep | null>(null);

  useEffect(() => {
    refreshData();
  }, []);

  const refreshData = () => {
    setHospitals(storageService.getHospitals());
    setCompanies(storageService.getCompanies());
    setMrs(storageService.getMRs());
    setApps(storageService.getApplications());
    setPasses(storageService.getPasses());
  };

  const handleSaveHospital = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingHospital?.name) return;

    const hospitalId = editingHospital.id || 'h' + Date.now();

    const hospitalData: Hospital = {
      id: hospitalId,
      name: editingHospital.name || '',
      isActive: editingHospital.isActive ?? true,
      supportedSessions: editingHospital.supportedSessions || ['MORNING', 'EVENING', 'FULL_DAY'],
      passLimits: editingHospital.passLimits || { 'MORNING': 10, 'EVENING': 10, 'FULL_DAY': 5 },
      sessionWindows: editingHospital.sessionWindows || { 
        'MORNING': { start: '08:00', end: '10:00' },
        'EVENING': { start: '16:00', end: '18:00' },
        'FULL_DAY': { start: '08:00', end: '18:00' }
      },
    };

    const currentHospitals = storageService.getHospitals();
    const updatedHospitals = editingHospital.id 
      ? currentHospitals.map(h => h.id === hospitalId ? hospitalData : h)
      : [...currentHospitals, hospitalData];

    storageService.saveHospitals(updatedHospitals);

    // Save Hospital User Accounts
    const u: HospitalUser[] = [
      { id: `u-a-${hospitalId}`, hospitalId, role: 'ADMIN', fullName: adminData.fullName, mobileNumber: adminData.mobileNumber, password: adminData.password },
      { id: `u-s-${hospitalId}`, hospitalId, role: 'SECURITY', fullName: securityData.fullName, mobileNumber: securityData.mobileNumber, password: securityData.password }
    ];

    const currentUsers = storageService.getHospitalUsers().filter(user => user.hospitalId !== hospitalId);
    storageService.saveHospitalUsers([...currentUsers, ...u]);

    refreshData();
    setIsHospitalModalOpen(false);
    setEditingHospital(null);
    setAdminData({ fullName: '', mobileNumber: '', password: '' });
    setSecurityData({ fullName: '', mobileNumber: '', password: '' });
    showFeedback("Hospital facility provisioned successfully.");
  };

  const handleSaveCompany = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingCompany?.name || !editingCompany?.companyCode) {
      showFeedback("Company name and code are required.", "error");
      return;
    }

    const companyId = editingCompany.id || 'c' + Date.now();
    const companyData: PharmaCompany = {
      id: companyId,
      name: editingCompany.name || '',
      companyCode: editingCompany.companyCode || '',
      adminMobile: editingCompany.adminMobile || '',
      adminPassword: editingCompany.adminPassword || '',
      contactEmail: editingCompany.contactEmail || '',
      isActive: editingCompany.isActive ?? true,
    };

    const currentCompanies = storageService.getCompanies();
    const updated = editingCompany.id 
      ? currentCompanies.map(c => c.id === companyId ? companyData : c)
      : [...currentCompanies, companyData];

    storageService.saveCompanies(updated);
    refreshData();
    setIsCompanyModalOpen(false);
    setEditingCompany(null);
    showFeedback(`Pharmaceutical company ${companyData.name} registered.`);
  };

  const toggleCompanyStatus = (id: string) => {
    const updated = companies.map(c => c.id === id ? { ...c, isActive: !c.isActive } : c);
    storageService.saveCompanies(updated);
    setCompanies(updated);
    const c = updated.find(x => x.id === id);
    showFeedback(`Company ${c?.name} is now ${c?.isActive ? 'active' : 'deactivated'}`);
  };

  return (
    <div className="space-y-6">
      {/* Tab Navigation */}
      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('hospitals')} className={`px-4 md:px-6 py-2 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'hospitals' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Building2 className="h-4 w-4" /> Hospitals</button>
        <button onClick={() => setActiveTab('companies')} className={`px-4 md:px-6 py-2 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'companies' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Briefcase className="h-4 w-4" /> Companies</button>
        <button onClick={() => setActiveTab('monitoring')} className={`px-4 md:px-6 py-2 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'monitoring' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Activity className="h-4 w-4" /> Monitoring</button>
      </div>

      {/* Hospitals Management */}
      {activeTab === 'hospitals' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
          <div className="flex justify-between items-center mb-8">
            <h3 className="text-xl font-bold">Facility Management</h3>
            <button 
              onClick={() => { setEditingHospital({ supportedSessions: ['MORNING', 'EVENING', 'FULL_DAY'] }); setIsHospitalModalOpen(true); }}
              className="bg-indigo-600 text-white px-5 py-2.5 rounded-xl font-bold flex items-center gap-2 hover:bg-indigo-700 shadow-lg active:scale-95 transition-all"
            >
              <Plus className="h-4 w-4" /> PROVISION HOSPITAL
            </button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {hospitals.map(h => (
              <div key={h.id} className="p-6 bg-slate-50 rounded-3xl border border-slate-100 relative group hover:shadow-md transition-all">
                <div className={`absolute top-4 right-4 w-2 h-2 rounded-full ${h.isActive ? 'bg-green-500' : 'bg-red-500'}`}></div>
                <h4 className="font-black text-slate-800 text-lg mb-4">{h.name}</h4>
                <div className="space-y-2">
                   <div className="flex items-center gap-2 text-xs font-bold text-slate-500">
                     <ShieldCheck className="h-4 w-4" /> 
                     Admin: {storageService.getHospitalUsers().find(u => u.hospitalId === h.id && u.role === 'ADMIN')?.fullName || 'Unassigned'}
                   </div>
                   <div className="flex items-center gap-2 text-[10px] font-black uppercase text-indigo-400 tracking-widest">
                     {h.supportedSessions.join(' • ')}
                   </div>
                </div>
              </div>
            ))}
          </div>
        </section>
      )}

      {/* Companies Management */}
      {activeTab === 'companies' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
          <div className="flex justify-between items-center mb-8">
            <h3 className="text-xl font-bold">Pharma Company Management</h3>
            <button 
              onClick={() => { setEditingCompany({ isActive: true }); setIsCompanyModalOpen(true); }}
              className="bg-indigo-600 text-white px-5 py-2.5 rounded-xl font-bold flex items-center gap-2 hover:bg-indigo-700 shadow-lg active:scale-95 transition-all"
            >
              <Plus className="h-4 w-4" /> NEW PARTNER
            </button>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* List */}
            <div className="lg:col-span-1 space-y-3">
              {companies.map(c => {
                const companyMRCount = mrs.filter(m => m.companyName === c.name).length;
                return (
                  <button 
                    key={c.id}
                    onClick={() => setSelectedCompanyId(c.id)}
                    className={`w-full text-left p-4 rounded-2xl border transition-all ${selectedCompanyId === c.id ? 'border-indigo-600 bg-indigo-50 shadow-sm' : 'border-slate-100 bg-slate-50 hover:bg-slate-100'}`}
                  >
                    <div className="flex justify-between items-center">
                      <h4 className="font-bold text-slate-800">{c.name}</h4>
                      <div className={`w-2 h-2 rounded-full ${c.isActive ? 'bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.5)]' : 'bg-slate-300'}`}></div>
                    </div>
                    <p className="text-[10px] text-slate-400 font-bold uppercase mt-1 tracking-tighter">{c.companyCode} • {companyMRCount} MRs Registered</p>
                  </button>
                );
              })}
            </div>

            {/* Details */}
            <div className="lg:col-span-2">
              {selectedCompanyId ? (
                <div className="bg-slate-50 rounded-2xl border border-slate-100 overflow-hidden animate-in fade-in duration-300">
                  <div className="bg-white p-6 border-b border-slate-100 flex justify-between items-center">
                    <div>
                      <h4 className="font-black text-xl text-slate-800">{companies.find(c => c.id === selectedCompanyId)?.name}</h4>
                      <p className="text-xs font-bold text-indigo-600">Admin Login ID: {companies.find(c => c.id === selectedCompanyId)?.adminMobile}</p>
                    </div>
                    <div className="flex gap-2">
                       <button onClick={() => toggleCompanyStatus(selectedCompanyId)} className={`text-[10px] font-black uppercase px-3 py-1.5 rounded-lg border transition-colors ${companies.find(c => c.id === selectedCompanyId)?.isActive ? 'border-red-200 text-red-600 bg-red-50' : 'border-green-200 text-green-600 bg-green-50'}`}>
                         {companies.find(c => c.id === selectedCompanyId)?.isActive ? 'Deactivate' : 'Activate'}
                       </button>
                       <button onClick={() => { setEditingCompany(companies.find(c => c.id === selectedCompanyId)); setIsCompanyModalOpen(true); }} className="p-1.5 bg-slate-100 hover:bg-slate-200 rounded-lg"><Edit3 className="h-4 w-4 text-slate-600" /></button>
                    </div>
                  </div>

                  <div className="p-6">
                    <h5 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Representative Registry</h5>
                    <div className="space-y-2">
                       {mrs.filter(m => m.companyName === companies.find(c => c.id === selectedCompanyId)?.name).map(mr => (
                         <div key={mr.id} className="flex items-center justify-between p-3 bg-white rounded-xl border border-slate-100 hover:border-indigo-200 transition-all cursor-pointer" onClick={() => setSelectedMR(mr)}>
                            <div className="flex items-center gap-3">
                               <div className="w-8 h-8 bg-slate-100 rounded-lg flex items-center justify-center"><User className="h-4 w-4 text-slate-400" /></div>
                               <div><p className="text-xs font-black">{mr.fullName}</p><p className="text-[9px] text-slate-400">{mr.mrId}</p></div>
                            </div>
                            <span className={`text-[9px] font-black uppercase tracking-tighter px-2 py-0.5 rounded ${mr.status === 'active' ? 'bg-green-50 text-green-600' : 'bg-red-50 text-red-600'}`}>{mr.status}</span>
                         </div>
                       ))}
                       {mrs.filter(m => m.companyName === companies.find(c => c.id === selectedCompanyId)?.name).length === 0 && (
                         <p className="text-center py-12 text-slate-400 italic text-xs">No MRs registered for this company yet.</p>
                       )}
                    </div>
                  </div>
                </div>
              ) : (
                <div className="h-full min-h-[400px] flex flex-col items-center justify-center p-12 bg-slate-50 rounded-3xl border border-dashed border-slate-200 text-slate-400">
                  <Briefcase className="h-16 w-16 mb-4 opacity-10" />
                  <p className="text-sm font-medium">Select a company from the list to view its registered representatives and management settings.</p>
                </div>
              )}
            </div>
          </div>
        </section>
      )}

      {/* Monitoring Dashboard */}
      {activeTab === 'monitoring' && (
        <section className="space-y-6">
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
             <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm"><p className="text-[10px] font-black text-slate-400 uppercase mb-1">System MR Pool</p><h3 className="text-3xl font-black text-slate-800">{mrs.length}</h3></div>
             <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm"><p className="text-[10px] font-black text-slate-400 uppercase mb-1">Active Nodes</p><h3 className="text-3xl font-black text-slate-800">{hospitals.filter(h => h.isActive).length}</h3></div>
             <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm"><p className="text-[10px] font-black text-slate-400 uppercase mb-1">Requests Today</p><h3 className="text-3xl font-black text-slate-800">{apps.length}</h3></div>
             <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm"><p className="text-[10px] font-black text-slate-400 uppercase mb-1">Entries Logged</p><h3 className="text-3xl font-black text-slate-800">{passes.filter(p => p.entryStatus === 'entered').length}</h3></div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <div className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
               <h4 className="font-black text-slate-800 mb-6 flex items-center gap-2"><TrendingUp className="h-5 w-5 text-indigo-600" /> Recent System Traffic</h4>
               <div className="space-y-4">
                 {apps.slice(-6).reverse().map(a => {
                   const mr = mrs.find(m => m.id === a.mrId);
                   const hosp = hospitals.find(h => h.id === a.hospitalId);
                   return (
                     <div key={a.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100">
                       <div className="flex items-center gap-3">
                         <div className="bg-white p-2 rounded-xl"><User className="h-4 w-4 text-slate-400" /></div>
                         <div>
                            <p className="text-xs font-black">{mr?.fullName || 'Unknown'}</p>
                            <p className="text-[10px] text-slate-400 truncate max-w-[150px]">{hosp?.name}</p>
                         </div>
                       </div>
                       <span className={`text-[10px] font-black px-2 py-1 rounded-lg ${a.status === 'selected' ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-700'}`}>{a.status.toUpperCase()}</span>
                     </div>
                   );
                 })}
               </div>
            </div>

            <div className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
               <h4 className="font-black text-slate-800 mb-6 flex items-center gap-2"><AlertTriangle className="h-5 w-5 text-amber-500" /> Operational Insights</h4>
               <div className="space-y-3">
                 {mrs.filter(m => !m.slcpiPhoto).length > 0 && (
                   <div className="p-4 bg-amber-50 rounded-2xl border border-amber-100 flex items-center gap-3">
                     <AlertTriangle className="h-4 w-4 text-amber-500" />
                     <p className="text-xs font-bold text-amber-800">{mrs.filter(m => !m.slcpiPhoto).length} users missing compliance documents.</p>
                   </div>
                 )}
                 <div className="p-4 bg-green-50 rounded-2xl border border-green-100 flex items-center gap-3">
                   <CheckCircle className="h-4 w-4 text-green-600" />
                   <p className="text-xs font-bold text-green-800">API Gateway and Storage are in healthy state.</p>
                 </div>
               </div>
            </div>
          </div>
        </section>
      )}

      {/* Hospital Provisioning Modal */}
      {isHospitalModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in zoom-in duration-200">
          <div className="bg-white w-full max-w-2xl rounded-3xl shadow-2xl overflow-hidden animate-in slide-in-from-bottom-4 duration-300">
            <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-bold">Facility Infrastructure Setup</h3>
              <button onClick={() => setIsHospitalModalOpen(false)}><X className="h-5 w-5 text-slate-400" /></button>
            </div>
            <form onSubmit={handleSaveHospital} className="p-8 space-y-6 max-h-[80vh] overflow-y-auto">
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Official Hospital Name</label>
                <input required type="text" value={editingHospital?.name || ''} onChange={e => setEditingHospital({...editingHospital, name: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold focus:ring-2 focus:ring-indigo-500 outline-none" />
              </div>

              <div className="p-5 bg-indigo-50/50 rounded-2xl border border-indigo-100 space-y-4">
                <p className="text-xs font-black text-indigo-900 uppercase">Management Account (Admin)</p>
                <div className="grid grid-cols-2 gap-3">
                  <input required type="text" value={adminData.fullName} onChange={e => setAdminData({...adminData, fullName: e.target.value})} className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg text-xs" placeholder="Full Name" />
                  <input required type="text" value={adminData.mobileNumber} onChange={e => setAdminData({...adminData, mobileNumber: e.target.value})} className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg text-xs" placeholder="Login ID" />
                  <input required type="text" value={adminData.password} onChange={e => setAdminData({...adminData, password: e.target.value})} className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg text-xs col-span-2" placeholder="Password" />
                </div>
              </div>

              <div className="p-5 bg-slate-50 rounded-2xl border border-slate-100 space-y-4">
                <p className="text-xs font-black text-slate-800 uppercase">Security Checkpoint Account</p>
                <div className="grid grid-cols-2 gap-3">
                  <input required type="text" value={securityData.fullName} onChange={e => setSecurityData({...securityData, fullName: e.target.value})} className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg text-xs" placeholder="Full Name" />
                  <input required type="text" value={securityData.mobileNumber} onChange={e => setSecurityData({...securityData, mobileNumber: e.target.value})} className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg text-xs" placeholder="Login ID" />
                  <input required type="text" value={securityData.password} onChange={e => setSecurityData({...securityData, password: e.target.value})} className="w-full px-3 py-2 bg-white border border-slate-200 rounded-lg text-xs col-span-2" placeholder="Password" />
                </div>
              </div>
              <button type="submit" className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-xl active:scale-95 transition-all">PROVISION SYSTEM ENDPOINTS</button>
            </form>
          </div>
        </div>
      )}

      {/* Company Registration Modal */}
      {isCompanyModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in zoom-in duration-200">
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden animate-in slide-in-from-bottom-4 duration-300">
            <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-bold">{editingCompany?.id ? 'Edit Partner' : 'Register New Partner'}</h3>
              <button onClick={() => setIsCompanyModalOpen(false)}><X className="h-5 w-5 text-slate-400" /></button>
            </div>
            <form onSubmit={handleSaveCompany} className="p-8 space-y-6">
              <div className="space-y-4">
                 <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Company Full Name</label>
                    <input required type="text" value={editingCompany?.name || ''} onChange={e => setEditingCompany({...editingCompany, name: e.target.value})} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold" />
                 </div>
                 <div>
                    <label className="text-[10px] font-black text-indigo-400 uppercase tracking-widest block mb-1">Partner Code</label>
                    <input required type="text" value={editingCompany?.companyCode || ''} onChange={e => setEditingCompany({...editingCompany, companyCode: e.target.value})} className="w-full px-4 py-3 bg-indigo-50 border border-indigo-200 rounded-xl font-mono font-black text-indigo-700 uppercase" placeholder="e.g. AZ-01" />
                 </div>
                 <div className="pt-4 border-t border-slate-100">
                    <p className="text-[10px] font-black text-indigo-400 uppercase mb-3">Provision Partner Admin Account</p>
                    <div className="space-y-2">
                       <input required type="text" value={editingCompany?.adminMobile || ''} onChange={e => setEditingCompany({...editingCompany, adminMobile: e.target.value})} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-xs font-bold" placeholder="Admin Mobile / Login" />
                       <input required type="text" value={editingCompany?.adminPassword || ''} onChange={e => setEditingCompany({...editingCompany, adminPassword: e.target.value})} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-xs font-bold" placeholder="Admin Password" />
                       <input required type="email" value={editingCompany?.contactEmail || ''} onChange={e => setEditingCompany({...editingCompany, contactEmail: e.target.value})} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-xs font-bold" placeholder="Official Email Address" />
                    </div>
                 </div>
              </div>
              <button type="submit" className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-xl active:scale-95 transition-all">SAVE PARTNER ENTITY</button>
            </form>
          </div>
        </div>
      )}

      {/* MR Profile Modal (Detailed View for Super Admin) */}
      {selectedMR && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-lg rounded-3xl shadow-2xl overflow-hidden animate-in slide-in-from-bottom-4 duration-300">
            <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-bold">System MR Profile</h3>
              <button onClick={() => setSelectedMR(null)}><X className="h-5 w-5 text-slate-400" /></button>
            </div>
            <div className="p-8 space-y-6 max-h-[85vh] overflow-y-auto text-center">
               <div className="w-20 h-20 bg-indigo-100 rounded-full flex items-center justify-center mx-auto mb-4 border-4 border-white shadow-sm">
                 <User className="h-10 w-10 text-indigo-600" />
               </div>
               <div>
                  <h4 className="text-2xl font-black text-slate-800">{selectedMR.fullName}</h4>
                  <p className="text-indigo-600 font-bold text-sm tracking-wide uppercase">{selectedMR.companyName}</p>
               </div>

               <div className="grid grid-cols-2 gap-4 text-left">
                  <div className="p-3 bg-slate-50 rounded-xl"><p className="text-[10px] font-black text-slate-400 uppercase">Login ID</p><p className="font-bold text-slate-700">{selectedMR.loginId}</p></div>
                  <div className="p-3 bg-slate-50 rounded-xl"><p className="text-[10px] font-black text-slate-400 uppercase">MR ID</p><p className="font-bold text-slate-700">{selectedMR.mrId}</p></div>
                  <div className="p-3 bg-slate-50 rounded-xl"><p className="text-[10px] font-black text-slate-400 uppercase">Contact</p><p className="font-bold text-slate-700">{selectedMR.mobileNumber}</p></div>
                  <div className="p-3 bg-slate-50 rounded-xl"><p className="text-[10px] font-black text-slate-400 uppercase">Expiry</p><p className="font-bold text-slate-700">{selectedMR.slcpiExpiry || 'N/A'}</p></div>
               </div>

               {selectedMR.slcpiPhoto && (
                 <div className="rounded-2xl overflow-hidden border border-slate-200 mt-4"><img src={selectedMR.slcpiPhoto} className="w-full object-contain max-h-48" alt="ID Document" /></div>
               )}

               <button onClick={() => setSelectedMR(null)} className="w-full bg-slate-800 text-white font-bold py-4 rounded-2xl shadow-xl hover:bg-slate-900 transition-all">CLOSE VIEW</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default SuperAdminDashboard;

import React, { useState, useEffect, useContext } from 'react';
import { Play, Sparkles, CheckCircle, Clock, UserPlus, Users, Settings, Save, X, Plus, Sun, Moon, Maximize, User, Info, Building, MapPin, ShieldCheck, Mail, Phone, CreditCard, ChevronRight, Briefcase, FileText, Image as ImageIcon, CheckCircle2, AlertCircle, Calendar, Eye } from 'lucide-react';
import { storageService } from '../services/storageService';
import { MedicalRep, Hospital, PassApplication, IssuedPass, MRHospitalApproval, SessionType } from '../types';
import { PRIORITY_WEIGHTS, TIME_SLOTS } from '../constants';
import { getAdminBriefing } from '../services/geminiService';
import { FeedbackContext } from '../App';

interface AdminDashboardProps {
  user: {
    id: string;
    role: string;
    fullName: string;
    hospitalId: string;
  };
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [activeTab, setActiveTab] = useState<'lottery' | 'approvals' | 'companies' | 'config'>('lottery');
  const [brief, setBrief] = useState('');
  const [selectedMR, setSelectedMR] = useState<MedicalRep | null>(null);
  const [selectedCompany, setSelectedCompany] = useState<string | null>(null);

  const [editingHospital, setEditingHospital] = useState<Hospital | null>(null);

  useEffect(() => { refreshData(); }, []);

  const refreshData = async () => {
    const allHospitals = storageService.getHospitals();
    const currentHosp = allHospitals.find(h => h.id === user.hospitalId) || (allHospitals.length > 0 ? allHospitals[0] : null);

    setMrs(storageService.getMRs()); 
    setHospitals(allHospitals);
    setApps(storageService.getApplications()); 
    setPasses(storageService.getPasses());
    setApprovals(storageService.getApprovals());
    setEditingHospital(currentHosp);

    try {
      const summary = await getAdminBriefing(storageService.getApplications(), storageService.getPasses());
      setBrief(summary);
    } catch (e) {
      console.error("Briefing failed", e);
    }
  };

  const currentHospital = hospitals.find(h => h.id === user.hospitalId) || (hospitals.length > 0 ? hospitals[0] : null);

  const runLottery = (session: SessionType) => {
    if (!currentHospital) {
      showFeedback("Hospital data missing. Please refresh.", "error");
      return;
    }

    const today = new Date().toISOString().split('T')[0];
    const hospitalId = currentHospital.id;
    const sessionApps = apps.filter(a => a.hospitalId === hospitalId && a.applicationDate === today && a.session === session && a.status === 'applied');

    if (sessionApps.length === 0) { 
      showFeedback(`No ${session} applications for today.`, 'error'); 
      return; 
    }

    const scored = sessionApps.map(a => ({ ...a, score: calculatePriority(a.mrId) })).sort((a,b) => b.score - a.score);
    const limit = currentHospital.passLimits?.[session] || 0;
    const selected = scored.slice(0, limit);
    const waitlisted = scored.slice(limit);

    const newPasses: IssuedPass[] = selected.map((s, i) => ({
      id: `PASS-${Math.random().toString(36).substr(2, 6).toUpperCase()}`,
      mrId: s.mrId, hospitalId: s.hospitalId, session, passDate: today,
      timeSlot: TIME_SLOTS[i % TIME_SLOTS.length], qrCode: `QR-${s.id}`, entryStatus: 'not_entered'
    }));

    const updatedApps = apps.map(original => {
      if (selected.find(x => x.id === original.id)) return { ...original, status: 'selected' as const };
      if (waitlisted.find(x => x.id === original.id)) return { ...original, status: 'waitlisted' as const };
      return original;
    });

    storageService.saveApplications(updatedApps);
    storageService.savePasses([...passes, ...newPasses]);
    refreshData();
    showFeedback(`Lottery complete for ${session}! Issued ${selected.length} passes.`);
  };

  const calculatePriority = (mrId: string) => {
    let s = 0; const now = new Date();
    const entered = passes.filter(p => p.mrId === mrId && p.entryStatus === 'entered');
    if (entered.length > 0) {
      const last = new Date(entered[entered.length - 1].passDate);
      const diff = Math.floor((now.getTime() - last.getTime()) / (1000 * 3600 * 24));
      if (diff >= 14) s += PRIORITY_WEIGHTS.NO_PASS_14_DAYS;
      else if (diff >= 7) s += PRIORITY_WEIGHTS.NO_PASS_7_DAYS;
    } else s += PRIORITY_WEIGHTS.NO_PASS_14_DAYS;
    return s;
  };

  const updateApproval = (id: string, status: 'approved' | 'rejected') => {
    const updated = approvals.map(a => a.id === id ? { ...a, status, updatedAt: new Date().toISOString() } : a);
    storageService.saveApprovals(updated); 
    refreshData();
    if (selectedMR) setSelectedMR(null);
    showFeedback(`Representative access ${status}.`);
  };

  const handleSaveConfig = () => {
    if (!editingHospital) return;
    const allHospitals = storageService.getHospitals();
    const updated = allHospitals.map(h => h.id === editingHospital.id ? editingHospital : h);
    storageService.saveHospitals(updated);
    setHospitals(updated);
    showFeedback("Hospital session configuration updated successfully.");
  };

  const viewMRProfile = (mrId: string) => {
    const mr = mrs.find(m => m.id === mrId);
    if (mr) setSelectedMR(mr);
  };

  if (!currentHospital) {
    return (
      <div className="flex items-center justify-center h-64 bg-white rounded-3xl border border-slate-100 animate-pulse">
        <p className="text-slate-400 font-bold">Synchronizing Facility Data...</p>
      </div>
    );
  }

  const pendingApprovals = approvals.filter(a => a.hospitalId === user.hospitalId && a.status === 'pending');
  const approvedMRs = mrs.filter(mr => 
    approvals.some(apprv => apprv.hospitalId === user.hospitalId && apprv.mrId === mr.id && apprv.status === 'approved')
  );
  const approvedCompanies = Array.from(new Set(approvedMRs.map(mr => mr.companyName)));

  return (
    <div className="space-y-6">
      <div className="bg-indigo-600 rounded-3xl p-6 text-white shadow-lg flex items-center gap-4 border border-indigo-400/30">
        <Sparkles className="h-6 w-6 text-indigo-200 shrink-0" />
        <p className="text-sm font-medium leading-relaxed">{brief || "Scanning daily activity and calculating rankings..."}</p>
      </div>

      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('lottery')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all whitespace-nowrap ${activeTab === 'lottery' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Play className="h-4 w-4" /> Lottery</button>
        <button onClick={() => setActiveTab('approvals')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all whitespace-nowrap relative ${activeTab === 'approvals' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}>
          <UserPlus className="h-4 w-4" /> Requests
          {pendingApprovals.length > 0 && <span className="absolute -top-1 -right-1 flex h-4 w-4 items-center justify-center rounded-full bg-red-500 text-[8px] text-white ring-2 ring-white">{pendingApprovals.length}</span>}
        </button>
        <button onClick={() => setActiveTab('companies')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all whitespace-nowrap ${activeTab === 'companies' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Briefcase className="h-4 w-4" /> Companies</button>
        <button onClick={() => setActiveTab('config')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all whitespace-nowrap ${activeTab === 'config' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Settings className="h-4 w-4" /> Config</button>
      </div>

      {activeTab === 'lottery' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
          <h3 className="text-lg font-bold mb-6 flex items-center gap-2 text-slate-800">
             <Clock className="h-5 w-5 text-indigo-500" />
             Daily Pass Lottery Selection
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {['MORNING', 'EVENING', 'FULL_DAY'].map((sess) => {
               if (!currentHospital.supportedSessions.includes(sess as SessionType)) return null;
               const today = new Date().toISOString().split('T')[0];
               const count = apps.filter(a => a.hospitalId === user.hospitalId && a.applicationDate === today && a.session === sess && a.status === 'applied').length;
               const selectedCount = apps.filter(a => a.hospitalId === user.hospitalId && a.applicationDate === today && a.session === sess && a.status === 'selected').length;

               return (
                 <div key={sess} className="p-6 bg-slate-50 border border-slate-100 rounded-3xl">
                   <div className="flex justify-between items-start mb-6">
                     <div className="flex items-center gap-3">
                       <div className="bg-white p-2 rounded-xl shadow-sm">
                         {sess === 'MORNING' ? <Sun className="h-6 w-6 text-amber-500" /> : sess === 'EVENING' ? <Moon className="h-6 w-6 text-indigo-400" /> : <Maximize className="h-6 w-6 text-indigo-600" />}
                       </div>
                       <div>
                         <h4 className="font-black text-slate-800 tracking-tight">{sess.replace('_', ' ')}</h4>
                         <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Limit: {currentHospital.passLimits?.[sess] || 0}</p>
                       </div>
                     </div>
                     <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest ${selectedCount > 0 ? 'bg-green-100 text-green-700' : 'bg-indigo-100 text-indigo-700'}`}>
                        {selectedCount > 0 ? 'DONE' : 'OPEN'}
                     </span>
                   </div>
                   <div className="flex items-center justify-between p-4 bg-white rounded-2xl mb-6">
                      <div>
                        <p className="text-[10px] font-black text-slate-400 uppercase">Apps Received</p>
                        <p className="text-2xl font-black text-slate-800">{count}</p>
                      </div>
                      <Users className="h-8 w-8 text-slate-200" />
                   </div>
                   <button 
                     disabled={count === 0 || selectedCount > 0}
                     onClick={() => runLottery(sess as SessionType)}
                     className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-lg hover:bg-indigo-700 active:scale-95 disabled:grayscale disabled:opacity-50 transition-all flex items-center justify-center gap-2"
                   >
                     {selectedCount > 0 ? <CheckCircle2 className="h-5 w-5" /> : <Play className="h-5 w-5" />}
                     {selectedCount > 0 ? 'RUN FINISHED' : 'EXECUTE LOTTERY'}
                   </button>
                 </div>
               );
            })}
          </div>
        </section>
      )}

      {activeTab === 'approvals' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
          <h3 className="text-lg font-bold mb-6">Verification Requests</h3>
          <div className="space-y-4">
             {pendingApprovals.map(approval => {
               const mr = mrs.find(m => m.id === approval.mrId);
               if (!mr) return null;
               return (
                 <div key={approval.id} className="p-5 bg-slate-50 border border-slate-100 rounded-2xl flex items-center justify-between hover:bg-indigo-50/30 transition-all group">
                   <div className="flex items-center gap-4">
                      <div className="bg-white p-2.5 rounded-xl shadow-sm border border-slate-100"><User className="h-6 w-6 text-slate-400" /></div>
                      <div>
                        <p className="font-bold text-slate-800 text-lg leading-tight">{mr.fullName}</p>
                        <p className="text-xs text-indigo-600 font-bold uppercase tracking-widest">{mr.companyName}</p>
                      </div>
                   </div>
                   <div className="flex items-center gap-3">
                      <button onClick={() => viewMRProfile(mr.id)} className="px-4 py-2 bg-white border border-slate-200 text-slate-500 rounded-xl text-xs font-black hover:bg-slate-50 transition-all shadow-sm">VIEW & VERIFY</button>
                      <button onClick={() => updateApproval(approval.id, 'approved')} className="bg-green-600 text-white px-5 py-2 rounded-xl text-xs font-black shadow-md hover:bg-green-700 transition-all active:scale-95">APPROVE</button>
                      <button onClick={() => updateApproval(approval.id, 'rejected')} className="bg-white border border-red-100 text-red-500 px-5 py-2 rounded-xl text-xs font-black hover:bg-red-50 transition-all">REJECT</button>
                   </div>
                 </div>
               );
             })}
             {pendingApprovals.length === 0 && (
               <div className="text-center py-16 border-2 border-dashed border-slate-100 rounded-3xl">
                 <ShieldCheck className="h-10 w-10 text-slate-200 mx-auto mb-3" />
                 <p className="text-slate-400 font-medium">No pending verification requests.</p>
               </div>
             )}
          </div>
        </section>
      )}

      {activeTab === 'companies' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
          <h3 className="text-lg font-bold mb-6">Pharmaceutical Partners</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {approvedCompanies.map(companyName => (
               <button 
                 key={companyName}
                 onClick={() => setSelectedCompany(companyName === selectedCompany ? null : companyName)}
                 className={`p-6 text-left rounded-3xl border transition-all ${selectedCompany === companyName ? 'bg-indigo-50 border-indigo-200 shadow-md ring-2 ring-indigo-100' : 'bg-slate-50 border-slate-100 hover:border-indigo-100'}`}
               >
                 <Briefcase className="h-6 w-6 text-indigo-500 mb-3" />
                 <h4 className="font-bold text-slate-800">{companyName}</h4>
                 <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">
                   {mrs.filter(m => m.companyName === companyName && approvals.some(a => a.mrId === m.id && a.hospitalId === user.hospitalId && a.status === 'approved')).length} Verified Members
                 </p>
               </button>
            ))}
          </div>

          {selectedCompany && (
            <div className="mt-8 animate-in slide-in-from-top duration-300">
               <div className="p-4 bg-indigo-600 rounded-t-3xl text-white flex justify-between items-center">
                  <h4 className="font-black text-xs uppercase tracking-widest flex items-center gap-2"><Users className="h-4 w-4" /> Active Members: {selectedCompany}</h4>
                  <button onClick={() => setSelectedCompany(null)} className="p-1 hover:bg-white/20 rounded-lg transition-all"><X className="h-4 w-4" /></button>
               </div>
               <div className="bg-slate-50 border border-t-0 border-slate-100 rounded-b-3xl overflow-hidden shadow-sm">
                  <table className="w-full text-left text-xs">
                    <thead>
                      <tr className="bg-white border-b border-slate-100 text-slate-400 font-black uppercase tracking-widest text-[9px]">
                        <th className="px-6 py-4">Full Name</th>
                        <th className="px-6 py-4">Mobile</th>
                        <th className="px-6 py-4">Status</th>
                        <th className="px-6 py-4 text-right">Actions</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                       {mrs.filter(m => m.companyName === selectedCompany && approvals.some(a => a.mrId === m.id && a.hospitalId === user.hospitalId && a.status === 'approved')).map(mr => (
                         <tr key={mr.id} className="hover:bg-indigo-50/10 transition-colors">
                            <td className="px-6 py-4 font-bold text-slate-700">{mr.fullName}</td>
                            <td className="px-6 py-4 text-slate-500 font-mono tracking-tighter">{mr.mobileNumber}</td>
                            <td className="px-6 py-4">
                              <span className="bg-green-100 text-green-700 px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-widest">VERIFIED</span>
                            </td>
                            <td className="px-6 py-4 text-right">
                              <button onClick={() => viewMRProfile(mr.id)} className="text-indigo-600 font-black hover:bg-indigo-50 px-3 py-1.5 rounded-lg transition-all flex items-center gap-1.5 ml-auto">
                                <Eye className="h-3 w-3" /> PROFILE
                              </button>
                            </td>
                         </tr>
                       ))}
                       {mrs.filter(m => m.companyName === selectedCompany && approvals.some(a => a.mrId === m.id && a.hospitalId === user.hospitalId && a.status === 'approved')).length === 0 && (
                         <tr>
                            <td colSpan={4} className="px-6 py-12 text-center text-slate-400 italic">No verified members found for this company at your facility.</td>
                         </tr>
                       )}
                    </tbody>
                  </table>
               </div>
            </div>
          )}
        </section>
      )}

      {activeTab === 'config' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm max-w-2xl mx-auto">
          <h3 className="text-xl font-bold mb-8">Facility Session Config</h3>
          {editingHospital && (
            <div className="space-y-8">
               <div className="p-6 bg-slate-50 rounded-3xl border border-slate-100 space-y-6">
                 {['MORNING', 'EVENING', 'FULL_DAY'].map(sess => (
                   <div key={sess} className="space-y-3">
                      <div className="flex items-center gap-2 mb-2">
                         {sess === 'MORNING' ? <Sun className="h-4 w-4 text-amber-500" /> : sess === 'EVENING' ? <Moon className="h-4 w-4 text-indigo-500" /> : <Maximize className="h-4 w-4 text-indigo-600" />}
                         <span className="text-sm font-black text-slate-800 uppercase tracking-widest">{sess.replace('_', ' ')} SETTINGS</span>
                         <label className="ml-auto inline-flex items-center cursor-pointer">
                            <input type="checkbox" checked={editingHospital.supportedSessions.includes(sess as SessionType)} onChange={(e) => {
                                const supported = e.target.checked ? [...editingHospital.supportedSessions, sess as SessionType] : editingHospital.supportedSessions.filter(s => s !== sess);
                                setEditingHospital({...editingHospital, supportedSessions: supported});
                            }} className="sr-only peer" />
                            <div className="w-9 h-5 bg-gray-200 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked:bg-indigo-600"></div>
                         </label>
                      </div>
                      <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-1">
                          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Daily Pass Limit</label>
                          <input 
                            type="number" 
                            disabled={!editingHospital.supportedSessions.includes(sess as SessionType)}
                            value={editingHospital.passLimits?.[sess] || 0}
                            onChange={(e) => setEditingHospital({...editingHospital, passLimits: {...(editingHospital.passLimits || {}), [sess]: parseInt(e.target.value) || 0 }})}
                            className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl font-bold text-lg disabled:opacity-50" 
                          />
                        </div>
                        <div className="grid grid-cols-2 gap-2">
                          <div className="space-y-1">
                            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Start</label>
                            <input disabled={!editingHospital.supportedSessions.includes(sess as SessionType)} type="time" value={editingHospital.sessionWindows?.[sess]?.start || '00:00'} onChange={(e) => setEditingHospital({...editingHospital, sessionWindows: {...(editingHospital.sessionWindows || {}), [sess]: { ...(editingHospital.sessionWindows?.[sess] || {start:'00:00', end:'23:59'}), start: e.target.value }}})} className="w-full px-2 py-3 bg-white border border-slate-200 rounded-xl font-bold text-sm disabled:opacity-50" />
                          </div>
                          <div className="space-y-1">
                            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">End</label>
                            <input disabled={!editingHospital.supportedSessions.includes(sess as SessionType)} type="time" value={editingHospital.sessionWindows?.[sess]?.end || '23:59'} onChange={(e) => setEditingHospital({...editingHospital, sessionWindows: {...(editingHospital.sessionWindows || {}), [sess]: { ...(editingHospital.sessionWindows?.[sess] || {start:'00:00', end:'23:59'}), end: e.target.value }}})} className="w-full px-2 py-3 bg-white border border-slate-200 rounded-xl font-bold text-sm disabled:opacity-50" />
                          </div>
                        </div>
                      </div>
                   </div>
                 ))}
               </div>
               <button onClick={handleSaveConfig} className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-xl hover:bg-indigo-700 active:scale-95 transition-all flex items-center justify-center gap-2">
                 <Save className="h-5 w-5" /> SAVE CONFIGURATION
               </button>
            </div>
          )}
        </section>
      )}

      {/* MR Profile Modal - Restricted View for Privacy */}
      {selectedMR && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in zoom-in duration-200">
          <div className="bg-white w-full max-w-lg rounded-3xl shadow-2xl overflow-hidden">
            <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-bold text-slate-800">MR Verification Profile</h3>
              <button onClick={() => setSelectedMR(null)} className="p-2 hover:bg-slate-200 rounded-full transition-all"><X className="h-5 w-5 text-slate-400" /></button>
            </div>
            <div className="p-8 space-y-6 max-h-[85vh] overflow-y-auto">
              <div className="flex flex-col items-center text-center">
                 <div className="w-20 h-20 bg-indigo-100 rounded-full flex items-center justify-center border-4 border-slate-50 shadow-sm mb-4">
                   <User className="h-10 w-10 text-indigo-600" />
                 </div>
                 <h4 className="text-2xl font-black text-slate-800">{selectedMR.fullName}</h4>
                 <p className="text-indigo-600 font-bold text-xs uppercase tracking-widest mb-1">{selectedMR.companyName}</p>
                 <div className="bg-green-50 px-3 py-1 rounded-full text-[10px] font-black text-green-700 uppercase tracking-widest">
                    SLCPI NUMBER: {selectedMR.slcpiId || 'PENDING'}
                 </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Contact Number</p>
                  <p className="font-bold text-slate-800">{selectedMR.mobileNumber}</p>
                </div>
                <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">National ID (NIC)</p>
                  <p className="font-bold text-slate-800">{selectedMR.identificationNumber}</p>
                </div>
                <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100 col-span-2">
                  <div className="flex justify-between items-center mb-1">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">SLCPI Expiry Date</p>
                    <Calendar className="h-3 w-3 text-slate-300" />
                  </div>
                  <p className="font-bold text-slate-800">{selectedMR.slcpiExpiry || 'NOT PROVIDED'}</p>
                </div>
              </div>

              <div className="space-y-3">
                 <h5 className="text-[10px] font-black uppercase tracking-widest text-slate-400 flex items-center gap-2"><ImageIcon className="h-3 w-3" /> SLCPI Verification Document</h5>
                 {selectedMR.slcpiPhoto ? (
                   <div className="rounded-2xl overflow-hidden border border-slate-200 bg-white aspect-video relative shadow-inner">
                      <img src={selectedMR.slcpiPhoto} className="w-full h-full object-contain" alt="SLCPI Photo" />
                   </div>
                 ) : (
                   <div className="p-10 text-center bg-slate-50 rounded-2xl border-2 border-dashed border-slate-200">
                      <ImageIcon className="h-8 w-8 text-slate-200 mx-auto mb-2 opacity-30" />
                      <p className="text-xs font-bold text-slate-400 italic">No SLCPI document photo provided.</p>
                   </div>
                 )}
              </div>

              <div className="flex gap-4 pt-4 border-t border-slate-100">
                {pendingApprovals.some(a => a.mrId === selectedMR.id) ? (
                  <>
                    <button onClick={() => { const approval = pendingApprovals.find(a => a.mrId === selectedMR.id); if (approval) updateApproval(approval.id, 'approved'); }} className="flex-1 bg-green-600 text-white font-black py-4 rounded-2xl shadow-xl hover:bg-green-700 transition-all active:scale-95 uppercase text-xs tracking-widest">Verify & Approve</button>
                    <button onClick={() => { const approval = pendingApprovals.find(a => a.mrId === selectedMR.id); if (approval) updateApproval(approval.id, 'rejected'); }} className="flex-1 bg-white border border-red-100 text-red-500 font-black py-4 rounded-2xl hover:bg-red-50 transition-all uppercase text-xs tracking-widest">Reject Access</button>
                  </>
                ) : (
                  <button onClick={() => setSelectedMR(null)} className="w-full bg-slate-800 text-white font-black py-4 rounded-2xl hover:bg-slate-900 transition-all uppercase tracking-widest text-xs">Close Profile View</button>
                )}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect, useContext } from 'react';
import { 
  Building2, Users, Settings, Plus, Power, Activity, Edit3, Trash2, X, 
  Briefcase, Clock, User, ShieldCheck, Lock, Key, Image as ImageIcon, 
  CheckCircle, TrendingUp, AlertTriangle, Info, Calendar, Mail, Phone, Eye, EyeOff 
} from 'lucide-react';
import { storageService } from '../services/storageService';
import { Hospital, PharmaCompany, MedicalRep, HospitalUser, PassApplication, IssuedPass } from '../types';
import { FeedbackContext } from '../App';

const SuperAdminDashboard: React.FC = () => {
  const { showFeedback } = useContext(FeedbackContext);

  // Data States
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [companies, setCompanies] = useState<PharmaCompany[]>([]);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);

  // UI States
  const [activeTab, setActiveTab] = useState<'hospitals' | 'companies' | 'monitoring'>('hospitals');

  // Hospital Modal States
  const [isHospitalModalOpen, setIsHospitalModalOpen] = useState(false);
  const [editingHospital, setEditingHospital] = useState<Partial<Hospital> | null>(null);
  const [adminData, setAdminData] = useState({ fullName: '', mobileNumber: '', password: '' });
  const [securityData, setSecurityData] = useState({ fullName: '', mobileNumber: '', password: '' });
  const [showPasswords, setShowPasswords] = useState(false);

  // Company Modal States
  const [isCompanyModalOpen, setIsCompanyModalOpen] = useState(false);
  const [editingCompany, setEditingCompany] = useState<Partial<PharmaCompany> | null>(null);
  const [selectedCompanyId, setSelectedCompanyId] = useState<string | null>(null);
  const [selectedMR, setSelectedMR] = useState<MedicalRep | null>(null);

  useEffect(() => {
    refreshData();
  }, []);

  const refreshData = () => {
    setHospitals(storageService.getHospitals());
    setCompanies(storageService.getCompanies());
    setMrs(storageService.getMRs());
    setApps(storageService.getApplications());
    setPasses(storageService.getPasses());
  };

  const handleSaveHospital = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingHospital?.name) return;

    const hospitalId = editingHospital.id || 'h' + Date.now();

    const hospitalData: Hospital = {
      id: hospitalId,
      name: editingHospital.name || '',
      isActive: editingHospital.isActive ?? true,
      supportedSessions: editingHospital.supportedSessions || ['MORNING', 'EVENING', 'FULL_DAY'],
      passLimits: editingHospital.passLimits || { 'MORNING': 10, 'EVENING': 10, 'FULL_DAY': 5 },
      sessionWindows: editingHospital.sessionWindows || { 
        'MORNING': { start: '08:00', end: '10:00' },
        'EVENING': { start: '16:00', end: '18:00' },
        'FULL_DAY': { start: '08:00', end: '18:00' }
      },
    };

    const currentHospitals = storageService.getHospitals();
    const updatedHospitals = editingHospital.id 
      ? currentHospitals.map(h => h.id === hospitalId ? hospitalData : h)
      : [...currentHospitals, hospitalData];

    storageService.saveHospitals(updatedHospitals);

    // Save Hospital User Accounts
    const u: HospitalUser[] = [
      { id: `u-a-${hospitalId}`, hospitalId, role: 'ADMIN', fullName: adminData.fullName, mobileNumber: adminData.mobileNumber, password: adminData.password },
      { id: `u-s-${hospitalId}`, hospitalId, role: 'SECURITY', fullName: securityData.fullName, mobileNumber: securityData.mobileNumber, password: securityData.password }
    ];

    const currentUsers = storageService.getHospitalUsers().filter(user => user.hospitalId !== hospitalId);
    storageService.saveHospitalUsers([...currentUsers, ...u]);

    refreshData();
    setIsHospitalModalOpen(false);
    setEditingHospital(null);
    setAdminData({ fullName: '', mobileNumber: '', password: '' });
    setSecurityData({ fullName: '', mobileNumber: '', password: '' });
    showFeedback(editingHospital.id ? "Hospital infrastructure updated." : "New facility provisioned.");
  };

  const startEditHospital = (h: Hospital) => {
    setEditingHospital(h);
    const users = storageService.getHospitalUsers().filter(u => u.hospitalId === h.id);
    const admin = users.find(u => u.role === 'ADMIN');
    const security = users.find(u => u.role === 'SECURITY');

    setAdminData({ 
      fullName: admin?.fullName || '', 
      mobileNumber: admin?.mobileNumber || '', 
      password: admin?.password || '' 
    });
    setSecurityData({ 
      fullName: security?.fullName || '', 
      mobileNumber: security?.mobileNumber || '', 
      password: security?.password || '' 
    });
    setIsHospitalModalOpen(true);
  };

  const handleSaveCompany = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingCompany?.name || !editingCompany?.companyCode) {
      showFeedback("Company name and code are required.", "error");
      return;
    }

    const companyId = editingCompany.id || 'c' + Date.now();
    const companyData: PharmaCompany = {
      id: companyId,
      name: editingCompany.name || '',
      companyCode: editingCompany.companyCode || '',
      adminMobile: editingCompany.adminMobile || '',
      adminPassword: editingCompany.adminPassword || '',
      contactEmail: editingCompany.contactEmail || '',
      isActive: editingCompany.isActive ?? true,
    };

    const currentCompanies = storageService.getCompanies();
    const updated = editingCompany.id 
      ? currentCompanies.map(c => c.id === companyId ? companyData : c)
      : [...currentCompanies, companyData];

    storageService.saveCompanies(updated);
    refreshData();
    setIsCompanyModalOpen(false);
    setEditingCompany(null);
    showFeedback(`Pharmaceutical company ${companyData.name} registered.`);
  };

  const toggleCompanyStatus = (id: string) => {
    const updated = companies.map(c => c.id === id ? { ...c, isActive: !c.isActive } : c);
    storageService.saveCompanies(updated);
    setCompanies(updated);
    const c = updated.find(x => x.id === id);
    showFeedback(`Company ${c?.name} is now ${c?.isActive ? 'active' : 'deactivated'}`);
  };

  return (
    <div className="space-y-6">
      {/* Tab Navigation */}
      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('hospitals')} className={`px-4 md:px-6 py-2 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'hospitals' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Building2 className="h-4 w-4" /> Hospitals</button>
        <button onClick={() => setActiveTab('companies')} className={`px-4 md:px-6 py-2 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'companies' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Briefcase className="h-4 w-4" /> Companies</button>
        <button onClick={() => setActiveTab('monitoring')} className={`px-4 md:px-6 py-2 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'monitoring' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Activity className="h-4 w-4" /> Monitoring</button>
      </div>

      {/* Hospitals Management */}
      {activeTab === 'hospitals' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
          <div className="flex justify-between items-center mb-8">
            <h3 className="text-xl font-bold">Facility Management</h3>
            <button 
              onClick={() => { 
                setEditingHospital({ supportedSessions: ['MORNING', 'EVENING', 'FULL_DAY'] }); 
                setAdminData({ fullName: '', mobileNumber: '', password: '' });
                setSecurityData({ fullName: '', mobileNumber: '', password: '' });
                setIsHospitalModalOpen(true); 
              }}
              className="bg-indigo-600 text-white px-5 py-2.5 rounded-xl font-bold flex items-center gap-2 hover:bg-indigo-700 shadow-lg active:scale-95 transition-all"
            >
              <Plus className="h-4 w-4" /> PROVISION HOSPITAL
            </button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {hospitals.map(h => (
              <div key={h.id} className="p-6 bg-slate-50 rounded-3xl border border-slate-100 relative group hover:shadow-md transition-all">
                <div className={`absolute top-4 right-4 w-2 h-2 rounded-full ${h.isActive ? 'bg-green-500' : 'bg-red-500'}`}></div>
                <h4 className="font-black text-slate-800 text-lg mb-4">{h.name}</h4>
                <div className="space-y-2 mb-6">
                   <div className="flex items-center gap-2 text-xs font-bold text-slate-500">
                     <ShieldCheck className="h-4 w-4" /> 
                     Admin: {storageService.getHospitalUsers().find(u => u.hospitalId === h.id && u.role === 'ADMIN')?.fullName || 'Unassigned'}
                   </div>
                   <div className="flex items-center gap-2 text-[10px] font-black uppercase text-indigo-400 tracking-widest">
                     {h.supportedSessions.join(' • ')}
                   </div>
                </div>
                <button 
                  onClick={() => startEditHospital(h)}
                  className="w-full py-2.5 bg-white border border-slate-200 text-slate-600 rounded-xl text-xs font-black hover:bg-indigo-50 hover:border-indigo-200 hover:text-indigo-600 transition-all flex items-center justify-center gap-2 shadow-sm"
                >
                  <Edit3 className="h-3.5 w-3.5" /> CONFIGURE & ACCOUNTS
                </button>
              </div>
            ))}
          </div>
        </section>
      )}

      {/* Companies Management */}
      {activeTab === 'companies' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
          <div className="flex justify-between items-center mb-8">
            <h3 className="text-xl font-bold">Pharma Company Management</h3>
            <button 
              onClick={() => { setEditingCompany({ isActive: true }); setIsCompanyModalOpen(true); }}
              className="bg-indigo-600 text-white px-5 py-2.5 rounded-xl font-bold flex items-center gap-2 hover:bg-indigo-700 shadow-lg active:scale-95 transition-all"
            >
              <Plus className="h-4 w-4" /> NEW PARTNER
            </button>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* List */}
            <div className="lg:col-span-1 space-y-3">
              {companies.map(c => {
                const companyMRCount = mrs.filter(m => m.companyName === c.name).length;
                return (
                  <button 
                    key={c.id}
                    onClick={() => setSelectedCompanyId(c.id)}
                    className={`w-full text-left p-4 rounded-2xl border transition-all ${selectedCompanyId === c.id ? 'border-indigo-600 bg-indigo-50 shadow-sm' : 'border-slate-100 bg-slate-50 hover:bg-slate-100'}`}
                  >
                    <div className="flex justify-between items-center">
                      <h4 className="font-bold text-slate-800">{c.name}</h4>
                      <div className={`w-2 h-2 rounded-full ${c.isActive ? 'bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.5)]' : 'bg-slate-300'}`}></div>
                    </div>
                    <p className="text-[10px] text-slate-400 font-bold uppercase mt-1 tracking-tighter">{c.companyCode} • {companyMRCount} MRs Registered</p>
                  </button>
                );
              })}
            </div>

            {/* Details */}
            <div className="lg:col-span-2">
              {selectedCompanyId ? (
                <div className="bg-slate-50 rounded-2xl border border-slate-100 overflow-hidden animate-in fade-in duration-300">
                  <div className="bg-white p-6 border-b border-slate-100 flex justify-between items-center">
                    <div>
                      <h4 className="font-black text-xl text-slate-800">{companies.find(c => c.id === selectedCompanyId)?.name}</h4>
                      <p className="text-xs font-bold text-indigo-600">Admin Login ID: {companies.find(c => c.id === selectedCompanyId)?.adminMobile}</p>
                    </div>
                    <div className="flex gap-2">
                       <button onClick={() => toggleCompanyStatus(selectedCompanyId)} className={`text-[10px] font-black uppercase px-3 py-1.5 rounded-lg border transition-colors ${companies.find(c => c.id === selectedCompanyId)?.isActive ? 'border-red-200 text-red-600 bg-red-50' : 'border-green-200 text-green-600 bg-green-50'}`}>
                         {companies.find(c => c.id === selectedCompanyId)?.isActive ? 'Deactivate' : 'Activate'}
                       </button>
                       <button onClick={() => { setEditingCompany(companies.find(c => c.id === selectedCompanyId)); setIsCompanyModalOpen(true); }} className="p-1.5 bg-slate-100 hover:bg-slate-200 rounded-lg"><Edit3 className="h-4 w-4 text-slate-600" /></button>
                    </div>
                  </div>

                  <div className="p-6">
                    <h5 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Representative Registry</h5>
                    <div className="space-y-2">
                       {mrs.filter(m => m.companyName === companies.find(c => c.id === selectedCompanyId)?.name).map(mr => (
                         <div key={mr.id} className="flex items-center justify-between p-3 bg-white rounded-xl border border-slate-100 hover:border-indigo-200 transition-all cursor-pointer" onClick={() => setSelectedMR(mr)}>
                            <div className="flex items-center gap-3">
                               <div className="w-8 h-8 bg-slate-100 rounded-lg flex items-center justify-center"><User className="h-4 w-4 text-slate-400" /></div>
                               <div><p className="text-xs font-black">{mr.fullName}</p><p className="text-[9px] text-slate-400">{mr.mrId}</p></div>
                            </div>
                            <span className={`text-[9px] font-black uppercase tracking-tighter px-2 py-0.5 rounded ${mr.status === 'active' ? 'bg-green-50 text-green-600' : 'bg-red-50 text-red-600'}`}>{mr.status}</span>
                         </div>
                       ))}
                       {mrs.filter(m => m.companyName === companies.find(c => c.id === selectedCompanyId)?.name).length === 0 && (
                         <p className="text-center py-12 text-slate-400 italic text-xs">No MRs registered for this company yet.</p>
                       )}
                    </div>
                  </div>
                </div>
              ) : (
                <div className="h-full min-h-[400px] flex flex-col items-center justify-center p-12 bg-slate-50 rounded-3xl border border-dashed border-slate-200 text-slate-400">
                  <Briefcase className="h-16 w-16 mb-4 opacity-10" />
                  <p className="text-sm font-medium">Select a company from the list to view its registered representatives and management settings.</p>
                </div>
              )}
            </div>
          </div>
        </section>
      )}

      {/* Monitoring Dashboard */}
      {activeTab === 'monitoring' && (
        <section className="space-y-6">
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
             <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm"><p className="text-[10px] font-black text-slate-400 uppercase mb-1">Total System MRs</p><h3 className="text-3xl font-black text-slate-800">{mrs.length}</h3></div>
             <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm"><p className="text-[10px] font-black text-slate-400 uppercase mb-1">Active Hospitals</p><h3 className="text-3xl font-black text-slate-800">{hospitals.filter(h => h.isActive).length}</h3></div>
