                    <textarea value={editingCompany?.address || ''} onChange={e => setEditingCompany({...editingCompany, address: e.target.value})} className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold focus:ring-2 focus:ring-indigo-500 outline-none h-20" placeholder="Corporate Headquarters Address" />
                 </div>
                 <div className="grid grid-cols-2 gap-4">
                   <div className="relative">
                     <Phone className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-300" />
                     <input type="tel" value={editingCompany?.contactNumber || ''} onChange={e => setEditingCompany({...editingCompany, contactNumber: e.target.value})} className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold focus:ring-2 focus:ring-indigo-500 outline-none" placeholder="Official contact Phone" />
                   </div>
                   <div className="relative">
                     <DollarSign className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-amber-500" />
                     <input type="email" value={editingCompany?.financeEmail || ''} onChange={e => setEditingCompany({...editingCompany, financeEmail: e.target.value})} className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold focus:ring-2 focus:ring-indigo-500 outline-none" placeholder="Finance Dept Email" />
                   </div>
                 </div>

                 <div className="pt-6 border-t border-slate-100">
                    <p className="text-[10px] font-black text-indigo-400 uppercase mb-3 tracking-widest flex items-center gap-2"><Key className="h-3 w-3" /> Partner Admin Node Provisioning</p>
                    <div className="space-y-3">
                       <div className="relative">
