                </div>
              </div>

              <div className="space-y-3">
                 <h5 className="text-[10px] font-black uppercase tracking-widest text-slate-400 flex items-center gap-2"><ImageIcon className="h-3 w-3" /> SLCPI Verification Document</h5>
                 {selectedMR.slcpiPhoto ? (
                   <div className="rounded-2xl overflow-hidden border border-slate-200 bg-white aspect-video relative shadow-inner">
                      <img src={selectedMR.slcpiPhoto} className="w-full h-full object-contain" alt="SLCPI Photo" />
                   </div>
                 ) : (
                   <div className="p-10 text-center bg-slate-50 rounded-2xl border-2 border-dashed border-slate-200">
                      <ImageIcon className="h-8 w-8 text-slate-200 mx-auto mb-2 opacity-30" />
                      <p className="text-xs font-bold text-slate-400 italic">No SLCPI document photo provided.</p>
                   </div>
                 )}
              </div>

              <div className="flex gap-4 pt-4 border-t border-slate-100">
                {pendingApprovals.some(a => a.mrId === selectedMR.id) ? (
                  <>
                    <button onClick={() => { const approval = pendingApprovals.find(a => a.mrId === selectedMR.id); if (approval) updateApproval(approval.id, 'approved'); }} className="flex-1 bg-green-600 text-white font-black py-4 rounded-2xl shadow-xl hover:bg-green-700 transition-all active:scale-95 uppercase text-xs tracking-widest">Verify & Approve</button>
                    <button onClick={() => { const approval = pendingApprovals.find(a => a.mrId === selectedMR.id); if (approval) updateApproval(approval.id, 'rejected'); }} className="flex-1 bg-white border border-red-100 text-red-500 font-black py-4 rounded-2xl hover:bg-red-50 transition-all uppercase text-xs tracking-widest">Reject Access</button>
                  </>
                ) : (
                  <button onClick={() => setSelectedMR(null)} className="w-full bg-slate-800 text-white font-black py-4 rounded-2xl hover:bg-slate-900 transition-all uppercase tracking-widest text-xs">Close Profile View</button>
                )}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect, useContext, useRef } from 'react';
import { 
  UserPlus, Search, Briefcase, Mail, Phone, CreditCard, X, Edit3, Trash2, Power, 
  User, ShieldCheck, Activity, Users, Plus, Key, BarChart3, Clock, CheckCircle2, 
  Image as ImageIcon, Upload, Calendar, MapPin, DollarSign, Save
} from 'lucide-react';
import { storageService } from '../services/storageService';
import { MedicalRep, PharmaCompany, AuthUser, PassApplication, IssuedPass } from '../types';
import { FeedbackContext } from '../App';

interface CompanyAdminDashboardProps {
  user: AuthUser;
}

const CompanyAdminDashboard: React.FC<CompanyAdminDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [allApps, setAllApps] = useState<PassApplication[]>([]);
  const [allPasses, setAllPasses] = useState<IssuedPass[]>([]);
  const [company, setCompany] = useState<PharmaCompany | null>(null);
  const [activeTab, setActiveTab] = useState<'staff' | 'profile'>('staff');
  const [searchTerm, setSearchTerm] = useState('');
  const [isMRModalOpen, setIsMRModalOpen] = useState(false);
  const [editingMR, setEditingMR] = useState<Partial<MedicalRep> | null>(null);

  const [summaryMR, setSummaryMR] = useState<MedicalRep | null>(null);
  const [editingProfile, setEditingProfile] = useState<PharmaCompany | null>(null);

  useEffect(() => {
    refreshData();
  }, []);

  const refreshData = () => {
    const allCompanies = storageService.getCompanies();
    const myCompany = allCompanies.find(c => c.id === user.companyId);
    if (myCompany) {
      setCompany(myCompany);
      setEditingProfile(myCompany);
      const allMRs = storageService.getMRs();
      setMrs(allMRs.filter(m => m.companyName === myCompany.name));
    }
    setAllApps(storageService.getApplications());
    setAllPasses(storageService.getPasses());
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setEditingMR(prev => ({ ...prev, slcpiPhoto: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveMR = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingMR?.fullName || !editingMR?.mobileNumber || !editingMR?.loginId || !company) {
      showFeedback("Required fields missing.", "error");
      return;
    }

    const allMRs = storageService.getMRs();
    const duplicate = allMRs.find(m => m.loginId === editingMR.loginId && m.id !== editingMR.id);
    if (duplicate) {
      showFeedback("Login ID is already taken.", "error");
      return;
    }

    const mrData: MedicalRep = {
      id: editingMR.id || 'mr-' + Date.now(),
      fullName: editingMR.fullName,
      companyName: company.name,
      mrId: editingMR.mrId || `SYS-${Math.floor(1000 + Math.random() * 9000)}`,
      loginId: editingMR.loginId,
      mobileNumber: editingMR.mobileNumber,
      password: editingMR.password || 'mr123', 
      identificationNumber: editingMR.identificationNumber || '',
      slcpiId: editingMR.slcpiId || '',
      slcpiPhoto: editingMR.slcpiPhoto,
      slcpiExpiry: editingMR.slcpiExpiry,
      status: (editingMR.status as any) || 'active',
      createdAt: editingMR.createdAt || new Date().toISOString()
    };

    let updated: MedicalRep[];
    if (editingMR.id) {
      updated = allMRs.map(m => m.id === editingMR.id ? mrData : m);
      showFeedback(`Updated ${mrData.fullName}`);
    } else {
      updated = [...allMRs, mrData];
      showFeedback(`Registered ${mrData.fullName}`);
    }

    storageService.saveMRs(updated);
    setMrs(updated.filter(m => m.companyName === company.name));
    setIsMRModalOpen(false);
    setEditingMR(null);
  };

  const handleSaveProfile = () => {
    if (!editingProfile) return;
    const allCompanies = storageService.getCompanies();
    const updated = allCompanies.map(c => c.id === editingProfile.id ? editingProfile : c);
    storageService.saveCompanies(updated);
    setCompany(editingProfile);
    showFeedback("Company profile updated successfully.");
  };

  const toggleMRStatus = (id: string) => {
    const allMRs = storageService.getMRs();
    const updated = allMRs.map(m => m.id === id ? { ...m, status: (m.status === 'active' ? 'suspended' : 'active') as any } : m);
    storageService.saveMRs(updated);
    setMrs(updated.filter(m => m.companyName === company?.name));
  };

  const getMRStats = (mrId: string) => {
    const mrPasses = allPasses.filter(p => p.mrId === mrId && p.entryStatus === 'entered');
    return { visits: mrPasses.length };
  };

  return (
    <div className="space-y-6">
      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('staff')} className={`px-4 sm:px-6 py-2 rounded-xl text-sm font-bold flex items-center gap-2 transition-all whitespace-nowrap ${activeTab === 'staff' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Users className="h-4 w-4" /> My Staff</button>
        <button onClick={() => setActiveTab('profile')} className={`px-4 sm:px-6 py-2 rounded-xl text-sm font-bold flex items-center gap-2 transition-all whitespace-nowrap ${activeTab === 'profile' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Briefcase className="h-4 w-4" /> Company Profile</button>
      </div>

      {activeTab === 'staff' && (
        <>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-indigo-600 rounded-3xl p-6 text-white shadow-xl flex flex-col justify-between relative overflow-hidden">
              <Briefcase className="absolute -right-4 -bottom-4 h-24 w-24 opacity-10" />
              <p className="text-[10px] font-black uppercase tracking-widest opacity-80 mb-1">Facility Partner</p>
              <h3 className="text-2xl font-black truncate">{company?.name || "Loading..."}</h3>
            </div>

            <div className="bg-white rounded-3xl p-6 border border-slate-100 shadow-sm flex flex-col justify-between">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Active Staff</p>
              <h3 className="text-3xl font-black text-slate-800">{mrs.filter(m => m.status === 'active').length} Reps</h3>
            </div>

            <button 
              onClick={() => { setEditingMR({ status: 'active', password: 'mr' + Math.floor(100+Math.random()*900) }); setIsMRModalOpen(true); }}
              className="bg-indigo-50 text-indigo-600 py-4 rounded-3xl border-2 border-dashed border-indigo-200 font-black text-sm flex items-center justify-center gap-2 hover:bg-indigo-100 transition-all active:scale-95"
            >
              <UserPlus className="h-5 w-5" /> REGISTER NEW MR
            </button>
          </div>

          <section className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-100">
                  <th className="px-4 py-4">Name</th>
                  <th className="px-4 py-4">Login ID</th>
                  <th className="px-4 py-4">SLCPI ID</th>
                  <th className="px-4 py-4 text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {mrs.map(mr => (
                  <tr key={mr.id} className="hover:bg-slate-50/50 transition-colors">
                    <td className="px-4 py-4 font-bold text-slate-800 text-sm">{mr.fullName}</td>
                    <td className="px-4 py-4 font-mono font-bold text-indigo-600 text-xs">{mr.loginId}</td>
                    <td className="px-4 py-4 text-xs font-bold text-slate-500">{mr.slcpiId || 'N/A'}</td>
                    <td className="px-4 py-4 text-right">
                      <div className="flex justify-end gap-1.5">
                         <button onClick={() => setSummaryMR(mr)} className="p-2 text-slate-400 hover:text-indigo-600 rounded-lg"><BarChart3 className="h-4 w-4" /></button>
                         <button onClick={() => { setEditingMR(mr); setIsMRModalOpen(true); }} className="p-2 text-slate-400 hover:text-indigo-600 rounded-lg"><Edit3 className="h-4 w-4" /></button>
                         <button onClick={() => toggleMRStatus(mr.id)} className={`p-2 rounded-lg ${mr.status === 'active' ? 'text-red-400' : 'text-green-500'}`}><Power className="h-4 w-4" /></button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </section>
        </>
      )}

      {activeTab === 'profile' && company && editingProfile && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm max-w-2xl mx-auto">
          <div className="flex items-center gap-3 mb-8">
            <Briefcase className="h-6 w-6 text-indigo-600" />
            <h3 className="text-xl font-bold">Manage Company Profile</h3>
          </div>

          <div className="space-y-6 animate-in fade-in duration-300">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Company Name</label>
                <input type="text" value={editingProfile.name} readOnly className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold text-slate-500" />
                <p className="text-[9px] text-slate-400 mt-1 italic">Contact Super Admin to change official name.</p>
              </div>
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">System Code</label>
                <input type="text" value={editingProfile.companyCode} readOnly className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-mono font-bold text-slate-500" />
              </div>
            </div>

            <div>
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Corporate Address</label>
              <div className="relative">
                <MapPin className="absolute left-3 top-4 h-4 w-4 text-slate-300" />
                <textarea 
                  value={editingProfile.address || ''} 
                  onChange={(e) => setEditingProfile({...editingProfile, address: e.target.value})}
                  className="w-full pl-10 pr-4 py-3 bg-white border border-slate-200 rounded-xl font-bold focus:ring-2 focus:ring-indigo-500 outline-none h-24" 
                  placeholder="Official headquarters address"
                />
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Admin Email</label>
                <div className="relative">
                  <Mail className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-300" />
                  <input 
                    type="email" 
                    value={editingProfile.contactEmail} 
                    onChange={(e) => setEditingProfile({...editingProfile, contactEmail: e.target.value})}
                    className="w-full pl-10 pr-4 py-3 bg-white border border-slate-200 rounded-xl font-bold focus:ring-2 focus:ring-indigo-500 outline-none" 
                  />
                </div>
              </div>
              <div>
                <label className="text-[10px] font-black text-amber-500 uppercase tracking-widest block mb-1">Finance Team Email</label>
                <div className="relative">
                  <DollarSign className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-amber-400" />
                  <input 
                    type="email" 
                    value={editingProfile.financeEmail || ''} 
                    onChange={(e) => setEditingProfile({...editingProfile, financeEmail: e.target.value})}
                    className="w-full pl-10 pr-4 py-3 bg-white border border-slate-200 rounded-xl font-bold focus:ring-2 focus:ring-indigo-500 outline-none" 
                  />
                </div>
              </div>
            </div>

            <div>
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Contact Number</label>
              <div className="relative">
                <Phone className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-300" />
                <input 
                  type="tel" 
                  value={editingProfile.contactNumber || ''} 
                  onChange={(e) => setEditingProfile({...editingProfile, contactNumber: e.target.value})}
                  className="w-full pl-10 pr-4 py-3 bg-white border border-slate-200 rounded-xl font-bold focus:ring-2 focus:ring-indigo-500 outline-none" 
                  placeholder="Main switchboard number"
                />
              </div>
            </div>

            <button 
              onClick={handleSaveProfile} 
              className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-xl hover:bg-indigo-700 active:scale-95 transition-all flex items-center justify-center gap-2"
            >
              <Save className="h-5 w-5" /> UPDATE CORPORATE PROFILE
            </button>
          </div>
        </section>
      )}

      {/* Summary Modal */}
      {summaryMR && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in zoom-in duration-200">
          <div className="bg-white w-full max-w-lg rounded-3xl shadow-2xl overflow-hidden p-8">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold">MR Profile Summary</h3>
              <button onClick={() => setSummaryMR(null)}><X className="h-5 w-5 text-slate-400" /></button>
            </div>
            <div className="space-y-4">
              <div className="flex items-center gap-4">
                 <div className="w-16 h-16 bg-indigo-100 rounded-full flex items-center justify-center"><User className="h-8 w-8 text-indigo-600" /></div>
                 <div><h4 className="text-xl font-black">{summaryMR.fullName}</h4><p className="text-sm font-bold text-indigo-500 uppercase">{summaryMR.companyName}</p></div>
              </div>
              <div className="grid grid-cols-2 gap-3 pt-4">
                <div className="p-3 bg-slate-50 rounded-xl border border-slate-100"><p className="text-[10px] font-black text-slate-400 uppercase">Login ID</p><p className="font-bold">{summaryMR.loginId}</p></div>
                <div className="p-3 bg-slate-50 rounded-xl border border-slate-100"><p className="text-[10px] font-black text-slate-400 uppercase">SLCPI ID</p><p className="font-bold">{summaryMR.slcpiId || 'N/A'}</p></div>
                <div className="p-3 bg-slate-50 rounded-xl border border-slate-100"><p className="text-[10px] font-black text-slate-400 uppercase">SLCPI Expiry</p><p className="font-bold">{summaryMR.slcpiExpiry || 'N/A'}</p></div>
                <div className="p-3 bg-slate-50 rounded-xl border border-slate-100"><p className="text-[10px] font-black text-slate-400 uppercase">Visits</p><p className="font-bold">{getMRStats(summaryMR.id).visits}</p></div>
