}>({ showFeedback: () => {} });

const FeedbackToast = ({ message, type, onClose }: { message: string, type: 'success' | 'error', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 4000);
    return () => clearTimeout(timer);
  }, [onClose]);

  return (
    <div className="fixed bottom-6 right-6 z-[200] animate-in slide-in-from-right-10 fade-in duration-300">
      <div className={`flex items-center gap-3 px-6 py-4 rounded-2xl shadow-2xl border ${
        type === 'success' ? 'bg-white border-green-100 text-green-800' : 'bg-white border-red-100 text-red-800'
      }`}>
        {type === 'success' ? <CheckCircle2 className="h-6 w-6 text-green-500" /> : <AlertCircle className="h-6 w-6 text-red-500" />}
        <p className="font-bold text-sm">{message}</p>
        <button onClick={onClose} className="ml-2 p-1 hover:bg-slate-100 rounded-lg transition-all">
          <X className="h-4 w-4 text-slate-400" />
        </button>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [user, setUser] = useState<any>(null);
  const [view, setView] = useState<'LOGIN' | 'DASHBOARD'>('LOGIN');
  const [role, setRole] = useState<UserRole>('MR');
  const [mobile, setMobile] = useState(''); // We'll use this as "Login ID" for MRs
  const [password, setPassword] = useState('');
  const [feedback, setFeedback] = useState<{ message: string, type: 'success' | 'error' } | null>(null);

  // Track automated runs in the current session to avoid log spamming
  const autoRunLogs = useRef<Set<string>>(new Set());

  useEffect(() => {
    const session = storageService.getCurrentUser();
    if (session) { setUser(session); setView('DASHBOARD'); }

    // Start Global Automation Background Task
    // This runs for ANY user currently on the site, ensuring hospitals don't need their own admin logged in.
    const automationInterval = setInterval(() => {
      const now = new Date();
      const today = now.toISOString().split('T')[0];
      const currentTimeStr = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;

      const hospitals = storageService.getHospitals();
      hospitals.forEach(hosp => {
        if (!hosp.isActive || !hosp.autoLotteryEnabled) return;

        (['MORNING', 'EVENING', 'FULL_DAY'] as SessionType[]).forEach(sess => {
          const isEnabled = hosp.autoLotteryEnabled?.[sess];
          const triggerTime = hosp.autoLotteryTimes?.[sess];

          if (isEnabled && triggerTime && currentTimeStr >= triggerTime) {
            const logKey = `${hosp.id}-${today}-${sess}`;
            if (!autoRunLogs.current.has(logKey)) {
              const result = lotteryService.runLottery(hosp.id, sess);
              if (result.success) {
                console.log(`[AUTOMATION] Triggered lottery for ${hosp.name} (${sess})`);
                autoRunLogs.current.add(logKey);
                // We show feedback only if the logged in user is the relevant admin
                // or maybe always show for system transparency?
                // Let's only show to Admin of that hospital to avoid confusing MRs.
                const currentUser = storageService.getCurrentUser();
                if (currentUser?.hospitalId === hosp.id && currentUser.role === 'ADMIN') {
                  showFeedback(`Scheduled lottery for ${sess} executed automatically!`, 'success');
                }
              } else {
                // If it failed because no apps, still mark as checked to prevent constant retries
                if (result.message === "No applications found.") {
                   autoRunLogs.current.add(logKey);
                }
              }
            }
          }
        });
      });
    }, 15000); // Check every 15 seconds

    return () => clearInterval(automationInterval);
  }, []);

  const showFeedback = (message: string, type: 'success' | 'error' = 'success') => {
    setFeedback({ message, type });
  };

  const handleLogin = (e?: React.FormEvent) => {
    e?.preventDefault();

    if (role === 'MR') {
      const mrs = storageService.getMRs();
      const existing = mrs.find(m => m.loginId === mobile);
      if (existing) {
        if (existing.status === 'suspended') {
          showFeedback("Your account has been suspended by your company.", 'error');
          return;
        }
        if (existing.password && existing.password !== password) {
          showFeedback("Invalid credentials.", 'error');
          return;
        }
        const u: AuthUser = { 
          id: existing.id, 
          fullName: existing.fullName, 
          role: 'MR', 
          companyName: existing.companyName, 
          loginId: existing.loginId,
          mobileNumber: existing.mobileNumber 
        };
        storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
        showFeedback(`Welcome back, ${u.fullName}!`);
      } else {
        showFeedback("Medical Representative not found.", 'error');
      }
    } else if (role === 'COMPANY_ADMIN') {
      const companies = storageService.getCompanies();
      const found = companies.find(c => c.adminMobile === mobile);
      if (found && found.adminPassword === password) {
        if (!found.isActive) {
          showFeedback("Company access is deactivated.", 'error');
          return;
        }
        const u: AuthUser = { 
          id: found.id, 
          role: 'COMPANY_ADMIN', 
          fullName: `${found.name} Admin`,
          companyId: found.id 
        };
        storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
        showFeedback(`Pharma Admin session: ${found.name}`);
      } else {
        showFeedback("Invalid Company Admin credentials.", 'error');
      }
    } else if (role === 'ADMIN' || role === 'SECURITY') {
      const hospitalUsers = storageService.getHospitalUsers();
      const found = hospitalUsers.find(u => u.mobileNumber === mobile && u.role === role);

      if (found) {
        if (found.password === password) {
          const u: AuthUser = { 
            id: found.id,
            role: found.role, 
            fullName: found.fullName, 
            hospitalId: found.hospitalId,
            mobileNumber: found.mobileNumber
          };
          storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
          showFeedback(`Logged in as ${found.fullName}`);
        } else {
          showFeedback("Invalid password for this account.", 'error');
        }
      } else {
        showFeedback(`${role} credentials not found. Check with Super Admin.`, 'error');
      }
    } else if (role === 'SUPER_ADMIN') {
      if (mobile === 'root' && password === 'root') {
        const u: AuthUser = { id: 'sa-1', role: 'SUPER_ADMIN', fullName: 'MedPass Authority' };
        storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
        showFeedback("Super Admin session started.");
      } else {
        showFeedback("Invalid Super Admin Credentials", 'error');
      }
    }
  };

  const quickLogin = (r: UserRole, phone = '', pass = '') => { 
    setRole(r); 
    setMobile(phone);
    setPassword(pass);
    setTimeout(() => handleLogin(), 100); 
  };

  if (view === 'LOGIN') {
    return (
      <FeedbackContext.Provider value={{ showFeedback }}>
        <div className="min-h-screen bg-indigo-600 flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden">
            <div className="bg-slate-50 p-8 text-center border-b border-slate-100">
              <div className="bg-indigo-600 w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-4"><HospitalIcon className="h-10 w-10 text-white" /></div>
              <h1 className="text-2xl font-black text-slate-800 tracking-tighter">MedPass Engine</h1>
            </div>
            <div className="p-8">
              <div className="mb-6 bg-indigo-50 rounded-xl p-4">
                <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-2">System Demo Credentials</p>
                <div className="grid grid-cols-2 gap-2">
                  <button onClick={() => quickLogin('MR', 'john_mr', 'pass')} className="p-2 bg-white border border-indigo-100 rounded text-[10px] font-bold text-slate-700 flex flex-col items-center">
                    <User className="h-3 w-3 mb-1" /> MR John
                  </button>
                  <button onClick={() => quickLogin('COMPANY_ADMIN', '0779', 'pfiz')} className="p-2 bg-indigo-50 border border-indigo-100 rounded text-[10px] font-bold text-indigo-700 flex flex-col items-center">
                     <Briefcase className="h-3 w-3 mb-1" /> Pharma Admin
                  </button>
                  <button onClick={() => quickLogin('ADMIN', '0771', 'admin')} className="p-2 bg-slate-50 border border-slate-100 rounded text-[10px] font-bold text-slate-700 flex flex-col items-center">
                     <ShieldCheck className="h-3 w-3 mb-1" /> Hospital Admin
                  </button>
                  <button onClick={() => quickLogin('SUPER_ADMIN', 'root', 'root')} className="p-2 bg-slate-800 border border-slate-700 rounded text-[10px] font-bold text-white flex flex-col items-center">
                     <Crown className="h-3 w-3 mb-1" /> Super Admin
                  </button>
                </div>
              </div>

              <div className="flex bg-slate-100 p-1 rounded-xl mb-6 overflow-x-auto scrollbar-hide">
                {(['MR', 'COMPANY_ADMIN', 'ADMIN', 'SECURITY', 'SUPER_ADMIN'] as const).map(r => (
                  <button key={r} onClick={() => setRole(r)} className={`flex-1 min-w-[80px] py-1.5 text-[10px] font-black rounded-lg transition-all ${role === r ? 'bg-white text-indigo-600 shadow' : 'text-slate-400'}`}>{r}</button>
                ))}
              </div>

              <form onSubmit={handleLogin} className="space-y-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">{role === 'MR' ? 'Login User ID' : 'Login ID / Mobile'}</label>
                  <input 
                    type="text" 
                    value={mobile} 
                    onChange={e => setMobile(e.target.value)} 
                    className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-bold" 
                    placeholder={role === 'MR' ? "e.g. john_mr" : role === 'SUPER_ADMIN' ? "root" : "Admin ID"}
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold text-slate-500 uppercase">Password</label>
                  <div className="relative">
                    <input 
                      type="password" 
                      value={password} 
                      onChange={e => setPassword(e.target.value)} 
                      className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-bold" 
                      placeholder="••••••••"
                    />
                    <Lock className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-300" />
                  </div>
                </div>
                <button type="submit" className="w-full bg-indigo-600 text-white font-black py-4 rounded-xl shadow-lg hover:bg-indigo-700 active:scale-95 transition-all flex items-center justify-center gap-2">
                  Enter System <ArrowRight className="h-5 w-5" />
                </button>
              </form>
            </div>
          </div>
          {feedback && <FeedbackToast message={feedback.message} type={feedback.type} onClose={() => setFeedback(null)} />}
        </div>
      </FeedbackContext.Provider>
    );
  }

  return (
    <FeedbackContext.Provider value={{ showFeedback }}>
      <Layout 
        user={user} 
        onLogout={() => { storageService.clearSession(); setUser(null); setView('LOGIN'); showFeedback("Logged out successfully"); }} 
        title={user.role === 'SUPER_ADMIN' ? 'Root Authority' : user.role === 'MR' ? 'MR Dashboard' : `${user.fullName} Panel`}
      >
        {user.role === 'MR' && <MRDashboard user={user} />}
        {user.role === 'COMPANY_ADMIN' && <CompanyAdminDashboard user={user} />}
        {user.role === 'ADMIN' && <AdminDashboard user={user} />}
        {user.role === 'SUPER_ADMIN' && <SuperAdminDashboard />}
        {user.role === 'SECURITY' && <SecurityView />}
      </Layout>
      {feedback && <FeedbackToast message={feedback.message} type={feedback.type} onClose={() => setFeedback(null)} />}
    </FeedbackContext.Provider>
  );
};

export default App;

import React, { useState, useEffect, useContext, useRef } from 'react';
import { 
  Play, Sparkles, CheckCircle, Clock, UserPlus, Users, Settings, Save, X, 
  Plus, Sun, Moon, Maximize, User, Info, Building, MapPin, ShieldCheck, 
  Mail, Phone, CreditCard, ChevronRight, Briefcase, FileText, 
  Image as ImageIcon, CheckCircle2, AlertCircle, Calendar, Eye, 
  Building2, Globe, Zap, Timer
} from 'lucide-react';
import { storageService } from '../services/storageService';
import { lotteryService } from '../services/lotteryService';
import { MedicalRep, Hospital, PassApplication, IssuedPass, MRHospitalApproval, SessionType, PharmaCompany } from '../types';
import { getAdminBriefing } from '../services/geminiService';
import { FeedbackContext } from '../App';

interface AdminDashboardProps {
  user: {
    id: string;
    role: string;
    fullName: string;
    hospitalId: string;
  };
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [companies, setCompanies] = useState<PharmaCompany[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [activeTab, setActiveTab] = useState<'lottery' | 'approvals' | 'companies' | 'settings'>('lottery');
  const [settingsTab, setSettingsTab] = useState<'profile' | 'sessions'>('profile');
  const [brief, setBrief] = useState('');
  const [selectedMR, setSelectedMR] = useState<MedicalRep | null>(null);
  const [selectedCompany, setSelectedCompany] = useState<PharmaCompany | null>(null);

  const [editingHospital, setEditingHospital] = useState<Hospital | null>(null);

  useEffect(() => { 
    refreshData(); 
    // Data refresh interval to pick up background lottery runs
    const refreshInterval = setInterval(refreshData, 10000);
    return () => clearInterval(refreshInterval);
  }, []);

  const refreshData = async () => {
    const allHospitals = storageService.getHospitals();
    const currentHosp = allHospitals.find(h => h.id === user.hospitalId) || (allHospitals.length > 0 ? allHospitals[0] : null);

    setMrs(storageService.getMRs()); 
    setHospitals(allHospitals);
    setCompanies(storageService.getCompanies());
    setApps(storageService.getApplications()); 
    setPasses(storageService.getPasses());
    setApprovals(storageService.getApprovals());
    setEditingHospital(currentHosp);

    try {
      const summary = await getAdminBriefing(storageService.getApplications(), storageService.getPasses());
      setBrief(summary);
    } catch (e) {
      console.error("Briefing failed", e);
    }
  };

  const currentHospital = hospitals.find(h => h.id === user.hospitalId) || (hospitals.length > 0 ? hospitals[0] : null);

  const handleManualLottery = (session: SessionType) => {
    const result = lotteryService.runLottery(user.hospitalId, session);
    if (result.success) {
      showFeedback(result.message, 'success');
      refreshData();
    } else {
      showFeedback(result.message, 'error');
    }
  };

  const updateApproval = (id: string, status: 'approved' | 'rejected') => {
    const currentApprovals = storageService.getApprovals();
    const updated = currentApprovals.map(a => a.id === id ? { ...a, status, updatedAt: new Date().toISOString() } : a);
    storageService.saveApprovals(updated); 
    refreshData();
    if (selectedMR) setSelectedMR(null);
    showFeedback(`Representative access ${status}.`);
  };

  const handleSaveHospitalData = () => {
    if (!editingHospital) return;
    const allHospitals = storageService.getHospitals();
    const updated = allHospitals.map(h => h.id === editingHospital.id ? editingHospital : h);
    storageService.saveHospitals(updated);
    setHospitals(updated);
    showFeedback("Hospital profile and session configuration updated.");
  };

  const viewMRProfile = (mrId: string) => {
    const mr = mrs.find(m => m.id === mrId);
    if (mr) setSelectedMR(mr);
  };

  if (!currentHospital) {
    return (
      <div className="flex items-center justify-center h-64 bg-white rounded-3xl border border-slate-100 animate-pulse">
        <p className="text-slate-400 font-bold">Synchronizing Facility Data...</p>
      </div>
    );
  }

  const pendingApprovals = approvals.filter(a => a.hospitalId === user.hospitalId && a.status === 'pending');
  const approvedMRs = mrs.filter(mr => 
    approvals.some(apprv => apprv.hospitalId === user.hospitalId && apprv.mrId === mr.id && apprv.status === 'approved')
  );
  const approvedCompanyNames = Array.from(new Set(approvedMRs.map(mr => mr.companyName)));
  const approvedCompanies = companies.filter(c => approvedCompanyNames.includes(c.name));

  return (
    <div className="space-y-6">
      <div className="bg-indigo-600 rounded-3xl p-6 text-white shadow-lg flex items-center gap-4 border border-indigo-400/30">
        <Sparkles className="h-6 w-6 text-indigo-200 shrink-0" />
        <p className="text-sm font-medium leading-relaxed">{brief || "Scanning daily activity and calculating rankings..."}</p>
      </div>

      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('lottery')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all whitespace-nowrap ${activeTab === 'lottery' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Play className="h-4 w-4" /> Lottery</button>
        <button onClick={() => setActiveTab('approvals')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all whitespace-nowrap relative ${activeTab === 'approvals' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}>
          <UserPlus className="h-4 w-4" /> Requests
          {pendingApprovals.length > 0 && <span className="absolute -top-1 -right-1 flex h-4 w-4 items-center justify-center rounded-full bg-red-500 text-[8px] text-white ring-2 ring-white">{pendingApprovals.length}</span>}
        </button>
        <button onClick={() => setActiveTab('companies')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all whitespace-nowrap ${activeTab === 'companies' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Briefcase className="h-4 w-4" /> Companies</button>
        <button onClick={() => setActiveTab('settings')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all whitespace-nowrap ${activeTab === 'settings' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Settings className="h-4 w-4" /> Settings</button>
      </div>

      {activeTab === 'lottery' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-lg font-bold flex items-center gap-2 text-slate-800">
              <Clock className="h-5 w-5 text-indigo-500" />
              Daily Pass Lottery Selection
            </h3>
            <div className="flex items-center gap-2 bg-indigo-50 px-3 py-1.5 rounded-full border border-indigo-100 shadow-sm">
               <Zap className="h-3 w-3 text-indigo-600" />
               <span className="text-[10px] font-black text-indigo-600 uppercase tracking-widest">Automation Engine Active</span>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {['MORNING', 'EVENING', 'FULL_DAY'].map((sess) => {
               if (!currentHospital.supportedSessions.includes(sess as SessionType)) return null;
               const today = new Date().toISOString().split('T')[0];
               const count = apps.filter(a => a.hospitalId === user.hospitalId && a.applicationDate === today && a.session === sess && a.status === 'applied').length;
               const selectedCount = apps.filter(a => a.hospitalId === user.hospitalId && a.applicationDate === today && a.session === sess && (a.status === 'selected' || a.status === 'waitlisted')).length;
               const isAuto = currentHospital.autoLotteryEnabled?.[sess];
               const autoTime = currentHospital.autoLotteryTimes?.[sess];

               return (
                 <div key={sess} className="p-6 bg-slate-50 border border-slate-100 rounded-3xl relative overflow-hidden group">
                   {isAuto && (
                     <div className="absolute top-0 right-0 p-2">
                        <div className="bg-indigo-600 text-white p-1.5 rounded-bl-2xl rounded-tr-xl shadow-lg" title={`Auto-run scheduled for ${autoTime}`}>
                           <Zap className="h-3.5 w-3.5" />
                        </div>
                     </div>
                   )}
                   <div className="flex justify-between items-start mb-6">
                     <div className="flex items-center gap-3">
                       <div className="bg-white p-2 rounded-xl shadow-sm">
                         {sess === 'MORNING' ? <Sun className="h-6 w-6 text-amber-500" /> : sess === 'EVENING' ? <Moon className="h-6 w-6 text-indigo-400" /> : <Maximize className="h-6 w-6 text-indigo-600" />}
                       </div>
                       <div>
                         <h4 className="font-black text-slate-800 tracking-tight">{sess.replace('_', ' ')}</h4>
                         <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Limit: {currentHospital.passLimits?.[sess] || 0}</p>
                       </div>
                     </div>
                     <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest ${selectedCount > 0 ? 'bg-green-100 text-green-700' : 'bg-indigo-100 text-indigo-700'}`}>
                        {selectedCount > 0 ? 'DONE' : 'OPEN'}
                     </span>
                   </div>

                   <div className="flex items-center justify-between p-4 bg-white rounded-2xl mb-6 shadow-sm">
                      <div>
                        <p className="text-[10px] font-black text-slate-400 uppercase">Apps Received</p>
                        <p className="text-2xl font-black text-slate-800">{count}</p>
                      </div>
                      <Users className="h-8 w-8 text-slate-100" />
                   </div>

                   {isAuto && (
                      <div className="mb-4 px-4 py-2 bg-indigo-50 border border-indigo-100 rounded-xl flex items-center justify-between">
                         <span className="text-[10px] font-bold text-indigo-600 uppercase">Auto-Spin</span>
                         <span className="text-[10px] font-black text-indigo-800 flex items-center gap-1"><Timer className="h-3 w-3" /> {autoTime}</span>
                      </div>
                   )}

                   <button 
                     disabled={count === 0 || selectedCount > 0}
                     onClick={() => handleManualLottery(sess as SessionType)}
                     className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-lg hover:bg-indigo-700 active:scale-95 disabled:grayscale disabled:opacity-50 transition-all flex items-center justify-center gap-2"
                   >
                     {selectedCount > 0 ? <CheckCircle2 className="h-5 w-5" /> : <Play className="h-5 w-5" />}
                     {selectedCount > 0 ? 'LOTTERY FINISHED' : 'EXECUTE MANUAL SPIN'}
                   </button>
                 </div>
               );
            })}
          </div>
        </section>
      )}

      {activeTab === 'approvals' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
          <h3 className="text-lg font-bold mb-6">Verification Requests</h3>
          <div className="space-y-4">
             {pendingApprovals.map(approval => {
               const mr = mrs.find(m => m.id === approval.mrId);
               if (!mr) return null;
               return (
                 <div key={approval.id} className="p-5 bg-slate-50 border border-slate-100 rounded-2xl flex items-center justify-between hover:bg-indigo-50/30 transition-all group">
                   <div className="flex items-center gap-4">
                      <div className="bg-white p-2.5 rounded-xl shadow-sm border border-slate-100"><User className="h-6 w-6 text-slate-400" /></div>
                      <div>
                        <p className="font-bold text-slate-800 text-lg leading-tight">{mr.fullName}</p>
                        <p className="text-xs text-indigo-600 font-bold uppercase tracking-widest">{mr.companyName}</p>
                      </div>
                   </div>
                   <div className="flex items-center gap-3">
                      <button onClick={() => viewMRProfile(mr.id)} className="px-4 py-2 bg-white border border-slate-200 text-slate-500 rounded-xl text-xs font-black hover:bg-slate-50 transition-all shadow-sm">VIEW & VERIFY</button>
                      <button onClick={() => updateApproval(approval.id, 'approved')} className="bg-green-600 text-white px-5 py-2 rounded-xl text-xs font-black shadow-md hover:bg-green-700 transition-all active:scale-95">APPROVE</button>
                      <button onClick={() => updateApproval(approval.id, 'rejected')} className="bg-white border border-red-100 text-red-500 px-5 py-2 rounded-xl text-xs font-black hover:bg-red-50 transition-all">REJECT</button>
                   </div>
                 </div>
               );
             })}
             {pendingApprovals.length === 0 && (
               <div className="text-center py-16 border-2 border-dashed border-slate-100 rounded-3xl">
                 <ShieldCheck className="h-10 w-10 text-slate-200 mx-auto mb-3" />
                 <p className="text-slate-400 font-medium">No pending verification requests.</p>
               </div>
             )}
          </div>
        </section>
      )}

      {activeTab === 'companies' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
          <h3 className="text-lg font-bold mb-6">Approved Pharma Partners</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {approvedCompanies.map(comp => (
               <button 
                 key={comp.id}
                 onClick={() => setSelectedCompany(comp.id === selectedCompany?.id ? null : comp)}
                 className={`p-6 text-left rounded-3xl border transition-all ${selectedCompany?.id === comp.id ? 'bg-indigo-50 border-indigo-200 shadow-md ring-2 ring-indigo-100' : 'bg-slate-50 border-slate-100 hover:border-indigo-100'}`}
               >
                 <Briefcase className="h-6 w-6 text-indigo-500 mb-3" />
                 <h4 className="font-bold text-slate-800">{comp.name}</h4>
                 <div className="mt-2 space-y-1">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
                        {comp.companyCode}
                    </p>
                    <p className="text-[10px] font-bold text-indigo-600 uppercase">
                      {mrs.filter(m => m.companyName === comp.name && approvals.some(a => a.mrId === m.id && a.hospitalId === user.hospitalId && a.status === 'approved')).length} Active MRs Here
                    </p>
                 </div>
               </button>
            ))}
            {approvedCompanies.length === 0 && (
              <div className="col-span-full py-20 text-center border-2 border-dashed border-slate-100 rounded-3xl">
                <Briefcase className="h-10 w-10 text-slate-200 mx-auto mb-3" />
                <p className="text-slate-400 font-medium">No pharmaceutical partners verified yet.</p>
              </div>
            )}
          </div>

          {selectedCompany && (
            <div className="mt-8 animate-in slide-in-from-top duration-300">
               <div className="p-5 bg-white border border-slate-200 rounded-t-3xl shadow-sm">
                  <div className="flex justify-between items-start">
                    <div>
                      <h4 className="font-black text-xl text-slate-800">{selectedCompany.name}</h4>
                      <div className="mt-3 grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div className="flex items-center gap-2 text-xs text-slate-500">
                           <MapPin className="h-4 w-4 text-slate-400" />
                           {selectedCompany.address || 'Address not provided'}
                        </div>
                        <div className="flex items-center gap-2 text-xs text-slate-500">
                           <Phone className="h-4 w-4 text-slate-400" />
                           {selectedCompany.contactNumber || 'Contact not provided'}
                        </div>
                        <div className="flex items-center gap-2 text-xs text-indigo-600 font-bold">
                           <Mail className="h-4 w-4 text-indigo-400" />
                           {selectedCompany.contactEmail}
                        </div>
                      </div>
                    </div>
                    <button onClick={() => setSelectedCompany(null)} className="p-2 hover:bg-slate-100 rounded-xl transition-all"><X className="h-5 w-5 text-slate-400" /></button>
                  </div>
               </div>
               <div className="bg-slate-50 border border-t-0 border-slate-200 rounded-b-3xl overflow-hidden shadow-sm">
                  <div className="px-6 py-4 border-b border-slate-100 bg-white/50">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Authorized Representatives List</p>
                  </div>
                  <table className="w-full text-left text-xs">
                    <thead>
                      <tr className="bg-white border-b border-slate-100 text-slate-400 font-black uppercase tracking-widest text-[9px]">
                        <th className="px-6 py-4">Full Name</th>
                        <th className="px-6 py-4">Mobile</th>
                        <th className="px-6 py-4">Status</th>
                        <th className="px-6 py-4 text-right">Actions</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                       {mrs.filter(m => m.companyName === selectedCompany.name && approvals.some(a => a.mrId === m.id && a.hospitalId === user.hospitalId && a.status === 'approved')).map(mr => (
                         <tr key={mr.id} className="hover:bg-indigo-50/10 transition-colors">
                            <td className="px-6 py-4 font-bold text-slate-700">{mr.fullName}</td>
                            <td className="px-6 py-4 text-slate-500 font-mono tracking-tighter">{mr.mobileNumber}</td>
                            <td className="px-6 py-4">
                              <span className="bg-green-100 text-green-700 px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-widest">VERIFIED</span>
                            </td>
                            <td className="px-6 py-4 text-right">
                              <button onClick={() => viewMRProfile(mr.id)} className="text-indigo-600 font-black hover:bg-indigo-50 px-3 py-1.5 rounded-lg transition-all flex items-center gap-1.5 ml-auto">
                                <Eye className="h-3 w-3" /> PROFILE
                              </button>
                            </td>
                         </tr>
                       ))}
                    </tbody>
                  </table>
               </div>
            </div>
          )}
        </section>
      )}

      {activeTab === 'settings' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm max-w-2xl mx-auto">
          <div className="flex border-b border-slate-100 mb-8">
            <button onClick={() => setSettingsTab('profile')} className={`px-6 py-3 text-sm font-black transition-all border-b-2 ${settingsTab === 'profile' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400'}`}>HOSPITAL PROFILE</button>
            <button onClick={() => setSettingsTab('sessions')} className={`px-6 py-3 text-sm font-black transition-all border-b-2 ${settingsTab === 'sessions' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400'}`}>SESSION & AUTO-LOTTERY</button>
          </div>

          {editingHospital && (
            <div className="space-y-8 animate-in fade-in duration-300">
              {settingsTab === 'profile' ? (
                <div className="space-y-6">
                  <div className="space-y-4">
                    <div>
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Official Name</label>
                      <input type="text" value={editingHospital.name} readOnly className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold text-slate-500 cursor-not-allowed" />
                      <p className="text-[9px] text-slate-400 mt-1 italic">Name can only be changed by Super Admin.</p>
                    </div>
                    <div>
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Facility Address</label>
                      <textarea 
                        value={editingHospital.address || ''} 
                        onChange={(e) => setEditingHospital({...editingHospital, address: e.target.value})}
                        className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl font-bold focus:ring-2 focus:ring-indigo-500 outline-none h-24" 
                        placeholder="Hospital physical address"
                      />
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Public Email</label>
                        <input 
                          type="email" 
                          value={editingHospital.email || ''} 
                          onChange={(e) => setEditingHospital({...editingHospital, email: e.target.value})}
                          className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl font-bold focus:ring-2 focus:ring-indigo-500 outline-none" 
                        />
                      </div>
                      <div>
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Contact Mobile</label>
                        <input 
                          type="tel" 
                          value={editingHospital.mobileNumber || ''} 
                          onChange={(e) => setEditingHospital({...editingHospital, mobileNumber: e.target.value})}
                          className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl font-bold focus:ring-2 focus:ring-indigo-500 outline-none" 
                        />
                      </div>
                    </div>
                  </div>
                </div>
              ) : (
