                              <input disabled={!editingHospital.supportedSessions.includes(sess)} type="time" value={editingHospital.sessionWindows?.[sess]?.start || '00:00'} onChange={(e) => setEditingHospital({...editingHospital, sessionWindows: {...(editingHospital.sessionWindows || {}), [sess]: { ...(editingHospital.sessionWindows?.[sess] || {start:'00:00', end:'23:59'}), start: e.target.value }}})} className="w-full px-2 py-2 bg-slate-50 border border-slate-200 rounded-xl font-bold text-xs disabled:opacity-50" />
                            </div>
                            <div className="space-y-1">
                              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Window End</label>
                              <input disabled={!editingHospital.supportedSessions.includes(sess)} type="time" value={editingHospital.sessionWindows?.[sess]?.end || '23:59'} onChange={(e) => setEditingHospital({...editingHospital, sessionWindows: {...(editingHospital.sessionWindows || {}), [sess]: { ...(editingHospital.sessionWindows?.[sess] || {start:'00:00', end:'23:59'}), end: e.target.value }}})} className="w-full px-2 py-2 bg-slate-50 border border-slate-200 rounded-xl font-bold text-xs disabled:opacity-50" />
