                          value={editingHospital.email || ''} 
                          onChange={(e) => setEditingHospital({...editingHospital, email: e.target.value})}
                          className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl font-bold focus:ring-2 focus:ring-indigo-500 outline-none" 
                        />
                      </div>
                      <div>
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Contact Mobile</label>
                        <input 
                          type="tel" 
                          value={editingHospital.mobileNumber || ''} 
                          onChange={(e) => setEditingHospital({...editingHospital, mobileNumber: e.target.value})}
                          className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl font-bold focus:ring-2 focus:ring-indigo-500 outline-none" 
                        />
                      </div>
                    </div>
                  </div>
                </div>
              ) : (
                <div className="space-y-6">
                  {(['MORNING', 'EVENING', 'FULL_DAY'] as SessionType[]).map(sess => (
                    <div key={sess} className={`p-6 rounded-3xl border-2 transition-all ${editingHospital.supportedSessions.includes(sess) ? 'bg-white border-indigo-100 shadow-sm' : 'bg-slate-50 border-dashed border-slate-200 opacity-60'}`}>
                        <div className="flex items-center justify-between mb-4">
                          <div className="flex items-center gap-2">
                             {sess === 'MORNING' ? <Sun className="h-5 w-5 text-amber-500" /> : sess === 'EVENING' ? <Moon className="h-5 w-5 text-indigo-500" /> : <Maximize className="h-5 w-5 text-indigo-600" />}
                             <span className="font-black text-slate-800 uppercase tracking-widest">{sess.replace('_', ' ')}</span>
                          </div>
