                                     type="number" 
                                     value={editingHospital.passLimits?.[sess] || 0}
                                     onChange={(e) => setEditingHospital({...editingHospital, passLimits: {...(editingHospital.passLimits || {}), [sess]: parseInt(e.target.value) || 0 }})}
                                     className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl font-bold" 
                                   />
                                </div>
                                <div className="grid grid-cols-2 gap-2">
                                   <div>
                                      <label className="text-[10px] font-black text-slate-400 uppercase mb-1 block">Start</label>
                                      <input type="time" value={editingHospital.sessionWindows?.[sess]?.start || '08:00'} onChange={(e) => setEditingHospital({...editingHospital, sessionWindows: {...(editingHospital.sessionWindows || {}), [sess]: { ...(editingHospital.sessionWindows?.[sess] || {start:'08:00', end:'10:00'}), start: e.target.value }}})} className="w-full px-2 py-2 bg-slate-50 border border-slate-200 rounded-xl font-bold text-xs" />
                                   </div>
                                   <div>
                                      <label className="text-[10px] font-black text-slate-400 uppercase mb-1 block">End</label>
                                      <input type="time" value={editingHospital.sessionWindows?.[sess]?.end || '10:00'} onChange={(e) => setEditingHospital({...editingHospital, sessionWindows: {...(editingHospital.sessionWindows || {}), [sess]: { ...(editingHospital.sessionWindows?.[sess] || {start:'08:00', end:'10:00'}), end: e.target.value }}})} className="w-full px-2 py-2 bg-slate-50 border border-slate-200 rounded-xl font-bold text-xs" />
                                   </div>
                                </div>
                             </div>

                             <div className="pt-4 border-t border-slate-50 flex items-center justify-between">
                                <div className="flex items-center gap-2">
                                   <Zap className={`h-4 w-4 ${editingHospital.autoLotteryEnabled?.[sess] ? 'text-indigo-600' : 'text-slate-300'}`} />
                                   <span className="text-xs font-bold text-slate-700">Scheduled Auto-Spin</span>
                                </div>
                                <div className="flex items-center gap-3">
                                   {editingHospital.autoLotteryEnabled?.[sess] && (
                                     <div className="flex items-center gap-2 bg-indigo-50 px-3 py-1.5 rounded-xl border border-indigo-100 shadow-sm">
                                        <Timer className="h-3 w-3 text-indigo-400" />
                                        <input 
                                          type="time" 
                                          value={editingHospital.autoLotteryTimes?.[sess] || '18:00'} 
                                          onChange={(e) => setEditingHospital({...editingHospital, autoLotteryTimes: {...(editingHospital.autoLotteryTimes || {}), [sess]: e.target.value}})}
                                          className="bg-transparent border-none text-xs font-black text-indigo-800 p-0 focus:ring-0 w-16"
                                        />
                                     </div>
                                   )}
                                   <button 
                                      type="button"
                                      onClick={() => setEditingHospital({...editingHospital, autoLotteryEnabled: {...(editingHospital.autoLotteryEnabled || {}), [sess]: !editingHospital.autoLotteryEnabled?.[sess]}})}
                                      className={`px-3 py-1.5 rounded-lg text-[10px] font-black uppercase transition-all ${editingHospital.autoLotteryEnabled?.[sess] ? 'bg-green-600 text-white shadow-md' : 'bg-slate-200 text-slate-500'}`}
                                   >
                                      {editingHospital.autoLotteryEnabled?.[sess] ? 'ON' : 'OFF'}
                                   </button>
                                </div>
                             </div>
                          </div>
                        )}
                    </div>
                  ))}
                </div>
              )}
               <button onClick={handleSaveHospitalData} className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-xl hover:bg-indigo-700 active:scale-95 transition-all flex items-center justify-center gap-2">
                 <Save className="h-5 w-5" /> COMMIT ALL CHANGES
               </button>
            </div>
          )}
        </section>
      )}

      {/* Approvals tab and other UI elements remain unchanged but included for context if needed */}
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect, useContext } from 'react';
import { 
  Play, Sparkles, CheckCircle, Clock, UserPlus, Users, Settings, Save, X, 
  Sun, Moon, Maximize, User, MapPin, ShieldCheck, 
  Mail, Phone, Briefcase, CheckCircle2, Eye, 
  Zap, Timer
} from 'lucide-react';
import { storageService } from '../services/storageService';
import { lotteryService } from '../services/lotteryService';
import { MedicalRep, Hospital, PassApplication, IssuedPass, MRHospitalApproval, SessionType, PharmaCompany } from '../types';
import { getAdminBriefing } from '../services/geminiService';
import { FeedbackContext } from '../App';

interface AdminDashboardProps {
  user: {
    id: string;
    role: string;
    fullName: string;
    hospitalId: string;
  };
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [companies, setCompanies] = useState<PharmaCompany[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [activeTab, setActiveTab] = useState<'lottery' | 'approvals' | 'companies' | 'settings'>('lottery');
  const [settingsTab, setSettingsTab] = useState<'profile' | 'sessions'>('profile');
  const [brief, setBrief] = useState('');
  const [selectedMR, setSelectedMR] = useState<MedicalRep | null>(null);
  const [selectedCompany, setSelectedCompany] = useState<PharmaCompany | null>(null);

  const [editingHospital, setEditingHospital] = useState<Hospital | null>(null);

  useEffect(() => { 
    refreshData(); 
    const refreshInterval = setInterval(refreshData, 30000);
    return () => clearInterval(refreshInterval);
  }, []);

  const refreshData = async () => {
    const allHospitals = storageService.getHospitals();
    const currentHosp = allHospitals.find(h => h.id === user.hospitalId) || (allHospitals.length > 0 ? allHospitals[0] : null);

    setMrs(storageService.getMRs()); 
    setHospitals(allHospitals);
    setCompanies(storageService.getCompanies());
    setApps(storageService.getApplications()); 
    setPasses(storageService.getPasses());
    setApprovals(storageService.getApprovals());

    // Only set initial editing state once or if user has no pending changes
    if (currentHosp && !editingHospital) {
      setEditingHospital({
        ...currentHosp,
        autoLotteryEnabled: currentHosp.autoLotteryEnabled || {},
        autoLotteryTimes: currentHosp.autoLotteryTimes || {},
        passLimits: currentHosp.passLimits || {},
        sessionWindows: currentHosp.sessionWindows || {}
      });
    }

    try {
      const summary = await getAdminBriefing(storageService.getApplications(), storageService.getPasses());
      setBrief(summary);
    } catch (e) {
      console.error("Briefing failed", e);
    }
  };

  const handleManualLottery = (session: SessionType) => {
    const result = lotteryService.runLottery(user.hospitalId, session);
    if (result.success) {
      showFeedback(result.message, 'success');
      refreshData();
    } else {
      showFeedback(result.message, 'error');
    }
  };

  const handleSaveHospitalData = () => {
    if (!editingHospital) return;
    const allHospitals = storageService.getHospitals();
    const updated = allHospitals.map(h => h.id === editingHospital.id ? editingHospital : h);
    storageService.saveHospitals(updated);
    setHospitals(updated);
    showFeedback("System configuration saved successfully.", "success");
  };

  const currentHospital = hospitals.find(h => h.id === user.hospitalId);

  if (!currentHospital) return null;

  const pendingApprovals = approvals.filter(a => a.hospitalId === user.hospitalId && a.status === 'pending');
  const approvedMRs = mrs.filter(mr => 
    approvals.some(apprv => apprv.hospitalId === user.hospitalId && apprv.mrId === mr.id && apprv.status === 'approved')
  );
  const approvedCompanies = companies.filter(c => Array.from(new Set(approvedMRs.map(mr => mr.companyName))).includes(c.name));

  const updateSessionSetting = (sess: SessionType, field: keyof Hospital, value: any) => {
    if (!editingHospital) return;
    setEditingHospital({
      ...editingHospital,
      [field]: {
        ...(editingHospital[field] as any || {}),
        [sess]: value
      }
    });
  };

  const toggleSupportedSession = (sess: SessionType) => {
    if (!editingHospital) return;
    const isSupported = editingHospital.supportedSessions.includes(sess);
    const newSupported = isSupported 
      ? editingHospital.supportedSessions.filter(s => s !== sess)
      : [...editingHospital.supportedSessions, sess];

    // Auto-disable lottery if session is removed
    const newAutoEnabled = { ...(editingHospital.autoLotteryEnabled || {}) };
    if (isSupported) newAutoEnabled[sess] = false;

    setEditingHospital({
      ...editingHospital,
      supportedSessions: newSupported,
      autoLotteryEnabled: newAutoEnabled
    });
  };

  const toggleAutoLottery = (sess: SessionType) => {
    if (!editingHospital) return;
    const currentVal = editingHospital.autoLotteryEnabled?.[sess] || false;
    updateSessionSetting(sess, 'autoLotteryEnabled', !currentVal);
