                     >
                       {selectedCount > 0 ? <CheckCircle2 className="h-5 w-5" /> : <Play className="h-5 w-5" />}
                       {selectedCount > 0 ? 'LOTTERY FINISHED' : 'MANUAL SPIN NOW'}
                     </button>
                   </div>
                 );
              })}
            </div>
          </div>
        </section>
      )}

      {activeTab === 'settings' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm max-w-2xl mx-auto">
          <div className="flex border-b border-slate-100 mb-8">
            <button onClick={() => setSettingsTab('profile')} className={`px-6 py-3 text-sm font-black transition-all border-b-2 ${settingsTab === 'profile' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400'}`}>FACILITY PROFILE</button>
            <button onClick={() => setSettingsTab('sessions')} className={`px-6 py-3 text-sm font-black transition-all border-b-2 ${settingsTab === 'sessions' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400'}`}>SESSIONS & AUTO-SPIN</button>
          </div>

          <div className="space-y-8 animate-in fade-in duration-300">
            {settingsTab === 'profile' ? (
