                  <div className="p-3 bg-slate-50 rounded-xl border border-slate-100"><p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">System ID</p><p className="font-bold text-slate-700 font-mono text-xs">{selectedMR.mrId}</p></div>
                  <div className="p-3 bg-slate-50 rounded-xl border border-slate-100"><p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Mobile</p><p className="font-bold text-slate-700 text-sm">{selectedMR.mobileNumber}</p></div>
                  <div className="p-3 bg-slate-50 rounded-xl border border-slate-100"><p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">SLCPI Expiry</p><p className="font-bold text-slate-700 text-sm">{selectedMR.slcpiExpiry || 'N/A'}</p></div>
               </div>

               {selectedMR.slcpiPhoto && (
                 <div className="rounded-2xl overflow-hidden border border-slate-200 mt-4 bg-slate-50 p-2 shadow-inner">
                   <img src={selectedMR.slcpiPhoto} className="w-full object-contain max-h-48 rounded-xl" alt="ID Document" />
                 </div>
               )}

               <button onClick={() => setSelectedMR(null)} className="w-full bg-slate-800 text-white font-black py-4 rounded-2xl shadow-xl hover:bg-slate-900 transition-all uppercase tracking-widest text-xs">CLOSE PROFILE</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect, useContext } from 'react';
import { 
  Calendar, Clock, QrCode, AlertCircle, CheckCircle2, Info, Building2, 
  PlusCircle, Sun, Moon, Maximize, Search, Send, CheckCircle, 
  UserCircle, Briefcase, Phone, CreditCard, ShieldCheck, 
  Image as ImageIcon, History, ChevronRight, MapPin, XCircle
} from 'lucide-react';
import { storageService } from '../services/storageService';
import { MedicalRep, PassApplication, IssuedPass, Hospital, MRHospitalApproval, SessionType } from '../types';
import { getPriorityInsights } from '../services/geminiService';
import { FeedbackContext } from '../App';

interface MRDashboardProps {
  user: MedicalRep;
}

const MRDashboard: React.FC<MRDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [loading, setLoading] = useState(false);
  const [aiInsight, setAiInsight] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'passes' | 'directory' | 'profile'>('passes');
  const [passSubTab, setPassSubTab] = useState<'live' | 'history'>('live');
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => { refreshData(); }, []);

  const refreshData = async () => {
    const h = storageService.getHospitals();
    const apprvs = storageService.getApprovals();
    const a = storageService.getApplications().filter(ap => ap.mrId === user.id);
    const p = storageService.getPasses().filter(ps => ps.mrId === user.id);
    setHospitals(h); setApprovals(apprvs); setApps(a); setPasses(p);
    const insight = await getPriorityInsights(a.slice(-3).map(app => ({ date: app.applicationDate, status: app.status })));
    setAiInsight(insight);
  };

  const isSessionWindowOpen = (h: Hospital, session: SessionType) => {
    const window = h.sessionWindows?.[session];
    if (!window) return false;

    const now = new Date();
    const time = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
    return time >= window.start && time <= window.end;
  };

  const checkEligibility = (hospitalId: string, session: SessionType) => {
    const today = new Date();
    const recentPasses = passes.filter(p => p.hospitalId === hospitalId && p.entryStatus !== 'expired');

    for (const p of recentPasses) {
      const passDate = new Date(p.passDate);
      const diff = Math.floor((today.getTime() - passDate.getTime()) / (1000 * 3600 * 24));
      if (diff < 3) {
        if (p.session === 'FULL_DAY') return { eligible: false, reason: "Full Day pass blocks all applications for 3 days." };
        if (p.session === session) return { eligible: false, reason: `You already had a ${session} pass within the last 3 days.` };
      }
    }
    return { eligible: true };
  };

  const handleApply = async (hospitalId: string, session: SessionType) => {
    const { eligible, reason } = checkEligibility(hospitalId, session);
    if (!eligible) { showFeedback(reason || "Ineligible", 'error'); return; }

    const todayStr = new Date().toISOString().split('T')[0];
    if (apps.some(a => a.hospitalId === hospitalId && a.applicationDate === todayStr && a.session === session)) {
      showFeedback("Application already submitted for this session today.", 'error'); return;
    }

    setLoading(true);
    const newApp: PassApplication = {
      id: Math.random().toString(36).substr(2, 9),
      mrId: user.id, hospitalId, session,
      applicationDate: todayStr, priorityScore: 0, status: 'applied',
      createdAt: new Date().toISOString()
    };
    storageService.saveApplications([...storageService.getApplications(), newApp]);
    setTimeout(() => { 
      refreshData(); 
      setLoading(false); 
      showFeedback("Pass application submitted successfully!");
    }, 600);
  };

  const requestApproval = (hospitalId: string) => {
    const existing = approvals.find(a => a.mrId === user.id && a.hospitalId === hospitalId);
    if (existing && existing.status !== 'rejected') return;

    const newApproval: MRHospitalApproval = {
      id: 'apprv-' + Math.random().toString(36).substr(2, 9),
      mrId: user.id,
      hospitalId,
      status: 'pending',
      updatedAt: new Date().toISOString()
    };

    const updated = existing 
      ? approvals.map(a => a.id === existing.id ? newApproval : a)
      : [...approvals, newApproval];

    storageService.saveApprovals(updated);
    refreshData();
    showFeedback("Access request sent to hospital admin.");
  };

  // Grouping logic for History
  const historyPasses = passes.filter(p => p.entryStatus !== 'not_entered' || new Date(p.passDate) < new Date(new Date().setHours(0,0,0,0)));
  const sortedHistory = [...historyPasses].sort((a, b) => new Date(b.passDate).getTime() - new Date(a.passDate).getTime());

  const groupedPasses = sortedHistory.reduce((groups, pass) => {
    const date = pass.passDate;
    if (!groups[date]) groups[date] = [];
    groups[date].push(pass);
    return groups;
  }, {} as Record<string, IssuedPass[]>);

  const approvedHospitals = hospitals.filter(h => 
    approvals.some(a => a.mrId === user.id && a.hospitalId === h.id && a.status === 'approved')
  );

  const availableHospitals = hospitals.filter(h => h.isActive && 
    !approvals.some(a => a.mrId === user.id && a.hospitalId === h.id && a.status === 'approved')
  ).filter(h => h.name.toLowerCase().includes(searchTerm.toLowerCase()));

  return (
    <div className="space-y-6">
      {/* Primary Tabs */}
      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('passes')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'passes' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><QrCode className="h-4 w-4" /> My Passes</button>
        <button onClick={() => setActiveTab('directory')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'directory' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Building2 className="h-4 w-4" /> Directory</button>
        <button onClick={() => setActiveTab('profile')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 whitespace-nowrap transition-all ${activeTab === 'profile' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><UserCircle className="h-4 w-4" /> My Profile</button>
      </div>

      {activeTab !== 'profile' && (
        <div className="bg-indigo-50 border border-indigo-100 p-4 rounded-xl flex items-start gap-3 shadow-sm animate-in slide-in-from-top-2">
          <Info className="h-5 w-5 text-indigo-500 mt-0.5" />
          <p className="text-sm text-indigo-800 leading-relaxed font-medium">{aiInsight || "Analyzing your profile and calculating your ranking factors..."}</p>
        </div>
      )}

      {activeTab === 'passes' && (
        <div className="space-y-6">
          {/* Sub-Tabs for Passes */}
          <div className="flex gap-4 border-b border-slate-100">
            <button 
              onClick={() => setPassSubTab('live')} 
              className={`pb-3 text-xs font-black uppercase tracking-widest transition-all relative ${passSubTab === 'live' ? 'text-indigo-600' : 'text-slate-400'}`}
            >
              Live Passes
              {passSubTab === 'live' && <div className="absolute bottom-0 left-0 w-full h-1 bg-indigo-600 rounded-t-full" />}
            </button>
            <button 
              onClick={() => setPassSubTab('history')} 
              className={`pb-3 text-xs font-black uppercase tracking-widest transition-all relative ${passSubTab === 'history' ? 'text-indigo-600' : 'text-slate-400'}`}
            >
              Pass History
              {passSubTab === 'history' && <div className="absolute bottom-0 left-0 w-full h-1 bg-indigo-600 rounded-t-full" />}
            </button>
          </div>

          {passSubTab === 'live' ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 animate-in fade-in duration-300">
              <section className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 md:col-span-2">
                <h3 className="text-lg font-bold mb-6 flex items-center gap-2 text-slate-800">
                  <Building2 className="h-5 w-5 text-indigo-500" /> Authorized Hospitals
                </h3>
                <div className="grid gap-6 sm:grid-cols-2">
                  {approvedHospitals.map(h => (
                    <div key={h.id} className="p-5 bg-slate-50 rounded-2xl border border-slate-100 hover:shadow-md transition-shadow group">
                      <div className="mb-4">
                        <p className="font-bold text-slate-800 text-lg group-hover:text-indigo-600 transition-colors">{h.name}</p>
                      </div>
                      <div className="space-y-3">
                        {h.supportedSessions.map(sess => {
                          const open = isSessionWindowOpen(h, sess);
                          const window = h.sessionWindows?.[sess];
                          return (
                            <div key={sess} className="space-y-1">
                              <button
                                disabled={!open || loading}
                                onClick={() => handleApply(h.id, sess)}
                                className={`w-full py-3 px-4 rounded-xl text-xs font-black flex items-center justify-between transition-all group/btn ${
                                  open 
                                    ? 'bg-white border-2 border-indigo-100 hover:border-indigo-400 text-indigo-700 shadow-sm active:scale-95' 
                                    : 'bg-slate-200/50 text-slate-400 cursor-not-allowed grayscale'
                                }`}
                              >
                                <span className="flex items-center gap-2">
                                  {sess === 'MORNING' ? <Sun className="h-4 w-4" /> : sess === 'EVENING' ? <Moon className="h-4 w-4" /> : <Maximize className="h-4 w-4" />}
                                  {sess}
                                </span>
                                <span className="flex items-center gap-1">
                                  {open ? 'APPLY NOW' : 'CLOSED'}
                                  {open && <PlusCircle className="h-3 w-3 group-hover/btn:scale-125 transition-transform" />}
                                </span>
                              </button>
                              <div className="flex justify-between px-1 text-[9px] font-bold text-slate-400">
                                <span className="uppercase tracking-tighter">Window: {window?.start} - {window?.end}</span>
                                {open && <span className="text-green-500 animate-pulse">LIVE</span>}
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  ))}
                  {approvedHospitals.length === 0 && (
                    <div className="sm:col-span-2 p-12 text-center bg-slate-50 border-2 border-dashed border-slate-200 rounded-3xl">
                      <Building2 className="h-8 w-8 text-slate-300 mx-auto mb-4 opacity-30" />
                      <p className="text-sm font-medium text-slate-500">No hospital access yet.</p>
                      <button onClick={() => setActiveTab('directory')} className="text-xs text-indigo-600 font-bold mt-2 hover:underline underline-offset-4 tracking-tight">Browse Hospital Directory →</button>
                    </div>
                  )}
                </div>
              </section>

              <section className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
                <h3 className="text-lg font-bold mb-6 flex items-center gap-2 text-slate-800">
                  <QrCode className="h-5 w-5 text-indigo-500" /> Active Today
                </h3>
                <div className="space-y-4">
                  {passes.filter(p => p.entryStatus === 'not_entered' && p.passDate === new Date().toISOString().split('T')[0]).map(p => (
                    <div key={p.id} className="p-4 bg-indigo-50 border-2 border-indigo-100 rounded-2xl shadow-sm hover:shadow-md transition-shadow">
                      <div className="flex justify-between items-center mb-3">
                         <div className="flex items-center gap-1.5">
                          {p.session === 'MORNING' ? <Sun className="h-3 w-3 text-amber-500" /> : p.session === 'EVENING' ? <Moon className="h-3 w-3 text-indigo-400" /> : <Maximize className="h-3 w-3 text-indigo-500" />}
                          <span className="text-[10px] font-black uppercase text-indigo-600 tracking-widest">{p.session}</span>
                         </div>
                        <span className="text-[10px] font-bold text-slate-400 bg-white px-2 py-0.5 rounded shadow-xs">{p.passDate}</span>
                      </div>
                      <p className="font-bold text-slate-800 text-sm mb-4 leading-tight">{hospitals.find(h => h.id === p.hospitalId)?.name}</p>
                      <div className="bg-white p-4 rounded-xl border border-indigo-100 flex justify-center shadow-inner group">
                        <QrCode className="h-24 w-24 text-indigo-900 group-hover:scale-105 transition-transform duration-300" />
                      </div>
                    </div>
                  ))}
                  {passes.filter(p => p.entryStatus === 'not_entered' && p.passDate === new Date().toISOString().split('T')[0]).length === 0 && (
                    <div className="text-center py-12 text-slate-400 border-2 border-dashed border-slate-100 rounded-2xl">
                      <p className="text-xs italic">No active passes for today.</p>
                      <p className="text-[10px] mt-1">Select a session on the left to apply.</p>
                    </div>
                  )}
                </div>
              </section>
            </div>
          ) : (
            <div className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm animate-in fade-in duration-300">
              <div className="flex items-center gap-3 mb-8 pb-4 border-b border-slate-50">
                <History className="h-6 w-6 text-indigo-500" />
                <div>
                  <h3 className="text-xl font-bold text-slate-800">Historical Pass Registry</h3>
                  <p className="text-xs text-slate-400 font-medium">Grouped chronological activity of all past hospital selections.</p>
                </div>
              </div>

              <div className="space-y-12">
                {Object.keys(groupedPasses).length > 0 ? Object.entries(groupedPasses).map(([date, datePasses]) => (
                  <div key={date} className="relative">
                    <div className="absolute left-4 top-8 bottom-0 w-0.5 bg-slate-100 -z-10" />
                    <div className="flex items-center gap-4 mb-6">
                      <div className="w-8 h-8 rounded-full bg-indigo-600 border-4 border-indigo-100 flex items-center justify-center shrink-0">
                        <Calendar className="h-3 w-3 text-white" />
                      </div>
                      <h4 className="text-sm font-black text-slate-700 tracking-wider uppercase">{new Date(date).toLocaleDateString(undefined, { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</h4>
                    </div>

                    <div className="ml-12 space-y-4">
                      {datePasses.map(p => (
                        <div key={p.id} className="bg-slate-50 border border-slate-100 p-5 rounded-2xl flex flex-col sm:flex-row sm:items-center justify-between gap-4 group hover:bg-white hover:shadow-md hover:border-indigo-100 transition-all">
                          <div className="flex items-start gap-4">
                             <div className="p-3 bg-white rounded-xl shadow-sm border border-slate-100">
                                {p.session === 'MORNING' ? <Sun className="h-5 w-5 text-amber-500" /> : p.session === 'EVENING' ? <Moon className="h-5 w-5 text-indigo-400" /> : <Maximize className="h-5 w-5 text-indigo-600" />}
                             </div>
                             <div>
                                <h5 className="font-bold text-slate-800 group-hover:text-indigo-600 transition-colors">{hospitals.find(h => h.id === p.hospitalId)?.name}</h5>
                                <div className="flex items-center gap-2 mt-1">
                                   <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{p.session} SESSION</span>
                                   <span className="text-[10px] font-black text-slate-400">•</span>
                                   <span className="text-[10px] font-bold text-indigo-500">{p.timeSlot}</span>
                                </div>
                             </div>
                          </div>

                          <div className="flex items-center justify-between sm:justify-end gap-3 px-1">
                             <span className="font-mono text-[10px] font-bold text-slate-400 bg-white px-2 py-1 rounded border border-slate-100">{p.id}</span>
                             {p.entryStatus === 'entered' ? (
                               <div className="flex items-center gap-1.5 px-3 py-1.5 bg-green-100 text-green-700 rounded-lg text-[10px] font-black uppercase tracking-widest">
                                  <CheckCircle className="h-3.5 w-3.5" /> VISITED
                               </div>
                             ) : (
                               <div className="flex items-center gap-1.5 px-3 py-1.5 bg-slate-200 text-slate-500 rounded-lg text-[10px] font-black uppercase tracking-widest">
                                  <XCircle className="h-3.5 w-3.5" /> NO SHOW / EXPIRED
                               </div>
                             )}
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )) : (
                  <div className="text-center py-24 bg-slate-50 rounded-3xl border-2 border-dashed border-slate-100">
                     <History className="h-12 w-12 text-slate-200 mx-auto mb-4 opacity-30" />
                     <p className="text-sm font-bold text-slate-400">Your pass history is currently empty.</p>
                     <p className="text-xs text-slate-300 mt-1">Completed hospital visits will appear here as a chronological timeline.</p>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      )}

      {activeTab === 'directory' && (
        <section className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 animate-in fade-in duration-300">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
            <h3 className="text-lg font-bold flex items-center gap-2 text-slate-800">
              <Search className="h-5 w-5 text-indigo-500" /> Hospital Directory
            </h3>
            <div className="relative max-w-md w-full">
              <input 
                type="text" 
                placeholder="Search hospitals..." 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all font-medium"
              />
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
            </div>
          </div>

          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {availableHospitals.map(h => {
              const approval = approvals.find(a => a.mrId === user.id && a.hospitalId === h.id);
              const isPending = approval?.status === 'pending';
              const isRejected = approval?.status === 'rejected';

              return (
                <div key={h.id} className="p-5 border border-slate-100 bg-slate-50 rounded-2xl flex flex-col justify-between group hover:border-indigo-200 transition-colors">
                  <div>
                    <h4 className="font-bold text-slate-800 group-hover:text-indigo-600 transition-colors">{h.name}</h4>
                    <p className="text-[10px] text-slate-400 uppercase font-black tracking-widest mt-1">
                      {h.supportedSessions.join(' • ')}
                    </p>
                  </div>

                  <div className="mt-6">
                    {isPending ? (
                      <div className="w-full py-2.5 px-4 bg-amber-50 text-amber-600 rounded-xl text-xs font-bold flex items-center justify-center gap-2 border border-amber-100">
                        <Clock className="h-4 w-4" /> Request Pending
                      </div>
                    ) : isRejected ? (
                      <button 
                        onClick={() => requestApproval(h.id)}
                        className="w-full py-2.5 px-4 bg-white border border-red-200 text-red-600 rounded-xl text-xs font-bold hover:bg-red-50 transition-all flex items-center justify-center gap-2 shadow-sm"
                      >
                        <AlertCircle className="h-4 w-4" /> Try Again
                      </button>
                    ) : (
                      <button 
                        onClick={() => requestApproval(h.id)}
                        className="w-full py-2.5 px-4 bg-indigo-600 text-white rounded-xl text-xs font-bold hover:bg-indigo-700 transition-all flex items-center justify-center gap-2 shadow-md active:scale-95"
                      >
                        <Send className="h-4 w-4" /> Request Authorization
                      </button>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </section>
      )}

      {activeTab === 'profile' && (
        <section className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100 max-w-3xl mx-auto animate-in zoom-in duration-300">
          <div className="text-center mb-8">
            <div className="w-24 h-24 bg-indigo-100 rounded-full flex items-center justify-center mx-auto mb-4 border-4 border-white shadow-md">
              <UserCircle className="h-14 w-14 text-indigo-600" />
            </div>
            <h3 className="text-2xl font-black text-slate-800 tracking-tight">{user.fullName}</h3>
            <p className="text-indigo-600 font-bold text-xs tracking-widest uppercase mt-1">{user.companyName}</p>
          </div>

          <div className="grid gap-4 sm:grid-cols-2">
            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
              <div className="flex items-center gap-3 text-slate-400 mb-1">
                <ShieldCheck className="h-4 w-4" />
                <span className="text-[10px] font-black uppercase tracking-widest">Login Alias</span>
              </div>
              <p className="font-bold text-slate-800">{user.loginId || 'N/A'}</p>
            </div>

            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
              <div className="flex items-center gap-3 text-slate-400 mb-1">
                <Briefcase className="h-4 w-4" />
                <span className="text-[10px] font-black uppercase tracking-widest">Official MR ID</span>
              </div>
              <p className="font-bold text-slate-800">{user.mrId}</p>
            </div>

            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
              <div className="flex items-center gap-3 text-slate-400 mb-1">
                <Phone className="h-4 w-4" />
                <span className="text-[10px] font-black uppercase tracking-widest">Verified Phone</span>
              </div>
              <p className="font-bold text-slate-800">{user.mobileNumber}</p>
            </div>

            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
              <div className="flex items-center gap-3 text-slate-400 mb-1">
                <CreditCard className="h-4 w-4" />
                <span className="text-[10px] font-black uppercase tracking-widest">National Identity</span>
              </div>
              <p className="font-bold text-slate-800">{user.identificationNumber}</p>
            </div>
          </div>

          {user.slcpiPhoto && (
            <div className="mt-8 space-y-3">
              <div className="flex items-center gap-2">
                <ImageIcon className="h-4 w-4 text-indigo-500" />
                <h5 className="text-[10px] font-black uppercase tracking-widest text-slate-400">Verification Credentials</h5>
              </div>
              <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100 flex items-center justify-center group relative cursor-zoom-in">
                <img src={user.slcpiPhoto} alt="SLCPI Photo" className="max-h-64 rounded-lg shadow-sm object-contain group-hover:scale-[1.02] transition-transform duration-300" />
                <div className="absolute inset-0 bg-indigo-600/0 group-hover:bg-indigo-600/5 transition-colors rounded-2xl" />
              </div>
            </div>
          )}

          <div className="mt-8 pt-8 border-t border-slate-100 text-center">
            <p className="text-[10px] font-black uppercase text-slate-300 tracking-widest">Member Since {new Date(user.createdAt).getFullYear()}</p>
          </div>
        </section>
      )}
    </div>
  );
};

