          <div className="grid gap-4 sm:grid-cols-2">
            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
              <div className="flex items-center gap-3 text-slate-400 mb-1">
                <ShieldCheck className="h-4 w-4" />
                <span className="text-[10px] font-black uppercase tracking-widest">Login Alias</span>
              </div>
              <p className="font-bold text-slate-800">{user.loginId || 'N/A'}</p>
            </div>

            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
              <div className="flex items-center gap-3 text-slate-400 mb-1">
                <Briefcase className="h-4 w-4" />
                <span className="text-[10px] font-black uppercase tracking-widest">Official MR ID</span>
              </div>
              <p className="font-bold text-slate-800">{user.mrId}</p>
            </div>

            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
              <div className="flex items-center gap-3 text-slate-400 mb-1">
                <Phone className="h-4 w-4" />
                <span className="text-[10px] font-black uppercase tracking-widest">Verified Phone</span>
              </div>
              <p className="font-bold text-slate-800">{user.mobileNumber}</p>
            </div>

            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
              <div className="flex items-center gap-3 text-slate-400 mb-1">
                <CreditCard className="h-4 w-4" />
                <span className="text-[10px] font-black uppercase tracking-widest">National Identity</span>
              </div>
              <p className="font-bold text-slate-800">{user.identificationNumber}</p>
            </div>
          </div>

          {user.slcpiPhoto && (
            <div className="mt-8 space-y-3">
              <div className="flex items-center gap-2">
                <ImageIcon className="h-4 w-4 text-indigo-500" />
                <h5 className="text-[10px] font-black uppercase tracking-widest text-slate-400">Verification Credentials</h5>
              </div>
              <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100 flex items-center justify-center group relative cursor-zoom-in">
                <img src={user.slcpiPhoto} alt="SLCPI Photo" className="max-h-64 rounded-lg shadow-sm object-contain group-hover:scale-[1.02] transition-transform duration-300" />
                <div className="absolute inset-0 bg-indigo-600/0 group-hover:bg-indigo-600/5 transition-colors rounded-2xl" />
              </div>
            </div>
          )}

          <div className="mt-8 pt-8 border-t border-slate-100 text-center">
            <p className="text-[10px] font-black uppercase text-slate-300 tracking-widest">Member Since {new Date(user.createdAt).getFullYear()}</p>
          </div>
        </section>
      )}
    </div>
  );
};

export default MRDashboard;

import React, { useState, useEffect, useContext, useCallback } from 'react';
import { 
  Play, Sparkles, CheckCircle, Clock, UserPlus, Users, Settings, Save, X, 
  Sun, Moon, Maximize, User, MapPin, ShieldCheck, 
  Mail, Phone, Briefcase, CheckCircle2, Eye, 
  Zap, Timer, HelpCircle, EyeOff, AlertTriangle, History, Search, Filter, Calendar
} from 'lucide-react';
import { storageService } from '../services/storageService';
import { lotteryService } from '../services/lotteryService';
import { MedicalRep, Hospital, PassApplication, IssuedPass, MRHospitalApproval, SessionType, PharmaCompany, EntryLog } from '../types';
import { getAdminBriefing } from '../services/geminiService';
import { FeedbackContext } from '../App';

interface AdminDashboardProps {
  user: {
    id: string;
    role: string;
    fullName: string;
    hospitalId: string;
  };
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ user }) => {
  const { showFeedback } = useContext(FeedbackContext);
  const [mrs, setMrs] = useState<MedicalRep[]>([]);
  const [hospitals, setHospitals] = useState<Hospital[]>([]);
  const [companies, setCompanies] = useState<PharmaCompany[]>([]);
  const [apps, setApps] = useState<PassApplication[]>([]);
  const [passes, setPasses] = useState<IssuedPass[]>([]);
  const [logs, setLogs] = useState<EntryLog[]>([]);
  const [approvals, setApprovals] = useState<MRHospitalApproval[]>([]);
  const [activeTab, setActiveTab] = useState<'lottery' | 'history' | 'approvals' | 'companies' | 'settings'>('lottery');
  const [settingsTab, setSettingsTab] = useState<'profile' | 'sessions'>('profile');
  const [brief, setBrief] = useState('');
  const [selectedMR, setSelectedMR] = useState<MedicalRep | null>(null);
  const [showHowItWorks, setShowHowItWorks] = useState(false);

  // History Filters
  const [historySearch, setHistorySearch] = useState('');
  const [historySessionFilter, setHistorySessionFilter] = useState<SessionType | 'ALL'>('ALL');

  const [editingHospital, setEditingHospital] = useState<Hospital | null>(null);

  const refreshData = useCallback(async () => {
    const allHospitals = storageService.getHospitals();
    const currentHosp = allHospitals.find(h => h.id === user.hospitalId);

    setHospitals(allHospitals);
    setMrs(storageService.getMRs()); 
    setCompanies(storageService.getCompanies());
    setApps(storageService.getApplications()); 
    setPasses(storageService.getPasses());
    setLogs(storageService.getLogs());
    setApprovals(storageService.getApprovals());

    if (currentHosp && !editingHospital) {
      setEditingHospital({
        ...currentHosp,
        autoLotteryEnabled: currentHosp.autoLotteryEnabled || {},
        autoLotteryTimes: currentHosp.autoLotteryTimes || {},
        passLimits: currentHosp.passLimits || {},
        sessionWindows: currentHosp.sessionWindows || {},
        supportedSessions: currentHosp.supportedSessions || []
      });
    }

    try {
      const summary = await getAdminBriefing(storageService.getApplications(), storageService.getPasses());
      setBrief(summary);
    } catch (e) {
      console.error("Briefing failed", e);
    }
  }, [user.hospitalId, editingHospital]);

  useEffect(() => { 
    refreshData(); 
    const interval = setInterval(refreshData, 30000);
    return () => clearInterval(interval);
  }, [refreshData]);

  const handleManualLottery = (session: SessionType) => {
    const result = lotteryService.runLottery(user.hospitalId, session);
    if (result.success) {
      showFeedback(result.message, 'success');
      refreshData();
    } else {
      showFeedback(result.message, 'error');
    }
  };

  const handleSaveHospitalData = () => {
    if (!editingHospital) return;
    const allHospitals = storageService.getHospitals();
    const updated = allHospitals.map(h => h.id === editingHospital.id ? editingHospital : h);
    storageService.saveHospitals(updated);
    setHospitals(updated);
    showFeedback("System settings saved successfully.", "success");
  };

  const updateSessionSetting = (sess: SessionType, field: keyof Hospital, value: any) => {
    setEditingHospital(prev => {
      if (!prev) return null;
      const currentFieldData = (prev[field] as any) || {};
      return { ...prev, [field]: { ...currentFieldData, [sess]: value } };
    });
  };

  const toggleSupportedSession = (sess: SessionType) => {
    setEditingHospital(prev => {
      if (!prev) return null;
      const isSupported = prev.supportedSessions.includes(sess);
      const newSupported = isSupported 
        ? prev.supportedSessions.filter(s => s !== sess)
        : [...prev.supportedSessions, sess];

      const newAutoEnabled = { ...(prev.autoLotteryEnabled || {}) };
      if (isSupported) newAutoEnabled[sess] = false;

      return { ...prev, supportedSessions: newSupported, autoLotteryEnabled: newAutoEnabled };
    });
  };

  const handleUpdateApproval = (id: string, status: 'approved' | 'rejected') => {
    const allApprovals = storageService.getApprovals();
    const updated = allApprovals.map(a => a.id === id ? { ...a, status, updatedAt: new Date().toISOString() } : a);
    storageService.saveApprovals(updated);
    setApprovals(updated);
    showFeedback(`MR Access Request ${status === 'approved' ? 'Authorized' : 'Rejected'}.`);
  };

  const currentHospital = hospitals.find(h => h.id === user.hospitalId);

  if (!currentHospital || !editingHospital) return (
    <div className="flex items-center justify-center p-20 text-slate-400 font-bold">
      Loading Facility Configuration...
    </div>
  );

  const pendingApprovals = approvals.filter(a => a.hospitalId === user.hospitalId && a.status === 'pending');
  const approvedMRs = mrs.filter(mr => approvals.some(a => a.mrId === mr.id && a.hospitalId === user.hospitalId && a.status === 'approved'));

  // Filtering Logic for History
  const filteredPasses = passes
    .filter(p => p.hospitalId === user.hospitalId)
    .filter(p => {
      const mr = mrs.find(m => m.id === p.mrId);
      const matchesSearch = mr?.fullName.toLowerCase().includes(historySearch.toLowerCase()) || p.id.toLowerCase().includes(historySearch.toLowerCase());
      const matchesSession = historySessionFilter === 'ALL' || p.session === historySessionFilter;
      return matchesSearch && matchesSession;
    })
    .sort((a, b) => new Date(b.passDate).getTime() - new Date(a.passDate).getTime());

  return (
    <div className="space-y-6">
      <div className="bg-indigo-600 rounded-3xl p-6 text-white shadow-lg flex items-center gap-4 border border-indigo-400/30">
        <Sparkles className="h-6 w-6 text-indigo-200 shrink-0" />
        <p className="text-sm font-medium leading-relaxed">{brief || "Analyzing booking patterns and priority scoring..."}</p>
      </div>

      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('lottery')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'lottery' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Play className="h-4 w-4" /> Lottery</button>
        <button onClick={() => setActiveTab('history')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'history' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><History className="h-4 w-4" /> Records</button>
        <button onClick={() => setActiveTab('approvals')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all relative ${activeTab === 'approvals' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}>
          <UserPlus className="h-4 w-4" /> Requests
          {pendingApprovals.length > 0 && <span className="absolute -top-1 -right-1 flex h-4 w-4 items-center justify-center rounded-full bg-red-500 text-[8px] text-white ring-2 ring-white">{pendingApprovals.length}</span>}
        </button>
        <button onClick={() => setActiveTab('companies')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'companies' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Briefcase className="h-4 w-4" /> Companies</button>
        <button onClick={() => setActiveTab('settings')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'settings' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Settings className="h-4 w-4" /> Settings</button>
      </div>

      {activeTab === 'lottery' && (
        <section className="space-y-6">
          <div className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-lg font-bold flex items-center gap-2 text-slate-800">
                <Clock className="h-5 w-5 text-indigo-500" /> Live Lottery Control
              </h3>
              <button 
                onClick={() => setShowHowItWorks(!showHowItWorks)} 
                className="flex items-center gap-2 px-3 py-1.5 rounded-xl text-xs font-bold text-indigo-600 bg-indigo-50 hover:bg-indigo-100 transition-colors"
              >
                <HelpCircle className="h-4 w-4" /> How it Works
              </button>
            </div>

            {showHowItWorks && (
              <div className="mb-8 p-6 bg-slate-50 rounded-2xl border border-slate-200 animate-in slide-in-from-top-4 duration-300">
                <h4 className="font-black text-slate-800 uppercase tracking-widest text-xs mb-4 underline decoration-indigo-200 underline-offset-4">Fairness Algorithm Logic</h4>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                   <div className="space-y-2">
                      <p className="text-xs font-black text-indigo-600">1. ELIGIBILITY</p>
                      <p className="text-[11px] font-medium text-slate-600">MRs who haven't had a pass in 3 days are eligible for a new selection.</p>
                   </div>
                   <div className="space-y-2">
                      <p className="text-xs font-black text-indigo-600">2. WEIGHTING</p>
                      <p className="text-[11px] font-medium text-slate-600">Priority score increases the longer an MR has waited (Max bonus at 14 days).</p>
                   </div>
                   <div className="space-y-2">
                      <p className="text-xs font-black text-indigo-600">3. SELECTION</p>
                      <p className="text-[11px] font-medium text-slate-600">System picks highest-scored candidates up to your set daily limit.</p>
                   </div>
                </div>
              </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {(['MORNING', 'EVENING', 'FULL_DAY'] as SessionType[]).map((sess) => {
                 if (!currentHospital.supportedSessions.includes(sess)) return null;
                 const today = new Date().toISOString().split('T')[0];
                 const count = apps.filter(a => a.hospitalId === user.hospitalId && a.applicationDate === today && a.session === sess && a.status === 'applied').length;
                 const selectedCount = apps.filter(a => a.hospitalId === user.hospitalId && a.applicationDate === today && a.session === sess && (a.status === 'selected' || a.status === 'waitlisted')).length;
                 const isAuto = currentHospital.autoLotteryEnabled?.[sess];
                 const autoTime = currentHospital.autoLotteryTimes?.[sess];

                 return (
                   <div key={sess} className="p-6 bg-slate-50 border border-slate-100 rounded-3xl relative overflow-hidden group">
                     {isAuto && (
                       <div className="absolute top-0 right-0 p-2">
                          <div className="bg-indigo-600 text-white px-2 py-1.5 rounded-bl-2xl rounded-tr-xl shadow-lg flex items-center gap-1.5 animate-pulse">
                             <Zap className="h-3 w-3" />
                             <span className="text-[10px] font-black">{autoTime}</span>
                          </div>
                       </div>
                     )}
                     <div className="flex justify-between items-start mb-6">
                       <div className="flex items-center gap-3">
                         <div className="bg-white p-2 rounded-xl shadow-sm">
                           {sess === 'MORNING' ? <Sun className="h-6 w-6 text-amber-500" /> : sess === 'EVENING' ? <Moon className="h-6 w-6 text-indigo-400" /> : <Maximize className="h-6 w-6 text-indigo-600" />}
                         </div>
                         <div>
                           <h4 className="font-black text-slate-800 tracking-tight">{sess.replace('_', ' ')}</h4>
                           <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Limit: {currentHospital.passLimits?.[sess] || 0}</p>
                         </div>
                       </div>
                       <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest ${selectedCount > 0 ? 'bg-green-100 text-green-700' : 'bg-indigo-100 text-indigo-700'}`}>
                          {selectedCount > 0 ? 'COMPLETED' : 'OPEN'}
                       </span>
                     </div>

                     <div className="flex items-center justify-between p-4 bg-white rounded-2xl mb-6 shadow-sm border border-slate-100">
                        <div>
                          <p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Applied Today</p>
                          <p className="text-2xl font-black text-slate-800">{count}</p>
                        </div>
                        <Users className="h-8 w-8 text-slate-100" />
                     </div>

                     <button 
                       disabled={count === 0 || selectedCount > 0}
                       onClick={() => handleManualLottery(sess)}
                       className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-lg hover:bg-indigo-700 active:scale-95 disabled:grayscale disabled:opacity-50 transition-all flex items-center justify-center gap-2"
                     >
                       {selectedCount > 0 ? <CheckCircle2 className="h-5 w-5" /> : <Play className="h-5 w-5" />}
                       {selectedCount > 0 ? 'SPIN COMPLETED' : 'MANUAL SPIN NOW'}
                     </button>
                   </div>
                 );
              })}
            </div>
          </div>
        </section>
      )}

      {activeTab === 'history' && (
        <section className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden flex flex-col min-h-[600px]">
           <div className="p-8 border-b border-slate-100">
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                 <div>
                    <h3 className="text-xl font-bold text-slate-800">Hospital Issued Pass Audit</h3>
                    <p className="text-xs text-slate-400 font-medium mt-1">Permanent day-wise history of all issued visitor credentials.</p>
                 </div>
                 <div className="flex flex-wrap items-center gap-3">
                    <div className="relative">
                       <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
                       <input 
                         type="text" 
                         placeholder="Search MR Name or Pass ID..." 
                         value={historySearch}
                         onChange={(e) => setHistorySearch(e.target.value)}
                         className="pl-10 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold focus:ring-2 focus:ring-indigo-500 outline-none w-64"
                       />
                    </div>
                    <select 
                      value={historySessionFilter}
                      onChange={(e) => setHistorySessionFilter(e.target.value as any)}
                      className="px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs font-black uppercase outline-none focus:ring-2 focus:ring-indigo-500"
                    >
                       <option value="ALL">All Sessions</option>
                       <option value="MORNING">Morning</option>
                       <option value="EVENING">Evening</option>
                       <option value="FULL_DAY">Full Day</option>
                    </select>
                 </div>
              </div>
           </div>

           <div className="flex-1 overflow-x-auto">
              <table className="w-full text-left border-collapse">
                 <thead className="bg-slate-50/50 sticky top-0 z-10 border-b border-slate-100">
                    <tr className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
                       <th className="px-6 py-4">Date & Session</th>
                       <th className="px-6 py-4">Medical Representative</th>
                       <th className="px-6 py-4">Company</th>
                       <th className="px-6 py-4">Time Slot</th>
                       <th className="px-6 py-4">Status</th>
                       <th className="px-6 py-4">Entry Log</th>
                    </tr>
                 </thead>
                 <tbody className="divide-y divide-slate-50">
                    {filteredPasses.map(p => {
                       const mr = mrs.find(m => m.id === p.mrId);
                       const entryLog = logs.find(l => l.issuedPassId === p.id);
                       return (
                          <tr key={p.id} className="hover:bg-indigo-50/20 transition-colors group">
                             <td className="px-6 py-4">
                                <p className="text-xs font-black text-slate-800">{p.passDate}</p>
                                <div className="flex items-center gap-1 mt-1">
                                   {p.session === 'MORNING' ? <Sun className="h-3 w-3 text-amber-500" /> : <Moon className="h-3 w-3 text-indigo-400" />}
                                   <span className="text-[9px] font-bold text-slate-400 uppercase">{p.session}</span>
                                </div>
                             </td>
                             <td className="px-6 py-4">
                                <div className="flex items-center gap-2">
                                   <div className="w-8 h-8 rounded-lg bg-white border border-slate-100 flex items-center justify-center shadow-xs group-hover:border-indigo-200 transition-colors">
                                      <User className="h-4 w-4 text-slate-400" />
                                   </div>
                                   <div>
                                      <p className="text-sm font-black text-slate-800">{mr?.fullName || 'N/A'}</p>
                                      <p className="text-[10px] font-bold text-indigo-500 font-mono">{p.id}</p>
                                   </div>
                                </div>
                             </td>
                             <td className="px-6 py-4">
                                <p className="text-xs font-bold text-slate-600">{mr?.companyName}</p>
                             </td>
                             <td className="px-6 py-4">
                                <div className="flex items-center gap-2">
                                   <Clock className="h-3 w-3 text-slate-300" />
                                   <span className="text-xs font-bold text-slate-700">{p.timeSlot}</span>
                                </div>
                             </td>
                             <td className="px-6 py-4">
                                <span className={`px-2 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest ${
                                   p.entryStatus === 'entered' ? 'bg-green-100 text-green-700' :
                                   p.entryStatus === 'expired' ? 'bg-slate-100 text-slate-500' :
                                   'bg-indigo-100 text-indigo-700'
                                }`}>
                                   {p.entryStatus === 'entered' ? 'VISITED' : p.entryStatus.replace('_', ' ')}
                                </span>
                             </td>
                             <td className="px-6 py-4">
                                {entryLog ? (
                                   <div className="flex flex-col">
                                      <p className="text-[10px] font-black text-slate-800">{new Date(entryLog.entryTime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</p>
                                      <p className="text-[8px] font-bold text-slate-400 uppercase tracking-tighter">Verified by Gate Staff</p>
                                   </div>
                                ) : (
                                   <span className="text-[10px] font-bold text-slate-300">--</span>
                                )}
                             </td>
                          </tr>
                       );
                    })}
                    {filteredPasses.length === 0 && (
                       <tr>
                          <td colSpan={6} className="px-6 py-24 text-center">
                             <div className="flex flex-col items-center opacity-30">
                                <History className="h-12 w-12 text-slate-300 mb-4" />
                                <p className="text-sm font-black text-slate-400 uppercase tracking-widest">No historical records found</p>
                             </div>
                          </td>
                       </tr>
                    )}
                 </tbody>
              </table>
           </div>
        </section>
      )}

      {activeTab === 'approvals' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
          <h3 className="text-xl font-bold mb-8 flex items-center gap-2 text-slate-800">
            <UserPlus className="h-6 w-6 text-indigo-500" />
            Authorization Requests
          </h3>

          <div className="space-y-4">
            {pendingApprovals.map(a => {
              const mr = mrs.find(m => m.id === a.mrId);
              return (
                <div key={a.id} className="flex flex-col md:flex-row md:items-center justify-between p-6 bg-slate-50 border border-slate-100 rounded-3xl gap-4 hover:border-indigo-100 transition-colors">
