  const [historySessionFilter, setHistorySessionFilter] = useState<SessionType | 'ALL'>('ALL');

  // Company selection state
  const [selectedCompanyId, setSelectedCompanyId] = useState<string | null>(null);

  const [editingHospital, setEditingHospital] = useState<Hospital | null>(null);

  const refreshData = useCallback(async () => {
    const allHospitals = storageService.getHospitals();
    const currentHosp = allHospitals.find(h => h.id === user.hospitalId);

    setHospitals(allHospitals);
    setMrs(storageService.getMRs()); 
    setCompanies(storageService.getCompanies());
    setApps(storageService.getApplications()); 
    setPasses(storageService.getPasses());
    setLogs(storageService.getLogs());
    setApprovals(storageService.getApprovals());

    if (currentHosp && !editingHospital) {
      setEditingHospital({
        ...currentHosp,
        autoLotteryEnabled: currentHosp.autoLotteryEnabled || {},
        autoLotteryTimes: currentHosp.autoLotteryTimes || {},
        passLimits: currentHosp.passLimits || {},
        sessionWindows: currentHosp.sessionWindows || {},
        supportedSessions: currentHosp.supportedSessions || []
      });
    }

    try {
      const summary = await getAdminBriefing(storageService.getApplications(), storageService.getPasses());
      setBrief(summary);
    } catch (e) {
      console.error("Briefing failed", e);
    }
  }, [user.hospitalId, editingHospital]);

  useEffect(() => { 
    refreshData(); 
    const interval = setInterval(refreshData, 30000);
    return () => clearInterval(interval);
  }, [refreshData]);

  const handleManualLottery = (session: SessionType) => {
    const result = lotteryService.runLottery(user.hospitalId, session);
    if (result.success) {
      showFeedback(result.message, 'success');
      refreshData();
    } else {
      showFeedback(result.message, 'error');
    }
  };

  const handleSaveHospitalData = () => {
    if (!editingHospital) return;
    const allHospitals = storageService.getHospitals();
    const updated = allHospitals.map(h => h.id === editingHospital.id ? editingHospital : h);
    storageService.saveHospitals(updated);
    setHospitals(updated);
    showFeedback("System settings saved successfully.", "success");
  };

  const updateSessionSetting = (sess: SessionType, field: keyof Hospital, value: any) => {
    setEditingHospital(prev => {
      if (!prev) return null;
      const currentFieldData = (prev[field] as any) || {};
      return { ...prev, [field]: { ...currentFieldData, [sess]: value } };
    });
  };

  const toggleSupportedSession = (sess: SessionType) => {
    setEditingHospital(prev => {
      if (!prev) return null;
      const isSupported = prev.supportedSessions.includes(sess);
      const newSupported = isSupported 
        ? prev.supportedSessions.filter(s => s !== sess)
        : [...prev.supportedSessions, sess];

      const newAutoEnabled = { ...(prev.autoLotteryEnabled || {}) };
      if (isSupported) newAutoEnabled[sess] = false;

      return { ...prev, supportedSessions: newSupported, autoLotteryEnabled: newAutoEnabled };
    });
  };

  const handleUpdateApproval = (id: string, status: 'approved' | 'rejected') => {
    const allApprovals = storageService.getApprovals();
    const updated = allApprovals.map(a => a.id === id ? { ...a, status, updatedAt: new Date().toISOString() } : a);
    storageService.saveApprovals(updated);
    setApprovals(updated);
    showFeedback(`MR Access Request ${status === 'approved' ? 'Authorized' : 'Rejected'}.`);
  };

  const currentHospital = hospitals.find(h => h.id === user.hospitalId);

  if (!currentHospital || !editingHospital) return (
    <div className="flex items-center justify-center p-20 text-slate-400 font-bold">
      Loading Facility Configuration...
    </div>
  );

  const pendingApprovals = approvals.filter(a => a.hospitalId === user.hospitalId && a.status === 'pending');

  // Identify MRs approved SPECIFICALLY for this hospital
  const approvedMRs = mrs.filter(mr => 
    approvals.some(a => a.mrId === mr.id && a.hospitalId === user.hospitalId && a.status === 'approved')
  );

  // Identify companies with at least one approved MR for this hospital
  const approvedCompanies = companies.filter(c => 
    approvedMRs.some(mr => mr.companyName === c.name)
  );

  // Filtering Logic for History
  const filteredPasses = passes
    .filter(p => p.hospitalId === user.hospitalId)
    .filter(p => {
      const mr = mrs.find(m => m.id === p.mrId);
      const matchesSearch = mr?.fullName.toLowerCase().includes(historySearch.toLowerCase()) || p.id.toLowerCase().includes(historySearch.toLowerCase());
      const matchesSession = historySessionFilter === 'ALL' || p.session === historySessionFilter;
      return matchesSearch && matchesSession;
    })
    .sort((a, b) => new Date(b.passDate).getTime() - new Date(a.passDate).getTime());

  return (
    <div className="space-y-6">
      <div className="bg-indigo-600 rounded-3xl p-6 text-white shadow-lg flex items-center gap-4 border border-indigo-400/30">
        <Sparkles className="h-6 w-6 text-indigo-200 shrink-0" />
        <p className="text-sm font-medium leading-relaxed">{brief || "Analyzing booking patterns and priority scoring..."}</p>
      </div>

      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit gap-1 overflow-x-auto max-w-full">
        <button onClick={() => setActiveTab('lottery')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'lottery' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Play className="h-4 w-4" /> Lottery</button>
        <button onClick={() => setActiveTab('history')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'history' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><History className="h-4 w-4" /> Records</button>
        <button onClick={() => setActiveTab('approvals')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all relative ${activeTab === 'approvals' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}>
          <UserPlus className="h-4 w-4" /> Requests
          {pendingApprovals.length > 0 && <span className="absolute -top-1 -right-1 flex h-4 w-4 items-center justify-center rounded-full bg-red-500 text-[8px] text-white ring-2 ring-white">{pendingApprovals.length}</span>}
        </button>
        <button onClick={() => setActiveTab('companies')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'companies' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Briefcase className="h-4 w-4" /> Partners</button>
        <button onClick={() => setActiveTab('settings')} className={`px-4 sm:px-6 py-2.5 rounded-xl text-sm font-bold flex items-center gap-2 transition-all ${activeTab === 'settings' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}><Settings className="h-4 w-4" /> Settings</button>
      </div>

      {activeTab === 'lottery' && (
        <section className="space-y-6">
          <div className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-lg font-bold flex items-center gap-2 text-slate-800">
                <Clock className="h-5 w-5 text-indigo-500" /> Live Lottery Control
              </h3>
              <button 
                onClick={() => setShowHowItWorks(!showHowItWorks)} 
                className="flex items-center gap-2 px-3 py-1.5 rounded-xl text-xs font-bold text-indigo-600 bg-indigo-50 hover:bg-indigo-100 transition-colors"
              >
                <HelpCircle className="h-4 w-4" /> How it Works
              </button>
            </div>

            {showHowItWorks && (
              <div className="mb-8 p-6 bg-slate-50 rounded-2xl border border-slate-200 animate-in slide-in-from-top-4 duration-300">
                <h4 className="font-black text-slate-800 uppercase tracking-widest text-xs mb-4 underline decoration-indigo-200 underline-offset-4">Fairness Algorithm Logic</h4>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                   <div className="space-y-2">
                      <p className="text-xs font-black text-indigo-600">1. ELIGIBILITY</p>
                      <p className="text-[11px] font-medium text-slate-600">MRs who haven't had a pass in 3 days are eligible for a new selection.</p>
                   </div>
                   <div className="space-y-2">
                      <p className="text-xs font-black text-indigo-600">2. WEIGHTING</p>
                      <p className="text-[11px] font-medium text-slate-600">Priority score increases the longer an MR has waited (Max bonus at 14 days).</p>
                   </div>
                   <div className="space-y-2">
                      <p className="text-xs font-black text-indigo-600">3. SELECTION</p>
                      <p className="text-[11px] font-medium text-slate-600">System picks highest-scored candidates up to your set daily limit.</p>
                   </div>
                </div>
              </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {(['MORNING', 'EVENING', 'FULL_DAY'] as SessionType[]).map((sess) => {
                 if (!currentHospital.supportedSessions.includes(sess)) return null;
                 const today = new Date().toISOString().split('T')[0];
                 const count = apps.filter(a => a.hospitalId === user.hospitalId && a.applicationDate === today && a.session === sess && a.status === 'applied').length;
                 const selectedCount = apps.filter(a => a.hospitalId === user.hospitalId && a.applicationDate === today && a.session === sess && (a.status === 'selected' || a.status === 'waitlisted')).length;
                 const isAuto = currentHospital.autoLotteryEnabled?.[sess];
                 const autoTime = currentHospital.autoLotteryTimes?.[sess];

                 return (
                   <div key={sess} className="p-6 bg-slate-50 border border-slate-100 rounded-3xl relative overflow-hidden group">
                     {isAuto && (
                       <div className="absolute top-0 right-0 p-2">
                          <div className="bg-indigo-600 text-white px-2 py-1.5 rounded-bl-2xl rounded-tr-xl shadow-lg flex items-center gap-1.5 animate-pulse">
                             <Zap className="h-3 w-3" />
                             <span className="text-[10px] font-black">{autoTime}</span>
                          </div>
                       </div>
                     )}
                     <div className="flex justify-between items-start mb-6">
                       <div className="flex items-center gap-3">
                         <div className="bg-white p-2 rounded-xl shadow-sm">
                           {sess === 'MORNING' ? <Sun className="h-6 w-6 text-amber-500" /> : sess === 'EVENING' ? <Moon className="h-6 w-6 text-indigo-400" /> : <Maximize className="h-6 w-6 text-indigo-600" />}
                         </div>
                         <div>
                           <h4 className="font-black text-slate-800 tracking-tight">{sess.replace('_', ' ')}</h4>
                           <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Limit: {currentHospital.passLimits?.[sess] || 0}</p>
                         </div>
                       </div>
                       <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest ${selectedCount > 0 ? 'bg-green-100 text-green-700' : 'bg-indigo-100 text-indigo-700'}`}>
                          {selectedCount > 0 ? 'COMPLETED' : 'OPEN'}
                       </span>
                     </div>

                     <div className="flex items-center justify-between p-4 bg-white rounded-2xl mb-6 shadow-sm border border-slate-100">
                        <div>
                          <p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Applied Today</p>
                          <p className="text-2xl font-black text-slate-800">{count}</p>
                        </div>
                        <Users className="h-8 w-8 text-slate-100" />
                     </div>

                     <button 
                       disabled={count === 0 || selectedCount > 0}
                       onClick={() => handleManualLottery(sess)}
                       className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-lg hover:bg-indigo-700 active:scale-95 disabled:grayscale disabled:opacity-50 transition-all flex items-center justify-center gap-2"
                     >
                       {selectedCount > 0 ? <CheckCircle2 className="h-5 w-5" /> : <Play className="h-5 w-5" />}
                       {selectedCount > 0 ? 'SPIN COMPLETED' : 'MANUAL SPIN NOW'}
                     </button>
                   </div>
                 );
              })}
            </div>
          </div>
        </section>
      )}

      {activeTab === 'history' && (
        <section className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden flex flex-col min-h-[600px]">
           <div className="p-8 border-b border-slate-100">
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                 <div>
                    <h3 className="text-xl font-bold text-slate-800">Hospital Issued Pass Audit</h3>
                    <p className="text-xs text-slate-400 font-medium mt-1">Permanent day-wise history of all issued visitor credentials.</p>
                 </div>
                 <div className="flex flex-wrap items-center gap-3">
                    <div className="relative">
                       <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
                       <input 
                         type="text" 
                         placeholder="Search MR Name or Pass ID..." 
                         value={historySearch}
                         onChange={(e) => setHistorySearch(e.target.value)}
                         className="pl-10 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold focus:ring-2 focus:ring-indigo-500 outline-none w-64"
                       />
                    </div>
                    <select 
                      value={historySessionFilter}
                      onChange={(e) => setHistorySessionFilter(e.target.value as any)}
                      className="px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-xs font-black uppercase outline-none focus:ring-2 focus:ring-indigo-500"
                    >
                       <option value="ALL">All Sessions</option>
                       <option value="MORNING">Morning</option>
                       <option value="EVENING">Evening</option>
                       <option value="FULL_DAY">Full Day</option>
                    </select>
                 </div>
              </div>
           </div>

           <div className="flex-1 overflow-x-auto">
              <table className="w-full text-left border-collapse">
                 <thead className="bg-slate-50/50 sticky top-0 z-10 border-b border-slate-100">
                    <tr className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
                       <th className="px-6 py-4">Date & Session</th>
                       <th className="px-6 py-4">Medical Representative</th>
                       <th className="px-6 py-4">SLCPI ID</th>
                       <th className="px-6 py-4">Company</th>
                       <th className="px-6 py-4">Time Slot</th>
                       <th className="px-6 py-4">Status</th>
                       <th className="px-6 py-4">Entry Log</th>
                    </tr>
                 </thead>
                 <tbody className="divide-y divide-slate-50">
                    {filteredPasses.map(p => {
                       const mr = mrs.find(m => m.id === p.mrId);
                       const entryLog = logs.find(l => l.issuedPassId === p.id);
                       return (
                          <tr key={p.id} className="hover:bg-indigo-50/20 transition-colors group">
                             <td className="px-6 py-4">
                                <p className="text-xs font-black text-slate-800">{p.passDate}</p>
                                <div className="flex items-center gap-1 mt-1">
                                   {p.session === 'MORNING' ? <Sun className="h-3 w-3 text-amber-500" /> : <Moon className="h-3 w-3 text-indigo-400" />}
                                   <span className="text-[9px] font-bold text-slate-400 uppercase">{p.session}</span>
                                </div>
                             </td>
                             <td className="px-6 py-4">
                                <div className="flex items-center gap-2">
                                   <div className="w-8 h-8 rounded-lg bg-white border border-slate-100 flex items-center justify-center shadow-xs group-hover:border-indigo-200 transition-colors">
                                      <User className="h-4 w-4 text-slate-400" />
                                   </div>
                                   <div>
                                      <p className="text-sm font-black text-slate-800">{mr?.fullName || 'N/A'}</p>
                                      <p className="text-[10px] font-bold text-indigo-500 font-mono">{p.id}</p>
                                   </div>
                                </div>
                             </td>
                             <td className="px-6 py-4">
                                <span className="text-xs font-mono font-bold text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded border border-indigo-100">
                                   {mr?.slcpiId || 'NO ID'}
                                </span>
                             </td>
                             <td className="px-6 py-4">
                                <p className="text-xs font-bold text-slate-600">{mr?.companyName}</p>
                             </td>
                             <td className="px-6 py-4">
                                <div className="flex items-center gap-2">
                                   <Clock className="h-3 w-3 text-slate-300" />
                                   <span className="text-xs font-bold text-slate-700">{p.timeSlot}</span>
                                </div>
                             </td>
                             <td className="px-6 py-4">
                                <span className={`px-2 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest ${
                                   p.entryStatus === 'entered' ? 'bg-green-100 text-green-700' :
                                   p.entryStatus === 'expired' ? 'bg-slate-100 text-slate-500' :
                                   'bg-indigo-100 text-indigo-700'
                                }`}>
                                   {p.entryStatus === 'entered' ? 'VISITED' : p.entryStatus.replace('_', ' ')}
                                </span>
                             </td>
                             <td className="px-6 py-4">
                                {entryLog ? (
                                   <div className="flex flex-col">
                                      <p className="text-[10px] font-black text-slate-800">{new Date(entryLog.entryTime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</p>
                                      <p className="text-[8px] font-bold text-slate-400 uppercase tracking-tighter">Verified by Gate Staff</p>
                                   </div>
                                ) : (
                                   <span className="text-[10px] font-bold text-slate-300">--</span>
                                )}
                             </td>
                          </tr>
                       );
                    })}
                    {filteredPasses.length === 0 && (
                       <tr>
                          <td colSpan={7} className="px-6 py-24 text-center">
                             <div className="flex flex-col items-center opacity-30">
                                <History className="h-12 w-12 text-slate-300 mb-4" />
                                <p className="text-sm font-black text-slate-400 uppercase tracking-widest">No historical records found</p>
                             </div>
                          </td>
                       </tr>
                    )}
                 </tbody>
              </table>
           </div>
        </section>
      )}

      {activeTab === 'approvals' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
          <h3 className="text-xl font-bold mb-8 flex items-center gap-2 text-slate-800">
            <UserPlus className="h-6 w-6 text-indigo-500" />
            Authorization Requests
          </h3>

          <div className="space-y-4">
            {pendingApprovals.map(a => {
              const mr = mrs.find(m => m.id === a.mrId);
              return (
                <div key={a.id} className="flex flex-col md:flex-row md:items-center justify-between p-6 bg-slate-50 border border-slate-100 rounded-3xl gap-4 hover:border-indigo-100 transition-colors">
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center shadow-sm">
                      <User className="h-6 w-6 text-slate-400" />
                    </div>
                    <div>
                      <p className="font-black text-slate-800">{mr?.fullName || 'Unknown MR'}</p>
                      <p className="text-xs font-bold text-indigo-600 uppercase tracking-wide">{mr?.companyName}</p>
                    </div>
                  </div>

                  <div className="flex items-center gap-2">
                    <button onClick={() => setSelectedMR(mr || null)} className="p-3 bg-white border border-slate-200 text-slate-500 rounded-xl hover:bg-indigo-50 hover:text-indigo-600 transition-all"><Eye className="h-5 w-5" /></button>
                    <button onClick={() => handleUpdateApproval(a.id, 'rejected')} className="px-6 py-3 bg-white border border-red-100 text-red-500 rounded-xl font-black text-xs hover:bg-red-50 transition-all">REJECT</button>
                    <button onClick={() => handleUpdateApproval(a.id, 'approved')} className="px-6 py-3 bg-indigo-600 text-white rounded-xl font-black text-xs shadow-md hover:bg-indigo-700 transition-all">APPROVE ACCESS</button>
                  </div>
                </div>
              );
            })}
            {pendingApprovals.length === 0 && (
              <div className="text-center py-20 bg-slate-50 rounded-3xl border-2 border-dashed border-slate-100">
                <ShieldCheck className="h-12 w-12 text-slate-200 mx-auto mb-4" />
                <p className="text-sm font-bold text-slate-400">No pending access requests at the moment.</p>
              </div>
            )}
          </div>
        </section>
      )}

      {activeTab === 'companies' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm">
          <div className="flex items-center justify-between mb-8">
            <div>
              <h3 className="text-xl font-bold text-slate-800">Authorized Pharma Partners</h3>
              <p className="text-xs text-slate-400 mt-1">Companies with Medical Representatives approved for your facility.</p>
            </div>
            <div className="bg-indigo-50 px-4 py-2 rounded-xl border border-indigo-100">
               <span className="text-[10px] font-black text-indigo-600 uppercase tracking-widest">Active Partnerships: {approvedCompanies.length}</span>
            </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {approvedCompanies.map(c => {
               const activeCompanyReps = approvedMRs.filter(mr => mr.companyName === c.name && mr.status === 'active');
               return (
                 <div key={c.id} className="bg-slate-50/50 border border-slate-100 rounded-3xl overflow-hidden hover:border-indigo-200 transition-all hover:shadow-md group">
                    <div 
                      onClick={() => setSelectedCompanyId(selectedCompanyId === c.id ? null : c.id)}
                      className="p-6 bg-white border-b border-slate-100 flex justify-between items-center cursor-pointer hover:bg-slate-50 transition-colors"
                    >
                       <div>
                          <h4 className="font-black text-lg text-slate-800 group-hover:text-indigo-600 transition-colors">{c.name}</h4>
                          <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest mt-1">{c.companyCode}</p>
                       </div>
                       <div className="flex items-center gap-3">
                          <div className="text-right hidden sm:block">
                             <p className="text-xs font-bold text-slate-500">{activeCompanyReps.length} Active MRs</p>
                             <p className="text-[9px] font-medium text-slate-400 uppercase tracking-tighter">Click to view staff</p>
                          </div>
                          <ChevronRight className={`h-5 w-5 text-slate-300 transition-transform ${selectedCompanyId === c.id ? 'rotate-90 text-indigo-500' : ''}`} />
                       </div>
                    </div>

                    {selectedCompanyId === c.id && (
                      <div className="p-6 animate-in slide-in-from-top-2 duration-300 bg-white">
                         <h5 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                            <Users className="h-3 w-3" /> Active Approved Representatives ({activeCompanyReps.length})
                         </h5>
                         <div className="grid gap-3 sm:grid-cols-2">
                            {activeCompanyReps.map(mr => (
                               <div 
                                  key={mr.id} 
                                  onClick={() => setSelectedMR(mr)}
                                  className="p-3 bg-slate-50 border border-slate-100 rounded-2xl flex items-center gap-3 hover:border-indigo-200 hover:shadow-sm transition-all cursor-pointer group/rep"
                               >
                                  <div className="w-8 h-8 rounded-lg bg-white flex items-center justify-center group-hover/rep:bg-indigo-50 transition-colors shadow-sm">
                                     <User className="h-4 w-4 text-slate-400 group-hover/rep:text-indigo-600" />
                                  </div>
                                  <div className="flex-1 min-w-0">
                                     <p className="text-xs font-black text-slate-800 truncate">{mr.fullName}</p>
                                     <p className="text-[9px] font-bold text-indigo-500 truncate">{mr.slcpiId || mr.mrId}</p>
                                  </div>
                                  <ExternalLink className="h-3 w-3 text-slate-200 group-hover/rep:text-indigo-400 transition-colors" />
                               </div>
                            ))}
                            {activeCompanyReps.length === 0 && (
                              <p className="text-[10px] text-slate-400 italic col-span-2 py-4 text-center">No currently active representatives registered for this company.</p>
                            )}
                         </div>
                      </div>
                    )}

                    <div className="px-6 py-3 bg-indigo-50/30 border-t border-slate-100 flex justify-between items-center">
                       <span className="text-[10px] font-bold text-slate-500 italic">Corporate Identity: {c.companyCode}</span>
                       <ShieldCheck className="h-4 w-4 text-green-500" />
                    </div>
                 </div>
               );
            })}

            {approvedCompanies.length === 0 && (
              <div className="lg:col-span-2 text-center py-24 bg-slate-50 border-2 border-dashed border-slate-100 rounded-3xl">
                 <Briefcase className="h-12 w-12 text-slate-200 mx-auto mb-4 opacity-30" />
                 <p className="text-sm font-black text-slate-400 uppercase tracking-widest">No Authorized Companies Yet</p>
                 <p className="text-xs text-slate-300 mt-1">Approve MR access requests to populate your partner list.</p>
              </div>
            )}
          </div>
        </section>
      )}

      {activeTab === 'settings' && (
        <section className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm max-w-2xl mx-auto">
          <div className="flex border-b border-slate-100 mb-8 overflow-x-auto">
            <button onClick={() => setSettingsTab('profile')} className={`px-6 py-3 text-sm font-black transition-all border-b-2 whitespace-nowrap ${settingsTab === 'profile' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400'}`}>HOSPITAL PROFILE</button>
            <button onClick={() => setSettingsTab('sessions')} className={`px-6 py-3 text-sm font-black transition-all border-b-2 whitespace-nowrap ${settingsTab === 'sessions' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400'}`}>SESSIONS & AUTO-SPIN</button>
          </div>

          <div className="space-y-8 animate-in fade-in duration-300">
            {settingsTab === 'profile' ? (
              <div className="space-y-6">
                <div className="space-y-4">
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Official Name</label>
                    <input type="text" value={editingHospital.name} readOnly className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold text-slate-500" />
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Facility Address</label>
                    <textarea 
                      value={editingHospital.address || ''} 
                      onChange={(e) => setEditingHospital({...editingHospital, address: e.target.value})}
                      className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl font-bold focus:ring-2 focus:ring-indigo-500 outline-none h-24" 
                    />
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Hospital Email</label>
                      <input 
                        type="email" 
                        value={editingHospital.email || ''} 
                        onChange={(e) => setEditingHospital({...editingHospital, email: e.target.value})}
                        className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl font-bold outline-none" 
                      />
                    </div>
                    <div>
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Public Mobile</label>
                      <input 
                        type="tel" 
                        value={editingHospital.mobileNumber || ''} 
                        onChange={(e) => setEditingHospital({...editingHospital, mobileNumber: e.target.value})}
                        className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl font-bold outline-none" 
                      />
                    </div>
                  </div>
                </div>
              </div>
            ) : (
              <div className="space-y-6">
                {(['MORNING', 'EVENING', 'FULL_DAY'] as SessionType[]).map(sess => {
                  const isSupported = editingHospital.supportedSessions.includes(sess);
                  const isAuto = editingHospital.autoLotteryEnabled?.[sess] || false;

                  return (
                    <div key={sess} className={`p-6 rounded-3xl border-2 transition-all ${isSupported ? 'bg-white border-indigo-100 shadow-sm' : 'bg-slate-50 border-dashed border-slate-200 opacity-60'}`}>
                        <div className="flex items-center justify-between mb-4">
                          <div className="flex items-center gap-2">
                             {sess === 'MORNING' ? <Sun className="h-5 w-5 text-amber-500" /> : sess === 'EVENING' ? <Moon className="h-5 w-5 text-indigo-500" /> : <Maximize className="h-5 w-5 text-indigo-600" />}
                             <span className="font-black text-slate-800 uppercase tracking-widest">{sess.replace('_', ' ')}</span>
                          </div>
                          <label className="relative inline-flex items-center cursor-pointer">
                              <input type="checkbox" checked={isSupported} onChange={() => toggleSupportedSession(sess)} className="sr-only peer" />
                              <div className="w-11 h-6 bg-gray-200 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-indigo-600"></div>
                          </label>
                        </div>

                        {isSupported && (
                          <div className="space-y-4 animate-in slide-in-from-top-2 duration-300">
                             <div className="grid grid-cols-2 gap-4">
                                <div>
                                   <label className="text-[10px] font-black text-slate-400 uppercase mb-1 block">Pass Limit</label>
                                   <input 
                                     type="number" 
                                     value={editingHospital.passLimits?.[sess] || 0}
                                     onChange={(e) => updateSessionSetting(sess, 'passLimits', parseInt(e.target.value) || 0)}
                                     className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl font-bold" 
                                   />
                                </div>
                                <div className="grid grid-cols-2 gap-2">
                                   <div>
                                      <label className="text-[10px] font-black text-slate-400 uppercase mb-1 block">Start Window</label>
                                      <input type="time" value={editingHospital.sessionWindows?.[sess]?.start || '08:00'} onChange={(e) => updateSessionSetting(sess, 'sessionWindows', { ...(editingHospital.sessionWindows?.[sess] || {start:'08:00', end:'10:00'}), start: e.target.value })} className="w-full px-2 py-2 bg-slate-50 border border-slate-200 rounded-xl font-bold text-xs" />
                                   </div>
                                   <div>
                                      <label className="text-[10px] font-black text-slate-400 uppercase mb-1 block">End Window</label>
                                      <input type="time" value={editingHospital.sessionWindows?.[sess]?.end || '10:00'} onChange={(e) => updateSessionSetting(sess, 'sessionWindows', { ...(editingHospital.sessionWindows?.[sess] || {start:'08:00', end:'10:00'}), end: e.target.value })} className="w-full px-2 py-2 bg-slate-50 border border-slate-200 rounded-xl font-bold text-xs" />
                                   </div>
                                </div>
                             </div>

                             <div className="pt-4 border-t border-slate-50 flex items-center justify-between">
                                <div className="flex items-center gap-2">
                                   <Zap className={`h-4 w-4 ${isAuto ? 'text-indigo-600' : 'text-slate-300'}`} />
                                   <span className="text-xs font-bold text-slate-700">Scheduled Auto-Spin</span>
                                </div>
                                <div className="flex items-center gap-3">
                                   {isAuto && (
                                     <div className="flex items-center gap-2 bg-indigo-50 px-3 py-1.5 rounded-xl border border-indigo-100 shadow-sm">
                                        <Timer className="h-3 w-3 text-indigo-400" />
                                        <input 
                                          type="time" 
                                          value={editingHospital.autoLotteryTimes?.[sess] || '18:00'} 
                                          onChange={(e) => updateSessionSetting(sess, 'autoLotteryTimes', e.target.value)}
                                          className="bg-transparent border-none text-xs font-black text-indigo-800 p-0 focus:ring-0 w-16"
                                        />
                                     </div>
                                   )}
                                   <button 
                                      type="button"
                                      onClick={() => updateSessionSetting(sess, 'autoLotteryEnabled', !isAuto)}
                                      className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all shadow-sm ${isAuto ? 'bg-indigo-600 text-white' : 'bg-slate-200 text-slate-500'}`}
                                   >
                                      {isAuto ? 'AUTO ON' : 'AUTO OFF'}
                                   </button>
                                </div>
                             </div>
                          </div>
                        )}
                    </div>
                  );
                })}
              </div>
            )}

            <div className="pt-6 border-t border-slate-100 space-y-4">
               {editingHospital !== currentHospital && (
                 <div className="bg-amber-50 border border-amber-100 p-4 rounded-2xl flex items-center gap-3">
                    <AlertTriangle className="h-5 w-5 text-amber-500" />
                    <p className="text-xs font-bold text-amber-800">You have unsaved configuration changes. These will not take effect until you commit them.</p>
                 </div>
               )}
               <button onClick={handleSaveHospitalData} className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl shadow-xl hover:bg-indigo-700 active:scale-95 transition-all flex items-center justify-center gap-2">
                 <Save className="h-5 w-5" /> COMMIT SYSTEM CHANGES
               </button>
            </div>
          </div>
        </section>
      )}

      {selectedMR && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-lg rounded-3xl shadow-2xl overflow-hidden animate-in slide-in-from-bottom-4 duration-300">
            <div className="p-6 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
              <h3 className="text-xl font-bold">Representative Identity</h3>
              <button onClick={() => setSelectedMR(null)}><X className="h-5 w-5 text-slate-400" /></button>
            </div>
            <div className="p-8 space-y-6 max-h-[85vh] overflow-y-auto">
               <div className="text-center">
                 <div className="w-20 h-20 bg-indigo-100 rounded-full flex items-center justify-center mx-auto mb-4 border-4 border-white shadow-sm">
                   <User className="h-10 w-10 text-indigo-600" />
                 </div>
                 <h4 className="text-2xl font-black text-slate-800">{selectedMR.fullName}</h4>
                 <p className="text-indigo-600 font-bold text-sm tracking-wide uppercase">{selectedMR.companyName}</p>
               </div>

               <div className="grid grid-cols-2 gap-4">
                  <div className="p-3 bg-slate-50 rounded-xl border border-slate-100"><p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Login ID</p><p className="font-bold text-slate-700 font-mono text-xs">{selectedMR.loginId}</p></div>
                  <div className="p-3 bg-slate-50 rounded-xl border border-slate-100"><p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">System ID</p><p className="font-bold text-slate-700 font-mono text-xs">{selectedMR.mrId}</p></div>
                  <div className="p-3 bg-slate-50 rounded-xl border border-slate-100"><p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">Mobile</p><p className="font-bold text-slate-700 text-sm">{selectedMR.mobileNumber}</p></div>
                  <div className="p-3 bg-slate-50 rounded-xl border border-slate-100"><p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">SLCPI ID</p><p className="font-bold text-slate-700 text-sm">{selectedMR.slcpiId || 'N/A'}</p></div>
               </div>

               {selectedMR.slcpiPhoto && (
                 <div className="rounded-2xl overflow-hidden border border-slate-200 mt-4 bg-slate-50 p-2 shadow-inner">
                   <img src={selectedMR.slcpiPhoto} className="w-full object-contain max-h-48 rounded-xl" alt="ID Document" />
                 </div>
               )}

               <button onClick={() => setSelectedMR(null)} className="w-full bg-slate-800 text-white font-black py-4 rounded-2xl shadow-xl hover:bg-slate-900 transition-all uppercase tracking-widest text-xs">CLOSE PROFILE</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;
